    /// <summary>Ustawienia w MCM. Plik XML dziala dalej jako wartosci startowe.</summary>
    public class McmSettings : AttributeGlobalSettings<McmSettings>
    {
        public override string Id => "Armoury";
        public override string DisplayName => "The Armoury";
        public override string FolderName => "Armoury";
        public override string FormatType => "json2";

        [SettingPropertyBool("Tidy Banner Kings Armour List", HintText = "real categories and tier labels in the Banner Kings armour tab", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public bool TidyBannerKingsArmourList { get; set; } = true;

        [SettingPropertyBool("Forge Armour Enabled", HintText = "off when Banner Kings' own armour tab in the smithy screen handles forging", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public bool ForgeArmourEnabled { get; set; } = false;

        [SettingPropertyBool("Crafting Enabled", HintText = "armour forging on or off", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public bool CraftingEnabled { get; set; } = true;

        [SettingPropertyInteger("Smithing Skill Per Tier", 0, 140, "0", HintText = "Smithing you need before you may attempt a piece, per tier above the first - 35 means tier 5 plate opens at 140 and tier 6 at 175 (cloth 20 and leather, bows and crossbows 10 lower); also the gate for mending your own gear by hand. It only opens the door - the dice are set by Smithing Difficulty Per Tier", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public int SmithingSkillPerTier { get; set; } = 35;

        [SettingPropertyInteger("Smithing Difficulty Per Tier", 0, 180, "0", HintText = "how hard a piece really is for the dice, per tier above the first, whatever the door says: the quality it comes out with (rusty to legendary - armour, bows and the reforged weapons alike), the risk of cracking it, the XP it teaches and the odds of copying a pattern. 45 keeps the odds as they were, so a lower Smithing Skill Per Tier lets you start finer work sooner - at first with more spoiled pieces - and never hands out more legends", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public int SmithingDifficultyPerTier { get; set; } = 45;

        [SettingPropertyBool("Armour Craft Like Weapons", HintText = "armour forged in the Banner Kings CRAFT tab follows the rule of bows and reforged weapons: you may start a piece once your smith reaches its threshold (Smithing Skill Per Tier - the tab shows it as Difficulty), and his Smithing against the piece's difficulty (Smithing Difficulty Per Tier) sets the risk of cracking it (the tab shows the real Botching Chance) and the quality it comes out with from its own armour group - rusty or ripped, dented or worn, plain, fine, lordly, legendary, with their protection bonus or loss (tier 1-3 at best fine, tier 4 at best lordly). Your own armour keeps its make under wear: wear never turns a rusty piece into a better one, and the smith's repair restores only the piece that was actually worn. Off: armour from the tab comes out plain as before, with the Banner Kings crack chance", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public bool ArmourCraftLikeWeapons { get; set; } = true;

        [SettingPropertyBool("Armour Botch Half Back", HintText = "when a piece of armour cracks on the anvil in the Banner Kings CRAFT tab, you lose only the share of each material set by Material Loss On Failure (at least one piece of each) and the rest goes back into your bags - the same rule as a cracked bow or crossbow (needs Armour Craft Like Weapons on; off = the whole bill of materials is lost, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Forging armour")]
        public bool ArmourBotchHalfBack { get; set; } = true;

