        [SettingPropertyGroup("The finished piece")]
        public bool SutlerClothing { get; set; } = true;

        [SettingPropertyInteger("Sutler Ramp Days", 0, 112, "0", HintText = "when the sutlers first come to a save whose parties hold more than 15 days of pay in their purses, their share rises from 1% to the full share over this many days (0 = the full share at once)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public int SutlerRampDays { get; set; } = 28;

        [SettingPropertyInteger("Men Upgrade Min Gain Percent", 0, 40, "0", HintText = "a new piece must be at least this much stronger than the old one (or of a higher tier) before the men pay for it", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public int MenUpgradeMinGainPercent { get; set; } = 10;

        [SettingPropertyInteger("Men Upgrade Max Per Visit", 0, 80, "0", HintText = "at most this many better pieces per party per day in town", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public int MenUpgradeMaxPerVisit { get; set; } = 20;

        [SettingPropertyBool("Men Upgrade One Tier Up", HintText = "a soldier who can afford it may buy kit one tier above his own rank, if the market has it and he meets its skill requirement - the same for your men, AI lords' men and garrisons (off: only kit up to his own tier)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool MenUpgradeOneTierUp { get; set; } = true;

        [SettingPropertyBool("Men Upgrade Ammo Needs Surplus", HintText = "arrows and bolts: the men swap a quiver only for one of a higher tier, and only from a stall that has enough of that kind (its price is not above worth) - a man with a full quiver does not take the last sheaves from those who have none; the same for your men, AI lords' men and garrisons (off: any clearly stronger quiver, as for the rest of their kit)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool MenUpgradeAmmoNeedsSurplus { get; set; } = true;

        [SettingPropertyBool("Garrison Purse Enabled", HintText = "garrisons keep a purse from their own pay: they buy what they lack and better kit at their own market (a castle orders from the town its villages trade with and the goods come by cart) and once a week sell their spare kit at their own town or castle - your garrisons too", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GarrisonPurseEnabled { get; set; } = true;

        [SettingPropertyBool("Quartermaster Swap One For One", HintText = "swap in the stores: the men take a piece of yours only if it fills empty hands or beats the one they wear (and they meet its skill requirement); for every piece that replaced one of theirs they hand you a piece of that kind back (with Swap Returns Their Old Kit the very piece it replaced, else their worst spare one); worse, equal or too heavy pieces stay yours in the stash; the men's spare is theirs - take it and you pay them the merchant's price (with Armoury Shows Only Yours their spare is not listed at all)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool QuartermasterSwapOneForOne { get; set; } = true;

        [SettingPropertyBool("Armoury Shows Only Yours", HintText = "the troop armoury (Dynamic Troop Equipment stash) lists only YOUR kit, free to take: what the men wear and their share of the spoils is theirs and is not listed - they sell their spare spoils in the next town and buy better kit if they can afford it (needs Men Purse Enabled and Armoury Protect Used; off = their spare is listed and you pay them for what you take)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool ArmouryShowsOnlyYours { get; set; } = true;

        [SettingPropertyBool("Swap Returns Their Old Kit", HintText = "when the men take a better piece of yours in the stores, you get back the very piece it replaced (the soldier's old kit), not their worst spare piece; a piece that filled empty hands gives nothing back (off = their worst spare piece of that kind, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool SwapReturnsTheirOldKit { get; set; } = true;

        [SettingPropertyBool("Player Men Sell Spare Horses", HintText = "your men sell spare horses from the troop armoury (beyond one per rider plus Surplus Keep Percent, and horses no rider of theirs can ride) to the merchants of the next town, like the rest of their spare kit - the coin goes to the men's purse (off = their horses stay in the armoury, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool PlayerMenSellSpareHorses { get; set; } = true;

        [SettingPropertyBool("Armoury Book Per Modifier", HintText = "the book of YOUR kit in the troop armoury remembers each piece with its condition (Fine, Rusty...), not only its kind: with two copies of the same item in different condition you keep exactly the copy you put in at every sorting, instead of the worse one. Old entries keep the copies you hold now (off = the book counts kinds only and your share falls on the worst copies, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool ArmouryBookPerModifier { get; set; } = true;

        [SettingPropertyBool("Armoury List Spare Horses When Kept", HintText = "with Armoury Shows Only Yours on and Player Men Sell Spare Horses off, the men's spare horses stay listed in the troop armoury - take one and you pay them the merchant's price on closing (off = they are hidden and never sold either, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool ArmouryListSpareHorsesWhenKept { get; set; } = true;

        [SettingPropertyBool("Surplus Usable Any Group", HintText = "when the men (yours, AI lords' and garrisons') pick what to sell or use up in drill, a spare piece counts as usable if ANY troop of theirs can use it, not only their best troop - a piece only riders, or only another people, can use is no longer dumped as 'nobody can use it' (off = only the most skilled troop is asked, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool SurplusUsableAnyGroup { get; set; } = true;

        [SettingPropertyBool("Gear Fit Store Sub No Legends", HintText = "with Gear Fit Realm From Stores: when a soldier's foreign piece is swapped for one from the battle stores, the swap never hands out a legendary weapon, nor giant's gear to anyone but giants (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GearFitStoreSubNoLegends { get; set; } = true;

        [SettingPropertyBool("Gear Fit Realm Foot In Hideout Siege", HintText = "in hideouts and siege assaults riders fight on foot (in a sally-out or relief battle only the besiegers, who spawn without horses there; the besieged and the relief force keep their horses): the battle stores (foreign-piece swap and the weapon floor) no longer refuse them long bows, pikes and other weapons that cannot be used from the saddle just because Dynamic Troop Equipment gave them a horse there (off = judged by that horse, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GearFitRealmFootInHideoutSiege { get; set; } = true;

        [SettingPropertyBool("Gear Fit Skill Law Foot In Hideout Siege", HintText = "the same rule for the whole-party weapon matching in battle (the skill check that gives the hardest usable piece to the most skilled man): in hideouts and siege assaults (in a sally-out or relief battle only the besiegers) a trooper whose template rides is matched as a man on foot, so he may get a long bow, a pike or another weapon that cannot be used from the saddle (off = always matched as a rider, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GearFitSkillLawFootInHideoutSiege { get; set; } = true;

        [SettingPropertyBool("Night Prompt Skip When Rested", HintText = "the 'Night Falls - make camp?' question (and 'always make camp at nightfall') is not raised when your men have already slept their daily hours, e.g. after you slept in the menu - marching on costs them no sleep then (off = asked as before)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool NightPromptSkipWhenRested { get; set; } = true;

        [SettingPropertyBool("Garrison Kit Menu", HintText = "'Hand kit to the garrison' in the menu of your towns and castles: drop kit on the garrison - they take what fills empty hands or beats their own and give you their worse pieces back; the rest comes back to you", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GarrisonKitMenu { get; set; } = true;

        [SettingPropertyBool("Garrison Armory In Battle", HintText = "garrisons in your battles fight with the kit in their stores (Dynamic Troop Equipment) instead of their full template for free", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GarrisonArmoryInBattle { get; set; } = true;

        [SettingPropertyBool("Garrison Fights With Armory Only", HintText = "a garrison in your battles fights only with what its stores hold, however little: a man with no piece for a slot fights without it - no free template kit and no emergency kit (off: below the fill threshold it fights in its full template; the threshold also applies while Ai Buys Gear or Garrison Armory Survives Save is off, because then the stores do not last)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool GarrisonFightsWithArmoryOnly { get; set; } = true;

        [SettingPropertyInteger("Garrison Armory Min Fill Percent", 0, 100, "0", HintText = "only when Garrison Fights With Armory Only is off: below this share of filled template slots a garrison still fights in its full template", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public int GarrisonArmoryMinFillPercent { get; set; } = 75;

        [SettingPropertyBool("Troops Fight With Own Kit Only", HintText = "in your battles every soldier - yours and AI lords' (your companions' and clan parties' too) - fights only with the kit his party's stores hold: a man with no piece for a slot fights without it. Dynamic Troop Equipment no longer gives your men emergency peasant kit nor fills AI lords' men's empty slots with template kit out of thin air, and in auto-resolved battles you loot only what they really had. A rider rides only a horse his party's stores hold, or goes on foot - yours and the AI's alike: the horse paid for a promotion goes into the stores, lords put their riders on horses from the baggage and buy more, new campaigns start with the riders' horses, and a horse goes with its rider when you move men between parties; heroes keep their own gear; the dead of the Night King are not affected (off: as before - see Lord Battle Kit Is Lent)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool TroopsFightWithOwnKitOnly { get; set; } = true;

        [SettingPropertyBool("Lord Battle Kit Is Lent", HintText = "only when Troops Fight With Own Kit Only is off: in your battles Dynamic Troop Equipment fills an AI lord's soldier's empty slots with his template kit out of thin air: that kit is only lent for the battle and no longer goes into the lord's stores afterwards (nor into your spoils from them); the men still fight with it (off: as before, it stays in the lord's stores)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool LordBattleKitIsLent { get; set; } = false;

        [SettingPropertyBool("Ai Wear Enabled", HintText = "AI lords' kit wears too: battle wear on pieces in use, loot comes in battered, town smiths mend it day by day from the men's purse", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool AiWearEnabled { get; set; } = true;

        [SettingPropertyBool("Mine Wages Stay In Town", HintText = "when a town buys a Banner Kings mine's ore, half the price is the lord's due and half the miners' wages - spent in that same town (before, that half vanished)", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public bool MineWagesStayInTown { get; set; } = true;

        [SettingPropertyFloatingInteger("Work Hours Per Man Day", 0.00f, 64.00f, "0.00", HintText = "hours a town smith works in a day when there are orders - dawn to dusk with journeymen at the bench; the town's smiths share them between mending (your men and AI lords alike) and new work in the workshops", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public float WorkHoursPerManDay { get; set; } = 16f;

        [SettingPropertyInteger("Troop Self Mend Percent Per Day", 0, 40, "0", HintText = "the men mend this PERCENT of all battle-worn pieces in the stores each day in town (at least 3 pieces) - a full refit takes about 100/percent days of rest; pay the smith yourself to skip the wait", RequireRestart = false)]
        [SettingPropertyGroup("The finished piece")]
        public int TroopSelfMendPercentPerDay { get; set; } = 10;

        [SettingPropertyBool("Troop Skill Auto Fit", HintText = "troops are audited on load: any skill below the demands of their OWN template gear (armour->Athletics, mount->Riding, weapons->their class) is raised to match - the elite keeps its heavy plate because it has earned the muscles", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public bool TroopSkillAutoFit { get; set; } = true;

        [SettingPropertyBool("Skills Decide Enabled", HintText = "no more 'default tier +2': troops use ANY gear their stats allow, main weapon follows their best skill, the backup their second best (an archer carries bow, two quivers and a sidearm of his second skill)", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public bool SkillsDecideEnabled { get; set; } = true;

        [SettingPropertyBool("Hero Gear Requirements", HintText = "you, your companions and the lords cannot put on armour above their Athletics - the same rule as for soldiers (arrows above Bow and bolts above Crossbow the game itself already refuses). On the inventory screen the card turns red, the game says 'You don't have enough Athletics skill to equip this item' and the description shows 'Requires: Athletics 175'. Armour asks Athletics by its weight only (Armour Kg Per Athletics), so gowns, robes, hats and gloves ask almost nothing. The same holds for Spoils' auto-equip of companions, for a lord buying or taking a renowned piece by the custom of war (what he cannot carry goes to his baggage and stays the renowned piece there), for the plain piece that replaces a renowned one, for the troop kit you and your companions are handed when enlisted in a lord's service (a piece you cannot carry is swapped for your own of the same kind, or for the best one you can carry) and for the weapon a captive gets when you take his famed one. What anyone already wears stays on him, in battle too. Horse barding asks Riding (Hero Barding Needs Riding). Off = only the game's own check of weapons, shields, arrows, bolts and horses", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public bool HeroGearRequirements { get; set; } = true;

        [SettingPropertyBool("Hero Barding Needs Riding", HintText = "horse barding and saddles ask Riding of you, your companions and the lords too - the same rule as for soldiers. Realm of Thrones' own gear requirements (on by default) already make the inventory screen refuse barding above your Riding; this makes the rest follow the screen: Spoils' auto-equip of companions, your starting kit, a lord taking renowned barding by the custom of war (what he cannot ride with goes to his baggage). With Realm of Thrones' requirements off, the screen refuses barding above your Riding by this rule. What anyone already wears stays on him. Off = barding is not checked for heroes, except by the game's own screen", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public bool HeroBardingNeedsRiding { get; set; } = true;

        [SettingPropertyBool("Hero Skill To Own Gear", HintText = "AI lords, companions and your grown family get the Athletics, Bow and Crossbow their own battle gear demands (armour, arrows, bolts) - raised, never lowered - so that nobody loses his armour to Hero Gear Requirements: on load, whenever the game dresses a hero from a template, and in a daily check. Works only while Hero Gear Requirements is on. You are never raised. Raised skills open their perks too: the game picks them for AI lords (Imposing Stature and Merry Men give a commander 5 more men), your companions and family get them as perk picks. Applied by CrashScribe; turning it off does not lower skills already raised", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public bool HeroSkillToOwnGear { get; set; } = false;

        [SettingPropertyInteger("Weapon Skill Per Tier", 0, 140, "0", HintText = "Weapon Tier Law: a weapon or shield needs at least (tier - 1) x this in its skill, whatever the data says - a tier 6 blade wants 175, so a One Handed 30 bandit never 'qualifies' for it; 0 turns the law off. Applied at session start", RequireRestart = false)]
        [SettingPropertyGroup("Skills rule the gear")]
        public int WeaponSkillPerTier { get; set; } = 35;

        [SettingPropertyBool("Elephant Quarantine Enabled", HintText = "elephants and their barding sell only in settlements of their own culture - no war beasts wintering in Winterfell", RequireRestart = false)]
        [SettingPropertyGroup("The menagerie")]
        public bool ElephantQuarantineEnabled { get; set; } = true;

        [SettingPropertyBool("Hideout Purge Enabled", HintText = "a cleared hideout must be SEARCHED: the plundered gold, renown and the gratitude of the district wait behind one more step", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public bool HideoutPurgeEnabled { get; set; } = true;

        [SettingPropertyInteger("Hideout Gold Base", 0, 600, "0", HintText = "gold a lived-in den keeps hidden before counting its bands - the hoard its bandits do not touch, found by whoever clears and searches it", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public int HideoutGoldBase { get; set; } = 150;

        [SettingPropertyInteger("Hideout Gold Per Band", 0, 480, "0", HintText = "each band that calls the den home adds this much to the hoard it keeps; whatever lies above the kept hoard is spent - on gear for its bands and on their living in town", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public int HideoutGoldPerBand { get; set; } = 120;

        [SettingPropertyFloatingInteger("Hideout Renown", 0.00f, 20.00f, "0.00", HintText = "renown for purging a hideout - the realm hears of it", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutRenown { get; set; } = 5f;

        [SettingPropertyInteger("Hideout Rep Max", 0, 20, "0", HintText = "relation gained with notables right next to the den, fading to zero at the edge of the district", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public int HideoutRepMax { get; set; } = 5;

        [SettingPropertyFloatingInteger("Hideout Rep Radius", 0.00f, 200.00f, "0.00", HintText = "the district: map-distance within which settlements care about the purge", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutRepRadius { get; set; } = 50f;

        [SettingPropertyFloatingInteger("Hideout Search Solo Hours", 0.00f, 96.00f, "0.00", HintText = "searching the den alone takes this long - a lone man turns every bedroll himself", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutSearchSoloHours { get; set; } = 24f;

        [SettingPropertyFloatingInteger("Hideout Search Per Man Hours", 0.00f, 2.00f, "0.00", HintText = "every soldier in the party cuts the search by this many hours", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutSearchPerManHours { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Hideout Search Min Hours", 0.00f, 16.00f, "0.00", HintText = "the search never drops below this many hours - some stones only come up slowly", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutSearchMinHours { get; set; } = 4f;

        [SettingPropertyBool("Hideout Reprisal Enabled", HintText = "nearby bands mass to take their den back while you dig - unless your line scares them off", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public bool HideoutReprisalEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Hideout Reprisal Radius", 0.00f, 160.00f, "0.00", HintText = "map-distance within which bandit parties join the reprisal", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutReprisalRadius { get; set; } = 40f;

        [SettingPropertyFloatingInteger("Hideout Reprisal Flee Odds", 0.00f, 12.00f, "0.00", HintText = "at this strength advantage (yours vs theirs) the reprisal loses its nerve and melts away", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutReprisalFleeOdds { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Hideout Reprisal Hours", 0.00f, 192.00f, "0.00", HintText = "the horde hunts you this long - then gives up and drifts back to its old ways", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutReprisalHours { get; set; } = 48f;

        [SettingPropertyFloatingInteger("Hideout Pursuit Hours", 0.00f, 2.00f, "0.00", HintText = "a reprisal band renews its chase every this many game hours, whatever the game speed (0 = the old every three real seconds)", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutPursuitHours { get; set; } = 0.5f;

        [SettingPropertyBool("Hideout Daily Stash", HintText = "every day a band with a home hideout carries part of its purse back to the den's hoard - outlaws keep their coin at home, so a band beaten in the field carries only its pocket money and a cleared, searched den pays (off = coin is put by only on the rare visits home, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public bool HideoutDailyStash { get; set; } = true;

        [SettingPropertyFloatingInteger("Hideout Daily Stash Share", 0.00f, 1.00f, "0.00", HintText = "with Hideout Daily Stash: share of its purse, after the day's living, a band carries home each day", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public float HideoutDailyStashShare { get; set; } = 0.25f;

        [SettingPropertyBool("Hideout Hoard To Ai Victor", HintText = "a hideout cleared without you: its hoard goes to the victor - the lord's purse, else the party's purse, else the nearest town (off = it stays in the empty den and leaks to the nearest town, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public bool HideoutHoardToAiVictor { get; set; } = true;

        [SettingPropertyBool("Hideout Gold Messages", HintText = "after a hideout fight you are told what coin the bands carried, after the search what the den held - also when there was nothing (off = only the old message when gold is found)", RequireRestart = false)]
        [SettingPropertyGroup("The hideout purge")]
        public bool HideoutGoldMessages { get; set; } = true;

        [SettingPropertyBool("Loot Arrives Worn", HintText = "gear stripped from the fallen comes to you already used", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public bool LootArrivesWorn { get; set; } = true;

        [SettingPropertyFloatingInteger("Loot Wear Base", 0.00f, 180.00f, "0.00", HintText = "the condition of an average piece of loot", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public float LootWearBase { get; set; } = 45f;

        [SettingPropertyFloatingInteger("Loot Wear Spread", 0.00f, 100.00f, "0.00", HintText = "how widely that varies", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public float LootWearSpread { get; set; } = 25f;

        [SettingPropertyBool("Captive Spoils Enabled", HintText = "a man you take captive is stripped at the rope: his whole kit lands in your baggage, battle-worn", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public bool CaptiveSpoilsEnabled { get; set; } = true;

        [SettingPropertyBool("Captive Spoils Include Mounts", HintText = "his horse and harness are seized too", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public bool CaptiveSpoilsIncludeMounts { get; set; } = true;

        [SettingPropertyBool("Captive Rags Preview", HintText = "the party screen shows your captives the way you actually keep them: stripped to rags, not in the full armour you already took (icons stay, only the 3D preview changes)", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public bool CaptiveRagsPreview { get; set; } = true;

        [SettingPropertyBool("Beaten Purse To Victor", HintText = "the victors take the whole purse of a beaten caravan, village cart party or bandit band that has no hero at its head - you, the lords and the bandits alike (until now the game gave the victors only a tenth of a caravan's or villagers' coin and half of a band's, and the rest vanished with the beaten party). The purse is shared among the victors by their part in the battle, just as the game shares its plunder; what no victor can carry (a militia, a patrol, the Others) stays in the beaten purse and, once the beaten party is gone, goes to the party that beat it, else to the coffers of that party's town, castle or village, else of the nearest town (a village cart party's purse goes on by Villager Purse Survives). With Crown Thirds, a realm at war takes a ninth of what its lords - and you, as a vassal - take this way, and of the coin a caravan or village cart party hands you without a fight (it surrenders, you take it captive, or it pays you to let it pass). A party that was not beaten in battle - a band that joins you, a party wiped out on the winning side - keeps the old rule: its purse vanishes with it. Off = the game's tenth and half, the rest vanishes as before", RequireRestart = false)]
        [SettingPropertyGroup("Loot from the field")]
        public bool BeatenPurseToVictor { get; set; } = true;

        [SettingPropertyBool("Battlefield Law Enabled", HintText = "battles you fight yourself: the dead drop their real gear (DTE), Spoils of War steps aside", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool BattlefieldLawEnabled { get; set; } = true;

        [SettingPropertyBool("Loot Arrives Battle Worn", HintText = "loot-screen items from fought battles arrive battle-worn but keep their worth", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LootArrivesBattleWorn { get; set; } = true;

        [SettingPropertyBool("Sim Battle Full Drop", HintText = "auto-resolved battles ignore the hidden per-tier drop multipliers", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SimBattleFullDrop { get; set; } = true;

        [SettingPropertyInteger("Player Loot Share Percent", 0, 132, "0", HintText = "the captain's third: your cut of what YOUR MEN strip from the foes they felled (the rest is theirs, in the army armoury); foes felled by you or your companions are all yours; auto-resolved battles use this share for everything", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public int PlayerLootSharePercent { get; set; } = 33;

        [SettingPropertyBool("Own Kills Loot Whole", HintText = "what you felled is yours: every piece stripped from a foe that you or a companion brought down goes to your loot whole, and from a foe felled by one of your men you take the captain's share (Player Loot Share Percent) - before, your cut was one average taken evenly from every kind of piece, so a single fine piece off your own kill could stay with the men", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool OwnKillsLootWhole { get; set; } = true;

        [SettingPropertyBool("Loot Is Transfer", HintText = "spoils are taken, not copied: whatever the victors of a battle get from a beaten party's armoury is taken out of that armoury - a garrison or a lord's band that lives through a defeat no longer keeps a second copy of the arms and armour the victors carried off (horses already worked this way; off = as before: the survivors keep a copy)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LootIsTransfer { get; set; } = true;

        [SettingPropertyBool("Send Troops One Loot", HintText = "'Send troops' pays once: when your men fight without you and win, the gear of the fallen goes to the army armoury as before, the captain's share of it (Player Loot Share Percent) comes to your loot, and neither the Spoils of War lottery nor the game's own template loot for the same dead comes on top (off = as before: the armoury takes all of it and the lottery pays a second time)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SendTroopsOneLoot { get; set; } = true;

        [SettingPropertyBool("Wreck Salvage Enabled", HintText = "the piece smashed by the killing blow is not lost - it lands in the loot as a wreck to mend at the forge", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool WreckSalvageEnabled { get; set; } = true;

        [SettingPropertyInteger("Loot Min Condition Percent", 0, 12, "0", HintText = "gear battered down to this percent of its worth or less is DESTROYED - it never reaches the loot screen (0 = off)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public int LootMinConditionPercent { get; set; } = 3;

        [SettingPropertyInteger("Legendary Loot Value Floor", 0, 400000, "0", HintText = "weapons worth this much clean (the named blades of the realm) never lie in the common loot sacks (0 = off)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public int LegendaryLootValueFloor { get; set; } = 100000;

        [SettingPropertyBool("Legendary Sweep Lazy", HintText = "the daily sweep of AI armouries checks who owns an armoury only when it holds giant gear or an exotic mount - the same items removed, faster; off = the owner of every armoury is checked first", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LegendarySweepLazy { get; set; } = true;

        [SettingPropertyBool("Spoils Clan Real Soldiers", HintText = "your Spoils of War mercenary company gets no soldiers out of thin air: a founded, reformed, newly hired or re-formed warband starts with its captain alone (no ready-made 50-odd men from the party template, no 20 initial troops, no volunteers from the map, and Banner Kings no longer swaps the captain out of his own warband for a soldier from nowhere) and grows only by real recruitment - notables' volunteers and tavern hirelings, paid from the company's own purse; what you pay Spoils of War to found, reform or hire a warband goes whole into the company's purse instead of partly vanishing (off = Spoils of War as before; the day's log line shows how many men either way)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsClanRealSoldiers { get; set; } = true;

        [SettingPropertyBool("Spoils No Auto Sale", HintText = "no automatic sale from the war stockpile: Spoils of War's quartermaster sold cheap stockpile gear every day - the goods vanished and the town treasury got coin that nobody paid; this stops it whatever the Spoils of War menu says (every Spoils preset turns auto-sell back on) - the gear stays in the stockpile until you take it (the day's log line shows how much was stopped)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsNoAutoSale { get; set; } = true;

        [SettingPropertyBool("Spoils No Free Gold", HintText = "no Spoils of War money out of thin air: no coins on the dead, no baggage-train chest, no lucky chest, ransom or extra gear while collecting (the beaten side's purse already pays the winner); the fence, the quartermaster's salvage and gear given to your mercenary company are paid from the town's coffers above its reserve, never above the market price, and the goods go onto the town's stalls - what the town cannot pay for stays with you; your company's share of its battle loot comes out of its own treasury; the war stockpile takes gear only clean or plundered (off = Spoils of War as before; the day's log line shows how much either way)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsNoFreeGold { get; set; } = true;

        [SettingPropertyBool("Hist Fence Min Old Coin", HintText = "the Spoils of War fence's lowest item worth (Fence Min Item Value) is compared with a piece's worth before the historical repricing, or with today's worth when that is higher - the same in the fence menu, in his offer and in the sale - otherwise he refuses almost every ordinary weapon. The price he pays stays the same", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool HistFenceMinOldCoin { get; set; } = true;

        [SettingPropertyBool("Hist Donate Renown Old Coin", HintText = "renown for gear you give to your Spoils of War company counts each piece sold at its worth before the historical repricing, or at today's worth when that is higher - otherwise it is 20-30 times smaller. The coin paid stays the same", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool HistDonateRenownOldCoin { get; set; } = true;

        [SettingPropertyBool("Spoils Quartermaster Repair", HintText = "the Spoils of War quartermaster's repairs are done by this town's smiths, like every other repair in Armoury: you pay into the town's coffers the smiths' work (with Smith Mend From Market on: its share of the days a master spent making the piece, at the town's day wage; off: a quarter of the worth it has lost), plus the materials they take from this market at its prices - iron (crude iron, scrap from wrecks or ore), wood, leather, linen or wool, more the worse the piece; with no such materials on the market the piece waits; wrecks (Mangled, or worn to a tenth of their worth or less - see Wrecks To Scrap) are not restored here - mend them at a forge with your own materials, or salvage them (off = Spoils of War as before: its price, the coin vanishes, no materials, wrecks restored; the day's log line shows how much either way)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsQuartermasterRepair { get; set; } = true;

        [SettingPropertyBool("Donation Xp Off", HintText = "gear you give away no longer trains anyone: no troop experience for weapons and armour you leave or discard on any screen (the quartermaster perks Giving Hands and Paid in Promise keep only their other half), no skill experience for gear handed to a Spoils of War company leader (horses too), for trophies left on the field or for gear and food given to a town (its security, militia, prosperity and relations still rise), and the Spoils menus no longer promise training; trade skill counts only what you actually sold at that stall, not what you gave away since your last market visit, put on a companion or slaughtered during the trade; on the Spoils of War war stockpile and trophy screens Done no longer asks 'You are discarding items' - Done throws nothing away there: the stockpile keeps what you leave, and trophies wait until you choose Leave, whose hint says how many stay on the field (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool DonationXpOff { get; set; } = true;

        [SettingPropertyBool("Spoils Cancel Keeps", HintText = "Cancel on the Spoils of War screens that say 'take back what you want to keep' (equip a leader, donate gear to your company, donate food, equip the garrison, supply the militia, salvage, donate to the town) leaves everything as it was: all items stay in your baggage and nothing is given away; gear for a company leader who has no party comes back to you instead of vanishing (off = as before: Cancel gave everything away)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsCancelKeeps { get; set; } = true;

        [SettingPropertyBool("Spoils Goods Home", HintText = "gear you give with 'Donate plundered equipment to the town' (Spoils of War) no longer vanishes: it goes into the armoury of that town's garrison, with its wear; wrecks and pieces the garrison's stores cannot book go onto the town's market stalls, unpaid (off = as before: the gear disappears)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsGoodsHome { get; set; } = true;

        [SettingPropertyBool("Spoils Gift No Militia", HintText = "giving gear with 'Donate plundered equipment to the town' (Spoils of War) no longer raises militiamen out of nothing (Spoils of War added militia for every piece given - its Militia bonus per item); the town's security and the notables' regard rise as before, and the menu no longer promises militia (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsGiftNoMilitia { get; set; } = true;

        [SettingPropertyBool("Spoils Remnants Home", HintText = "trophies you leave on the field when you choose Leave after a battle (Spoils of War) are not lost: what your men do not keep for their drill stock is carted to the market of the nearest friendly town or castle, unpaid - abandoned goods (off = as before: they vanish)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsRemnantsHome { get; set; } = true;

        [SettingPropertyBool("Living Economy Sealed", HintText = "BetterEconomy (Living Economy) may not make gold vanish nor conjure goods, men or experience out of nothing: its actions that would pay your gold into nothing (contributions to a town or castle treasury, town and village investments, market access, armory, training camp, paid drill) stay in its menus but are closed and say why, and the Lord wealth realism switch in its ledger stays off; finished armories stop turning market iron into weapons from nothing, AI training camps stop handing out free experience, villages stop their second production from nothing, and the taking of lords' gold and the AI's 5000 market-access fee stop (the fee only once BetterEconomy's own settings shut village trade diversion - until then the fee is the only thing holding it back; off = BetterEconomy as before; the log shows what was stopped)", RequireRestart = false)]
        [SettingPropertyGroup("The living economy")]
        public bool LivingEconomySealed { get; set; } = true;

        [SettingPropertyBool("Bee Player Gifts Real", HintText = "your payments into a town's or castle's treasury in BetterEconomy (Living Economy) become real: the gold goes into the settlement's own purse - the coin its merchants trade with and from which its lord's rent or dues are paid - and conjures no prosperity, goods or readiness out of nothing; a town takes such payments only once its purse holds real coin (Town Purse Regulator), a castle with Castle Purse Enabled. The Living Economy menu of every town and village also gets 'Give gifts to the notables': your gold goes to the notables, shared by their power, and each warms to you as after a generous barter (a few points at most, the dearer the better they already like you; once every few days per notable; not where the place is at war with you). Off = both treasury payments stay closed as with Living Economy Sealed, and there is no gift option", RequireRestart = false)]
        [SettingPropertyGroup("The living economy")]
        public bool BeePlayerGiftsReal { get; set; } = true;

        [SettingPropertyBool("Plague Spares Your Men", HintText = "sickness may weaken your men - it will not kill them: any troop death caused by a disease system is refused for YOUR party (the rest of the world still buries its dead)", RequireRestart = false)]
        [SettingPropertyGroup("Plague shield")]
        public bool PlagueSparesYourMen { get; set; } = true;

        [SettingPropertyInteger("Plague Shield Log Every", 0, 80, "0", HintText = "after the first three saves, log every Nth - a long epidemic must not drown the log", RequireRestart = false)]
        [SettingPropertyGroup("Plague shield")]
        public int PlagueShieldLogEvery { get; set; } = 20;

        [SettingPropertyBool("Desertion Law Enabled", HintText = "men desert only when party morale falls below THEIR tier's threshold (vanilla: below 10 for everyone); a fed and paid party at decent morale loses no one; pay and party-size desertion stay as in vanilla (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public bool DesertionLawEnabled { get; set; } = true;

        [SettingPropertyInteger("Desertion Morale Tier1", 0, 100, "0", HintText = "morale threshold for tier 1 troops - pressed men run first; every tier above lowers the threshold by Desertion Morale Step Per Tier; nobody deserts above this morale", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public int DesertionMoraleTier1 { get; set; } = 25;

        [SettingPropertyInteger("Desertion Morale Step Per Tier", 0, 12, "0", HintText = "with tier 1 at 25 and step 3: tier 2 deserts below 22, tier 3 below 19, tier 4 below 16, tier 5 below 13, tier 6 below 10 (0 = one threshold for all tiers)", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public int DesertionMoraleStepPerTier { get; set; } = 3;

        [SettingPropertyInteger("Desertion Morale Floor", 0, 40, "0", HintText = "no threshold drops below this - even the elite leave once morale is broken", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public int DesertionMoraleFloor { get; set; } = 10;

        [SettingPropertyFloatingInteger("Desertion Percent Per Morale Point", 0.00f, 4.00f, "0.00", HintText = "share of a stack (percent) that deserts per day for every morale point below its threshold", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public float DesertionPercentPerMoralePoint { get; set; } = 1.0f;

        [SettingPropertyInteger("Desertion Daily Cap Percent", 0, 100, "0", HintText = "at most this share of a stack deserts in one day", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public int DesertionDailyCapPercent { get; set; } = 25;

        [SettingPropertyBool("Desertion Law For Ai", HintText = "apply the tiered thresholds to AI parties as well - lords, garrisons and caravans, one rule with yours (183); the Others keep the game's rule. Off = AI keeps vanilla desertion below morale 10", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public bool DesertionLawForAi { get; set; } = true;

        [SettingPropertyBool("Overflow Goes Home", HintText = "men who leave a lord's party or a garrison only because there is no room for them (more men than the party size limit - the game sends a quarter of the excess away each day) go home to the Banner Kings population of a village, the same way as men released by the house budget: a garrison to the villages of its own castle or town, a party to the nearest village of its house, then of its realm; only when no such village exists do they join the outlaw pool as before. Yours too. Men leaving over pay or unpaid wages still go to the woods (off = everyone to the outlaw pool as before)", RequireRestart = false)]
        [SettingPropertyGroup("Desertion")]
        public bool OverflowGoesHome { get; set; } = true;

        [SettingPropertyBool("Unique Gear Law Enabled", HintText = "named heroes' gear (Ramsay, the Hound, the Mountain, Brienne, Renly...) belongs to its owner alone: copies in armouries, packs and on other heroes become same-tier gear of the wearer's own culture, and DTE swaps them on the way into any armoury. A renowned piece taken by the custom of war stays itself in a baggage train (yours or a lord's); worn by anyone but its owner it is still swapped on load", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool UniqueGearLawEnabled { get; set; } = true;

        [SettingPropertyInteger("Min Sell Percent Of Value", 0, 10, "0", HintText = "merchants never pay less than this share of what an item is worth in its present condition (with Sell Price By Condition off: of its clean worth) - scrap is still metal and leather. Only junk ever sinks this low: above the floor the price of worn gear follows its condition and the stall's supply and demand (0 = off)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public int MinSellPercentOfValue { get; set; } = 2;

        [SettingPropertyBool("One Scrap Floor", HintText = "one floor for junk, after the stall's supply and demand: in towns and castles worn-out gear fetches its condition times the stall, never under Min Sell Percent Of Value - and never more than that stall itself asks for the very same piece, so a glutted stall pays little and nobody can buy junk cheap and sell it back at the floor. The glutted market's 5% start steps aside while supply and demand is on. Off = as before: a floor before the stall, the glutted market's 5% start, and the floor again after the stall", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool OneScrapFloor { get; set; } = true;

        [SettingPropertyBool("Bk Trade Penalty Once", HintText = "Banner Kings' trade penalty on arms, armour and saddles counts ONCE (x5, as Banner Kings means it): the price model of the Banner Kings - Realm of Thrones patch calls the game's own penalty, which Banner Kings has already multiplied by 5, and Banner Kings then multiplied the result by 5 again - x25 on every weapon and piece of armour you or the AI sell (x225 in a castle). Only that doubled patch is lifted; Banner Kings' castle, Gladiator and perk effects still apply once. Applied when a session loads; the log line 'Kara handlowa BK' shows the multiplier at every start (off = as before, x25)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool BkTradePenaltyOnce { get; set; } = true;

        [SettingPropertyBool("Sell Price By Condition", HintText = "what a merchant pays for arms, armour and horses follows the piece's condition and quality: Min Sell Percent Of Value and the wholesale price between towns count from what the piece is worth as it is, not from a clean one; when the game's price drops to its 1-denar minimum the true fraction is kept before supply and demand multiplies it; and no town or castle stall pays more for a weapon, a piece of armour, a saddle or a quiver than Sell Cap Percent Of New Ask of what it asks for a new one of the same quality. A wreck fetches pennies, a clean or finer piece more, a legendary one many times more (off = as before: floor and wholesale from the clean worth, no cap)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SellPriceByCondition { get; set; } = true;

        [SettingPropertyInteger("Sell Cap Percent Of New Ask", 0, 40, "0", HintText = "the most a town or castle merchant pays for a weapon, a piece of armour, a saddle or ammunition, as % of what his own stall asks for a NEW one of the same kind and quality - and never more than he charges for its wreck, so buying worn gear or spoilt arrows, putting them right and selling them back in the same town never pays; carrying mended gear to a town that lacks it still pays. Horses and pack animals are not capped (0 = no cap; needs Sell Price By Condition)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public int SellCapPercentOfNewAsk { get; set; } = 10;

        [SettingPropertyBool("Enlisted Soldier No Looting", HintText = "serving in a lord's army: the quartermasters strip the field - one soldier does not pocket the army's loot and gold", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool EnlistedSoldierNoLooting { get; set; } = true;

        [SettingPropertyBool("Lord Third On Total", HintText = "an AI lord's third (and a garrison lord's share) of his men's sale of spare kit is reckoned on the whole visit's takings, not piece by piece - a one-denar piece no longer rounds his share down to nothing (off = per piece, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LordThirdOnTotal { get; set; } = true;

        [SettingPropertyBool("Spoils Bandits To Band", HintText = "Spoils of War's 'bandits raided the camp' event: the stolen piece goes into the packs of the nearest band within your sight - with no band near, nothing is stolen (off = the piece vanishes, as in Spoils of War)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool SpoilsBanditsToBand { get; set; } = true;

        [SettingPropertyBool("Dte Scrap Keep", HintText = "Dynamic Troop Equipment no longer deletes the cheapest gear above its per-category cap in your army armoury (only with Commander's Greed off): the gear stays, and your men sell what they cannot use to the merchants of the next town - horses are not sold and stay in the armoury (off = deleted, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool DteScrapKeep { get; set; } = true;

        [SettingPropertyBool("Town Pays Rewards", HintText = "prisoners sold in a town (also yours at the ransom broker), tournament prizes, siege loot and the captives Banner Kings raiders sell are paid from the town's (a castle's: the lord's) spare money above its merchants' reserve instead of out of thin air - a poor town pays less and you are told how much; the ransom for captive heroes stays as it was. Toll fees (Tollgates perk) come out of the entering caravan's purse (off = all of it out of thin air, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool TownPaysRewards { get; set; } = true;

        [SettingPropertyBool("Casualty Loot From Purse", HintText = "the gold an AI victor takes from the bodies of the fallen comes out of the purse of the beaten men - a third to the lord (or the caravan), the rest to his men - not out of thin air; an empty purse (bandits) gives nothing, and the Others take no coin. When your men lose, the victors strip their purse. Works only with Beaten Purse To Victor and Men Purse Enabled on (off = out of thin air, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool CasualtyLootFromPurse { get; set; } = true;

        [SettingPropertyBool("Upgrade Cost To Purse", HintText = "the gold paid to upgrade troops (by you on the party screen or by the AI) goes to the purse of the party's men - they buy the kit of their new rank in town - not into thin air; a garrison keeps no more than its purse limit (Men Gear Save Days of pay), the rest goes to its town's or castle's coffers; bandits and the Others pay into the coffers of the nearest town (off = into thin air, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool UpgradeCostToPurse { get; set; } = true;

        [SettingPropertyBool("Caravan Capital Real", HintText = "a caravan bought by a lord (Banner Kings) or by you starts with capital taken out of the payment - the rest stays with the town that sold the beasts and carts; supply convoys that do not trade (Dynamic Troop Equipment) start with none. A party disbanded or removed without a battle hands its purse to the head of its owner's house (a notable's caravan - to the notable), else to the nearest town, and its men's purse to the nearest town (off = capital out of thin air, and such purses vanish, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool CaravanCapitalReal { get; set; } = true;

        [SettingPropertyBool("Notable Gold Real", HintText = "a notable's gold above or below what the game keeps him at goes to or comes from the purse of the town he trades in - his own town, or his village's market town - instead of vanishing or appearing; a new notable is set up from that purse. Only the town's spare money above its merchants' reserve is paid out: a town without it pays less, and the notable keeps the power he would have sold. The notables of a new world keep the game's starting gold. Off = out of thin air and into nothing, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool NotableGoldReal { get; set; } = true;

        [SettingPropertyBool("Notable Caravan Capital Real", HintText = "a notable's new caravan starts with capital out of his own purse above 4,500 and the rest from the spare money of the town it starts from (its merchants invest) - less if they have less. The caravans of a new world keep the game's starting capital. Off = capital out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool NotableCaravanCapitalReal { get; set; } = true;

        [SettingPropertyBool("Notable Bk Gift Cut", HintText = "the second 10,000 Banner Kings hands every new notable on top of the game's 10,000 is no longer made out of thin air - a new notable starts with the game's 10,000 only (paid by his town while Notable Gold Real is on). The notables of a new world keep it. Off = Banner Kings adds 10,000 out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool NotableBkGiftCut { get; set; } = true;

        [SettingPropertyBool("Alley Income From Town", HintText = "the 30 gold a day a gang leader earns for each alley he holds in his town is paid from that town's spare money above its merchants' reserve instead of out of thin air - a town without spare money pays nothing that day. Off = out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool AlleyIncomeFromTown { get; set; } = true;

        [SettingPropertyBool("Raid Loot From Village", HintText = "the gold a raider takes for every house burnt in a village (you or the AI) comes out of that village's purse, as much as it holds - an empty village gives no coin; you are told when its purse runs short. Off = out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool RaidLootFromVillage { get; set; } = true;

        [SettingPropertyBool("Garrison No Start Purse", HintText = "a garrison formed after the campaign has begun no longer gets 5,000 out of thin air - the new garrison of a captured castle or town takes over the purse of the garrison it replaces (which used to vanish), any other new garrison starts with an empty purse, and its owner's house fills it from its own coffers with the daily wages, as for any party. The garrisons of a new world keep the game's starting purse. Off = 5,000 out of thin air and the old garrison's purse lost, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool GarrisonNoStartPurse { get; set; } = true;

        [SettingPropertyBool("Tier Income Ai Off", HintText = "AI houses without fiefs outside a realm (minor factions) and AI mercenaries no longer get gold 'for their tier' out of thin air (tier x 80 a day, mercenaries tier x 120) - they live on what they earn and on their contract. Your house is unchanged. Off = out of thin air, as before (mercenaries on a Merc Contract still lose it through Merc Game Contract Ai Off)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool TierIncomeAiOff { get; set; } = true;

        [SettingPropertyBool("Trade Perk Gifts Ai Off", HintText = "the 5,000 denars an AI lord or notable got out of thin air from the Insurance Plans perk (his caravan destroyed) or the Rapid Development perk (his workshop's town taken by an enemy) are no longer paid - nobody would pay them. Your own perks are unchanged. Off = out of thin air for the AI too, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool TradePerkGiftsAiOff { get; set; } = true;

        [SettingPropertyBool("Gentry Purse From Town", HintText = "a new Banner Kings gentry house (a local who takes up a vacant estate) no longer gets 15,000 out of thin air - it starts with nothing (see Gentry Start From Town). The estate passes without a price, as it always did in practice (Banner Kings paid that price to nobody). Off = out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool GentryPurseFromTown { get; set; } = true;

        [SettingPropertyBool("Gentry Start From Town", HintText = "only with Gentry Purse From Town: the new gentry house's 15,000 is paid from the spare money of the town the estate's village trades with (above its merchants' reserve), as much as there is. Off (default) = the new house starts with nothing", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool GentryStartFromTown { get; set; } = false;

        [SettingPropertyBool("Bandit Hero Purse From Hideout", HintText = "a Banner Kings bandit leader no longer gets 10,000 out of thin air - he takes it from his hideout's spare coin (above the hoard kept for whoever clears it), as much as there is. When his band leaves the hideout its loot is no longer turned into coin out of thin air: it stays in the packs and goes to the fences like any band's loot. Off = out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool BanditHeroPurseFromHideout { get; set; } = true;

        [SettingPropertyBool("Feast Town Gets Paid", HintText = "when a Banner Kings feast buys its food and drink from the town market, the town gets only what the host actually paid - a host short of coin no longer makes the town richer by the full price out of thin air. Off = the town gets the full price, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool FeastTownGetsPaid { get; set; } = true;

        [SettingPropertyBool("Pact Cost To Other Realm", HintText = "the gold a ruler (or you) pays in Diplomacy for a non-aggression pact or for peace goes to the treasury of the other realm in the treaty instead of vanishing; if that realm is gone or falls with this very peace, nothing is taken. Off = the gold vanishes, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool PactCostToOtherRealm { get; set; } = true;

        [SettingPropertyBool("Court Shopping Pays Town", HintText = "when a Banner Kings court buys its seasonal goods from a town market, the town gets the price the lord paid for them - before, the lord's gold vanished and the town gave its goods for nothing. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool CourtShoppingPaysTown { get; set; } = true;

        [SettingPropertyBool("Group Compromise Pays Group", HintText = "when a ruler (or you) settles a Banner Kings interest group's demand with a Financial Compromise, the gold goes to the group as Banner Kings says - two thirds to its leader, the rest shared by its other members - instead of vanishing. Without a living leader the members share it all; with nobody to take it, the ruler's seat gets it. Off = the gold vanishes, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool GroupCompromisePaysGroup { get; set; } = true;

        [SettingPropertyBool("Merc Clans Real Soldiers", HintText = "the sellsword clans of the world keep their captains and get no men out of thin air from Banner Kings: every day Banner Kings threw each hero of a hired mercenary clan out of his own warband and put a soldier made from nothing in his place, and it would hand a clan without a contract 3 to 5 free men per warband. With this on the heroes stay, hired men of other stock are still turned one for one into the clan's own troops as Banner Kings does, and Banner Kings adds nobody from nothing. The few recruits a clan without a contract picks up and pays for on the road are the game's own rule and are left as they are. Your Spoils of War company has its own switch. Off = as Banner Kings does", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool MercClansRealSoldiers { get; set; } = true;

