        [SettingPropertyFloatingInteger("Soldier Posture Tier6 Multiplier", 1.00f, 3.00f, "0.00", HintText = "posture pool of tier 6 soldiers as a share of plain RBM (1.7 = 70% more); the tiers between follow a smooth curve and tier 7 goes one step further", RequireRestart = false)]
        [SettingPropertyGroup("Flesh and wind")]
        public float SoldierPostureTier6Multiplier { get; set; } = 1.7f;

        [SettingPropertyBool("Blood Through Armour", HintText = "with RBM a blow that cuts or crushes into mail or plate only shows sweat, even when it went through - now such a blow (30 damage or more) and every killing blow RBM left dry bursts blood from the wound. At most one burst per man every half second and 20 a second on the whole field. Off = RBM's particles only, as before", RequireRestart = false)]
        [SettingPropertyGroup("Flesh and wind")]
        public bool BloodThroughArmour { get; set; } = true;

        [SettingPropertyBool("Ground Blood Pools", HintText = "blood pools spread on the ground a moment after a man falls in battle, killed or knocked out by a blade or an arrow (a crushing blow leaves less blood than a cut, an arrow less than a blade, a head wound more; a man stunned by a mace or club only a small spot), and under dead horses; a small splat lands where a cut, stab or arrow wound of 30 damage or more gets through armour. They stay until you leave the battlefield. Field battles, sieges and hideouts only - not tournaments, the arena, training or sea battles; none in water, on ladders or on siege towers. At most 600 per battle, 20 a second and 3 pools on the same spot. Off = only the blood of the game and other mods, as before", RequireRestart = false)]
        [SettingPropertyGroup("Flesh and wind")]
        public bool GroundBloodPools { get; set; } = true;

        [SettingPropertyBool("Battle Cries And Moans", HintText = "AI formations roar a battle cry when they charge, not only when you order a charge: the captain always, his men by tier, morale and his Leadership; badly wounded men (below 30% health) near you moan now and then, at most three times each. Never the same man over and over: one voice per man every 4 seconds (a battle cry every 20), at most 6 voices a second on the field, none in sea battles or sea raids. Off = the game's own voices only, as before", RequireRestart = false)]
        [SettingPropertyGroup("Flesh and wind")]
        public bool BattleCriesAndMoans { get; set; } = true;

        [SettingPropertyFloatingInteger("Stamina Regen Per Second", 0.00f, 100.00f, "0.00", HintText = "without RBM: points regained each second of easing off (with RBM its own regen rules)", RequireRestart = false)]
