        [SettingPropertyBool("Wounded Flee Battles Only", HintText = "the wounded break and run (Wounded Flee and AI Flee When Near Death) only in real battles on the map - tournament, arena and brawl fighters fight on to the knock-out, as the game itself intends", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
