        [SettingPropertyBool("Broken Men Never Rally", HintText = "a wounded man who breaks (Wounded Flee or AI Flee When Near Death) panics once per battle and runs for good: one scream and one fright, no turning back to brawl with bare fists - RBM no longer talks him back into the fight, and if his flight stalls he is sent off again quietly, at most every 4 seconds. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
        public bool BrokenMenNeverRally { get; set; } = true;

        [SettingPropertyBool("Flee Away From Enemies", HintText = "with Broken Men Never Rally on: in a field battle a broken man runs where the enemy is not - straight away from the foes around him, never across their front, horsemen and you counting double; if you are within 15 metres he always runs away from you; when the enemy is all around, he runs where there are fewest of them, to the edge of the field by a path he can really walk. The game's own way out stays when it is safe and leads away from them. Sieges, sorties, sea battles and hideouts keep the game's way. Off = the game's way, as before", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
        public bool FleeAwayFromEnemies { get; set; } = true;

        [SettingPropertyBool("Commander Tactics", HintText = "in field battles an AI army fights by its commander's Tactics skill, not only by its culture as RBM sets it: below 30 a mob that just charges, from 60 cavalry charges at the front and defenders may form a ring or hold a choke point, from 150 a side of 150 men or more also tries to outflank with its infantry. Your own team's AI is left as it is. Off = RBM's culture tactics only, as before", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
        public bool CommanderTactics { get; set; } = true;

        [SettingPropertyBool("Veterans By Tier", HintText = "AI soldiers fight by their experience on top of RBM: every tier has a floor of combat sense no difficulty setting takes away, tier 5 and above (without a shield) parry, read blows and riposte beyond RBM's caps, recruits hesitate to attack and veterans press harder. RBM's stamina penalties stay. Needs RBM; takes effect from the next game start when switched on. Off = plain RBM, as before", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
        public bool VeteransByTier { get; set; } = true;

        [SettingPropertyFloatingInteger("Auto Parry Full Diff", 0.00f, 100.00f, "0.00", HintText = "your lead IS your chance: each point of skill lead gives (100 / this) % odds per swing, certain at this many points (25 = 4% a point: 13 pts -> 52%, 1 pt -> 4%)", RequireRestart = false)]
        [SettingPropertyGroup("The master's parry")]
