        [SettingPropertyInteger("Noble Horse From Tier", 0, 24, "0", HintText = "from this tier nothing but a noble steed will do", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int NobleHorseFromTier { get; set; } = 6;

        [SettingPropertyBool("Ai Buys Mounts", HintText = "lords restock their stables when they ride into a settlement - the AI keeps its cavalry instead of slowly losing it", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool AiBuysMounts { get; set; } = true;

        [SettingPropertyInteger("Ai Mount Spare Buffer", 0, 10, "0", HintText = "a few head over the count actually waiting to be raised to horse - for losses on the road", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int AiMountSpareBuffer { get; set; } = 2;

        [SettingPropertyFloatingInteger("Ai Mount Purse Share", 0.00f, 1.00f, "0.00", HintText = "he never spends more than this share of his purse on horses in one visit", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public float AiMountPurseShare { get; set; } = 0.15f;

        [SettingPropertyFloatingInteger("Ai Mount Gear Purse Share", 0.00f, 1.00f, "0.00", HintText = "a lord whose house has an arms share (Gear Share Peace / War) buys his horses out of that share, like his arms and armour: at one stop he spends on horses at most this part of what his purse holds above Ai Gear Gold Reserve and never more than the unspent arms share of his house, and what he pays comes off that share. The horses a house buys for its knights leave the same reserve in his purse. Houses without a budget, your own house and mercenary companies go by Ai Mount Purse Share as before (0 = off: every lord goes by Ai Mount Purse Share and knights' horses are bought without the reserve, as before)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public float AiMountGearPurseShare { get; set; } = 0.75f;

        [SettingPropertyInteger("Ai Mount Max Per Visit", 0, 40, "0", HintText = "and never buys more than this many head at one stop - a stable is topped up, not a herd bought", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int AiMountMaxPerVisit { get; set; } = 10;

        [SettingPropertyFloatingInteger("Ai Mount Buy Cooldown Days", 0.00f, 16.00f, "0.00", HintText = "days before that same party restocks again: without a pause the AI resold the horses as ordinary goods and bought them back, pumping millions through the market", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public float AiMountBuyCooldownDays { get; set; } = 4f;

        [SettingPropertyBool("Ai Mount Breeder Fallback", HintText = "market empty? he orders from the local breeder instead of riding away horseless", RequireRestart = false)]
