        public bool AiMountBreederFallback { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Mount Breeder Markup", 0.00f, 5.20f, "0.00", HintText = "the breeder charges this much over the plain worth for the trouble", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public float AiMountBreederMarkup { get; set; } = 1.3f;

        [SettingPropertyBool("Horses At Market Price", HintText = "a horse costs what the local town market asks for it: a lord ordering from the village breeders pays them the town's market price for that horse instead of a flat markup over its worth, and - only with Recruits Own Horse off - a mounted recruit is charged his own horse at that market price instead of the game's flat 150 or 500 (with Historical Recruit Cost on) (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool HorsesAtMarketPrice { get; set; } = true;

        [SettingPropertyBool("Merc Horse From Shelf", HintText = "only with Recruits Own Horse off: a mounted hireling from a tavern costs a horse only if the town's market has one of the same breed on its shelf (the same horse, or one of the same kind and grade): that horse leaves the shelf with him and the town is paid for it what the hirer is charged for it (its market price, with the hirer's own discounts or surcharges). With no such horse he rides in on his own and costs only his days of pay; if more men are hired than horses stand on the shelf, what was charged for the missing horses goes back to the purse. Needs Historical Recruit Cost and Horses At Market Price (off = the market price of his horse is charged and paid to the town though no horse leaves the shelf)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool MercHorseFromShelf { get; set; } = true;

        [SettingPropertyBool("Recruits Own Horse", HintText = "a mounted recruit - a hireling from a tavern or a volunteer from a notable, yours and the AI's - rides in on his own horse: taking him on costs his prest money (days of his pay) and nothing for the horse, and no horse leaves the town's shelf; a man who keeps a horse asks for more pay instead (Mounted Wage Premium). Needs Historical Recruit Cost (off = the horse is charged at recruitment as before: Horses At Market Price, Merc Horse From Shelf)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool RecruitsOwnHorse { get; set; } = true;

        [SettingPropertyBool("Mounted Wage Premium", HintText = "a soldier who keeps his own horse wants more pay: every mounted man in a lord's party (yours too) and in a garrison draws the wage of his tier times Mounted Wage Factor - in Edward III's armies of 1346 a mounted archer had 6 pence a day, an archer on foot 3. The pay goes the usual way (to the men's purses, a garrison's to its town) and his prest money follows his pay; caravan guards are paid as before (off = a rider costs what a footman of his tier costs)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool MountedWagePremium { get; set; } = true;

        [SettingPropertyFloatingInteger("Mounted Wage Factor", 0.00f, 6.00f, "0.00", HintText = "how much more a mounted soldier is paid than a footman of the same tier: 1.5 puts a tier 4 rider at 12 pence a day like a man-at-arms and a tier 6 knight at 26 like a knight's 24 (2.0 = the 1346 ratio of mounted to foot archer, 1.0 = no premium)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public float MountedWageFactor { get; set; } = 1.5f;

        [SettingPropertyInteger("Ai Mount Market Share Percent", 0, 100, "0", HintText = "a lord may take at most this share of the horses on a town's shelf in one visit - the rest he orders from the breeder, so markets are not stripped bare (Jeff 15.09: no horses to buy anywhere); the last few head always stay (Ai Mount Shelf Floor). Was 25 until 14.10", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int AiMountMarketSharePercent { get; set; } = 40;

        [SettingPropertyInteger("Ai Mount Shelf Floor", 0, 16, "0", HintText = "and never buys the last few: this many head always stay on the shelf for other buyers", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int AiMountShelfFloor { get; set; } = 4;

        [SettingPropertyInteger("Ai Saddle Shelf Floor", 0, 10, "0", HintText = "the same for saddles: an AI lord buying harness for riders who have a horse and no saddle leaves this many pieces of fitting horse harness on a town's shelf for other buyers (horses keep their own floor above)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public int AiSaddleShelfFloor { get; set; } = 1;

        [SettingPropertyBool("Ai Upgrade Horse To Armory", HintText = "the horse an AI lord or garrison pays for a man's upgrade to a mounted troop goes into that party's armoury for the new rider, just as yours does, instead of vanishing. Always on while Troops Fight With Own Kit Only is on - a rider there rides only a horse from the stores. Takes effect at once (off, with own kit only also off = the AI horse is gone on upgrade as before)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool AiUpgradeHorseToArmory { get; set; } = true;

        [SettingPropertyBool("Ai Free Armory Horses First", HintText = "at an AI upgrade to a mounted troop (and when Realm of Thrones hands a Dothraki party a rider) a horse lying free in the party's armoury - more horses of that kind there than riders entitled to them - is used first, before one is taken from the baggage or bought. Off by default: with Troops Fight With Own Kit Only lords already move spare armoury horses back to the baggage at every stop, where upgrades use them. Takes effect at once", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool AiFreeArmoryHorsesFirst { get; set; } = false;

        [SettingPropertyBool("Rider Needs Harness", HintText = "a mounted soldier needs a saddle as well as a horse - any horse harness will do: raising a footman to a rider takes a spare harness from the baggage or the troop armoury (yours and the AI's alike), in your battles a rider whose horse has no harness fights on foot, AI lords buy the cheapest saddle for every rider who has a horse and none, a veteran takes his saddle along to the tavern and a mounted mercenary brings it back; heroes are not checked; works with Cavalry Needs Mounts and Troops Fight With Own Kit Only (off = a horse alone is enough, as before)", RequireRestart = false)]
        [SettingPropertyGroup("A knight needs a horse")]
        public bool RiderNeedsHarness { get; set; } = true;

        [SettingPropertyBool("Long Year Enabled", HintText = "stretch the year so the world stops racing: children grow, lords age and seasons turn at a pace a long campaign can live with", RequireRestart = false)]
        [SettingPropertyGroup("The turning year")]
        public bool LongYearEnabled { get; set; } = true;

        [SettingPropertyInteger("Weeks Per Season", 0, 52, "0", HintText = "weeks in a season (vanilla 3 = an 84-day year; 13 = a 364-day year, one day is one day). SET IT BEFORE STARTING A CAMPAIGN and leave it alone afterwards", RequireRestart = false)]
        [SettingPropertyGroup("The turning year")]
        public int WeeksPerSeason { get; set; } = 13;

        [SettingPropertyBool("March Pace Enabled", HintText = "a column moves at the pace of its slowest man: any soldier or prisoner on foot holds the whole party to walking speed", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool MarchPaceEnabled { get; set; } = true;

        [SettingPropertyInteger("World Pace Percent", 0, 200, "0", HintText = "base map speed of EVERY party as a percent of the game's own (100 or more = unchanged, it never speeds the world up) - the whole world travels at one slower rhythm; terrain, cargo, sleep and the column cap still count on top of it", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WorldPacePercent { get; set; } = 50;

        [SettingPropertyBool("Terrain Ease Enabled", HintText = "replace the game's percentage terrain and night penalties with the flat map-speed penalties below (the vanilla share is shown undone in the tooltip, then ours applied)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool TerrainEaseEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Forest Speed Penalty", 0.00f, 1.00f, "0.00", HintText = "flat speed lost in forest (vanilla: 30% of your speed)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float ForestSpeedPenalty { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Desert Speed Penalty", 0.00f, 1.00f, "0.00", HintText = "flat speed lost in desert and dunes (vanilla: 10%)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float DesertSpeedPenalty { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("Snow Speed Penalty", 0.00f, 1.00f, "0.00", HintText = "flat speed lost in snowfall or blizzard (vanilla: 10%)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SnowSpeedPenalty { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("Swamp Speed Penalty", 0.00f, 1.20f, "0.00", HintText = "flat speed lost crossing swamp and marshland (vanilla: nothing at all)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SwampSpeedPenalty { get; set; } = 0.30f;

        [SettingPropertyFloatingInteger("Ford Speed Penalty", 0.00f, 2.00f, "0.00", HintText = "flat speed lost fording rivers and crossing bridges (vanilla: 30%)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float FordSpeedPenalty { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Night Speed Penalty", 0.00f, 2.00f, "0.00", HintText = "flat speed lost at night on land (vanilla: 25%)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float NightSpeedPenalty { get; set; } = 0.5f;

        [SettingPropertyBool("Ammo Tracer Enabled", HintText = "diagnostic: log every change in the troop armoury's stock of arrows, bolts and harnesses, with time and place", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool AmmoTracerEnabled { get; set; } = true;

        [SettingPropertyBool("Plague Watch Enabled", HintText = "a daily word when YOU are the one who is ill - the disease mod tells the player nothing outside a town hospital", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool PlagueWatchEnabled { get; set; } = true;

        [SettingPropertyBool("Influence Watch Enabled", HintText = "diagnostic: log the full daily breakdown of your clan influence - the game itself never shows it anywhere", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool InfluenceWatchEnabled { get; set; } = true;

        [SettingPropertyBool("Speed Audit Enabled", HintText = "once a day the full speed breakdown of your party is written to Armoury.log (before the marching-column cap and sleep debt)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SpeedAuditEnabled { get; set; } = true;

        [SettingPropertyBool("World Measure Log", HintText = "once a day Armoury.log measures the world: how many km a day the AI lords' hosts really march (median and 90th percentile, big hosts, army leaders and all-mounted parties, the world pace in force) and how many days of food every town and castle has left, the North apart - log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WorldMeasureLog { get; set; } = true;

        [SettingPropertyInteger("Siege Pace Percent", 0, 200, "0", HintText = "siege engine construction speed - 50% makes sieges last twice as long, so starving a fortress out matters again", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegePacePercent { get; set; } = 50;

        [SettingPropertyBool("Siege Sickness Enabled", HintText = "camp fever: long sieges breed dysentery - the sick go down as wounded, some die; medicine is the shield", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeSicknessEnabled { get; set; } = true;

        [SettingPropertyInteger("Siege Sickness Incubation Days", 0, 36, "0", HintText = "clean-camp grace period before the fever wakes", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSicknessIncubationDays { get; set; } = 9;

        [SettingPropertyFloatingInteger("Siege Sickness Base Percent", 0.00f, 2.40f, "0.00", HintText = "daily share of healthy men falling sick once the fever wakes (before ramp, crowding and medicine)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeSicknessBasePercent { get; set; } = 0.6f;

        [SettingPropertyInteger("Siege Sickness Ramp Percent", 0, 60, "0", HintText = "the daily rate grows by this much for every day past incubation - time is a weapon", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSicknessRampPercent { get; set; } = 15;

        [SettingPropertyInteger("Siege Sickness Defender Factor", 0, 160, "0", HintText = "defenders behind walls catch this share of the besiegers' rate; famine doubles it", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSicknessDefenderFactor { get; set; } = 40;

        [SettingPropertyInteger("Siege Sickness Death Share", 0, 40, "0", HintText = "share of the sick who die instead of joining the wounded (Siege Medic halves this)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSicknessDeathShare { get; set; } = 10;

        [SettingPropertyInteger("Siege Sickness Medicine Max", 0, 200, "0", HintText = "ceiling of the surgeon's risk reduction (0.25% per Medicine point up to this cap)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSicknessMedicineMax { get; set; } = 50;

        [SettingPropertyBool("Siege Walls Hold Until Breached", HintText = "AI lords never storm a town or castle with ladders alone: first a battering ram and a siege tower must stand ready, or their engines must batter a breach in the walls - and even then only when their strength beats what the walls make of the defenders. The walls count in full however long the siege lasts and weaken only as engines batter them down (the game let them count for less every hour after the fourth day and after the sixth for nothing). You decide your own assaults as before - with ladders as soon as the camp is ready. Off = the game's waning patience", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeWallsHoldUntilBreached { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Capital Walls Factor", 1.00f, 2.00f, "0.00", HintText = "the walls of a realm's capital count this many times more in every assault and in the decision to storm them - the king's guard and his keep within the walls (one step of wall level is worth 17-20% in the game). The same for AI lords and for you, attacking or defending. 1 = like any other town", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeCapitalWallsFactor { get; set; } = 1.25f;

        [SettingPropertyBool("Siege Defender Engines On Walls", HintText = "the defenders' ballistas and catapults on the walls (from the siege workshop or built during the siege) make the walls stronger in an assault just as the besiegers' engines make them weaker (+8% each, +12% for a fire engine) - until the besiegers' engines smash them. Off = only the besiegers' engines count, as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeDefenderEnginesOnWalls { get; set; } = true;

        [SettingPropertyBool("Siege Ai Breach When Walls Hold", HintText = "an AI siege camp that has its ram and siege tower ready and still cannot hope to take the walls turns to battering them down with trebuchets (with Realistic Battle Mod only trebuchets strike walls - catapults and onagers hit engines and men). Off = the AI keeps the plan it drew at the start of the siege", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeAiBreachWhenWallsHold { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Assault Repel Loss", 0.00f, 0.50f, "0.00", HintText = "an AI assault on manned walls breaks off when the stormers have lost this share of their men (wounded, killed and routed) - each assault draws its own breaking point within Siege Assault Repel Spread of it. The besiegers fall back to their camp and the siege goes on. 0 = assaults go on until one side is gone, as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeAssaultRepelLoss { get; set; } = 0.22f;

        [SettingPropertyFloatingInteger("Siege Assault Repel Spread", 0.00f, 0.10f, "0.00", HintText = "each assault's breaking point lies up to this far either side of Siege Assault Repel Loss (0.22 +- 0.05 = 17 to 27% of the men) - every army has its own endurance; with Siege Attacker Morale its morale decides where", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeAssaultRepelSpread { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Siege Repel Pause Days", 1.00f, 28.00f, "0.0", HintText = "after a repelled assault the besiegers wait about this many days before trying again - longer when their morale is low, when few of them are left against the defenders and when the place is worth little against the army's pay; shorter otherwise (from 3/7 to 4 times this)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeRepelPauseDays { get; set; } = 7f;

        [SettingPropertyBool("Siege Relief From Walls", HintText = "when a relief force joins the defence of a town or castle under assault, the defenders keep fighting from the walls as long as the men of the fortress are most of the defence (Siege Relief Walls Share) - the game turned such a battle into a fight in the open field. Your own fortresses too. Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeReliefFromWalls { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Relief Walls Share", 0.00f, 1.00f, "0.00", HintText = "with Siege Relief From Walls: the share of the defence that must be men of the fortress (garrison, militia, lords inside the walls) for the battle to be fought from the walls", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeReliefWallsShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Siege Besieger Prep Percent", 10, 100, "0", HintText = "besiegers - AI lords and you alike - build their siege camp and engines at this percent of the speed set by Siege Pace Percent (towns and capitals still take longer by Siege Town / Capital Prep Factor). 100 = Siege Pace Percent alone (a town camp of 3000 men has its camp, ram and tower in about 8 days); 50 = twice as long", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeBesiegerPrepPercent { get; set; } = 100;

        [SettingPropertyFloatingInteger("Siege Town Prep Factor", 1.00f, 4.00f, "0.00", HintText = "preparing the siege of a town takes this many times longer than of a castle", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeTownPrepFactor { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Siege Capital Prep Factor", 1.00f, 4.00f, "0.00", HintText = "preparing the siege of a realm's capital takes this many times longer than of a castle", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeCapitalPrepFactor { get; set; } = 2.5f;

        [SettingPropertyBool("Siege Walls Any Garrison", HintText = "the walls fight for any garrison, however small: in every assault - AI lords' and your own auto-resolved ones - a handful of men on the walls fights from them, where the game let only more than 100 men in a town or 30 in a castle do so and below that fought the assault as a battle in the open field. Also counts for breaking off an AI assault (Siege Assault Repel Loss) - for a small garrison only while at least a quarter of the defenders who began the assault still stand on the walls - and for a relief force fighting from the walls. Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeWallsAnyGarrison { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Ladder Walls Factor", 1.00f, 4.00f, "0.00", HintText = "an assault with ladders alone on whole walls - no battering ram, no siege tower, no breach - meets walls this many times stronger and the stormers pay dearly for every rung; with one of the two engines, half of it. A ram and a tower bring the walls back to what they are, a breach brings them down. 1 = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeLadderWallsFactor { get; set; } = 2f;

        [SettingPropertyBool("Siege Breach One Section", HintText = "one wall section battered down is a breach: the walls count for a quarter of their level, as the game does only once every section is down - in assaults, in AI lords' decisions to storm and in the renown of the battle. Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeBreachOneSection { get; set; } = true;

        [SettingPropertyBool("Siege Defender Morale", HintText = "the defenders' will to hold multiplies the strength of their walls in an assault: starving -25, food for under a week down to -10, for four weeks or more +10; the town's loyalty -20 to +20; unpaid garrison wages down to -20; a relief force on its way +7 (+15 when it has half the besiegers' strength); battered walls down to -15. Morale starts at 50: at 50 the walls count as they are, at 100 they count 1.67 times, at 0 a third. Off = the walls alone", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeDefenderMorale { get; set; } = true;

        [SettingPropertyBool("Siege Attacker Morale", HintText = "the stormers' state tells in an assault: a camp short of food (down to -10), the sick and wounded lying in camp - camp fever and earlier assaults (down to -15) - and assaults already repelled at these walls (-8 each, down to -24) cut their blows by as many percent; with their morale they set where within Siege Assault Repel Spread an AI assault breaks off - low morale gives up early, high morale holds on longer. Off = only the game's own morale and a random breaking point", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeAttackerMorale { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Machines Front", 0.00f, 1.00f, "0.00", HintText = "a battering ram and a siege tower open a gate and a bridge: this share of the assault is fought as in the open field, where the numbers of both sides count (half of it with one of the two engines). 0 = through the walls only, as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeMachinesFront { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Siege Breach Front", 0.00f, 1.00f, "0.00", HintText = "a breach lets the stormers run in: this share of the assault is fought as in the open field, where numbers count and the defenders keep only what a breach leaves of their walls - the walls' advantage all but vanishes and men and morale decide. 0 = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeBreachFront { get; set; } = 0.75f;

        [SettingPropertyBool("Siege Ai Trebuchets", HintText = "AI lords besieging a town or a realm's capital build trebuchets from the start - the only engines that batter walls with Realistic Battle Mod - with a second crew, alongside the battering ram and siege tower instead of after them. A castle siege goes as before unless the camp still has no ram and tower Siege Trebuchet Castle Days after its siege camp stood ready - then it turns to trebuchets the same way. Off = the AI draws its siege plan by chance and builds one engine at a time, as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeAiTrebuchets { get; set; } = true;

        [SettingPropertyInteger("Siege Trebuchet Castle Days", 0, 60, "0", HintText = "with Siege Ai Trebuchets: days after the siege camp stands ready that an AI camp before a castle may go without both a ram and a siege tower before it turns to trebuchets (a camp of 1000 men has both in about 9 days)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeTrebuchetCastleDays { get; set; } = 10;

        [SettingPropertyBool("Siege Starvation", HintText = "a besieged town or castle gets no food from outside: its food stock can only fall. Once it is empty the garrison and militia die of hunger every day (Siege Starve Loss Percent, the wounded first) and a handful left (under Siege Surrender Share of the men at the start of the siege or under Siege Surrender Men) lays down its arms to the besiegers, who then take the empty fortress as the game does. Not when lords with their men still hold the walls, not to a camp weaker than what is left, never to a siege you lead (you storm it yourself). Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeStarvation { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Starve Loss Percent", 0.00f, 20.00f, "0.0", HintText = "with Siege Starvation: share of the garrison and militia that dies of hunger every day once the food stock of a besieged fortress is empty (5 = half in two weeks, a tenth left after about six weeks)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeStarveLossPercent { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Siege Surrender Share", 0.00f, 0.50f, "0.00", HintText = "with Siege Starvation: a starving fortress surrenders when fewer men than this share of its garrison and militia at the start of the siege are left", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeSurrenderShare { get; set; } = 0.1f;

        [SettingPropertyInteger("Siege Surrender Men", 0, 200, "0", HintText = "with Siege Starvation: a starving fortress surrenders when fewer men than this are left in its garrison and militia, whatever it started with", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeSurrenderMen { get; set; } = 20;

        [SettingPropertyBool("Siege Ladder Overwhelm", HintText = "after a long siege (Siege Ladder Min Days) an AI host at least Siege Ladder Min Ratio times stronger than the defenders storms the walls even without a ram and a siege tower - with ladders, paying dearly in the assault. Off = AI lords storm only with a ram and a tower or through a breach", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeLadderOverwhelm { get; set; } = true;

        [SettingPropertyInteger("Siege Ladder Min Days", 0, 364, "0", HintText = "with Siege Ladder Overwhelm: days the siege must have lasted (three weeks)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int SiegeLadderMinDays { get; set; } = 21;

        [SettingPropertyFloatingInteger("Siege Ladder Min Ratio", 2.00f, 20.00f, "0.0", HintText = "with Siege Ladder Overwhelm: how many times stronger than the defenders the besiegers must be (the game asks three to one to begin a siege)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float SiegeLadderMinRatio { get; set; } = 4f;

        [SettingPropertyBool("Siege Engines In Progress Dont Hold", HintText = "AI lords whose battering ram and siege tower stand ready (or whose engines have battered a breach) storm the walls without waiting for the trebuchets still being built - the game held every assault while any engine was half done, so a camp building trebuchets never stormed. Also lets Siege Ladder Overwhelm work when no engine is built at all (the game never storms without one). Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeEnginesInProgressDontHold { get; set; } = true;

        [SettingPropertyBool("Siege Assault Runs To End", HintText = "an AI lord who has stormed a fortress fights the assault to its end: he no longer drops the siege halfway through the battle for another goal, and Strategic Campaign AI does not lift it while the battle runs - a relief force still joins the battle. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeAssaultRunsToEnd { get; set; } = true;

        [SettingPropertyBool("Siege Ai Trebuchets Hit Walls", HintText = "AI trebuchets aim at the walls while any stretch of wall still stands - the game rolled between the walls and the defenders' engines, and walls were almost never hit; other engines still choose as in the game. Your own camp is unchanged. Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeAiTrebuchetsHitWalls { get; set; } = true;

        [SettingPropertyBool("Siege Trebuchet Early", HintText = "AI lords besieging a town or a realm's capital start their first trebuchet on the first day of the siege, while the siege camp is still being prepared, instead of waiting for the camp to stand ready (castle sieges as before). A trebuchet takes as long to build before a town or a capital as before a castle - the longer preparations of a large fortress (Siege Town / Capital Prep Factor) still slow the camp, the battering ram and the siege tower - for AI lords and for you alike. Once a stretch of wall is battered down, an AI camp may storm through the breach without waiting for engines still being built, as readily as an assault with ladders. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeTrebuchetEarly { get; set; } = true;

        [SettingPropertyBool("Siege Walls Log", HintText = "writes log lines about these siege rules: a daily summary, each assault held back by the walls, each repelled assault with the pause before the next, each assault joined by a relief force, each siege camp slowed (log only - nothing in the game changes)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SiegeWallsLog { get; set; } = true;

        [SettingPropertyBool("Single Winter Source", HintText = "one source of winter: our Winter Bite alone cuts harvests and feeds armies more; Better Economy seasons no longer cut harvests, raise food prices or slow caravans on top of it", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool SingleWinterSource { get; set; } = true;

        [SettingPropertyBool("Winter Bite Enabled", HintText = "winter with teeth: armies eat more, villages yield less, town granaries drain faster - the north bites hardest", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WinterBiteEnabled { get; set; } = true;

        [SettingPropertyInteger("Winter Party Food Bonus Percent", 0, 200, "0", HintText = "extra food a party consumes in winter (scaled by how far north it stands)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WinterPartyFoodBonusPercent { get; set; } = 50;

        [SettingPropertyInteger("Winter Village Output Cut Percent", 0, 200, "0", HintText = "village production lost in winter - food prices rise on their own as supply dries up", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WinterVillageOutputCutPercent { get; set; } = 50;

        [SettingPropertyFloatingInteger("Winter Town Appetite Per1000", 0.00f, 2.00f, "0.00", HintText = "extra daily food-stock drain per 1000 town prosperity in winter", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float WinterTownAppetitePer1000 { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Autumn Stock Multiplier", 0.00f, 8.00f, "0.00", HintText = "in autumn the AI supply cap (BkSupplyDaysCap) is multiplied by this - stock up or starve", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float AutumnStockMultiplier { get; set; } = 2f;

        [SettingPropertyInteger("North Gradient Percent", 0, 100, "0", HintText = "how much harder winter bites in the far north (and softer in Dorne)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int NorthGradientPercent { get; set; } = 25;

        [SettingPropertyBool("Winter By Realm", HintText = "winter bites by realm: the Summer Isles know no winter, the warm south (Dorne, Qarth, Slaver's Bay, Lys, Tyrosh, Myr, Volantis, Valyria) feels it at Winter Warm Realm Factor, the rest of the world in full - harvests, granaries and the food of armies alike. A village keeps the climate of its region (a Dornish village taken by the Reach stays Dornish), an army that of the land it stands on. Off = the same winter everywhere, only the north gradient", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WinterByRealm { get; set; } = true;

        [SettingPropertyFloatingInteger("Winter Warm Realm Factor", 0.00f, 1.00f, "0.00", HintText = "with Winter By Realm: how hard winter bites in the warm south compared with the rest of the world (0.4 = Dorne loses about 15% of its harvest instead of about 38%)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float WinterWarmRealmFactor { get; set; } = 0.4f;

        [SettingPropertyBool("Winter Horses Eat", HintText = "in winter horses and pack animals cannot graze and eat fodder out of the party's food: every mounted soldier's horse and every animal in the baggage (Banner Kings feed rates, prisoners have no horses) times Winter Horse Feed Share, times the winter of the realm - not on the steppe, where they still graze; in desert, snow and blizzard only when Banner Kings' own animal feed is not already counted there (it is not when another mod replaces the party food model)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WinterHorsesEat { get; set; } = true;

        [SettingPropertyFloatingInteger("Winter Horse Feed Share", 0.00f, 1.00f, "0.00", HintText = "with Winter Horses Eat: the share of an animal's full Banner Kings feed eaten in winter (horse 0.25, warhorse 0.5, pack animal 0.15 food a day; 0.5 = a horse eats as much as about 2.5 men)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float WinterHorseFeedShare { get; set; } = 0.5f;

        [SettingPropertyBool("Scorched Earth Enabled", HintText = "war leaves scars: enemy armies forage villages on the march, and plundered villages heal slowly (with Devastation Enabled the march drives out a share of the countryside's people instead of taking hearths, and they come home in time)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool ScorchedEarthEnabled { get; set; } = true;

        [SettingPropertyBool("Scorched Earth Fast Scan", HintText = "foraging armies look at villages within reach before asking who is at war with whom - the same villages are foraged, found faster; off = the old order", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool ScorchedEarthFastScan { get; set; } = true;

        [SettingPropertyInteger("Forage Min Men", 0, 400, "0", HintText = "armies at least this large live off enemy land", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int ForageMinMen { get; set; } = 100;

        [SettingPropertyFloatingInteger("Forage Radius", 0.00f, 12.00f, "0.00", HintText = "map range within which a passing army drains a hostile village", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float ForageRadius { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Forage Hearth Per Day", 0.00f, 3.20f, "0.00", HintText = "hearths a 500-man army drains per day (scales with army size) - used only with Devastation Enabled off, with it on see Devastation Per Forager Day", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float ForageHearthPerDay { get; set; } = 0.8f;

        [SettingPropertyInteger("Forage Floor", 0, 100, "0", HintText = "marching armies can never drain a village below this - true ruin takes a real raid - used only with Devastation Enabled off, with it on the limit is Devastation Max Percent", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int ForageFloor { get; set; } = 25;

        [SettingPropertyInteger("Scar Threshold Hearth", 0, 600, "0", HintText = "below this many hearths a village counts as scarred and heals slowly; works only with Natural Growth Enabled off - natural growth has no fast regrowth left to slow", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int ScarThresholdHearth { get; set; } = 150;

        [SettingPropertyInteger("Scar Regen Percent", 0, 100, "0", HintText = "share of normal hearth growth a scarred village keeps (vanilla springs back at +4/day); works only with Natural Growth Enabled off", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int ScarRegenPercent { get; set; } = 25;

        [SettingPropertyInteger("Refugee Floor Hearth", 0, 160, "0", HintText = "below this the refugees trickle home (+0.5/day flat) - regions never die for good - used only with Devastation Enabled off, with it on the refugees of a raid come home from the people ledger within Refugee Return Days", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int RefugeeFloorHearth { get; set; } = 40;

        [SettingPropertyBool("Forage From Village Stock", HintText = "an army living off enemy land takes its food from the village's own stores - grain first, then any other food; nothing appears from nowhere, and a village with empty stores feeds no one (off = the old rule: grain from nowhere)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool ForageFromVillageStock { get; set; } = true;

        [SettingPropertyBool("Hideout Boss From Own Men", HintText = "when the game puts a chief into a spotted hideout, he is the best man of the chief's own band raised to lead it, not a man from nowhere; a band with no men gets no chief (off = the game adds him from nowhere)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool HideoutBossFromOwnMen { get; set; } = true;

        [SettingPropertyBool("Enlisted Pay From Lord", HintText = "while you serve in a lord's army (Realm of Thrones enlistment), your company's pay comes once a day from that lord's purse, each hero his own wage - Realm of Thrones paid every hero of your party your own wage, from nowhere; a lord with an empty purse pays what he has (off = Realm of Thrones pay)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool EnlistedPayFromLord { get; set; } = true;

        [SettingPropertyBool("Wages Due Enabled", HintText = "unpaid wages: vanilla already cuts morale - we add desertion, the best-paid men first", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WagesDueEnabled { get; set; } = true;

        [SettingPropertyInteger("Wages Grace Days", 0, 10, "0", HintText = "days of unpaid wages the men will stomach before walking", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WagesGraceDays { get; set; } = 2;

        [SettingPropertyFloatingInteger("Wages Desert Percent Per Day", 0.00f, 2.00f, "0.00", HintText = "share of the party deserting per day past grace, growing with every unpaid day (AI the same since 183 - War Ledger Ai Half)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float WagesDesertPercentPerDay { get; set; } = 0.5f;

        [SettingPropertyInteger("Wages Desert Max Days", 0, 32, "0", HintText = "ceiling on that growth - without it a debt left unpaid for weeks bleeds a tenth of the army every single day", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WagesDesertMaxDays { get; set; } = 8;

        [SettingPropertyBool("War Ledger Ai Half", HintText = "AI parties lose men over unpaid wages at half the rate (the old rule); off = the same rate as yours (183 - with the house budget unpaid wages are rare among the AI)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WarLedgerAiHalf { get; set; } = false;

        [SettingPropertyInteger("War Ledger Min Men", 0, 120, "0", HintText = "unpaid wages never take a party below this many men (a banneret's retinue) - it still loses the men above it; 0 = no floor", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int WarLedgerMinMen { get; set; } = 30;

        [SettingPropertyBool("War Ledger Min Men Player", HintText = "the floor of War Ledger Min Men holds for your own party and your house's parties too (one rule); off = only for the AI", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WarLedgerMinMenPlayer { get; set; } = true;

        [SettingPropertyBool("War Ledger To Outlaws", HintText = "men who walk off over unpaid wages join the outlaw pool of the region (and the people ledger) instead of vanishing - needs Outlaw Law enabled, without it they still vanish", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool WarLedgerToOutlaws { get; set; } = true;

        [SettingPropertyBool("March Pace Ai Too", HintText = "the same law binds lords, bandits and patrols (villagers and caravans keep their own pace either way)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool MarchPaceAiToo { get; set; } = true;

        [SettingPropertyFloatingInteger("March Foot Pace", 0.00f, 16.00f, "0.00", HintText = "map speed cap while anyone walks - footmen without a spare mount, or prisoners on the rope", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MarchFootPace { get; set; } = 4.0f;

        [SettingPropertyFloatingInteger("March Train Pace", 0.00f, 16.80f, "0.00", HintText = "map speed cap for an all-riding party that still drags a baggage train (pack animals, livestock)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MarchTrainPace { get; set; } = 4.2f;

        [SettingPropertyFloatingInteger("March Foot Rider Pace", 0.00f, 20.00f, "0.00", HintText = "map speed cap when footmen ride spare horses - a man in the saddle is not a horseman born", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MarchFootRiderPace { get; set; } = 5.0f;

        [SettingPropertyFloatingInteger("March Rider Pace", 0.00f, 26.00f, "0.00", HintText = "map speed cap for a clean column of riders - every man horsed, no train", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MarchRiderPace { get; set; } = 6.5f;

        [SettingPropertyFloatingInteger("March Pack Allowance", 0.00f, 1.00f, "0.00", HintText = "this many pack animals PER MAN count as field supply, not a train (0.25 = a mule per four men rides free)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MarchPackAllowance { get; set; } = 0.25f;

        [SettingPropertyBool("Map Road Speed Bonus", HintText = "on the painted roads of the Realm of Thrones map every land party - yours, the lords', caravans, villagers, bandits - travels faster by Map Road Speed Percent: the speed tooltip shows a 'Road' line and the marching-column cap is raised by the same share, so the bonus is not lost under it; ships at sea are not affected. The roads come from the map's own road paint (file arm_map_roads_geo.tsv in the module's ModuleData folder). Off = no road bonus, as before", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool MapRoadSpeedBonus { get; set; } = true;

        [SettingPropertyInteger("Map Road Speed Percent", 0, 50, "0", HintText = "how much faster a land party travels on a road, in percent of its speed (15 = +15%; at most 50)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public int MapRoadSpeedPercent { get; set; } = 15;

        [SettingPropertyFloatingInteger("Map Road Margin", 0.00f, 2.00f, "0.00", HintText = "how far beyond the painted edge of a road (in map units) a party still counts as on it when Map Road Wide Field is off - the road paint is coarse and party paths never follow it exactly (0.4 = about two kilometres; at most 2)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MapRoadMargin { get; set; } = 0.40f;

        [SettingPropertyBool("Map Road Wide Field", HintText = "a wider road: a party that strays a little from a road - a painted main road or a village lane - keeps its road bonus up to Map Road Wide Margin beyond the edge of the road. Off = the narrow field of Map Road Margin, as before", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool MapRoadWideField { get; set; } = true;

        [SettingPropertyFloatingInteger("Map Road Wide Margin", 0.00f, 2.00f, "0.00", HintText = "with Map Road Wide Field on: how far beyond the edge of a road (in map units) a party still counts as on it - on the painted roads and on the village lanes alike (1.0 = about five kilometres; at most 2)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MapRoadWideMargin { get; set; } = 1.00f;

        [SettingPropertyBool("Map Side Road Speed Bonus", HintText = "the lanes to the villages drawn on the campaign map (Map Side Roads) speed up every land party too - yours, the lords', caravans, villagers, bandits - by Map Side Road Speed Percent: the speed tooltip shows a 'Side road' line and the marching-column cap is raised by the same share. On a painted main road the main road bonus counts instead - the two never add up. Needs Map Road Speed Bonus and Map Side Roads. Off = the lanes are only a picture, as before", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public bool MapSideRoadSpeedBonus { get; set; } = true;

        [SettingPropertyFloatingInteger("Map Side Road Speed Percent", 0.00f, 50.00f, "0.0", HintText = "how much faster a land party travels on a village lane, in percent of its speed (7.5 = +7.5%; at most 50)", RequireRestart = false)]
        [SettingPropertyGroup("The marching column")]
        public float MapSideRoadSpeedPercent { get; set; } = 7.5f;

        [SettingPropertyBool("Material Law Enabled", HintText = "charcoal and iron bars get honest prices and honest smelting: a load of wood gives a few sacks of charcoal, a bloomery eats charcoal by the sackful, each finer grade of steel loses metal", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool MaterialLawEnabled { get; set; } = true;

        [SettingPropertyBool("Real Refining Enabled", HintText = "refining recipes follow the bloomery: 1 wood -> 4 charcoal, 1 ore + charcoal -> 3 crude iron, 5 bars + charcoal -> 4 bars of the next grade (a fifth of the metal lost) (perks still gate the steels)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool RealRefiningEnabled { get; set; } = true;

        [SettingPropertyInteger("Bloomery Charcoal Per Ore", 0, 80, "0", HintText = "charcoal (0.5 kg each) a bloomery burns for one load of ore (10 kg) - about a kilo of charcoal per kilo of ore", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int BloomeryCharcoalPerOre { get; set; } = 20;

        [SettingPropertyInteger("Charcoal Value", 0, 36, "0", HintText = "worth of one charcoal (0.5 kg): a quarter of a load of wood plus the burner's work (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int CharcoalValue { get; set; } = 9;

        [SettingPropertyInteger("Crude Iron Value", 0, 348, "0", HintText = "worth of one bar of crude iron (0.5 kg), costed from ore and charcoal (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int CrudeIronValue { get; set; } = 87;

        [SettingPropertyInteger("Wrought Iron Value", 0, 472, "0", HintText = "worth of one bar of wrought iron (0.5 kg) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int WroughtIronValue { get; set; } = 118;

        [SettingPropertyInteger("Iron Value", 0, 628, "0", HintText = "worth of one bar of iron (0.5 kg) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int IronValue { get; set; } = 157;

        [SettingPropertyInteger("Steel Value", 0, 840, "0", HintText = "worth of one bar of steel (0.5 kg) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int SteelValue { get; set; } = 210;

        [SettingPropertyInteger("Fine Steel Value", 0, 1124, "0", HintText = "worth of one bar of fine steel (0.5 kg) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int FineSteelValue { get; set; } = 281;

        [SettingPropertyInteger("Castle Steel Value", 0, 1500, "0", HintText = "worth of one bar of castle-forged steel (0.5 kg), the last grade of the ordinary chain (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int CastleSteelValue { get; set; } = 375;

        [SettingPropertyBool("Travellers No Ingots", HintText = "Banner Kings travellers (craftsmen, serfs, nobles on the road) no longer carry iron bars of any grade or charcoal out of thin air - bars come only from smelting; the rest of their load is drawn exactly as before (off = Banner Kings as before)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool TravellersNoIngots { get; set; } = true;

        [SettingPropertyBool("Travellers No Goods", HintText = "Banner Kings travellers (serfs, craftsmen, nobles on the road) no longer set out with trade goods, ore or timber out of thin air - Banner Kings handed each new party a load from nowhere and it vanished with the party at its town; now they carry only their road food and pack animals (off = Banner Kings as before)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool TravellersNoGoods { get; set; } = true;

        [SettingPropertyBool("Travellers Real Goods", HintText = "Banner Kings travellers carry real goods: no road food or pack animals from nowhere - they take only the food their road needs from the stalls of their home town or castle (if the stalls run short, the rest comes out of its food stores), and between two towns they carry a small load of goods (not food) bought from the home merchants, picked by the profit it fetches at the destination; the destination town pays for the goods and the takings go back to the home town's coffers (works only with Travellers No Goods on; off = Banner Kings road food and pack animals from nowhere, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool TravellersRealGoods { get; set; } = true;

        [SettingPropertyInteger("Traveller Trade Per Head", 0, 40, "0", HintText = "how much the home merchants entrust to each traveller for goods to sell at the destination - the load is also capped by what the travellers can carry and by 5% of either town's coffers", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public int TravellerTradePerHead { get; set; } = 10;

        [SettingPropertyBool("Tier6 Castle Steel", HintText = "tier 6 arms and armour count castle-forged steel as their metal everywhere - your forge, town workshops, repairs and their worth (one rule for tier 6; off = workshops and prices count fine steel for tier 6 as before; takes effect after reloading the game)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool Tier6CastleSteel { get; set; } = true;

        [SettingPropertyBool("Minerals Counted Once", HintText = "Banner Kings lists the mineral of a mining village twice and so credited it twice a day (iron ore, salt, clay, silver); this strikes the second entry and counts the first one twice instead - the village digs exactly as much as before, but mines, village storehouses and village carts now all reckon with the same true output", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool MineralsCountedOnce { get; set; } = true;

        [SettingPropertyFloatingInteger("Mine Output Multiplier", 0.00f, 12.00f, "0.00", HintText = "iron mines dig this many times the old output - the workshops of the realm were starving for ore", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public float MineOutputMultiplier { get; set; } = 3f;

        [SettingPropertyBool("Casterly Gold Exhausted", HintText = "the gold of Casterly Rock has run out, as in the books: the mine under the Rock (Rockford, the mining village of Casterly Rock) digs no more silver or gold ore, and no village of the Westerlands digs gold ore - the Lannisters live on rents, trade and loans. Their timber and every other good stay as they were. Off: the mine digs as before", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool CasterlyGoldExhausted { get; set; } = true;

        [SettingPropertyBool("Dragons Eat Herds", HintText = "dragons are not free: every dragon eats two sheep a day (a hog counts as two, a cow as four) - first from the herd its rider's party drives, and with none there it takes the animals the nearest villages (within a day's flight) are sending to market; the village loses them and gets nothing. A burning or looted village is spared. With nothing within reach the dragon goes hungry. Applies to Daenerys and to you alike. Off: dragons eat nothing", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool DragonsEatHerds { get; set; } = true;

        [SettingPropertyFloatingInteger("Lumber Output Multiplier", 0.00f, 12.00f, "0.00", HintText = "woodcutters fell this many times the old output - charcoal burners need wood by the cartload (a forge burns ~5 loads of wood per load of ore)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public float LumberOutputMultiplier { get; set; } = 3f;

        [SettingPropertyBool("No Free Timber And Tools", HintText = "no timber or tools out of thin air: Realistic Bannerlord tops every settlement up each day from nothing - a town to 30 loads of timber and 15 tools, a castle to 15 and 8, a village or hideout to 10 and 4; this stops it, so timber and tools come only from woodcutters, smithies, village carts, caravans and the fence (off = Realistic Bannerlord's daily top-up as before; the day's log line shows either way how much it is or would be)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool NoFreeTimberAndTools { get; set; } = true;

        [SettingPropertyFloatingInteger("Village Woodlot Loads", 0.00f, 10.00f, "0.00", HintText = "every village that is not a woodcutters' village fells this many loads (100 kg) of timber a day in its own woods and sends them to market with its carts - firewood and building timber came to a town from the woods of all the villages around it, not from a few woodcutters alone; the village storehouse holds five days of it like any other produce; it stands in for Realistic Bannerlord's free timber, so it works only while No Free Timber And Tools is on (0 = off)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public float VillageWoodlotLoads { get; set; } = 2.5f;

        [SettingPropertyBool("Smelt Cap To Craft Cost", HintText = "melting a piece down never gives back more metal than a share of what forging it costs - no metal out of thin air", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool SmeltCapToCraftCost { get; set; } = true;

        [SettingPropertyBool("Smelt Cap From Forge Bill", HintText = "with Smelt Cap To Craft Cost: the limit is a share of the metal that forging the same piece really takes at the anvil (its weight), not of its armour points - plate and mail gave back a tenth of their metal instead of up to half. Off = limit from armour points, as before", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool SmeltCapFromForgeBill { get; set; } = true;

        [SettingPropertyBool("Bk Shield Bill By Recipe", HintText = "a shield forged on the Banner Kings armour screen takes the same materials as at your own anvil - wood, iron for the rim and boss, leather and charcoal - instead of two pieces of wood (a wooden shield cost no iron to make, yet melted down into several bars). Off = the Banner Kings bill", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool BkShieldBillByRecipe { get; set; } = true;

        [SettingPropertyBool("Shield No Velvet", HintText = "shields need no velvet: a tier 5-6 shield is faced with leather instead (the same count) - one piece of velvet costs many times the shield itself, and armour takes none either. Off = tier 5-6 shields also take velvet, at your anvil and on the Banner Kings screen", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool ShieldNoVelvet { get; set; } = true;

        [SettingPropertyBool("Start Stock In Loads", HintText = "new campaign only: the ore and timber the world starts with are counted by the load too - the game hands out the starting stock before the 100 kg load comes into force, so every storehouse, stall and pack train held ten times the intended weight and choked village storehouses stopped all work; done once, at the first launch of a new campaign (saves older than a day are left as they are)", RequireRestart = false)]
        [SettingPropertyGroup("Smithing materials")]
        public bool StartStockInLoads { get; set; } = true;

        [SettingPropertyBool("Arms Cost Pricing Enabled", HintText = "every piece of arms and armour is priced from what it costs to make - its weight, its metal, its leather and cloth, the days at the anvil and how well it protects; unique pieces keep the price of their fame", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public bool ArmsCostPricingEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Arms Price Band", 0.00f, 8.00f, "0.00", HintText = "how far the market price may stray from the cost of making it (1 = price is the cost, 2 = between half and double, higher = closer to the old prices)", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float ArmsPriceBand { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Smith Day Wage", 0.00f, 40.00f, "0.00", HintText = "what a day of a master smith and his helper costs, in the price of a piece", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float SmithDayWage { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Smith Profit Percent", 0.00f, 100.00f, "0.00", HintText = "the workshop's profit on top of materials and labour", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float SmithProfitPercent { get; set; } = 25f;

        [SettingPropertyBool("Material Index Enabled", HintText = "the market prices by the cost of making it AGAIN: dear ore and wood make armour dear, even the pieces already on the stall", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public bool MaterialIndexEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Material Index Inertia", 0.00f, 1.00f, "0.00", HintText = "share of the gap to today's material prices the market closes each day - prices drift, they do not jump", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float MaterialIndexInertia { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Material Ratio Min", 0.00f, 2.00f, "0.00", HintText = "cheapest a raw material (ore, wood, leather, linen) counts in one town against its usual price - below that it is shipped out (Jeff: 0.5)", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float MaterialRatioMin { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Material Ratio Max", 0.00f, 6.00f, "0.00", HintText = "dearest a raw material counts in one town against its usual price - above that a smith buys it in the next town (Jeff: 1.5)", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float MaterialRatioMax { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Material Index Min", 0.00f, 2.00f, "0.00", HintText = "floor of the material-cost factor on a finished piece", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float MaterialIndexMin { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Material Index Max", 0.00f, 6.00f, "0.00", HintText = "ceiling of the material-cost factor on a finished piece (before it was 5 - a leather garb sold for 20 000)", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float MaterialIndexMax { get; set; } = 1.5f;

        [SettingPropertyBool("War Expectation Enabled", HintText = "when war is declared, traders on both sides expect armies to buy and raise their asking prices before the first lord arrives. Off since stage 8: the armies' real unfilled orders already raise demand on the stalls, so with this on a war counts twice - arms cost up to a third more than the true shortage calls for, and merchants haul them to towns where nobody has bought yet", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public bool WarExpectationEnabled { get; set; } = false;

        [SettingPropertyFloatingInteger("War Expectation Base", 0.00f, 2.00f, "0.00", HintText = "extra demand expected at the declaration of war, scaled by the enemy's strength against ours (0.5x to 2x)", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float WarExpectationBase { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("War Expectation Days", 0.00f, 60.00f, "0.00", HintText = "days over which the traders' expectation fades unless real purchases bear it out", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float WarExpectationDays { get; set; } = 15f;

        [SettingPropertyBool("Substitution Enabled", HintText = "when no piece of the better tier is on the stall, buyers settle for the tier below", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public bool SubstitutionEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Substitution Share", 0.00f, 1.20f, "0.00", HintText = "share of the missing tier's demand that falls to the tier below", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float SubstitutionShare { get; set; } = 0.3f;

        [SettingPropertyFloatingInteger("Trade Transport Percent Per100", 0.00f, 20.00f, "0.00", HintText = "hauling costs this % of a piece's worth per 100 leagues - traders carry goods only where the price difference pays for the road", RequireRestart = false)]
        [SettingPropertyGroup("Arms pricing")]
        public float TradeTransportPercentPer100 { get; set; } = 5f;

        [SettingPropertyBool("Ai Buys Gear", HintText = "AI lords buy their soldiers' arms and armour on the market with their own gold - no more free gear from the quartermaster's hat, no more gold for sweeping the baggage into the armoury", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool AiBuysGear { get; set; } = true;

        [SettingPropertyBool("Garrison Buys Gear", HintText = "a garrison buys the gear its men lack at the market of its own town, paid by the lord of the place - the coin goes to the town", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool GarrisonBuysGear { get; set; } = true;

        [SettingPropertyBool("Garrison Buys Gear Player", HintText = "your own garrisons may top up from YOUR purse what their own pay does not cover when they buy missing kit", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool GarrisonBuysGearPlayer { get; set; } = false;

        [SettingPropertyBool("Unique Spoils From Player", HintText = "the custom of war binds you too: whoever takes you captive takes the renowned arms you wear", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool UniqueSpoilsFromPlayer { get; set; } = true;

        [SettingPropertyBool("Valyrian Guard", HintText = "Valyrian steel is a finite store - no smith alive can make more: every blade in the world is counted each day against the blades the world began with (and those reworked in Qohor); a copy beyond that, from any source, is only a fine forgery and becomes ordinary steel of the same kind; a blade that goes missing is reported in the log (off = only counted; the first count after this version - forgeries made ordinary, lost blades returned to their line - waits until it is on)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool ValyrianGuard { get; set; } = true;

        [SettingPropertyBool("Valyrian No Smelt", HintText = "no forge but the masters of Qohor can work Valyrian steel: Valyrian blades are not on the smelting list and cannot be melted down (other legendary pieces as before); off = a Valyrian blade melts like any other and its steel is lost to the world for good", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool ValyrianNoSmelt { get; set; } = true;

        [SettingPropertyBool("Unique Inheritance", HintText = "a Valyrian blade does not die with its bearer: the executioner takes it, otherwise the heir (clan leader, children, spouse, siblings, kin); with no heir it lies on the market of his clan's town; blades of your own clan come to your baggage", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool UniqueInheritance { get; set; } = true;

        [SettingPropertyBool("Unique Never Lost", HintText = "named pieces and Valyrian steel never vanish with a beaten or disbanded party (they go to the victor, the owner or a town market) nor when the game re-dresses a lord (a new ruler keeps his blade)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool UniqueNeverLost { get; set; } = true;

        [SettingPropertyBool("Uniques Not Folk Goods", HintText = "a renowned piece lying on a market (Cersei's red dress, Renly's armour, a Valyrian blade...) is not used up by the townsfolk's daily wants nor cleared away by the game with the market's worn stock - it leaves the shelf only when someone buys it or a merchant's cart takes it. Off = the townsfolk wear it out like any garment, as before", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool UniquesNotFolkGoods { get; set; } = true;

        [SettingPropertyBool("No Conjured Legends", HintText = "reinforcement caravans of Dynamic Troop Equipment and tournament prizes (also Tournaments XPanded) no longer conjure legendary or named pieces: each becomes an ordinary piece of the same kind", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool NoConjuredLegends { get; set; } = true;

        [SettingPropertyFloatingInteger("Hist Valyrian Per Measure", 0.00f, 240000.00f, "0.00", HintText = "worth of one measure of Valyrian steel (a one-handed blade; a greatsword such as Ice is two), pence - about what a typical lord keeps in his purse, so no lord parts with one and only the richest can buy one; on a market stall it weighs only its making cost (needs Historical Prices; takes effect after reloading the game)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public float HistValyrianPerMeasure { get; set; } = 60000f;

        [SettingPropertyBool("Qohor Rework Enabled", HintText = "the masters of Qohor rework Valyrian steel - the only way to a new Valyrian sword: bring a blade from your baggage to Qohor, pay the guild and wait; a blade of one measure becomes one sword of a new shape, a greatsword of two measures (such as Ice) becomes two swords; nothing is added and nothing is lost (off = no new orders; collecting and taking back still work)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool QohorReworkEnabled { get; set; } = true;

        [SettingPropertyBool("Qohor Own Design", HintText = "the masters of Qohor can also forge a Valyrian blade of one measure to a design of your own: pick one of your forge designs (or a sword you forged and carry) - they keep its guard, grip and pommel, make the blade of Valyrian steel close to its length - and give it the name you choose. The same fee, days and charcoal as any reforging; the new sword is Valyrian steel of one measure and the only one of its kind. Off: only the patterns of the realm", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool QohorOwnDesign { get; set; } = true;

        [SettingPropertyBool("Qohor Ai Rework", HintText = "a lord whose party stands in Qohor and who bears a Valyrian greatsword won from another house may have it reforged into two swords by the same rule - the same fee to Qohor's treasury, the same days (as Tywin Lannister did with Ice); the masters send the finished swords to him, or to his heir; lords of your own house never order it on their own", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public bool QohorAiRework { get; set; } = true;

        [SettingPropertyInteger("Qohor Days", 0, 28, "0", HintText = "days of the masters' work on one order - shortened for the game; in the books it took months", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public int QohorDays { get; set; } = 7;

        [SettingPropertyInteger("Qohor Crew", 0, 16, "0", HintText = "masters of the guild at one order - each day takes their hours from the town's smiths (the same hands that mend and make arms in Qohor)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public int QohorCrew { get; set; } = 4;

        [SettingPropertyFloatingInteger("Qohor Toll Percent", 0.00f, 25.00f, "0.00", HintText = "the guild's toll, percent of the worth of the steel that goes into the fire - the only guild in the world that knows the art takes its share as a lord's mill took its multure (a sixteenth); paid with the masters' wages to Qohor's treasury", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public float QohorTollPercent { get; set; } = 6.25f;

        [SettingPropertyInteger("Qohor Charcoal Per Measure", 0, 10, "0", HintText = "charcoal the masters take from Qohor's stalls for each measure of steel; with none on the stalls the order waits", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public int QohorCharcoalPerMeasure { get; set; } = 2;

        [SettingPropertyFloatingInteger("Valyrian Greatsword Min Cm", 0.00f, 420.00f, "0.00", HintText = "a two-handed Valyrian blade at least this long (cm) is a greatsword of two measures - steel enough for two swords, as Ice gave Oathkeeper and Widow's Wail (Ice 140, Heartsbane 114, Blackfyre 111, Brightroar 108); shorter blades are one measure (takes effect after reloading the game)", RequireRestart = false)]
        [SettingPropertyGroup("Valyrian steel")]
        public float ValyrianGreatswordMinCm { get; set; } = 105f;

        [SettingPropertyInteger("Battle Real Min Side", 0, 200, "0", HintText = "a clash counts as a real battle for the chronicle's averages only if both sides had at least this many men and neither outnumbered the other more than 4 to 1", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int BattleRealMinSide { get; set; } = 50;

        [SettingPropertyInteger("Unique Max Wearers", 0, 12, "0", HintText = "an item worn by more than this many characters is ordinary attire, not a unique (kept out of the chronicle and the spoils of capture)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int UniqueMaxWearers { get; set; } = 3;

        [SettingPropertyInteger("Battle Chronicle Min Men", 0, 120, "0", HintText = "battles where both sides together had fewer men than this are only counted, not written out in the battle chronicle (yours always are)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int BattleChronicleMinMen { get; set; } = 30;

        [SettingPropertyBool("Build Diary Enabled", HintText = "write a daily diary of building works in every town and castle (progress, daily construction power, days left, stalled works) - log only", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool BuildDiaryEnabled { get; set; } = true;

        [SettingPropertyBool("Finance Ledger Enabled", HintText = "write a daily ledger of every kingdom: treasury and its change, the king's purse and daily balance, clan purses, poor clans and clans losing money, troops - log only", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool FinanceLedgerEnabled { get; set; } = true;

        [SettingPropertyInteger("Finance Ledger Poor", 0, 4000, "0", HintText = "a clan with less gold than this counts as poor in the ledger", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int FinanceLedgerPoor { get; set; } = 1000;

        [SettingPropertyInteger("Finance Ledger Poorest", 0, 20, "0", HintText = "how many of the poorest clans of each kingdom the ledger lists", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int FinanceLedgerPoorest { get; set; } = 5;

        [SettingPropertyBool("Goods Ledger Tick Authors", HintText = "with the goods ledger: for goods that appear or vanish in the daily ticks of villages, castles and towns without a known cause, also write which game or mod behaviour did it (read from the call stack, at most 1,500 times a day) - written to the log only, changes nothing in the game; off = not traced", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool GoodsLedgerTickAuthors { get; set; } = true;

        [SettingPropertyBool("A17 Diagnostic Lines", HintText = "with the goods ledger: also write where horses and fish change hands outside the known flows (by flow and by holder, a few call stacks a session) and every unique piece leaving a market (at most 20 a session) - written to the log only, changes nothing in the game; off = not traced", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool A17DiagnosticLines { get; set; } = true;

        [SettingPropertyBool("Goods Ledger Enabled", HintText = "write a daily ledger of every trade good and farm animal - how much villages, workshops and hidden craftsmen made, how much townsfolk, workshops, armies, builders and Banner Kings supplies used up, what carts and caravans carried, who holds the stock and what is left unexplained; each line balances yesterday's stock + made - used = today's stock - log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool GoodsLedgerEnabled { get; set; } = true;

        [SettingPropertyBool("Ore Ledger Town Crafts Column", HintText = "the ore and wood ledger counts what town craftsmen take off the stall for their own crafts (tools from iron and the other town crafts) as its own entry, the same way the goods ledger does, so the two ledgers agree piece for piece - log only, changes nothing in the game; off = counted with the workshop lines as before", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool OreLedgerTownCraftsColumn { get; set; } = true;

        [SettingPropertyBool("Circulation Ledger Enabled", HintText = "write the daily money circulation ledger: which named causes create or destroy gold in the world (notable caravan wages, sales commission, battlefield loot, Banner Kings and BetterEconomy spending, ship trade, prisoner sales, sieges, deaths), what clans paid and earned, the crown, the Iron Bank and the notables - log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool CirculationLedgerEnabled { get; set; } = true;

        [SettingPropertyBool("Circulation Probe Enabled", HintText = "check the circulation ledger against the whole world: at most 8 times a day count all gold in the world just before and just after one measured game action and compare the change with the causes the ledger named for it - log only, costs two full counts of the world per check", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool CirculationProbeEnabled { get; set; } = true;

        [SettingPropertyBool("Ledger Segment Bisect Log", HintText = "with the circulation ledger: also write one daily line that splits the gold our own daily tick leaves unexplained into smaller steps (one count of all the gold in the world at each step, about 50 a day, a few milliseconds) - log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool LedgerSegmentBisectLog { get; set; } = true;

        [SettingPropertyBool("Clan Income Book Enabled", HintText = "keep every clan's steady income (average of its last 28 days, saved with the game) and write a dry run of the planned clan budget and debt rules: wage ceiling against wages paid, clans over the ceiling, men who would be released, clans that would borrow or face seizure - log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool ClanIncomeBookEnabled { get; set; } = true;

        [SettingPropertyBool("Clan Income Book Stable D", HintText = "with the clan income book: also split every clan's income into the parts of its steady income (land of the fiefs it holds today, crown, contract, workshops and caravans) and the parts left out of it (its own money coming back through its own town purse, one-off gains, other model income, money sent within the house, estates counted twice), and write the stage 2 measures (captive lords and ransoms, garrison growth, town purses, knights' spending, desertion by cause, Banner Kings population, marriages, travellers' goods, the Others, the historical measure) - log and CSV only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool ClanIncomeBookStableD { get; set; } = true;

        [SettingPropertyBool("Paid Construction", HintText = "buildings rise only as fast as their owner pays: wages and carting go to the town or castle purse, materials are bought off the market", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool PaidConstruction { get; set; } = true;

        [SettingPropertyBool("Paid Construction Player", HintText = "your own fiefs too: their works take the same share of your daily income", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool PaidConstructionPlayer { get; set; } = true;

        [SettingPropertyFloatingInteger("Build Income Share", 0.00f, 1.00f, "0.00", HintText = "share of a lord's daily income (fiefs and rents) spent each day on building works, split over his fiefs with works; in war only military works (walls, towers, barracks)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float BuildIncomeShare { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Build Material Share", 0.00f, 1.00f, "0.00", HintText = "of that money, this share buys materials (limestone, timber, clay, tools, marble) at the market; the rest pays masons, labourers and carters", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float BuildMaterialShare { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Build Pence Per Point Military", 0.00f, 192.00f, "0.00", HintText = "pence per construction point of walls, towers and other military works", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float BuildPencePerPointMilitary { get; set; } = 48f;

        [SettingPropertyFloatingInteger("Build Pence Per Point Civil", 0.00f, 96.00f, "0.00", HintText = "pence per construction point of civil buildings", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float BuildPencePerPointCivil { get; set; } = 24f;

        [SettingPropertyBool("Folk Builds Town", HintText = "the townsfolk (and castle folk) pay for the works of their own town each day, beside the lord: only buildings that serve the town - walls, granary, marketplace, harbour and port, warehouse, mason, waterworks, roads, mines, courthouse, theatre and the like; barracks, training fields, guard houses, siege workshops, the tax office and other military works stay the lord's. When the lord's military works are first in line, they pay into their own next building. The money comes first from the town's common purse (its works budget from the market dues), then from what the people hold above their reserve after the war aid. They buy timber, stone and tools from the market (never above Building Material Price Cap times their worth) and pay their own masons and labourers; wages return to the town's labourers and craftsmen. War does not stop them, a siege does. Needs Paid Construction. Off = the common purse pays its public works as before, without buildings", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool FolkBuildsTown { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Works Share", 0.000f, 0.200f, "0.000", HintText = "with Folk Builds Town: the part of the coin they hold above their reserve that each class of townsfolk offers the town's works each day (0.02 = one part in fifty a day); the market, the hands and the cost of the present stage usually limit the works long before this", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float FolkWorksShare { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Folk Works Hands", 0.000f, 0.200f, "0.000", HintText = "with Folk Builds Town: the share of the town's labourers (castle folk) that can work on the townsfolk's own works at once, at Workshop Wage Per Day each (0.03 = three in a hundred, about the most the great works of the Middle Ages took) - this keeps the rebuilding of a sacked town slow", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float FolkWorksHands { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Build Material Price Cap", 0.00f, 5.00f, "0.0", HintText = "with Folk Builds Town: neither the lord nor the townsfolk buy a piece of building material dearer than this many times its worth (0 = no limit)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float BuildMaterialPriceCap { get; set; } = 2.0f;

        [SettingPropertyFloatingInteger("Folk Works Level Days", 0.00f, 365.00f, "0", HintText = "with Folk Builds Town: the townsfolk's own works never raise a stage of a building faster than in this many days (each day they put in at most the cost of the stage divided by this; 60 = at most about six stages a year in any town or castle, so a sacked town rebuilds slowly; 0 = no limit); the lord's works are not limited by this", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float FolkWorksLevelDays { get; set; } = 60f;

        [SettingPropertyBool("Build Wages By Town", HintText = "the masons and labourers are paid the day wage of the market town they come from: a penny of wages buys less work in a rich town and more in a poor one (materials at the market price either way; off = a penny of wages is a penny of work everywhere)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool BuildWagesByTown { get; set; } = true;

        [SettingPropertyBool("Build Wood Above Craft Stock", HintText = "building works (the lord's and the townsfolk's) take timber off the market only above the stock the town keeps for its own smiths, bloomeries, workshops and households, never less than 40 loads (the same stock caravans fill for it - Caravan Bulk Stock Days of their use, building works not counted); below it the works buy the other materials or wait, so the armourers and fletchers are not left without wood. Off = the works buy timber down to the last piece (the townsfolk's works leave 50), as before", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool BuildWoodAboveCraftStock { get; set; } = true;

        [SettingPropertyBool("Ai Recruits Bring Kit", HintText = "a fresh recruit still arrives with his own kit (levies came armed); turn off and lords must buy for every new man", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool AiRecruitsBringKit { get; set; } = true;

        [SettingPropertyBool("Kit From Notable", HintText = "an AI lord's new recruits bring only the kit their notable actually bought for them (tier 1 men bring their own belongings) - no full kit from thin air", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool KitFromNotable { get; set; } = true;

        [SettingPropertyBool("Player Recruit No Free Kit", HintText = "your recruits come as an AI lord's do, with no full free kit from Dynamic Troop Equipment: a volunteer above the first rank brings what his notable bought for him and what he owns, a first-rank man brings his own belongings as before, and a tavern hireling brings what he owns plus, if he rides, his own horse and its harness. The rest you buy or loot. Off = as before (every recruit brings a full kit)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public bool PlayerRecruitNoFreeKit { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Gear Budget Percent", 0.00f, 100.00f, "0.00", HintText = "share of a lord's gold (above the reserve) he is willing to spend on gear in one visit to a town", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public float AiGearBudgetPercent { get; set; } = 25f;

        [SettingPropertyInteger("Ai Gear Gold Reserve", 0, 8000, "0", HintText = "gold a lord always keeps back - wages come first", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int AiGearGoldReserve { get; set; } = 2000;

        [SettingPropertyInteger("Ai Gear Max Pieces Per Visit", 0, 240, "0", HintText = "most pieces a lord buys in one visit", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int AiGearMaxPiecesPerVisit { get; set; } = 60;

        [SettingPropertyInteger("Ai Gear Log Per Day", 0, 60, "0", HintText = "how many lords' purchases are written to the log each day (the daily total is always written)", RequireRestart = false)]
        [SettingPropertyGroup("Army purchases")]
        public int AiGearLogPerDay { get; set; } = 15;

        [SettingPropertyBool("Workshop Law Enabled", HintText = "town workshops that make arms and armour run as real businesses: they buy ore, wood, leather and linen on the market by the true weight of each piece, pay their workers, sell to the market - and make only what turns a profit", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WorkshopLawEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Workshop Workers Artisans", 0.00f, 24.00f, "0.00", HintText = "man-days of work the town's artisans put in each day", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopWorkersArtisans { get; set; } = 6f;

        [SettingPropertyFloatingInteger("Workshop Workers", 0.00f, 24.00f, "0.00", HintText = "man-days of work a notable's smithy or wood workshop puts in each day (a master with journeymen and apprentices)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopWorkers { get; set; } = 6f;

        [SettingPropertyFloatingInteger("Workshop Prosperity Per Hand", 0.00f, 680.00f, "0.00", HintText = "the town's own craftsmen: one man-day of arms work each day for this much prosperity (a town of 4800 keeps about 28 hands busy) - history had 10-20x more (Paris 1292, Milan), raised step by step as ore allows", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopProsperityPerHand { get; set; } = 170f;

        [SettingPropertyFloatingInteger("Workshop Artisans Min", 0.00f, 24.00f, "0.00", HintText = "fewest man-days a day the craftsmen of even a poor town put in", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopArtisansMin { get; set; } = 6f;

        [SettingPropertyFloatingInteger("Workshop Artisans Max", 0.00f, 240.00f, "0.00", HintText = "most man-days a day the craftsmen of the richest town put in", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopArtisansMax { get; set; } = 60f;

        [SettingPropertyInteger("Artisan Tan Weave Per Cycle", 0, 20, "0", HintText = "the town's own tanners and weavers turn this many loads of raw hides into leather, or flax into linen, each working cycle - from the town market, nothing from thin air (one for one; not used while Town Crafts Enabled is on)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public int ArtisanTanWeavePerCycle { get; set; } = 5;

        [SettingPropertyBool("Town Crafts Enabled", HintText = "the town's own fullers, weavers and tanners, in every town: wool into woollen cloth (felt), flax into linen, raw hides into leather, taken from their own town's stalls whenever the cloth or leather fetches enough to pay for its material, the work and a master's profit (Smith Profit Percent) at today's prices - one piece at a time, each priced anew, the best paying trade first. Material by the worth of the goods - 60% of the cloth's worth, never less than the cloth weighs: about 3 sacks of wool for 2 bolts of cloth, 3 of flax for 1 of linen, 12 hides for 5 leathers; the work is 20% of the worth at a craftsman's day wage (cloth 13 man-days, linen 7, leather 3), paid as dear as the town is prosperous (Workshop Wage By Tier, Town Wage Ref Prosperity). No coin changes hands - from stall to stall of the same town. What they work up counts in the town's daily use, so wool and flax are dear where they are worked and caravans bring them there. Replaces the one-for-one tanning and weaving (Artisan Tan Weave Per Cycle); needs Historical Prices (off = one for one as before)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool TownCraftsEnabled { get; set; } = true;

        [SettingPropertyBool("Weaver Export Price", HintText = "the town's weavers also weave for the towns that lack linen: while their own stall holds less linen than the town keeps for itself and for carrying out (what it will not sell to other towns, and as much again - at least one cart load), a bolt is worth to them what the best town short of linen within reach of a hired caravan or a merchants' cart (Town Material Order Range, by road or by sea) pays for it, less the carriage - not only what their own market pays. The linen then leaves by the existing caravan contracts and merchants' carts. Off = they weave only as much as their own market pays for, as before", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WeaverExportPrice { get; set; } = true;

        [SettingPropertyBool("Tanner Export Price", HintText = "the town's tanners also tan for the towns that lack leather, like the weavers do for linen (Weaver Export Price): while their own stall holds less leather than the town keeps for itself and for carrying out, a leather is worth to them what the best town short of leather within reach of a hired caravan or a merchants' cart pays for it, less the carriage - not only what their own market pays, which fell once the townsfolk stopped buying leather from their savings. The leather then leaves by the existing caravan contracts and merchants' carts. Off = they tan only as much as their own market pays for, as before", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool TannerExportPrice { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Craft Hands Per Arms Hand", 0.00f, 8.00f, "0.00", HintText = "hands of a town's cloth and leather trades for each hand of its arms craftsmen (Workshop Prosperity Per Hand), so they grow with the town's prosperity - weaving, fulling and tanning kept about twice as many people as the arms guilds (Paris 1292, Ghent 1356, estimate); 0 = town crafts off, the one-for-one tanning and weaving as before", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float TownCraftHandsPerArmsHand { get; set; } = 2f;

        [SettingPropertyBool("Town Fletchers Enabled", HintText = "the town's own fletchers and arrowsmiths, in every town: arrows and bolts made from the ore and wood on their own town's stalls (the same recipe arms workshops use - the iron heads, the shafts, the charcoal of the bloomery and the forge; feathers, glue and thread are counted in the work), one quiver at a time, after the town's workshops have taken their share, whenever the quiver fetches enough to pay for its material, the work and a master's profit (Workshop Min Profit Percent) at today's prices; no coin changes hands - from stall to stall of the same town; lords buy them there. While on, workshops no longer make arrows out of thin air, townsfolk no longer eat them off the stalls and Banner Kings' party supplies no longer buy and burn them for AI parties (the player's own party as before; the player's own workshops - see Player Workshops Same Rule). Needs Historical Prices", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool TownFletchersEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Fletcher Hands Per Arms Hand", 0.00f, 2.40f, "0.00", HintText = "hands of a town's fletchers and arrowsmiths for each hand of its arms craftsmen (Workshop Prosperity Per Hand) - about 3,700 man-days a day for the world, some 0.07 fletchers per 1,000 people, up to about 1,600 quivers of 30 a day at full work (0.9 left 43 towns without ore in the 09.10 test - fletchers outbid the armourers); they work only while a quiver pays for its ore, wood and work, so most stand idle once the stalls are full (England 1359: 850,000 arrows came to the Tower for the crown alone - about 275 fletchers at full work, 0.1 per 1,000 people); 0 = off, arrows as before", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float TownFletcherHandsPerArmsHand { get; set; } = 0.6f;

        [SettingPropertyFloatingInteger("Workshop Sell Share", 0.00f, 3.60f, "0.00", HintText = "a craftsman sells his wares at the market price buyers pay, less this merchant's cut (0.9 = he keeps 90%); with the maker's profit of 25% built into worth, at a normal price he earns 1.125x his cost", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopSellShare { get; set; } = 0.9f;

        [SettingPropertyFloatingInteger("Guild Share Tailor", 0.00f, 1.20f, "0.00", HintText = "share of a town's craftsmen who are tailors and doublet-makers (Paris tax roll 1292)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareTailor { get; set; } = 0.30f;

        [SettingPropertyFloatingInteger("Guild Share Armourer", 0.00f, 1.00f, "0.00", HintText = "share who are armourers and mail-makers", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareArmourer { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("Guild Share Weaponsmith", 0.00f, 1.00f, "0.00", HintText = "share who are weaponsmiths, cutlers and spear-makers", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareWeaponsmith { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("Guild Share Saddler", 0.00f, 1.00f, "0.00", HintText = "share who are saddlers and harness-makers", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareSaddler { get; set; } = 0.15f;

        [SettingPropertyFloatingInteger("Guild Share Bowyer", 0.00f, 1.00f, "0.00", HintText = "share who are bowyers and fletchers", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareBowyer { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Guild Share Shieldwright", 0.00f, 1.00f, "0.00", HintText = "share who are shield-makers", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float GuildShareShieldwright { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Workshop Forge Wood Per Metal Kg", 0.00f, 50.00f, "0.00", HintText = "kilograms of wood (as charcoal) the forge burns for each kilogram of metal worked, on top of the bloomery", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopForgeWoodPerMetalKg { get; set; } = 12.5f;

        [SettingPropertyFloatingInteger("Workshop Wage Per Day", 0.00f, 12.00f, "0.00", HintText = "wages for one man-day at the forge, paid into the town (3 d - a craftsman's day in historical prices)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopWagePerDay { get; set; } = 3f;

        [SettingPropertyBool("Workshop Wage By Tier", HintText = "an arms workshop pays every day of work at the master's day wage for the tier of the piece - the same wage that makes the piece's worth (3 d plain gear up to 10.5 d the finest harness) - and every workshop pays wages and keep as dear as its town is prosperous (off = 3 d a day for every piece, the same in every town)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WorkshopWageByTier { get; set; } = true;

        [SettingPropertyFloatingInteger("Workshop Min Profit Percent", 0.00f, 20.00f, "0.00", HintText = "a workshop makes a piece only if the market pays at least this much over materials and wages (a glutted stall - price below about 0.93 of worth - stops it)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopMinProfitPercent { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Workshop Crude Kg Per Ore", 0.00f, 6.00f, "0.00", HintText = "kilograms of crude iron a bloomery wins from one load of ore (10 kg); each finer grade costs a fifth more", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopCrudeKgPerOre { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Workshop Wood Per Ore", 0.00f, 20.00f, "0.00", HintText = "loads of wood burnt to charcoal for each load of ore smelted", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopWoodPerOre { get; set; } = 5f;

        [SettingPropertyInteger("Workshop Candidates", 0, 160, "0", HintText = "how many different pieces a workshop weighs each morning when deciding what pays best to make", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public int WorkshopCandidates { get; set; } = 40;

        [SettingPropertyBool("Workshop Trade Enabled", HintText = "workshops keep their books in the new coin (needs Historical Prices): the daily keep and the wages go into the town purse instead of vanishing, a failed shop is refitted with its new owner's own coin instead of 10000 from nowhere, the coin in the till stays with the shop when it changes hands, and a workshop is bought and sold for what it earns (off = the game's rules in the old coin: 100 a day into thin air, price by town prosperity)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WorkshopTradeEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Workshop Trade Upkeep Per Day", 0.00f, 16.00f, "0.00", HintText = "what every workshop pays the town each day whether it works or not - the master's own keep (a craftsman's 3 d) and the rent of the house (about 1 d a day, 30 shillings a year); the game took 100 a day", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopTradeUpkeepPerDay { get; set; } = 4f;

        [SettingPropertyBool("Workshop Trade Batch Wages", HintText = "journeymen are paid by the batch: a workshop makes a batch of trade goods (bread, beer, wine, leather, linen, pottery, oil, tools, felt, velvet, jewelry) only when the market pays for the materials and for that batch's wages, and the wages go into the town - Workshop Workers man-days a day at Workshop Wage Per Day, shared by its trade lines (off = the game's rule: a batch must clear 200 of the old coin per day of work, which no baker, brewer, tanner or potter can at today's prices, so they stand idle)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WorkshopTradeBatchWages { get; set; } = true;

        [SettingPropertyInteger("Workshop Trade Start Capital", 0, 8000, "0", HintText = "working coin of a workshop that makes only trade goods (bakery, brewery, tannery, weavery...): what it starts a new campaign with, what a new owner puts in from his own purse after a failure, and the level above which profit is paid out - a season of wages and a few batches of materials (the game: 10000 out of thin air). Never less than ten batches of its dearest material at the usual price, up to the game's 10000 (a velvet weavery buys raw silk at 1000 a bale, so it keeps 10000). Workshops that also make arms keep the game's 10000 - the materials of one mail barding cost thousands - and workshops in an old save keep their mark until they change trade", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public int WorkshopTradeStartCapital { get; set; } = 2000;

        [SettingPropertyInteger("Workshop Trade Low Capital", 0, 2000, "0", HintText = "when your own workshop's till holds no more than this, its keep and wages are paid from your purse instead (the game: 5000)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public int WorkshopTradeLowCapital { get; set; } = 500;

        [SettingPropertyFloatingInteger("Workshop Trade Equipment Scale", 0.00f, 1.00f, "0.00", HintText = "worth of a workshop's tools and fittings in the new coin as a share of the old price list (bakery 6000 -> 1200, tannery 1000 -> 200): the floor under a workshop's price and the cost of changing what it makes - about what wages and tools fell by between the two coins", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopTradeEquipmentScale { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Workshop Trade Price Years", 0.00f, 12.00f, "0.00", HintText = "a workshop sells for this many years of its profit after the workshop tax its buyer will really pay (a notable pays Banner Kings' tax; you and the lords pay it to the town's lord for a workshop in a town of another house when Workshop Owner Pays Town Tax is on - otherwise only if Banner Kings' own workshop model is the game's - and none in a town of your own house), never less than its tools and fittings, plus the coin in its till; town rents sold at about ten years' purchase and merchant ventures paid 15-30% a year, but here a workshop is seized without payment whenever its owner's realm goes to war with the town's - so a buyer wants his coin back in three years", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopTradePriceYears { get; set; } = 3f;

        [SettingPropertyInteger("Workshop Trade Profit Days", 0, 120, "0", HintText = "the profit a price is reckoned from is a running average over about this many days of the workshop's real takings (before that - what today's market prices promise); the shop also remembers its past year: a seller asks by the better of the two, a notable buying from you pays by the worse, so a shop that stood idle for a month is no bargain", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public int WorkshopTradeProfitDays { get; set; } = 30;

        [SettingPropertyFloatingInteger("Workshop Trade Resale Share", 0.00f, 3.20f, "0.00", HintText = "a notable buying your workshop pays this share of its worth to him (after his own tax) plus the coin in its till - out of his own purse, and no more than he has (0 to 1 - anything above 1 counts as 1)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float WorkshopTradeResaleShare { get; set; } = 0.8f;

        [SettingPropertyBool("Artisan Own Inputs", HintText = "every loaf from its own grain: Banner Kings lets the hidden craftsmen of a town make several pieces from one piece of material - with today's prices about 5 loaves or 9 jugs of beer from one sack of grain, 4 pots from one load of clay, three times the meat and hides from one beast - and the town pays them for every piece. On: that number stays as the work the craftsmen can do that day, but every extra batch takes its own grain, clay or beast from the town market at the town's price, paid from the craftsmen's till, and only when the batch is worth more than its material (the game's own rule for their first batch); where the market has none or it does not pay, the extra pieces are not made and the town gets back what it paid for them. A slaughter yields one beast's meat, hides and wool per batch. Quality, the lines without any material and the arms lines stay as they are (off = Banner Kings as before)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool ArtisanOwnInputs { get; set; } = true;

        [SettingPropertyBool("Artisan Byproducts Full", HintText = "with Artisan Own Inputs on: every extra beast the town's craftsmen slaughter in a day yields its hides and its other by-products too - until now only the first cow, sheep or hog of a line gave them and the rest were lost. The town's merchants pay the craftsmen for these pieces only out of the coin they hold above their reserve; what they cannot pay for is not made. Wool from slaughter follows Artisan Wool Per Sheep (off = the by-products of the extra beasts are lost, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool ArtisanByproductsFull { get; set; } = true;

        [SettingPropertyFloatingInteger("Artisan Wool Per Sheep", 0.00f, 1.00f, "0.00", HintText = "with Artisan Byproducts Full on: how much of a bale of wool the fleece of one slaughtered sheep is worth, for every sheep beyond the first of a line (the first gives a whole bale, as the recipe says). The share is tallied town by town and kept in the save; a whole bale reaches the market each time a town's tally fills up (0 = no wool from the extra sheep, 1 = a whole bale from each)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public float ArtisanWoolPerSheep { get; set; } = 0.15f;

        [SettingPropertyBool("Workshop Trade Fair Price", HintText = "the just price of the towns (assize of bread, guild prices): for each batch of trade goods the town pays a workshop at most what the batch cost - its materials at the town's price and its wages - plus the master's profit (Smith Profit Percent, the same margin as in the price of arms); whatever an empty stall would pay above that stays in the town purse. Bakers, weavers and silversmiths earn a craftsman's living instead of a lord's rent, so a workshop costs what such a living is worth. Your own workshops too; arms lines keep their own price (off = a workshop gets the town's full price for every piece)", RequireRestart = false)]
        [SettingPropertyGroup("Workshops")]
        public bool WorkshopTradeFairPrice { get; set; } = true;

        [SettingPropertyBool("Castle Villages Sell In Town", HintText = "villagers of a village held from a castle cart their goods to the nearest town market of their realm instead of the lord's castle - the castle was the lord's storehouse and garrison, never a market (off = they keep hauling to the castle)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CastleVillagesSellInTown { get; set; } = true;

        [SettingPropertyFloatingInteger("Market Max Distance", 0.00f, 1000.00f, "0.00", HintText = "the farthest town market, by road, villagers will cart to - about four days on the road, the game's own trade range for a village (three spans between neighbouring towns). Beyond it a castle village keeps selling at its lord's castle (0 = no limit of ours, only the game's own trade range)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float MarketMaxDistance { get; set; } = 250f;

        [SettingPropertyFloatingInteger("Market Cart Factor", 0.00f, 8.00f, "0.00", HintText = "carts instead of pack loads: villagers hauling to a town market carry this many times their usual load - the longer road would otherwise choke the village storehouse (1 = off; above 2 changes little, they take at most three fifths of the store unless they set out on a long road; with Village Cart Whole Store on they take the whole store whatever it weighs)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float MarketCartFactor { get; set; } = 2f;

        [SettingPropertyBool("Market Cart All Villages", HintText = "every village's villagers haul by cart, not only those of villages held from a castle - town villages now take longer roads too, and they already choked their storehouses more often (off = carts for castle villages only)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool MarketCartAllVillages { get; set; } = true;

        [SettingPropertyBool("Village Carts Best Market", HintText = "villagers take their load to the town within Market Max Distance that pays most for it per day of their journey - valued as that town's stalls would pay for it; their own town always counts, besieged and enemy towns never; a journey longer than the village storehouse can bear (it stops all work once full) earns less per day (off = the village's own town, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartsBestMarket { get; set; } = true;

        [SettingPropertyBool("Village Cart Full Load Far", HintText = "villagers setting out on a road longer than their storehouse can bear take everything their cart can carry, so the village does not stand idle and its goods do not lie waiting (needs Village Carts Best Market)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartFullLoadFar { get; set; } = true;

        [SettingPropertyBool("Village Cart Whole Store", HintText = "villagers setting out for a town market take the whole village storehouse every time - the district hires as many carts as the load needs, so a heavy load (ore, timber) neither stays behind nor slows the train; a journey counts as free only while they are back before the storehouse holds the next load (five days of the village's output, waits in town and at home included) - every day beyond that earns less, and a full storehouse stops all village work, food too. Takes the place of Village Cart Full Load Far (needs Village Carts Best Market; off = the game's three fifths of each stack, a full cart only for a long road)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartWholeStore { get; set; } = true;

        [SettingPropertyBool("Village Cart Road News", HintText = "villagers know what other carts are already hauling to a town and count it as if it were on the stalls, so they do not all drive their loads to the same empty market (needs Village Carts Best Market)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartRoadNews { get; set; } = true;

        [SettingPropertyBool("Village Cart Fair Price", HintText = "a town pays for a cartload piece by piece - each piece at the price its stall gives once the pieces before it lie there - not the whole load at the price of the first piece; what was overpaid goes back from the villagers' purse to the town's. Keep it on while Village Carts Best Market is on - carts sent to empty markets would otherwise take the first piece's price for the whole load out of those towns' purses (off = the whole load at the first piece's price, as the game does)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartFairPrice { get; set; } = true;

        [SettingPropertyBool("Castle Market First", HintText = "a castle's own villages sell it food for its people first - enough for ten days - and carry the rest of their load on to the town: a cart setting out for a town market calls first at the castle its village belongs to whenever that castle's market holds less of a food the cart carries than the people under its walls buy in Castle Market Food Days (each kind of food counted on its own, by what the castle folk spend on it each day); the castle buys only what is missing, at its own market price (piece by piece with Village Cart Fair Price), paid only from the coin its purse holds above the working coin (Castle Purse Enabled), and the cart goes straight on to the best town for the rest. The garrison's granary is not counted - the villages feed it as before. You and the AI alike. Off = the carts drive straight to the town market, as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CastleMarketFirst { get; set; } = true;

        [SettingPropertyFloatingInteger("Castle Market Food Days", 1.00f, 30.00f, "0", HintText = "how many days of each food the castle folk buy the castle market should hold before its villages' carts stop calling there first (1-30; needs Castle Market First)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float CastleMarketFoodDays { get; set; } = 10f;

        [SettingPropertyBool("Castle Cart Food Only", HintText = "a village cart that drives into a castle it was not bound for - as a rule to hide from raiders - sells there only the food the castle folk are short of and takes the rest of its load on to a town market, instead of leaving iron, timber and wool at a castle that uses none of it (needs Castle Market First; a cart with no town in reach still sells the castle its whole load, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CastleCartFoodOnly { get; set; } = true;

        [SettingPropertyBool("Village Takings Whole", HintText = "what a village's carts bring home from market no longer vanishes: after the lord's tax (Banner Kings: 70 percent, or 50 / 90 by the fief's tax decree) and the estate owners' cut, the village purse keeps the whole remainder - until now half of that remainder was simply deleted. The lord's tax, the estates and his tax counter stay exactly as Banner Kings sets them. Off = half the remainder vanishes as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageTakingsWhole { get; set; } = true;

        [SettingPropertyBool("Village Food Sales Kept", HintText = "coin a lord's party pays a village for what it buys there (food above all) no longer vanishes (the game took the whole price back out of the village purse as a tax nobody received): it stays in the village purse in full, just as the price does when you buy there yourself, and the lord gets his part later through the village rents. Off = the price vanishes as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageFoodSalesKept { get; set; } = true;

        [SettingPropertyBool("Villager Purse Survives", HintText = "the purse of a village cart party that is wiped off the map no longer vanishes with it: beaten in battle, what the game left after the victors' tenth goes to the victor as well - to the winning party's leader (to you, if you beat them) or into a bandit band's purse - just as villagers who surrender hand you the whole purse; disbanded, or with no victor able to take it, the purse goes home and is shared like takings (a cart with no home village leaves it in the purse of its home town or castle, or else of the nearest town). Off = the purse vanishes as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillagerPurseSurvives { get; set; } = true;

        [SettingPropertyBool("Map Road Table Fix", HintText = "the map's road table is completed when a campaign loads: the Realm of Thrones map was reworked after its road table was made, and the new spots by Wickenden, Lord Hewett's Town, Acorn Hall, Griffin's Roost, Pinkmaiden and a hideout had no entry, so every party standing there - in those settlements or on the road beside them - looked cut off from the whole world: Banner Kings refused all its orders, caravans thought every town too far, and lords, caravans and villagers stood there for good. Each spot the road table never saw gets the nearest gate by road, worked out exactly as the game's own map tool does; spots the tool saw and left empty (no road to any settlement) stay as they are. Nothing goes into the save - the table is read anew at every load (off = the table as the map ships it)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool MapRoadTableFix { get; set; } = true;

        [SettingPropertyBool("Village Cart Leave Town", HintText = "villagers who have sold their load in a town always set off again - Banner Kings refuses a 'go to' order whenever the map's road table has no entry for the spot a party stands on, and the gates of Wickenden, Lord Hewett's Town and Acorn Hall stand on such spots (the Realm of Thrones map was reworked after its road table was made), so carts that drove in there never left and their villages stopped all work; with this on, a village cart standing in a settlement may go wherever the game's own settlement road table knows a road (off = as Banner Kings decides, and Village Cart Town Max Days stands idle too)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageCartLeaveTown { get; set; } = true;

        [SettingPropertyFloatingInteger("Village Cart Town Max Days", 0.00f, 8.00f, "0.00", HintText = "a village cart still standing in a town this many days after it drove in is sent home with whatever it carries - nothing is made or lost; carts in a besieged town or one under attack wait as before. A sound cart leaves within hours (the game sends it home with one chance in five every hour), so two days catch only a cart that is truly stuck (needs Village Cart Leave Town; 0 = never)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float VillageCartTownMaxDays { get; set; } = 2f;

        [SettingPropertyBool("Island Roads Fix", HintText = "caravans and lords on islands are no longer left standing by a Banner Kings order to a place they cannot reach over land: a party with ships goes to the same place by land and sea; a caravan without ships picks the best town it can reach by land - by Banner Kings' own trade reckoning, else its home or the nearest town by road - and Banner Kings no longer picks towns across the water for such a caravan at all; if its island has no other town, it waits in town as the game's own caravans do when no trip pays; a lord whose Banner Kings feast or estate order cannot be carried out gets his own will back instead of standing frozen in a castle or town. Only orders change - nothing is made or lost (off = as Banner Kings decides)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool IslandRoadsFix { get; set; } = true;

        [SettingPropertyBool("Caravan Town Hourly", HintText = "a Banner Kings caravan standing in a town decides every hour again whether to buy and move on, as Banner Kings meant it - the Realm of Thrones patch let it decide only once a day, so caravans stood about three days in every town instead of about three hours. On the road the once-a-day limit stays. Expect more trade between towns. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CaravanTownHourly { get; set; } = true;

        [SettingPropertyInteger("Caravan Town Hourly Max Ticks", 0, 48, "0", HintText = "a caravan still standing in the same town after this many hourly looks goes back to one look a day until it leaves - a caravan with nowhere to go no longer costs time every hour. A healthy caravan with somewhere to go leaves within a few hours anyway. 0 = no limit", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public int CaravanTownHourlyMaxTicks { get; set; } = 12;

        [SettingPropertyBool("Island Caravan Fix", HintText = "a caravan without ships is no longer left stranded where it cannot trade: a lord does not buy one (Banner Kings) in a town, castle or village that has no road to two towns - his gold stays with him - and a caravan already standing in a town with no other town in reach by land is wound up: the town buys its goods out of its spare money, the purse goes to the owner, the men go home. Your own caravans are never touched. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool IslandCaravanFix { get; set; } = true;

        [SettingPropertyInteger("Notable Caravan Cap", 0, 12, "0", HintText = "a merchant keeps at most this many caravans; caravans asleep in the field count too. The game gave a merchant another caravan whenever none of his caravans was awake, so with night camps their number grew without end and every day took longer. Your own clan is never limited. 0 = the game's rule, no limit", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public int NotableCaravanCap { get; set; } = 3;

        [SettingPropertyBool("Village Clog Diagnostics", HintText = "log only, changes nothing in the game: once a day the Armoury log says why village storehouses stand full (one and a half times their size stops all village work) - village types, what lies in them, where each village's villagers are (at home, on the road and for how long, in town, none at all) and how many villages filled up or emptied that day; ten examples every five days (off = no such lines)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool VillageClogDiagnostics { get; set; } = true;

        [SettingPropertyBool("Caravan Bulk Enabled", HintText = "caravans haul bulk raw goods (iron ore, timber, raw hides, leather, flax, linen, wool) by need: a town short of its own stock buys what it lacks from any passing caravan, and a caravan leaving a town buys only what that town holds to spare (off = Banner Kings' price-driven caravan trade alone)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CaravanBulkEnabled { get; set; } = true;

        [SettingPropertyInteger("Caravan Bulk Stock Days", 0, 40, "0", HintText = "a town wants this many days of its own craftsmen's and workshops' use of each bulk good on its stalls - and never less than one large piece of work takes (8 loads of ore, 40 of timber)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public int CaravanBulkStockDays { get; set; } = 10;

        [SettingPropertyFloatingInteger("Caravan Bulk Surplus Factor", 0.00f, 8.00f, "0.00", HintText = "a town sells to caravans only what it holds above this many times the stock it wants for itself (2 = it keeps twenty days of use and sells the rest; never counted below 1)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float CaravanBulkSurplusFactor { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Caravan Bulk Capacity Share", 0.00f, 2.00f, "0.00", HintText = "at most this share of a caravan's carrying capacity goes to bulk raw goods, and no single one of them takes more than half of that - the rest stays free for its usual trade (never above 0.8)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float CaravanBulkCapacityShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Caravan Bulk Transit Cover", 0.00f, 24.00f, "0.00", HintText = "caravans keep buying a bulk good only while all of them together carry less than this many times what the towns of the world lack - above that they stop buying and unload it into any town up to its surplus mark (higher = fewer empty stalls, more cargo idling on the road; 0 = they never buy)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float CaravanBulkTransitCover { get; set; } = 6f;

        [SettingPropertyBool("Caravan Bulk Buy Before Route", HintText = "a caravan buys its bulk raw goods right after its usual purchases and before it picks the next town, so the fresh cargo already counts in that choice (off = it buys on its way out of the gate, when the destination is already set)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CaravanBulkBuyBeforeRoute { get; set; } = true;

        [SettingPropertyFloatingInteger("Caravan Bulk Fill Limit", 0.00f, 4.00f, "0.00", HintText = "bulk raw goods bought at a profit may fill a caravan's packs up to this share of its carrying capacity - Banner Kings stops its own buying at 0.8 and leaves the rest empty (0.8 = no more room than before; never below 0.8 or above 1; the player's own caravans always stay at 0.8)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public float CaravanBulkFillLimit { get; set; } = 1f;

        [SettingPropertyBool("Caravans No Ammo Trade", HintText = "caravans do not trade arrows and bolts: Banner Kings caravans (notables', lords' and your own) no longer buy them for trade, take them out of towns when leaving or head for towns just because arrows are cheap there, so quivers stay on the stalls where lords and garrisons buy them; arrows and bolts a caravan already carries are sold to the next town it enters, at the market price, from the town's purse above its rent reserve (whatever the town cannot pay for goes to the next town) - nothing is made or lost (off = caravans trade arrows and bolts as in Banner Kings)", RequireRestart = false)]
        [SettingPropertyGroup("The road to market")]
        public bool CaravansNoAmmoTrade { get; set; } = true;

        [SettingPropertyBool("Levy Enabled", HintText = "volunteers come forward only where there are men to spare: hands the fields do not need, and men who want to leave a poor, burnt or warring land", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool LevyEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Recruit Base Willing", 0.00f, 1.00f, "0.00", HintText = "younger sons and restless lads: the small chance of a volunteer even in a land that needs every hand (against Banner Kings' daily chance)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RecruitBaseWilling { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Recruit Excess Weight", 0.00f, 4.00f, "0.00", HintText = "how strongly hands without work on the land (Banner Kings workforce surplus) bring volunteers forward", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RecruitExcessWeight { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Recruit Misery Weight", 0.00f, 1.00f, "0.00", HintText = "how strongly poverty, war, burnt villages and hunger push men to leave and take service", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RecruitMiseryWeight { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Recruit Willing Max", 0.00f, 6.00f, "0.00", HintText = "ceiling on the willingness multiplier", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RecruitWillingMax { get; set; } = 1.5f;

        [SettingPropertyBool("Recruit Gold To Seller", HintText = "the gold an AI lord pays for a recruit goes to the notable who raised him (tavern hirelings: to the town), as it already does for you - not into thin air", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RecruitGoldToSeller { get; set; } = true;

        [SettingPropertyBool("No Free Kit For New Parties", HintText = "a new AI warband no longer gets a full free kit for all its men (Dynamic Troop Equipment) after the campaign has begun - its lord buys gear at market", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NoFreeKitForNewParties { get; set; } = true;

        [SettingPropertyBool("Volunteer Kit Enabled", HintText = "a volunteer rises to a better troop only when his notable buys the missing gear for it on the town market (paid to the town, taken off the stall) - no gear from thin air", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool VolunteerKitEnabled { get; set; } = true;

        [SettingPropertyBool("Volunteer Kit Key Only", HintText = "the volunteer rises once his notable buys the key pieces (body armour, main weapon - bow or crossbow plus one quiver for archers - and horse with harness for riders); helmet, shield, boots and the rest are bought if on the stall, otherwise they become orders for the workshops", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool VolunteerKitKeyOnly { get; set; } = true;

        [SettingPropertyBool("Cold Start Enabled", HintText = "new campaign only: the world does not start empty - lords and garrisons have the kit their men already wear in their armouries, and town stalls hold the craftsmen's stock", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ColdStartEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Cold Start Market Days", 0.00f, 240.00f, "0.00", HintText = "new campaign only: how many days of the town craftsmen's work lie on the stalls at the start (mostly common gear of the town's culture); two months of stock, because recruits no longer bring a second kit from thin air", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ColdStartMarketDays { get; set; } = 60f;

        [SettingPropertyBool("Cold Start Tier Up", HintText = "new campaign only: when the craftsmen's starting stock is laid out and a guild makes nothing as plain as the piece that was drawn, it lays out its next better piece instead of losing the rest of its share - armourers and shield makers no longer start with half-empty stalls. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ColdStartTierUp { get; set; } = true;

        [SettingPropertyBool("Cold Start Late Lord Parties", HintText = "new campaign only: an AI lord's warband raised in the first three days of the campaign starts with the kit its men already wear lying in its stores, like the warbands that stood on the map at the very start - once for each lord, so the first days are no longer one great rush on the markets. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ColdStartLateLordParties { get; set; } = true;

        [SettingPropertyBool("Historical Prices Enabled", HintText = "the whole world in historical prices (1 coin = 1 medieval penny): arms and armour priced from their real making cost, smithing materials at medieval prices - wages and incomes already sit at this scale", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistoricalPricesEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Hist Iron Ore Per Kg", 0.00f, 1.00f, "0.00", HintText = "iron ore, pence per kg (England c.1300, estimate) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistIronOrePerKg { get; set; } = 0.075f;

        [SettingPropertyFloatingInteger("Hist Wood Per Kg", 0.00f, 1.00f, "0.00", HintText = "timber and firewood, pence per kg (Clark/Rogers) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistWoodPerKg { get; set; } = 0.035f;

        [SettingPropertyFloatingInteger("Hist Charcoal Per Kg", 0.00f, 1.00f, "0.00", HintText = "charcoal, pence per kg (Clark/Rogers) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistCharcoalPerKg { get; set; } = 0.07f;

        [SettingPropertyFloatingInteger("Hist Crude Iron Per Kg", 0.00f, 5.60f, "0.00", HintText = "crude bloom iron, pence per kg (Tudeley bloom 3s 4d) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistCrudeIronPerKg { get; set; } = 1.4f;

        [SettingPropertyFloatingInteger("Hist Wrought Iron Per Kg", 0.00f, 10.00f, "0.00", HintText = "wrought bar iron, pence per kg (Clark/Rogers 1300-49: 1.15 d a pound) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistWroughtIronPerKg { get; set; } = 2.5f;

        [SettingPropertyFloatingInteger("Hist Iron Per Kg", 0.00f, 14.00f, "0.00", HintText = "refined iron, pence per kg (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistIronPerKg { get; set; } = 3.5f;

        [SettingPropertyFloatingInteger("Hist Steel Per Kg", 0.00f, 24.00f, "0.00", HintText = "steel, pence per kg (estimate) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistSteelPerKg { get; set; } = 6f;

        [SettingPropertyFloatingInteger("Hist Fine Steel Per Kg", 0.00f, 32.00f, "0.00", HintText = "fine steel, pence per kg (estimate) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistFineSteelPerKg { get; set; } = 8f;

        [SettingPropertyFloatingInteger("Hist Castle Steel Per Kg", 0.00f, 48.00f, "0.00", HintText = "castle-forged steel, pence per kg (fine steel plus a fifth of the metal lost and double charcoal) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistCastleSteelPerKg { get; set; } = 12f;

        [SettingPropertyFloatingInteger("Hist Leather Per Kg", 0.00f, 16.00f, "0.00", HintText = "tanned leather, pence per kg (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistLeatherPerKg { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Hist Linen Per Kg", 0.00f, 40.00f, "0.00", HintText = "linen and canvas for padding, pence per kg (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistLinenPerKg { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Hist Special Factor", 0.00f, 1.00f, "0.00", HintText = "horn, sinew and glue of bows, against the old game-scale bill (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistSpecialFactor { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Hist Master Wage T1", 0.00f, 12.00f, "0.00", HintText = "a smith's day of work on plain gear, pence (a craftsman earned about 3 d a day) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistMasterWageT1 { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Hist Master Wage Per Tier", 0.00f, 6.00f, "0.00", HintText = "each tier above the first adds this to the master's day (a master armourer of fine harness about 10 d) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistMasterWagePerTier { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Hist Profit Percent", 0.00f, 100.00f, "0.00", HintText = "the maker's profit on top of material and labour (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistProfitPercent { get; set; } = 25f;

        [SettingPropertyFloatingInteger("Town Wage Ref Prosperity", 0.00f, 19200.00f, "0.00", HintText = "a town this prosperous pays its craftsmen exactly the historical day wage (the middle town of Westeros and Essos); a richer town pays more, up to half again (London paid about half again the provinces), a poorer less, down to half (0 = the same everywhere)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownWageRefProsperity { get; set; } = 4800f;

        [SettingPropertyFloatingInteger("Hist Ammo Labor Multiplier", 0.00f, 32.00f, "0.00", HintText = "fletcher and arrowsmith work on a stack of arrows or bolts (a sheaf of 24 cost about 15 d) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistAmmoLaborMultiplier { get; set; } = 8f;

        [SettingPropertyFloatingInteger("Hist Tournament Scale", 0.00f, 16.00f, "0.00", HintText = "the game seeks tournament prizes worth 1600-5000; with historical prices the range is divided by this (400-1250 pence: a fine sword, a good harness piece). Used only while Hist Worth Windows Old Coin is off (or cannot reach the game's prize list): with it on, the range is compared with a piece's worth before the repricing and is not divided", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistTournamentScale { get; set; } = 4f;

        [SettingPropertyBool("Hist Quest Qty Old Coin", HintText = "quest quantities the game computes as a fixed sum divided by an item's price (gang axes and the guards' toll at the town gate, village crafting iron, The Art of the Trade, the overpriced artisan's goods, village tools, herds, draught animals and the meat offered for them, the gang's stolen goods, the smugglers' cargo) count from the piece's worth before the historical repricing - otherwise a quest asks for hundreds of pieces instead of a dozen. Rewards stay as they are. Applies to quests offered after loading; switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistQuestQtyOldCoin { get; set; } = true;

        [SettingPropertyBool("Hist Roguery Xp Old Value", HintText = "Roguery XP for raiding villages, looting villagers and caravans and forcing supplies counts the trade goods at their worth before the historical repricing, with the game's own factors (never less than the game gives) - otherwise cheaper goods slow Roguery 3-20 times, for you and for the AI lords. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistRogueryXpOldValue { get; set; } = true;

        [SettingPropertyBool("Hist Warehouse Xp Old Value", HintText = "Trade XP from your own workshops' output counts each piece at its worth before the historical repricing, as the game meant (never less than the game gives) - otherwise beer, pottery or tools give 6-26 times less Trade XP. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistWarehouseXpOldValue { get; set; } = true;

        [SettingPropertyBool("Hist Ai Loot Score Old Coin", HintText = "AI lords weigh the loot in their baggage at its worth before the historical repricing when they decide to ride to a town and sell it - otherwise cheap loot never seems worth a trip and arms return to the markets slowly. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistAiLootScoreOldCoin { get; set; } = true;

        [SettingPropertyBool("Hist Bandit Hideout Score Old Coin", HintText = "bandits weigh their plunder at its worth before the historical repricing when they decide to carry it back to their hideout - otherwise they hardly ever go home with loot. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistBanditHideoutScoreOldCoin { get; set; } = true;

        [SettingPropertyBool("Hist Hideout Loot Old Coin", HintText = "the extra goods you find after a night raid on a hideout are counted at their worth before the historical repricing, never as worth less than the game counts them (so never more goods than without it) - otherwise the game's sum buys many times more goods out of nothing. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistHideoutLootOldCoin { get; set; } = true;

        [SettingPropertyBool("Hist Old Coin From Definition", HintText = "for every rule that counts in the old coin (quest quantities, Roguery and Trade XP, the AI's and bandits' loot weights, hideout goods, the fence, company renown) the worth before the historical repricing of the Banner Kings goods that a Realm of Thrones patch divides by 100 (fur 125 becomes 1, gold ingot 1000 becomes 10, ink 200 becomes 2) is taken from the worth they were defined with - otherwise these goods count as worth 1-10 and, for one, the gang's stolen-goods quest can ask for thousands of furs. Off = the worth at load, as before. Switching it mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistOldCoinFromDefinition { get; set; } = true;

        [SettingPropertyBool("Hist Research From Old Value", HintText = "smithing part research (new parts for a weapon class) counts from a piece's worth before the historical repricing, as smithing XP already does - otherwise a forged sword worth 21 pence instead of 1105 gives almost no research and no new parts unlock", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistResearchFromOldValue { get; set; } = true;

        [SettingPropertyFloatingInteger("Hist Unique Prestige", 0.00f, 16.00f, "0.00", HintText = "named pieces of the great houses cost this many times their making (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistUniquePrestige { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Hist Bulk Unit Factor", 0.00f, 40.00f, "0.00", HintText = "ore and timber are sold by the load: one unit weighs this many times the game's 10 kg, so a unit costs whole pence (ore 100 kg = about 8 d, timber 100 kg = about 4 d) instead of a fraction of a penny rounded up to 1-2; village output, town use and every recipe are counted by weight, so nothing else changes. New campaigns only: with Bulk Unit Per Campaign a campaign keeps the load it was begun with (saved with it), and moving this slider later changes nothing in it", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistBulkUnitFactor { get; set; } = 10f;

        [SettingPropertyBool("Hist Trade Goods", HintText = "trade goods at historical prices too (grain, wine, tools, wool, silk, velvet, spices, ore of silver and gold...) - England c.1300 by the kilogram (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistTradeGoods { get; set; } = true;

        [SettingPropertyBool("Hist Livestock Prices", HintText = "farm animals at historical prices too (England mid-14th century, by the head): ox 157, cow 113, hog 30, sheep 17, goose 4, chicken 1 penny, where the game asked 300, 200, 60, 80, 50 and 50. Horses, mules and camels keep their worth, which is already about right. Town demand for these animals is counted in the new coin like every other repriced good, so towns buy as many head as before (needs Historical Prices Enabled; off = the game's worth; a change takes effect when a game is next loaded)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistLivestockPrices { get; set; } = true;

        [SettingPropertyFloatingInteger("Hist Hides Per Kg", 0.00f, 4.00f, "0.00", HintText = "raw hides, pence per kg (an ox hide of 25-30 kg sold for 1-3 shillings) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistHidesPerKg { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Hist Flax Per Kg", 0.00f, 8.00f, "0.00", HintText = "raw flax and hemp, pence per kg (estimate) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistFlaxPerKg { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Hist Bow Labor Multiplier", 0.00f, 4.00f, "0.00", HintText = "a bowyer's days on a bow, against the smith's model (a war longbow cost 12-18 d) (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HistBowLaborMultiplier { get; set; } = 1.0f;

        [SettingPropertyFloatingInteger("Harness Kg Per Armor", 0.00f, 1.00f, "0.00", HintText = "horse harness is priced by a real weight, not by the weight the game gives it: at most this many kilograms for each point of horse armour (and never under 3 kg) count in its worth, at the workshop, at your forge and in repairs - a Realm of Thrones barding of 140 kg was priced as 140 kg of plate, a saddle of 100 kg as 100 kg (0 = the game's weight, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HarnessKgPerArmor { get; set; } = 0.4f;

        [SettingPropertyFloatingInteger("Helm Days Per Kg", 0.00f, 3.00f, "0.00", HintText = "a plate helmet of tier 4 to 6 (of every tier with Helm One Rule) takes this many days of an armourer's work for each kilogram, plus half a day for each tier above the third - before, it was priced like a breastplate and cost three to five times a real bascinet (0 = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float HelmDaysPerKg { get; set; } = 1.0f;

        [SettingPropertyBool("Hist Bow Days New", HintText = "a bowyer makes a bow in one and a half to two and a half days, as a war bow sold for 12 to 18 pence says, instead of 2 to 12 days - bows of tier 3 to 6 cost a half to a third of what they did, and workshops make more of them in a day's work", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistBowDaysNew { get; set; } = true;

        [SettingPropertyBool("Hist Thrown Own Days", HintText = "javelins, throwing axes and throwing knives are priced by their own days of work; before, they also carried the eightfold fletcher's work of a sheaf of arrows (prices of items already in the world are recalculated after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistThrownOwnDays { get; set; } = true;

        [SettingPropertyBool("Hist Horse Prices", HintText = "horses by their kind: a common riding horse (tier 3, a rouncey) costs four tenths of the game's worth, a man-at-arms' war horse (tier 4) half as much again; pack horses, palfreys, chargers and noble horses keep their worth. Town demand for horses is counted in the new coin, so townsfolk buy as many of these horses as before (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistHorsePrices { get; set; } = true;

        [SettingPropertyBool("Xbow Like Bow", HintText = "a crossbow is priced at Xbow Price Vs Bow times the price of a bow of the same draw strength (Realistic Battle Mod draw weights). The extra price is the crossbow maker's longer work - more days at a master's day wage - so town workshops, repairs and your forge reckon the same work and nobody pockets a free margin. The game ranks crossbows as tier 1-2 goods, so the strongest crossbow (330 lb) cost 27 pence while the best longbow cost 48; the estimate after the change is about 117 (not yet checked in a game). Repeating crossbows keep their price (their draw is weak). Needs historical prices and Realistic Battle Mod; takes effect when a game is next loaded (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crossbows by draw strength")]
        public bool XbowLikeBow { get; set; } = true;

        [SettingPropertyFloatingInteger("Xbow Price Vs Bow", 1.00f, 3.00f, "0.00", HintText = "a crossbow's price as a multiple of the price of a bow of the same draw strength (a crossbow of a draw stronger than any bow is priced in proportion to its strength) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Crossbows by draw strength")]
        public float XbowPriceVsBow { get; set; } = 1.75f;

        [SettingPropertyBool("Xbow Forge Equiv Tier", HintText = "at your forge a strong crossbow asks the smithing skill and stamina of a bow of the same strength (the 330 lb crossbow those of a tier 6 bow), not those of its low game tier - otherwise it would be the cheapest way to make money in the game. Metal and materials stay as before", RequireRestart = false)]
        [SettingPropertyGroup("Crossbows by draw strength")]
        public bool XbowForgeEquivTier { get; set; } = true;

        [SettingPropertyBool("Xbow Buy By Power", HintText = "AI lords, garrisons and your men pick a crossbow on the stall by its power: effectiveness squared over price instead of effectiveness over price, so they buy the strong crossbow when they can pay for it and a lighter one when the purse is short, instead of light 80-100 lb crossbows (all crossbows but one sit in the same tier basket)", RequireRestart = false)]
        [SettingPropertyGroup("Crossbows by draw strength")]
        public bool XbowBuyByPower { get; set; } = true;

        [SettingPropertyBool("Town Household Use", HintText = "townsfolk buy only their household share of raw goods - flax, wool, hides and ore went to weavers, tanners and smiths, not into homes (England c.1300)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TownHouseholdUse { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Use Flax", 0.00f, 1.00f, "0.00", HintText = "share of the townsfolk's old appetite for raw flax they keep (home spinning)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseFlax { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Town Use Wool", 0.00f, 1.00f, "0.00", HintText = "share kept for raw wool", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseWool { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Town Use Hides", 0.00f, 1.00f, "0.00", HintText = "share kept for raw hides", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseHides { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Town Use Iron", 0.00f, 1.00f, "0.00", HintText = "share kept for iron ore - households bought nails and tools, never ore", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseIron { get; set; } = 0f;

        [SettingPropertyFloatingInteger("Town Use Leather", 0.00f, 2.00f, "0.00", HintText = "share kept for leather (shoes, belts, straps)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseLeather { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Town Use Linen", 0.00f, 1.60f, "0.00", HintText = "share kept for linen cloth (shirts, bedding)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseLinen { get; set; } = 0.4f;

        [SettingPropertyFloatingInteger("Town Use Hardwood", 0.00f, 4.00f, "0.00", HintText = "share kept for timber and firewood (hearths, bakers, brewers, building)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownUseHardwood { get; set; } = 1f;

        [SettingPropertyBool("Hist Demand Scaling", HintText = "town demand for each repriced kind of goods is counted in the new coin too - otherwise townsfolk with the old purse buy up tens of times more cheap swords, ore and cloth and the stalls run dry", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistDemandScaling { get; set; } = true;

        [SettingPropertyBool("Hist Demand From Definition", HintText = "the new-coin town demand of each kind of goods is reckoned from the worth its goods were defined with. A Realm of Thrones patch to Banner Kings divides the worth of every Banner Kings good by 100 (bread 20 becomes 0, honey 28 becomes 0, mead 120 becomes 1, fur 125 becomes 1), so bread, pies, fruit, honey, eggs, garum, papyrus and limestone kept their town demand in the old coin (bread up to 10 times its worth in big towns) and mead, fur, gold, ink and dyes got it many times too high. On: reckoned from the defined worth, like every other good; off = as before (a change takes effect when a game is next loaded)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistDemandFromDefinition { get; set; } = true;

        [SettingPropertyBool("Hist Mixed Category Shelf", HintText = "goods that share one town market but were repriced in opposite directions weigh on the stall by the share their makers gave them, not by their new worth. Gold ore became 8 times cheaper and the gold ingot nearly 5 times dearer than Banner Kings set them, so one ingot on a stall (worth 4750) counted like a hundred days of the whole town demand for gold: the first sold for about 2 in 5 parts of its worth, the next for less, and ore fetched 4.6 times its worth on a bare stall. On: an ingot weighs on the stall like 2.5 sacks of ore, as Banner Kings designed, so a bare stall pays about 1.2 times worth for an ingot and about 2 times for ore; the same rule evens apples, carrots and oranges, meat and whale meat, iron ingots beside ore. Prices are still paid in the new worth; kinds of goods with a single good do not change (needs Hist Demand Scaling; off = as before; a change takes effect when a game is next loaded)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistMixedCategoryShelf { get; set; } = true;

        [SettingPropertyBool("Price Formula In New Coin", HintText = "the game's price formula keeps a fixed 2 coins beside the worth of the goods on the stall; in the new coin that weighs like a quarter load of ore or a whole measure of salt, so a bare stall of a cheap good never grew dear (ore 1.5 times its worth at most, timber 0.8). On: every trade good the new coin made cheaper is priced as the unmodded game prices it - a bare stall up to 10 times worth, a glutted one down to a tenth; goods the new coin made dearer (fur, wool, raw silk, velvet) keep the fixed 2 coins, which weigh little beside them; and a new campaign opens with the towns' memory of supply and demand for every repriced trade good already in the new coin instead of drifting out of the old one for weeks (needs Hist Demand Scaling; off = prices as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PriceFormulaInNewCoin { get; set; } = true;

        [SettingPropertyBool("Raw Price By Use", HintText = "a town prices the seven bulk raw goods (iron ore, timber, raw hides, leather, flax, linen, wool) by what it really uses each day: the share of the townsfolk's old appetite that households truly buy, plus what its craftsmen and workshops work up - the same daily use the caravans stock it by. A town with a smithy and no ore pays many times its worth, a town sitting on a hundred days of use pays a fraction, and wool is dear only where someone weaves it. Arms workshops then pay the market price for ore and timber too (needs Hist Demand Scaling; off = demand and workshop prices as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RawPriceByUse { get; set; } = true;

        [SettingPropertyBool("Population Rent Enabled", HintText = "a fief pays by the people it stands for: each village and town on the map is a symbol of a whole land, and its lord's rents follow that land's population (the Reach richest, the Iron Islands poor)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PopulationRentEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Population Rent Per Head", 0.00f, 160.00f, "0.00", HintText = "rents and dues a lord draws from each subject a year, in coins (about 40 pence a head in the medieval estimate)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float PopulationRentPerHead { get; set; } = 40f;

        [SettingPropertyFloatingInteger("Population Scale", 0.00f, 4.00f, "0.00", HintText = "scale on every land's population (Westeros ~30 million, Essos with its hinterlands ~30 million)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float PopulationScale { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Population Max Per Hearth", 0.00f, 2600.00f, "0.00", HintText = "no village on the map stands for more people per hearth than this (650: a little above the most crowded land, Qarth with 629). A land above it - the Summer Isles, whose three small villages had to carry 4,500 people a hearth - keeps only what its villages can hold and the rest of its table population lies off the map (0.75 million -> about 0.11 million); its towns keep the same share. Takes effect in a new campaign; 0 = no cap", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float PopulationMaxPerHearth { get; set; } = 650f;

        [SettingPropertyBool("People Measure Enabled", HintText = "log only: daily lines accounting for every hearth, prosperity point and militia man gained or lost and why, prisoners taken, freed and changing sides, the realms' free hands, the Night's Watch and the Free Folk, the Others by place, and the bite of winter by realm - changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PeopleMeasureEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Population Rent Max Share", 0.00f, 1.00f, "0.00", HintText = "a village pays its lord at most this share of its purse each day (0.5 emptied the villages in a few days). Villages pay this rent only with Town Folk Live off - with the townsfolk's purse live they pay fixed dues instead (Village Dues Per Head Year)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float PopulationRentMaxShare { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Rent Tax Low", 0.00f, 2.80f, "0.00", HintText = "the fief's tax decree (Banner Kings) sets the rent: Low takes this share of the usual rent", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RentTaxLow { get; set; } = 0.7f;

        [SettingPropertyFloatingInteger("Rent Tax High", 0.00f, 5.20f, "0.00", HintText = "High tax takes this much of the usual rent (and Banner Kings costs loyalty for it)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RentTaxHigh { get; set; } = 1.3f;

        [SettingPropertyFloatingInteger("Rent Tax Exemption", 0.00f, 1.00f, "0.00", HintText = "Exemption: no rent at all", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RentTaxExemption { get; set; } = 0f;

        [SettingPropertyBool("Rent Replaces Town Tax", HintText = "one source of land income: Banner Kings' town population tax (paid from nothing) is replaced by rent from the town purse", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RentReplacesTownTax { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Rent Share", 0.00f, 1.00f, "0.00", HintText = "share of the town purse above the merchants' working coin that leaves it each day as rents, tolls and farms; with Town Purse Regulator on, the lord keeps Town Rent Lord Share of it and the crown the rest", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownRentShare { get; set; } = 0.07f;

        [SettingPropertyFloatingInteger("Town Rent Floor Gold", 0.00f, 80000.00f, "0.00", HintText = "with Town Purse Regulator 0 only: floor of a town purse for rents and taxes, as before (below 20 000 Banner Kings takes prosperity away)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownRentFloorGold { get; set; } = 20000f;

        [SettingPropertyBool("Council Wages Real Base", HintText = "Banner Kings council wages (1% to 4.5% of a fief's tax per seat) follow the income the lord really has: for a town or castle, its kept tax lines plus the day's rent (or the lord's share of the castle dues) instead of the town population tax the rents replaced; a house with no town or castle pays its council nothing. Off = Banner Kings as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool CouncilWagesRealBase { get; set; } = true;

        [SettingPropertyBool("Council Wages Paid To All", HintText = "every councillor receives the wage the council's lord pays, when it is paid: lords on a council (the lord's spouse and kin, kin of vassals, heads of other houses) are paid into their own purse as commoners already were - before, the wage of a lord who is not head of a house vanished; a dead councillor's wage goes back to the payer; when the lord's purse cannot cover the day's accounts even after his soldiers' pay is cut, the uncovered part of the council wages is taken back from the councillors (nothing from thin air). Off = Banner Kings as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool CouncilWagesPaidToAll { get; set; } = true;

        [SettingPropertyBool("Workshop No Free Raw", HintText = "nothing from thin air: the hidden town artisans no longer make timber, ore, hides, meat, leather and linen without any input, and a workshop roll never yields charcoal or ingots (those only come from smelting) - raw goods come from the villages", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool WorkshopNoFreeRaw { get; set; } = true;

        [SettingPropertyBool("Workshop No Free Raw All Types", HintText = "with Workshop No Free Raw: the same rule for every workshop, not only the hidden town artisans - a workshop line left with no input at all (the Banner Kings butcher's chicken and goose lines, whose input the game cannot read: about 33 meat a day out of nothing) no longer makes meat, hides, timber, ore, leather or linen; mines still dig ore. Off = only the hidden artisans, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool WorkshopNoFreeRawAllTypes { get; set; } = true;

        [SettingPropertyBool("Bk Workshop Inputs Fix", HintText = "TEST FIRST: the Banner Kings workshop lines whose second input the game cannot read get a real one - the bakery's grain-and-carrot and grain-and-orange pies take fruit (the apple goods) besides the grain, and the butcher's chicken and goose lines take two small animals (the animal goods) for one meat. Fewer pies until fruit reaches the towns (about 59% of all pies are made from grain alone today). Takes effect at the next load. Off = the lines as the game reads them", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool BkWorkshopInputsFix { get; set; } = false;

        [SettingPropertyBool("Village Fruit From Bk", HintText = "wheat farms grow carrots and apples, olive groves oranges, woodsmen and trappers honey - the Banner Kings list of village goods with its weights (2, 2, 2 and 0.5), grown the way the game grows any crop (the weight times the village's size step plus one, halved, each day). It is an extra crop: the village's own crops stay as they were (Banner Kings' own village model would share the village's work among them, but that model is not the one counting in this game). The game counted these goods as nothing, so no town ever had carrots, apples, oranges or honey; the village carts take them to market", RequireRestart = false)]
        [SettingPropertyGroup("Fruit and food on the stalls")]
        public bool VillageFruitFromBk { get; set; } = true;

        [SettingPropertyBool("Food Substitute When Short", HintText = "when a kind of food is missing from a town stall, the townsfolk spend part of that money on the nearest substitute that lies there in plenty (pie - bread, then grain; fruit - dates, grapes, olives; honey - butter, cheese; eggs - meat, cheese; grain and fish last). All the missing foods of a town together take at most half of what a substitute stall holds above the day's buying (counted after the townsfolk's own better-table spending), so the substitute stall is never emptied by it; the missing food's demand and price fall accordingly. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Fruit and food on the stalls")]
        public bool FoodSubstituteWhenShort { get; set; } = true;

        [SettingPropertyFloatingInteger("Food Substitute Share", 0.00f, 1.00f, "0.00", HintText = "the share of the townsfolk's unmet money for a missing food that goes to a substitute (the rest stays in their purse, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Fruit and food on the stalls")]
        public float FoodSubstituteShare { get; set; } = 0.5f;

        [SettingPropertyBool("Ai Food Skips Dear", HintText = "an AI party that is not starving does not buy food dearer than Ai Food Dear Index times its worth when cheaper food lies on the same stall - it picks among the cheaper ones (by value for money). A starving party still buys at any price", RequireRestart = false)]
        [SettingPropertyGroup("Fruit and food on the stalls")]
        public bool AiFoodSkipsDear { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Food Dear Index", 1.00f, 10.00f, "0.0", HintText = "price over worth above which a fed AI party looks for cheaper food on the same stall", RequireRestart = false)]
        [SettingPropertyGroup("Fruit and food on the stalls")]
        public float AiFoodDearIndex { get; set; } = 2.5f;

        [SettingPropertyBool("Historical Recruit Cost", HintText = "a recruit costs his prest money - some days of his pay (mercenaries twice that) - instead of the game's flat table by level", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool HistoricalRecruitCost { get; set; } = true;

        [SettingPropertyFloatingInteger("Recruit Cost Days", 0.00f, 40.00f, "0.00", HintText = "days of a troop's daily pay paid to take him on (historical prest/advance: a few to a dozen days of wages)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RecruitCostDays { get; set; } = 10f;

        [SettingPropertyBool("Companion Naval Skills Priced", HintText = "a wanderer's sailing skills count like body skills and party roles in his price and pay (Mariner like Riding, Boatswain and Shipmaster like Scouting or Engineering), not like command as Banner Kings counted them - about two fifths of a Realm of Thrones companion's skill premium came from the sea. The same rule sets the pay of heroes in every party and of your own mercenary contract", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public bool CompanionNavalSkillsPriced { get; set; } = true;

        [SettingPropertyBool("Companion Hire By Wage", HintText = "a wanderer asks half the worth of his gear plus Companion Hire Days of his daily pay to join you, like the prest of a sell-sword, instead of the Banner Kings skill premium (estimate, not yet checked in a game: a Realm of Thrones companion who asked about 15 000 would ask about 2 600). His daily pay does not change", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public bool CompanionHireByWage { get; set; } = true;

        [SettingPropertyFloatingInteger("Companion Hire Days", 0.00f, 60.00f, "0", HintText = "days of a wanderer's daily pay in his hiring price (a sell-sword's prest: Recruit Cost Days 10 x 2)", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public float CompanionHireDays { get; set; } = 20f;

        [SettingPropertyBool("Companion Wage By Level", HintText = "the daily pay of your companions and of your kin in your clan's parties (not you) follows their level and climbs steeply: about 1 at level 1, 3 at level 5, 8 at 10, 15 at 15, 25 at 20, 40 at 25 and 60 at level 30 (in between in a straight line), instead of the Banner Kings pay of about 100 a day for a level 19 companion. The pay is taken from your purse as before and goes into their own purse, not into thin air; a wanderer's hiring price stays Companion Hire Days of this pay plus half his gear", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public bool CompanionWageByLevel { get; set; } = true;

        [SettingPropertyBool("Companion Buys Own Gear", HintText = "in a town your companions and kin in your party spend their own coin on better gear from the market, as your soldiers do: only empty armour slots, armour at least one tier worse than what is on sale, or a weapon of the same kind at least one tier better; never a unique piece. They pay the town, keep Companion Gear Reserve Days of their pay, and the piece they take off goes into your inventory - nothing is lost. One message per town visit", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public bool CompanionBuysOwnGear { get; set; } = true;

        [SettingPropertyFloatingInteger("Companion Gear Reserve Days", 0.00f, 120.00f, "0.00", HintText = "days of his own daily pay a companion always keeps in his purse when he buys gear", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public float CompanionGearReserveDays { get; set; } = 30f;

        [SettingPropertyBool("Companion Autotest Hire", HintText = "FOR THE AUTOTEST ONLY: while the CrashScribe autotest runs, a free wanderer joins your party on the first day (you pay his hiring price, as in a tavern) and, on a day your clan's pay did not reach your companions, you pay their daily wage by hand - so the test sees companion pay and companion gear buying. In a normal game it does nothing", RequireRestart = false)]
        [SettingPropertyGroup("Hiring companions")]
        public bool CompanionAutotestHire { get; set; } = true;

        [SettingPropertyBool("Ammo Recovery Enabled", HintText = "arrows and bolts are spent: of those shot, the side holding the field gathers some back, some are mended, the rest are lost; the beaten side loses all it shot", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool AmmoRecoveryEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Ammo Recover Percent", 0.00f, 180.00f, "0.00", HintText = "share of shot arrows the winner picks up whole (estimate from Poitiers, Towton and the 1343 Breton shipment)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float AmmoRecoverPercent { get; set; } = 45f;

        [SettingPropertyFloatingInteger("Ammo Repair Percent", 0.00f, 80.00f, "0.00", HintText = "share of shot arrows mended by the army's fletchers (new fletching, heads) - the rest are broken or lost", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float AmmoRepairPercent { get; set; } = 20f;

        [SettingPropertyBool("Ammo Recovery By Side", HintText = "in a battle you fight yourself each side is judged by its own outcome: the men of the side that holds the field gather their shot arrows back (Ammo Recover Percent + Ammo Repair Percent), the men of the beaten side lose what they shot - before, your result decided for the enemy too (a beaten foe gathered arrows, a winning foe lost them all)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool AmmoRecoveryBySide { get; set; } = true;

        [SettingPropertyBool("Thrown As Missile", HintText = "javelins, throwing axes and throwing knives are missiles: they are spent by being thrown (some are gathered back after the battle, like arrows) and no longer get battered like a sword as well. A thrown weapon that is already damaged stays damaged until a smith mends it", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ThrownAsMissile { get; set; } = true;

        [SettingPropertyBool("Keep Wear Through Battle", HintText = "gear your men take into battle comes back in the state it went out (and worse after the fight) - worn mail no longer returns as new; damage piles up and must be repaired", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool KeepWearThroughBattle { get; set; } = true;

        [SettingPropertyBool("Start Kit Enabled", HintText = "starting gear you cannot wear (heavy armour your Athletics cannot carry) is swapped once, after character creation, for the best piece of the same kind you can wear - never dearer than the original", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool StartKitEnabled { get; set; } = true;

        [SettingPropertyInteger("Start Gold Adventurer", 0, 400, "0", HintText = "coins an Adventurer starts with in the Banner Kings start (Banner Kings gives 1000 - over a year of a labourer's pay); with Start Gold Cut it also sets the cut for every other start (this / 1000); -1 leaves Banner Kings as it is", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int StartGoldAdventurer { get; set; } = 100;

        [SettingPropertyBool("Start Gold Cut", HintText = "every coin you are handed at the start of a new campaign - the game's own 1000 and each Banner Kings start (Mariner 10000, Mercenary 250, Outlaw 50, Adventurer 1000), also a Banner Kings start picked later in an older save - is cut by the same ratio as the Adventurer (Start Gold Adventurer / 1000), so each start keeps its place against the others but in this world's coin; the start window shows the cut amounts; the rest was nobody's and is gone. Off = only the Adventurer and a start with no Banner Kings choice are cut, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool StartGoldCut { get; set; } = true;

        [SettingPropertyBool("Outlaw Law Enabled", HintText = "outlaws are real men: deserters, unpaid soldiers, men routed from battle, villagers driven off by raids, hunger and war; bands form only where such men exist and wear only what they brought, looted or bought", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawLawEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Seed Per Hearth", 0.00f, 1.00f, "0.00", HintText = "outlaws already in the woods when the campaign begins, per hearth of each region's villages (taken from those villages)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawSeedPerHearth { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Outlaw Daily Per Thousand Hearth", 0.00f, 1.00f, "0.00", HintText = "men a region loses to the woods each day per 1000 hearths, times its misery (poverty, war, burnt villages, hunger, lawlessness)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawDailyPerThousandHearth { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Outlaw War Misery", 0.00f, 2.00f, "0.00", HintText = "misery added while the region's realm is at war - no order, easy plunder", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawWarMisery { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Outlaw Looted Misery", 0.00f, 8.00f, "0.00", HintText = "misery added when all of a region's villages lie burnt (scaled by the share burnt)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawLootedMisery { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Outlaw Starving Misery", 0.00f, 6.00f, "0.00", HintText = "misery added while the region's town or castle is starving", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawStarvingMisery { get; set; } = 1.5f;

        [SettingPropertyInteger("Outlaw Prosperity Good", 0, 20000, "0", HintText = "prosperity at which a town counts as fully well-off (no misery from poverty)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int OutlawProsperityGood { get; set; } = 5000;

        [SettingPropertyFloatingInteger("Outlaw Return Base Percent", 0.00f, 2.00f, "0.00", HintText = "percent of a region's outlaws who go home each day in any times", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawReturnBasePercent { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Outlaw Return Peace Percent", 0.00f, 8.00f, "0.00", HintText = "extra percent going home each day in peace, scaled by prosperity", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawReturnPeacePercent { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Outlaw Routed Share", 0.00f, 2.00f, "0.00", HintText = "share of soldiers routed or fleeing a lost battle who take to the woods instead of going home (outlaws follow their own share, villagers always go home)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawRoutedShare { get; set; } = 0.5f;

        [SettingPropertyBool("Outlaw No Undead", HintText = "wights of the Others who fall away from their host (desertion) return to nothing instead of joining the outlaw pool of the region, and new and recruiting bands no longer draw the old wights still waiting in the pool (they fade away there as before) - the dead do not turn bandit (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawNoUndead { get; set; } = true;

        [SettingPropertyBool("Band Shields Stolen Arms", HintText = "bandits in battle no longer carry a bandit banner on their shields. A deserter or a soldier who fled a battle keeps the arms of the lord whose land he was raised from (else the nearest house of his own people, else his realm); a born outlaw carries shields stolen from the houses that hold the villages, castles and towns nearest the fight, a different one for each man. Never your own arms. Off = the bandit banner, as before", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool BandShieldsStolenArms { get; set; } = true;

        [SettingPropertyBool("Losers Flee Enabled", HintText = "battles fought without you: the beaten side mostly flees instead of dying - the slain follow the situation (horse to pursue, river or marsh behind, odds, seasoned men against levies), 5-65%; a few are taken; the rest go home or to the woods. The winner loses at most a few slain - the rest of his fallen are wounded. Your own battles fought on the field are not touched (auto-resolved ones: Losers Flee Player Auto)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LosersFleeEnabled { get; set; } = true;

        [SettingPropertyBool("Losers Flee Player Auto", HintText = "your own battles decided without you on the field (send troops / auto-resolve) follow the same rule as battles fought without you: the beaten side - theirs or yours - mostly flees, a few are taken, the slain follow the situation; the winner, you too, loses at most a few slain. Battles you fight on the field yourself, even in part, are not touched (needs Losers Flee Enabled)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LosersFleePlayerAuto { get; set; } = true;

        [SettingPropertyBool("Losers Flee Besiegers", HintText = "the same rule under the walls, in battles fought without you: a besieging host beaten by a sally from the fortress, or beaten in the open under the walls by the defenders and a relief force, and a relief force beaten by the besiegers' camp, mostly flees like a host beaten in the field instead of being slain or taken to the last man; the winner there, a garrison too, loses at most a few slain. The siege still ends and the beaten host is still scattered; the men who flee go home or to the woods. Storming the walls, the defenders of a fortress when they are beaten, and battles at sea are not touched. Your own battles under the walls: fought on the field - not touched; auto-resolved - as Losers Flee Player Auto says (needs Losers Flee Enabled; off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool LosersFleeBesiegers { get; set; } = true;

        [SettingPropertyFloatingInteger("Winner Death Cap Percent", 0.00f, 20.00f, "0.00", HintText = "the winner of a battle fought without you loses at most this share of his men slain; the rest of his fallen live, wounded (history: 1-5%)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public float WinnerDeathCapPercent { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Loser Captive Veteran Percent", 0.00f, 120.00f, "0.00", HintText = "of the beaten men who live, this share of seasoned troops (tier 4 and up) is taken - they were worth a ransom", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public float LoserCaptiveVeteranPercent { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Loser Captive Common Percent", 0.00f, 20.00f, "0.00", HintText = "of the beaten men who live, this share of the rest is taken", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public float LoserCaptiveCommonPercent { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Non Combatant Death Percent", 0.00f, 20.00f, "0.00", HintText = "villagers and fishermen beaten on the road: share slain; the rest run back to their own village (a few are taken only by peoples who keep slaves). Caravan guards fight and are judged like soldiers", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public float NonCombatantDeathPercent { get; set; } = 5f;

        [SettingPropertyBool("Destroyed Party Men Routed", HintText = "when the game strikes off a beaten host that still has men in it - caught while fleeing, left with only its wounded when the enemy broke off the fight, or a beaten besieger the victors did not take - those men no longer vanish with it: the victors take the same few as from any beaten host (seasoned men first), the rest scatter like any routed men (back to their lord's banner, home or to the woods), and the captives it held go free. Off = they vanish with the host, as before (needs Losers Flee Enabled)", RequireRestart = false)]
        [SettingPropertyGroup("The law of the battlefield")]
        public bool DestroyedPartyMenRouted { get; set; } = true;

        [SettingPropertyBool("Prisoner Law Enabled", HintText = "captives sold in a town or castle, or set free, in a land that keeps no slaves no longer become slaves: common men and soldiers go back to their own land, and in Westeros bandits and outlaws are sent to the Wall to take the black. Westeros but the Iron Islands, and Braavos, Pentos, Lorath and the other free lands, keep no slaves; Slaver's Bay, Qarth (with New Ghys, Qarkash and the City of Bones), Volantis, Lys, Myr, Tyrosh, Qohor, Norvos, Valyria, the Dothraki and the Iron Islands (thralls) do: there captives sold, by the lords or by you at the ransom broker, become slaves of that town or castle, and captives you set free or leave behind after your battles go home. A land follows the present culture of its town or castle. In every land the criminal policy of the town or castle (yours to choose in your own fiefs) rules alike for the lords' sales and yours: Execution - the captives are put to death, Forgiveness - none are enslaved and they go home", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PrisonerLawEnabled { get; set; } = true;

        [SettingPropertyBool("Player Ransom To Captor", HintText = "the ransom you pay from the captivity menu goes to your captor: the leader of the party that holds you, the head of its house if it has no leader, a bandit gang's hideout purse, or the lord of the town or castle whose dungeon holds you (failing them the head of the captor's house, then the purse of the nearest town) - off = the game's way, the money simply disappears", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PlayerRansomToCaptor { get; set; } = true;

        [SettingPropertyBool("Ransom Courier No Top Up", HintText = "when you accept a courier's ransom offer for a prisoner you hold, the paying house pays out of its own purse - the game no longer hands it the missing gold out of nothing; if it cannot raise the price the offer lapses and the prisoner stays with you (off = the game tops the payer up)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RansomCourierNoTopUp { get; set; } = true;

        [SettingPropertyBool("Ransom Harness In Autotest", HintText = "during the automatic test only: check the ransom rules once without putting you in captivity - a small real ransom from your purse to an AI lord on the 5th day of the session, the courier rules on the 8th - log only, does nothing outside the automatic test", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RansomHarnessInAutotest { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Band Routed Share", 0.00f, 2.00f, "0.00", HintText = "share of outlaws fleeing a lost fight who go back to the woods; the rest - mostly villagers driven out by want - go home to the villages", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawBandRoutedShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Outlaw Raid Flee Percent", 0.00f, 12.00f, "0.00", HintText = "percent of a village's hearths that flee to the woods when it is burnt - used only with Devastation Enabled off, with it on see Devastation Outlaw Base Percent and Devastation Outlaw Danger Percent", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawRaidFleePercent { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Outlaw Hearth Per Man", 0.00f, 2.00f, "0.00", HintText = "hearths a village loses for each man who becomes an outlaw (and regains when he returns); with People Unit Enabled this is only the most a man can cost in lands with very few people to a hearth", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawHearthPerMan { get; set; } = 0.5f;

        [SettingPropertyBool("People Unit Enabled", HintText = "one man is one man: a village on the map stands for a whole countryside, so each of its people who leaves or comes back is worth 1/k of a hearth (k = people one hearth of that village stood for when the campaign began: about 444 in the Reach, 132 in the North, 4 at the Wall) instead of the game's half a hearth - for outlaws, village caravans and fishing crews, routed villagers going home, men pressed by the player, and the hearths the player's village quests give or take. A village whose culture later changes keeps its people. Off = the game's rates as before. Change it only when you start a new campaign: people who left a village at one rate would come back at the other", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PeopleUnitEnabled { get; set; } = true;

        [SettingPropertyBool("Outlaws Counted By People", HintText = "outlaws are counted from a land's people, not from its number of villages: every village sends the same share of its people to the woods (at the start of a campaign, each day by misery, and when it is burnt), so the Reach has many outlaws and the Wall almost none. The per-hearth outlaw settings then mean hearths of the world's average village and the world's total stays the same. Works only with People Unit Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawsCountedByPeople { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Routed Home Days", 0.00f, 120.00f, "0.00", HintText = "soldiers routed from a battle and deserters hiding in the woods of a land at peace make their way home on average after this many days - a few weeks, as after medieval battles - unless a band takes them in first; villagers driven off by want or fire still go home with peace and prosperity. 0 = the old slow rate everywhere (half a percent a day in war)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawRoutedHomeDays { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Outlaw Routed Home Days War", 0.00f, 480.00f, "0.00", HintText = "the same in a land whose realm is at war with another realm (the endless wars with the Free Folk and the Others do not count): the war goes on around them, so routed soldiers and deserters stay in the woods far longer and feed the bands while the war lasts; when peace comes they drain away and the bands shrink back. 0 = the same as in peace", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawRoutedHomeDaysWar { get; set; } = 120f;

        [SettingPropertyBool("Disbanded Villagers Go Home", HintText = "a village caravan or fishing crew the game breaks up without a fight (no healthy men left, a lost party, too many boats) goes back to its village, the wounded too, instead of vanishing", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool DisbandedVillagersGoHome { get; set; } = true;

        [SettingPropertyBool("Natural Growth Enabled", HintText = "villages grow as medieval lands did: each village's people change by a yearly rate (births over deaths, better in a prosperous land, worse in war, raids and lawlessness) instead of the game's flat +4 / +1.2 / +0.2 hearths a day, which grew the world's people by over half in a year. A burnt or raided village does not grow. Hearth perks, buildings and laws no longer add hearths - they scale the growth. When the game lifts a nearly empty village back to 10 hearths, those people come from the outlaws of its land. Off = the game's hearth growth as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NaturalGrowthEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Growth Base Percent", 0.00f, 2.00f, "0.00", HintText = "yearly natural growth of a village's people, in percent, in an average land at peace (medieval England grew 0.2-0.8 percent a year before 1300)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthBasePercent { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Growth Prosperity Weight", 0.00f, 2.40f, "0.00", HintText = "percent a year added or taken by prosperity: the village's town or castle is compared with the middle one of its kind in the same land; half as rich or half again as rich moves growth by half of this", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthProsperityWeight { get; set; } = 0.6f;

        [SettingPropertyFloatingInteger("Growth Danger Weight", 0.00f, 2.40f, "0.00", HintText = "percent a year lost in the worst danger; danger is made of lawlessness of the town or castle (low security), the land's realm being at war with another realm (the endless wars with the Free Folk and the Others do not count), and the share of the region's villages burnt or under raid", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthDangerWeight { get; set; } = 0.6f;

        [SettingPropertyBool("Growth Hunger Enabled", HintText = "hunger slows natural growth: a village whose people went short of food from the granary of its countryside (Famine Enabled) loses growth by Growth Hunger Weight times the share of food missing, and while famine kills nobody is born beyond those who die. Off = growth ignores hunger", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool GrowthHungerEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Growth Hunger Weight", 0.00f, 6.00f, "0.00", HintText = "percent a year lost by a village with no food at all (a tenth short in the lean weeks before harvest costs a tenth of it); works only with Growth Hunger Enabled and Famine Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthHungerWeight { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Growth Max Percent", 0.00f, 3.20f, "0.00", HintText = "the most a village's people can grow in a year, in percent, after all bonuses (the best medieval decades)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthMaxPercent { get; set; } = 0.8f;

        [SettingPropertyFloatingInteger("Growth Max Decline Percent", 0.00f, 5.20f, "0.00", HintText = "the most a village's people can shrink in a year from natural causes, in percent (the Great Famine of 1315-17)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GrowthMaxDeclinePercent { get; set; } = 1.3f;

        [SettingPropertyBool("Town People Frozen", HintText = "a town's people are counted once and kept: the number of townsfolk (used for rents, the people ledger and the craftsmen's hands) no longer follows the town's prosperity up and down every day - it changes only with real births, deaths, recruits and newcomers (Town Growth Enabled needs this). Off = townsfolk are prosperity times the town's people per prosperity point, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TownPeopleFrozen { get; set; } = true;

        [SettingPropertyBool("Devastation Enabled", HintText = "a burnt village on the map stands for a whole countryside: raiders and foraging armies drive out only as many of its people as their numbers and days allow, instead of the game's two fifths of the village for every raid. A few of them die, a few take to the woods, the rest are refugees who come home within a year of the last raid in the region. The harvest falls with the share of people away. Raiders still get the game's plunder. Needs People Unit Enabled and Natural Growth Enabled. Off = as before (refugees still away come home the next day)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool DevastationEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Devastation Per Raider Day", 0.00f, 2.00f, "0.00", HintText = "people of a village's countryside driven from their homes by each raider for each day of looting (the great mounted raids of the 1350s drove out 0.3-0.9 a man a day, lesser raids 0.1-0.2)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float DevastationPerRaiderDay { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Devastation Per Forager Day", 0.00f, 1.00f, "0.00", HintText = "people driven from their homes by each soldier of a hostile army camped or marching beside the village for a day (see Forage Min Men and Forage Radius)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float DevastationPerForagerDay { get; set; } = 0.2f;

        [SettingPropertyInteger("Devastation Max Percent", 0, 95, "0", HintText = "the most of a countryside that can lie devastated at once, in percent of its people (at most 95) - the nearer to it, the less each new raid finds to burn", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationMaxPercent { get; set; } = 90;

        [SettingPropertyInteger("Devastation Killed Percent", 0, 100, "0", HintText = "percent of the people struck by a raid or by foraging who are killed, never more than one for each soldier for each day", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationKilledPercent { get; set; } = 2;

        [SettingPropertyInteger("Devastation Killed Slaver Percent", 0, 100, "0", HintText = "the same when the raiders' realm keeps slaves (they kill those who resist being taken)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationKilledSlaverPercent { get; set; } = 5;

        [SettingPropertyInteger("Devastation Outlaw Base Percent", 0, 100, "0", HintText = "percent of the people struck who take to the woods and join the region's outlaws in a quiet land (in place of Outlaw Raid Flee Percent)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationOutlawBasePercent { get; set; } = 2;

        [SettingPropertyInteger("Devastation Outlaw Danger Percent", 0, 100, "0", HintText = "extra percent who take to the woods at the worst danger (a lawless town or castle, a realm at war, burnt villages around)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationOutlawDangerPercent { get; set; } = 3;

        [SettingPropertyInteger("Devastation Captives Percent", 0, 100, "0", HintText = "percent of the people struck carried off as captives by raiders whose realm keeps slaves - taken from the village's refugees when the raid is won, only together with Raid Captives From Village; otherwise they stay refugees", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DevastationCaptivesPercent { get; set; } = 10;

        [SettingPropertyInteger("Refugee Return Quiet Days", 0, 120, "0", HintText = "no refugee goes home while a raid or a foraging army struck the region (the town or castle and its villages) within this many days", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int RefugeeReturnQuietDays { get; set; } = 30;

        [SettingPropertyInteger("Refugee Return Days", 30, 1092, "0", HintText = "after the quiet days the refugees come home evenly, all of the living by this many days after the last raid in the region (364 = one year); a siege of the town or castle holds them back, the rest come after it", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int RefugeeReturnDays { get; set; } = 364;

        [SettingPropertyFloatingInteger("Refugee Yearly Loss Percent", 0.00f, 20.00f, "0.0", HintText = "percent of the refugees who die each year while away from home (no births on the road)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RefugeeYearlyLossPercent { get; set; } = 1.3f;

        [SettingPropertyFloatingInteger("Devastation Yield Elasticity", 0.00f, 2.00f, "0.00", HintText = "how hard missing people cut a village's output: goods, ore and food are multiplied by (people at home / people of the village) to this power; 1 = output falls as fast as the people, 0 = not at all", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float DevastationYieldElasticity { get; set; } = 1f;

        [SettingPropertyBool("Looted Produces By People", HintText = "a plundered village keeps working with the people who stayed instead of producing nothing for two weeks (the harvest falls with the share of people away). Works only with Devastation Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool LootedProducesByPeople { get; set; } = true;

        [SettingPropertyBool("Famine Enabled", HintText = "every village stands for a countryside with a granary of its own: its fields give in an ordinary year a fifth more food than its people eat and the surplus fills the granary (beyond Famine Barn Years of food it goes to market as before); winter, raids, missing hands and a plundered village shrink the harvest by themselves. When the granary is empty and the harvest falls short people go hungry - a tenth short kills nobody, beyond that famine kills as in the great famines of history, and as many as die take to the road. When a town's food runs out its townsfolk starve too. Needs People Unit Enabled and Natural Growth Enabled. Off = no granaries, nobody dies of hunger (as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FamineEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Famine Yield Per Person", 0.50f, 3.00f, "0.00", HintText = "food a village's fields give in an ordinary year for each person who eats from them (1.2 = a fifth more than they eat; the harvest follows the game's food production of the village, so winter, raids and plunder cut it)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FamineYieldPerPerson { get; set; } = 1.2f;

        [SettingPropertyFloatingInteger("Famine Barn Years", 0.05f, 8.00f, "0.00", HintText = "the most food a countryside's granary holds, in years of its people's food", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FamineBarnYears { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Famine Start Share", 0.00f, 1.00f, "0.00", HintText = "how full the granaries are at the start of a campaign (and in a game saved before the granaries came), as a share of Famine Barn Years (1 = full - long summers before the war)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FamineStartShare { get; set; } = 1f;

        [SettingPropertyInteger("Famine Ration Days", 0, 360, "0", HintText = "when a granary holds less than this many days of food and the harvest does not feed the village, everyone eats a tenth less (nobody dies of it; growth slows)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineRationDays { get; set; } = 90;

        [SettingPropertyInteger("Famine Threshold Percent", 0, 90, "0", HintText = "how much food may be missing before people die of hunger, in percent (they eat less, eat substitutes, slaughter their animals); also the share beyond which nobody is born", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineThresholdPercent { get; set; } = 10;

        [SettingPropertyInteger("Famine Death Max Percent", 0, 100, "0", HintText = "yearly deaths with no food at all, in percent; deaths grow with the square of the food missing beyond the threshold (a third short - about 3.5% a year, as in 1315-17; half short - about 14%)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineDeathMaxPercent { get; set; } = 70;

        [SettingPropertyBool("Famine Flee Enabled", HintText = "as many as die of hunger leave their village and become refugees in the nearest land of the same realm (else of a realm not at war with it) whose granaries hold more than Famine Refuge Min Days of food; with none in reach they stay and starve. They go home once their village takes them back (see Famine Return Min Days), all of the living within Refugee Return Days of that day; refugees of a raid on the same village keep their own year from the last raid. Works only with Devastation Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FamineFleeEnabled { get; set; } = true;

        [SettingPropertyInteger("Famine Refuge Min Days", 0, 720, "0", HintText = "a land takes in famine refugees only while its granaries hold more than this many days of food for its own people and its guests", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineRefugeMinDays { get; set; } = 180;

        [SettingPropertyFloatingInteger("Famine Refuge Radius", 0.00f, 1000.00f, "0", HintText = "how far famine refugees go looking for a land with food (map distance from their town or castle)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FamineRefugeRadius { get; set; } = 250f;

        [SettingPropertyInteger("Famine Move Days", 0, 120, "0", HintText = "the refugees of a village move on to another land at most once in this many days", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineMoveDays { get; set; } = 30;

        [SettingPropertyInteger("Famine Return Min Days", 0, 360, "0", HintText = "nobody goes back to hunger: no refugee goes home while his village's people are starving, and refugees staying in another land do not go home in a season when the village's fields cannot feed a man (winter) unless its granary holds this many days of food for those at home. Refugees still in their own land eat from the same granaries, so only starving at home holds them back", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int FamineReturnMinDays { get; set; } = 90;

        [SettingPropertyBool("Famine Siege Shelter", HintText = "when a town or castle is besieged, the refugees of its land shelter behind its walls and eat from its food stores ('Refugees sheltering'); they stay until the siege ends and starve with the townsfolk when the food runs out. Works only with Famine Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FamineSiegeShelter { get; set; } = true;

        [SettingPropertyBool("Raid Refugees To Towns", HintText = "the people a raid drives from their homes go to the nearest town of their realm (else of a realm not at war with it, within Raid Refugees Town Radius) and live there among its labourers until they go home: they work for the town's wages, buy their food at its market like the town poor and bring their share of their village's purse with them (what is left goes home with them). They go home by the same rules as before (Refugee Return Quiet Days, Refugee Return Days); a siege of the town keeps them inside its walls, where they eat from its food stores and starve with the townsfolk when the food runs out. A town takes them in only when its people buy their food by the market basket of the start calibration and the town folk purses are on (otherwise nobody would feed them there); a town that can no longer take them in, or that goes to war with their realm, sends them back to their own land. With no such town in reach they stay in their own land as before. Works only with Devastation Enabled; off = raid refugees stay in their own land as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RaidRefugeesToTowns { get; set; } = true;

        [SettingPropertyFloatingInteger("Raid Refugees Town Radius", 0.00f, 1000.00f, "0", HintText = "how far raid refugees go looking for a town (map distance from their village; 0 = they never leave their land)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RaidRefugeesTownRadius { get; set; } = 250f;

        [SettingPropertyFloatingInteger("Raid Refugees Purse Share", 0.00f, 1.00f, "0.00", HintText = "the share of their village purse that raid refugees take with them: 1 = all of their own share (the village purse divided by its people), 0 = nothing", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RaidRefugeesPurseShare { get; set; } = 1f;

        [SettingPropertyInteger("Raid Refugees Message Min", 0, 10000, "0", HintText = "a message tells you when at least this many raid refugees reach in one day a town you own or the town you are in (0 = no message)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int RaidRefugeesMessageMin { get; set; } = 500;

        [SettingPropertyFloatingInteger("Raid Refugees Town Intake", 0.000f, 0.200f, "0.000", HintText = "how many new raid refugees a town takes in a day, as a share of its own people (0.01 = one in a hundred); the people of the first village that comes to it in a day are always taken in, the rest wait in their own land and come on the following days, so that refugees who gathered over a whole season do not all move into the towns on the one day the towns first can take them in. People driven from a village whose refugees already live in the town join them at once. With Raid Refugees Intake Meter on (the default) this daily intake counts everyone who comes, the first village comes whole only up to Raid Refugees Intake First Mult times the intake and newly driven people wait for room like the rest. 0 = no limit (all on one day)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RaidRefugeesTownIntake { get; set; } = 0.01f;

        [SettingPropertyBool("Famine Shared Village Refugees", HintText = "Realm of Thrones places a few villages on the map twice (two settlements share one village). The refugees of such a village eat from the granaries of the land they stay in and go hungry when those granaries run out, like the refugees of every other village. Works only with Famine Enabled. Off = the granaries never feed them and they never starve (as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FamineSharedVillageRefugees { get; set; } = true;

        [SettingPropertyBool("Granary Spoilage", HintText = "the grain stored in the countryside granaries slowly spoils (damp, mould, weevils, rats): each day a small share of what lies in a granary is lost, Granary Spoilage Percent Per Year in a year, so a granary no longer keeps its food untouched for ever. In an ordinary year the harvest surplus still fills it up to Famine Barn Years; in winter, after raids or in a siege it empties a little faster than its people eat. Works only with Famine Enabled; off = stored grain never spoils (as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool GranarySpoilage { get; set; } = true;

        [SettingPropertyFloatingInteger("Granary Spoilage Percent Per Year", 0.00f, 30.00f, "0.0", HintText = "with Granary Spoilage: the share of the stored grain lost in a year, in percent (6 = a well-kept village or manor granary; traditional farm stores lose about 5-10% of their grain a year), counted day by day over the game's year", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float GranarySpoilagePercentPerYear { get; set; } = 6f;

        [SettingPropertyBool("Raid Refugees Intake Meter", HintText = "raid refugees move into a town no faster than Raid Refugees Town Intake a day, counting everyone who comes that day: the people of new villages, the rest of a village that came only in part, and the people newly driven from a village whose refugees already live there. A village whose people do not all fit comes in part and the rest wait in their own land (eating from its granaries) and follow on the next days, the longest waiting first; the first village that comes to a town in a day is taken in whole only when it is no larger than Raid Refugees Intake First Mult times the daily intake. Those waiting go home first when their land is quiet again, and a siege of the town keeps in its walls only those already inside. A town too small to take in even one person a day is passed over and the village goes to the next town within reach. Off = the first village of a day always comes in whole and newly driven people join their kin in the town at once (as before); those still waiting when it is switched off (or when a save is loaded with it off) are not let in all at once - they keep coming in at Raid Refugees Town Intake a day, without the first-village exception, and only then the old rule applies", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RaidRefugeesIntakeMeter { get; set; } = true;

        [SettingPropertyFloatingInteger("Raid Refugees Intake First Mult", 1.00f, 10.00f, "0.0", HintText = "the first village that comes to a town in a day is taken in whole when its people are at most this many times the town's daily intake (2 = twice Raid Refugees Town Intake); a larger village comes in parts over the following days. Works only with Raid Refugees Intake Meter", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float RaidRefugeesIntakeFirstMult { get; set; } = 2f;

        [SettingPropertyBool("People Origin Enabled", HintText = "every soldier and captive remembers the land he came from: men who die are lost to that land for good, men who come home go back to its villages, and the people book of each land counts its men at home, under arms, held captive and fallen. Off = soldiers have no homeland, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PeopleOriginEnabled { get; set; } = true;

        [SettingPropertyBool("Levy From Villages", HintText = "a recruit leaves his village (1/k of a hearth, as any man who leaves it) or his town; a soldier from that land who comes home brings him back. Works only with People Origin Enabled and People Unit Enabled. Change it only when you start a new campaign", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool LevyFromVillages { get; set; } = true;

        [SettingPropertyBool("Press Untaken Go Home", HintText = "villagers you force into service but leave behind on the loot screen go back home to their village and its hearth instead of being lost to it", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PressUntakenGoHome { get; set; } = true;

        [SettingPropertyBool("Party Gone Men Go Home", HintText = "when a house falls (for example in a story event, or when its last lord dies) while one of its war parties is in the middle of a battle, the game pulls that party out of the fight and removes it; its living men now go home to their own lands (sworn brothers back to the Wall) instead of vanishing from the world. Parties of a fallen house that were not fighting already went home, and parties beaten in battle are not affected (off = the men pulled out of the battle vanish, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PartyGoneMenGoHome { get; set; } = true;

        [SettingPropertyBool("Party Gone Men Counted", HintText = "men lost with a vanished party are counted against the land they came from in the people book of that land, like the fallen, so each land's tally of its people stays whole - a book-keeping rule, nobody is added or removed (off = they leave the land's tally unexplained, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PartyGoneMenCounted { get; set; } = true;

        [SettingPropertyBool("Levy Village From Town", HintText = "when every village of a land is down to its last 50 hearths, a man recruited there comes from the people of the land's town instead of from nowhere", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool LevyVillageFromTown { get; set; } = true;

        [SettingPropertyBool("Town Levy By Share", HintText = "a man recruited in a town comes from the town only in proportion to the town's share of its land's people; the rest come from the land's villages. The number of recruits does not change. Off = the town gives every recruit until it is down to its last 100 people, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TownLevyByShare { get; set; } = true;

        [SettingPropertyBool("Prison Escape Go Home", HintText = "captives who slip away from an overfull party prison make their way home like freed captives (or to the woods, or to a tavern) instead of vanishing", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PrisonEscapeGoHome { get; set; } = true;

        [SettingPropertyBool("Garrison Levy From Bk", HintText = "a garrison filling its ranks from the notables of its town and villages takes the man from Banner Kings' population too, as any other recruit does", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool GarrisonLevyFromBk { get; set; } = true;

        [SettingPropertyFloatingInteger("Free Hands Share", 0.00f, 1.00f, "0.00", HintText = "share of a land's men who can leave the fields without the harvest suffering (counted with the fallen not yet made up by births)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FreeHandsShare { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Free Hands Harvest Factor", 0.00f, 1.00f, "0.00", HintText = "during the harvest weeks of a summer or autumn year only this part of that share is free", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FreeHandsHarvestFactor { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Free Hands Elasticity", 0.00f, 2.00f, "0.00", HintText = "how much the harvest falls when more men are away than the land can spare (0.5: a tenth fewer hands, a twentieth less harvest; 0 = not at all)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FreeHandsElasticity { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Free Hands Iron Islands Extra Max", 0.00f, 1.00f, "0.00", HintText = "Iron Islands: thralls work the land, so up to this much more of the men may go reaving (grows with the number of thralls)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float FreeHandsIronIslandsExtraMax { get; set; } = 0.2f;

        [SettingPropertyBool("Free Hands Brake", HintText = "a land with no free hands left raises no new volunteers until births make up its losses (the Free Folk and the Watch excepted)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FreeHandsBrake { get; set; } = true;

        [SettingPropertyBool("People Menu Entry", HintText = "'People of this land' in the menus of villages, towns and castles: the land's people at home, under arms, held captive, outlawed, fallen and its free hands", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PeopleMenuEntry { get; set; } = true;

        [SettingPropertyBool("People Menu Shows Bread", HintText = "'People of this land' also tells how many of the people of the town or castle you are in can afford their daily bread and their full basket, as reckoned at the last dawn (in a village: how much of the salt, tools, cloth, pots and ale they need the villagers bought at their market). Needs Town Folk Live", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PeopleMenuShowsBread { get; set; } = true;

        [SettingPropertyBool("Garrison Growth Only Recruits", HintText = "garrisons grow only from men who really join them - recruits the garrison pays for and men left by parties; the game's free daily growth (enlistment policy, rebels, quests) adds no one. The Night's Watch keeps it until it gets its own recruits from all of Westeros", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool GarrisonGrowthOnlyRecruits { get; set; } = true;

        [SettingPropertyInteger("Garrison Auto Recruit Per Day", 1, 5, "0", HintText = "a garrison may take up to this many paid recruits a day from the notables of its town and villages (the game allows 1) - only within its wage limit and free room, only men of that land, and not while the land has no free hands left; the Night's Watch keeps 1 (1 = as in the game)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int GarrisonAutoRecruitPerDay { get; set; } = 2;

        [SettingPropertyBool("Militia From Free Hands", HintText = "militia grows only from the free hands of its own land: each new militiaman leaves his village (1/k of a hearth) or town, a land with no free hands left raises no new militia, and militia that shrinks without a fight goes back home", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool MilitiaFromFreeHands { get; set; } = true;

        [SettingPropertyBool("New Party From People", HintText = "a lord raising a new party takes his men from the free hands of his seat's land, not out of thin air; with no free hands and no garrison to spare he rides out with fewer men and recruits the rest", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NewPartyFromPeople { get; set; } = true;

        [SettingPropertyBool("New Party From Seat Garrison", HintText = "when the land has no free hands left, a new party takes its men from the garrison of the lord's seat (the garrison keeps at least 25 men in a castle, 50 in a town; their gear goes with them)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NewPartyFromSeatGarrison { get; set; } = true;

        [SettingPropertyBool("New Party Grain From Seat", HintText = "the grain a new lord's party sets out with comes from the food stores of his seat (or the nearest fortress of his realm), not out of thin air", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NewPartyGrainFromSeat { get; set; } = true;

        [SettingPropertyBool("Food Sources In Ledger", HintText = "the goods ledger names what it used to call unexplained: the grain a new lord's party sets out with (paid from his seat's food stores), the fish that fishing boats catch at sea, and the goods of parties removed without a battle (supply convoys); and when no fortress of his realm has food to spare, the new party's grain no longer comes from nothing - it sets out without it and buys food at the next market (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool FoodSourcesInLedger { get; set; } = true;

        [SettingPropertyBool("Caravans From People", HintText = "a new caravan's guards and drivers are people of the town it sets out from (villagers, if it starts from a village), and a sea convoy fills its ranks from the town it reaches", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool CaravansFromPeople { get; set; } = true;

        [SettingPropertyBool("Travellers From People", HintText = "Banner Kings travellers and convoys are real people: they leave their home's people when they set out and join the people of the place they reach (most simply come back home); convoy escorts go back home when the convoy is done", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TravellersFromPeople { get; set; } = true;

        [SettingPropertyBool("Town Growth Enabled", HintText = "towns have their own births and deaths (a medieval town buried more than it baptised) and are refilled by people from their own villages when the land is not starving. Needs Town People Frozen and Natural Growth Enabled", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TownGrowthEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Growth Penalty Percent", 0.00f, 3.00f, "0.0", HintText = "how many points a year a town's natural rate stays below that of its villages (1 = London 1580-1650, about 0.87 births for each death)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float TownGrowthPenaltyPercent { get; set; } = 1.0f;

        [SettingPropertyInteger("Town Migration Refill Days", 0, 1456, "0", HintText = "villagers move to their town to cover its natural shortfall and the gap to its share of the land's people within about this many days (0 = only the natural shortfall)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int TownMigrationRefillDays { get; set; } = 364;

        [SettingPropertyBool("Veterans Enabled", HintText = "a tavern's hirelings are real men: soldiers who left service - released by their lord, routed from a lost battle, freed from captivity or sent off when their company was disbanded - and stopped at the nearest town to sell their sword. No hireling appears from nowhere; at the start the taverns hold the old soldiers already there. Off = taverns as in the game (veterans already waiting still go home in time)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool VeteransEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Veteran Share To Tavern", 0.00f, 1.00f, "0.00", HintText = "share of soldiers leaving service alive who stop at the tavern of the nearest town instead of going straight home", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float VeteranShareToTavern { get; set; } = 0.33f;

        [SettingPropertyInteger("Veteran Wait Days", 1, 1092, "0", HintText = "days a veteran waits in a tavern for a master before he gives up and goes home", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int VeteranWaitDays { get; set; } = 120;

        [SettingPropertyInteger("Veteran Min Tier", 1, 7, "0", HintText = "only a soldier of at least this tier stops at a tavern - a green levy would stand there as a seasoned sellsword he never was; lower ranks always go home", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int VeteranMinTier { get; set; } = 3;

        [SettingPropertyBool("Veteran Purse Follows Man", HintText = "a soldier's coin goes where he goes: when a released soldier stops at a tavern, his share of the company purse stays with him and he spends it in that town - a tenth a day like soldiers in the field (Sutler Daily Share), the rest when the last veteran leaves; whoever hires him takes his savings into the men's purse, and the hire money itself goes into the purse of the men hired, not into the town's coffers. You and the AI alike. Needs Men Purse Enabled (the hire money also Recruit Gold To Seller). Off = released soldiers' purses go to their villages and the hire money to the town (yours vanishes), as before; coin already held by veterans is spent in their towns at once", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool VeteranPurseFollowsMan { get; set; } = true;

        [SettingPropertyBool("Village Book Enabled", HintText = "every map village keeps its own people and its share of the district's harvest: raids and foraging armies empty its settlements (the side facing the raiders burns first), famine leaves them abandoned, and they stand again as their people come home - within a year of the last raid in the land. Shown in 'People of this land' and in the map village tooltip. Needs Devastation Enabled to burn anything. Off = all map villages stand, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool VillageBookEnabled { get; set; } = true;

        [SettingPropertyInteger("District Settlement People", 50, 1000, "0", HintText = "people of one settlement (a village with its fields) when a district is first reckoned; a district's villages share its settlements. Change it only when you start a new campaign", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int DistrictSettlementPeople { get; set; } = 250;

        [SettingPropertyBool("Town Food By Village People", HintText = "the food a town or castle gets from each of its villages follows the people at home and at work there, as the village's own harvest does: villagers away cut it, and a plundered village keeps feeding its castle with the people who stayed instead of nothing. Off = as in the game", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool TownFoodByVillagePeople { get; set; } = true;

        [SettingPropertyBool("Watch Law Enabled", HintText = "every man who joins the Night's Watch comes from the Seven Kingdoms: first the convicts sent to the Wall, then outlaws who take the black, then common folk of every land by its numbers. A brother never goes home: routed or disbanded he walks back to the Wall, and a deserter hides among the outlaws of the North", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool WatchLawEnabled { get; set; } = true;

        [SettingPropertyInteger("Watch Pool Share Percent", 0, 12, "0", HintText = "percent of a land's outlaws who may take the black in a single day", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int WatchPoolSharePercent { get; set; } = 3;

        [SettingPropertyBool("Watch Does Not Raid", HintText = "the Night's Watch holds the Wall: its rangers fight beyond it but never burn villages", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool WatchDoesNotRaid { get; set; } = true;

        [SettingPropertyBool("Thrall Law Enabled", HintText = "captives sold where slavery is the custom (the Iron Islands, Slaver's Bay, the Free Cities that keep slaves, Qarth) become slaves of that land: they bear no children and some die each year; the thralls of the ironborn let more free men go reaving", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ThrallLawEnabled { get; set; } = true;

        [SettingPropertyInteger("Thrall Yearly Loss Percent", 0, 20, "0", HintText = "slaves who die each year", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ThrallYearlyLossPercent { get; set; } = 5;

        [SettingPropertyInteger("Iron Islands Start Thralls", 0, 108000, "0", HintText = "thralls already working the Iron Islands when a new campaign begins - counted out of the islands' people, not added to them. Takes effect only in a new campaign", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronIslandsStartThralls { get; set; } = 27000;

        [SettingPropertyBool("Raid Captives From Village", HintText = "captives carried off in a raid are villagers taken from the plundered village - a tenth of those the raid struck - and only raiders whose realm keeps slaves take them; the Banner Kings captives out of thin air end (your own Take or Leave choice stays)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool RaidCaptivesFromVillage { get; set; } = true;

        [SettingPropertyBool("Debtor Disbands Home", HintText = "a house whose creditors hold its villages sends the men it can no longer pay home to their own lands instead of letting them desert to the woods", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool DebtorDisbandsHome { get; set; } = true;

        [SettingPropertyBool("Debtor Home Nearest Village", HintText = "a landless house with no realm (sellswords between contracts) that its creditors hold sends the men it cannot pay to the nearest village instead of to the woods", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool DebtorHomeNearestVillage { get; set; } = true;

        [SettingPropertyInteger("Outlaw Min Band", 0, 24, "0", HintText = "fewest men needed nearby before a new band can form", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int OutlawMinBand { get; set; } = 6;

        [SettingPropertyInteger("Outlaw Neighbour Regions", 0, 16, "0", HintText = "a new band gathers men from its own region and this many nearest ones", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int OutlawNeighbourRegions { get; set; } = 4;

        [SettingPropertyFloatingInteger("Outlaw Band Size Scale", 0.00f, 4.00f, "0.00", HintText = "size of a new band against the game's usual size (still only as many as there are men)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawBandSizeScale { get; set; } = 1f;

        [SettingPropertyInteger("Outlaw Daily Recruit", 0, 10, "0", HintText = "men a band can take in each day from the outlaws of the region it roams", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int OutlawDailyRecruit { get; set; } = 2;

        [SettingPropertyFloatingInteger("Outlaw Prisoner Join Percent", 0.00f, 40.00f, "0.00", HintText = "percent of a band's healthy prisoners who join it each day (green men sooner than veterans)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawPrisonerJoinPercent { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Outlaw Commoner Max Armor Kg", 0.00f, 32.00f, "0.00", HintText = "a commoner joins a band as its clan's lowest bandit only if that troop wears body armour this light; otherwise as a looter", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawCommonerMaxArmorKg { get; set; } = 8f;

        [SettingPropertyBool("Outlaw Gear Upgrades", HintText = "a bandit rises in rank only with gear for it: armour and horse from the band's loot, or bought from a fence in a town within reach", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawGearUpgrades { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Fence Radius", 0.00f, 800.00f, "0.00", HintText = "reach of the fences: a band deals with every unbesieged town this near and takes the best bargain; a band with no town this near still reaches the nearest one, on the far-edge terms", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawFenceRadius { get; set; } = 200f;

        [SettingPropertyFloatingInteger("Outlaw Fence Markup", 0.00f, 6.00f, "0.00", HintText = "what the fence asks over an item's value when the band stands at the town's gates", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawFenceMarkup { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Outlaw Fence Markup Far", 0.00f, 8.00f, "0.00", HintText = "what the fence asks over an item's value at the edge of his reach - the price rises evenly with the road he must ride (armour and horses are light for their worth, so less steeply than plunder loses value)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawFenceMarkupFar { get; set; } = 2f;

        [SettingPropertyBool("Outlaw No Free Gold", HintText = "bands get no gold from nowhere: only what they plunder (no daily top-up, no purse at birth beyond a few coins a man)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawNoFreeGold { get; set; } = true;

        [SettingPropertyInteger("Outlaw Coins Per Man", 0, 10, "0", HintText = "coins each man of a new band is handed from what its home hideout holds above the kept hoard, as far as that goes (no surplus or no hideout - the band starts with none)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int OutlawCoinsPerMan { get; set; } = 2;

        [SettingPropertyBool("Outlaw Fence Buys Loot", HintText = "bands sell their plunder to the fences of the towns within reach, each piece where it pays the band best: trade goods, livestock and food go back on the town's shelves, and the town pays from its purse above the merchants' floor", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawFenceBuysLoot { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Fence Loot Share", 0.00f, 2.00f, "0.00", HintText = "share of the town's buying price the fence hands a band standing at the town's gates - the rest is the fence's cut and stays in the town's purse", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawFenceLootShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Outlaw Fence Loot Share Far", 0.00f, 1.00f, "0.00", HintText = "share of the town's buying price the fence hands a band at the edge of his reach - it falls evenly with the road and the risk of carting stolen goods", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawFenceLootShareFar { get; set; } = 0.25f;

        [SettingPropertyBool("Outlaw Fence Dothraki Arms", HintText = "with Gear Fit Dothraki Only: an arakh or other Dothraki weapon in the stores of a band led by a chief (only such bands keep stores) that none of its men may carry goes into its packs, and the band sells it to a fence like the rest of its loot - the town pays and the piece goes on its stall (off = it stays in the band's stores, and whoever beats the band takes it)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawFenceDothrakiArms { get; set; } = true;

        [SettingPropertyBool("Outlaw Fence Buys Spare Animals", HintText = "bands also sell the animals they have no use for: pack beasts beyond what their remaining packs weigh, and riding horses beyond one for every man on foot", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawFenceBuysSpareAnimals { get; set; } = true;

        [SettingPropertyBool("Outlaw No Free Food", HintText = "bands get no food from nowhere (they do not eat in this game - what they carry is plunder), and so the fence takes their food too; off = the game hands every new band food again and the fence leaves food alone", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawNoFreeFood { get; set; } = true;

        [SettingPropertyBool("Outlaw No Hideout Gold", HintText = "a band coming home no longer gets a quarter of the worth of its packs as gold from nowhere, and neither does its hideout", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawNoHideoutGold { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Hideout Stash Share", 0.00f, 1.00f, "0.00", HintText = "share of its own purse a band leaves in the hideout's hoard each time it comes home - real coin, found by whoever clears and searches the hideout (0 = nothing is put by)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawHideoutStashShare { get; set; } = 0.25f;

        [SettingPropertyBool("Outlaw Hoard Circulates", HintText = "a hideout's hoard is spent, not only heaped: whatever lies above the kept hoard hands new bands their first coins, tops up its bands when they are short at the fence, and goes on their living in town", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool OutlawHoardCirculates { get; set; } = true;

        [SettingPropertyFloatingInteger("Outlaw Life Spend Share", 0.00f, 1.00f, "0.00", HintText = "share of its purse a band spends each day on food, drink and company in the nearest open town - and the share of a hoard's surplus its hideout spends the same way (0 = nothing is spent)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float OutlawLifeSpendShare { get; set; } = 0.1f;

        [SettingPropertyBool("Climate Enabled", HintText = "the seasons of Westeros: one season at a time lasting for years, its end proclaimed by a white raven from the Citadel; dates name the season of the day ('Year 299, Day 256, Autumn')", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ClimateEnabled { get; set; } = true;

        [SettingPropertyBool("Climate Drives Economy", HintText = "food, harvests, sickness, travel and the AI's winter caution (RealisticBannerlord, BetterEconomy, StrategicCampaignAI) follow the long seasons too - a winter of years is a hungry one", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool ClimateDrivesEconomy { get; set; } = true;

        [SettingPropertyInteger("Climate Summer Days So Far", 0, 14560, "0", HintText = "how long the summer has already lasted when the campaign begins (the summer that lasted ten years)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ClimateSummerDaysSoFar { get; set; } = 3640;

        [SettingPropertyInteger("Climate Summer Days Left Min", 0, 480, "0", HintText = "fewest days the long summer still lasts after the campaign begins", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ClimateSummerDaysLeftMin { get; set; } = 120;

        [SettingPropertyInteger("Climate Summer Days Left Max", 0, 1080, "0", HintText = "most days the long summer still lasts after the campaign begins", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ClimateSummerDaysLeftMax { get; set; } = 270;

        [SettingPropertyInteger("Climate First Autumn Days Min", 0, 1200, "0", HintText = "the first autumn lasts at least this many days", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ClimateFirstAutumnDaysMin { get; set; } = 300;

        [SettingPropertyInteger("Climate First Autumn Days Max", 0, 1800, "0", HintText = "the first autumn lasts at most this many days", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int ClimateFirstAutumnDaysMax { get; set; } = 450;

        [SettingPropertyFloatingInteger("Climate First Winter Years Min", 0.00f, 12.00f, "0.00", HintText = "the first winter lasts at least this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateFirstWinterYearsMin { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Climate First Winter Years Max", 0.00f, 20.00f, "0.00", HintText = "the first winter lasts at most this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateFirstWinterYearsMax { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Climate Spring Years Min", 0.00f, 4.00f, "0.00", HintText = "later springs last at least this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateSpringYearsMin { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Climate Spring Years Max", 0.00f, 12.00f, "0.00", HintText = "later springs last at most this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateSpringYearsMax { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Climate Summer Years Min", 0.00f, 8.00f, "0.00", HintText = "later summers last at least this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateSummerYearsMin { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Climate Summer Years Max", 0.00f, 32.00f, "0.00", HintText = "later summers last at most this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateSummerYearsMax { get; set; } = 8f;

        [SettingPropertyFloatingInteger("Climate Autumn Years Min", 0.00f, 4.00f, "0.00", HintText = "later autumns last at least this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateAutumnYearsMin { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Climate Autumn Years Max", 0.00f, 8.00f, "0.00", HintText = "later autumns last at most this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateAutumnYearsMax { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Climate Winter Years Min", 0.00f, 8.00f, "0.00", HintText = "later winters last at least this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateWinterYearsMin { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Climate Winter Years Max", 0.00f, 24.00f, "0.00", HintText = "later winters last at most this many years", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float ClimateWinterYearsMax { get; set; } = 6f;

        [SettingPropertyBool("Crown Dues Enabled", HintText = "vassals owe the crown a share of their daily income (fief income and rents), paid into the kingdom treasury - small in peace, heavy in war as with medieval war taxes", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool CrownDuesEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Dues Peace Percent", 0.00f, 8.00f, "0.00", HintText = "share of a vassal house's daily income owed to the crown in peace (aids and dues)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float CrownDuesPeacePercent { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Crown Dues War Percent", 0.00f, 12.00f, "0.00", HintText = "share owed while the realm is at war (aids, scutage in place of service) - the war tax itself is paid by the subjects (lay subsidy below)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float CrownDuesWarPercent { get; set; } = 3f;

        [SettingPropertyBool("Lay Subsidy Enabled", HintText = "in war the realm's towns and villages pay a war subsidy (the fifteenth and tenth) from their purses into the kingdom treasury", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool LaySubsidyEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Lay Subsidy Town Share", 0.00f, 1.00f, "0.00", HintText = "share of a town's purse above the merchants' floor paid each day of war", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float LaySubsidyTownShare { get; set; } = 0.01f;

        [SettingPropertyFloatingInteger("Lay Subsidy Village Share", 0.00f, 1.00f, "0.00", HintText = "share of a village purse paid each day of war (above its 15 days of purchases)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float LaySubsidyVillageShare { get; set; } = 0.025f;

        [SettingPropertyFloatingInteger("Lay Subsidy War Tax Multiplier", 0.00f, 8.00f, "0.00", HintText = "with the War Tax policy the subsidy is this many times heavier", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float LaySubsidyWarTaxMultiplier { get; set; } = 2f;

        [SettingPropertyBool("Crown Customs Enabled", HintText = "every crown takes customs on trade: a share of each town's toll counter goes to the kingdom treasury (the wool custom of 1275)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool CrownCustomsEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Customs Share", 0.00f, 1.00f, "0.00", HintText = "share of a town's daily toll counter taken as customs", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float CrownCustomsShare { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Crown Customs Duty Multiplier", 0.00f, 8.00f, "0.00", HintText = "with the Crown Duty policy the customs are this many times heavier", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float CrownCustomsDutyMultiplier { get; set; } = 2f;

        [SettingPropertyBool("Policy Income Conserved", HintText = "Debasement and State Monopolies no longer make gold from nothing: the mint's profit comes out of the realm's town purses, monopoly dues out of workshop capital; foreign caravans no longer bring 500 from nothing under trade agreements; Banner Kings' village tax office is replaced by the rent", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool PolicyIncomeConserved { get; set; } = true;

        [SettingPropertyFloatingInteger("Debasement Share", 0.00f, 1.00f, "0.00", HintText = "share of each town purse above the merchants' floor the crown takes each day while it debases the coin", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float DebasementShare { get; set; } = 0.005f;

        [SettingPropertyBool("Monopoly From Daily Profit", HintText = "State Monopolies: in the towns of the ruling clan the ruler takes 5% of what a workshop pays its owner that day, out of the workshop's capital - not 5% of all the profit the workshop has piled up, which was several times the policy's five percent, taken every day. Off = the old reckoning", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool MonopolyFromDailyProfit { get; set; } = true;

        [SettingPropertyBool("Besieged Pay Nothing", HintText = "a besieged town, castle or village pays no rents, dues or war taxes while the siege lasts: its lord's rent and the crown's Crown Duty, War Tax and Road Tolls stay in its purse - but only where the purse holds real coin (a town with Town Purse Regulator 1 or 2, a castle with Castle Purse Enabled); elsewhere the game's daily regulator would delete most of what stays, so such a place pays as before (the war subsidy, the customs and a castle's dues were never taken during a siege, and a village being raided or looted pays nothing - as before). You and the AI alike. Off = a besieged town keeps paying its lord's rent and a besieged town or castle the crown's policy dues, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool BesiegedPayNothing { get; set; } = true;

        [SettingPropertyBool("No Rot Clan Bailout", HintText = "Realm of Thrones no longer hands every poor AI house Tier x 5000 gold a day from thin air - a house short of money borrows from the Iron Bank or goes bankrupt", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NoRotClanBailout { get; set; } = true;

        [SettingPropertyBool("No Free Kingdom Gold", HintText = "the kingdom treasury no longer refills from thin air (vanilla +1000 a day and random windfalls of 100-400 thousand); it lives on what the houses pay in - change needs a game restart", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool NoFreeKingdomGold { get; set; } = true;

        [SettingPropertyInteger("Iron Bank Min Days To Lend", 0, 120, "0", HintText = "the Bank lends no more to a house whose running debt falls due within this many days - pay first", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankMinDaysToLend { get; set; } = 30;

        [SettingPropertyFloatingInteger("Iron Bank Loan Fee Percent", 0.00f, 8.00f, "0.00", HintText = "fee the Iron Bank adds to every loan, owed with the debt - no free same-day borrowing", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankLoanFeePercent { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Iron Bank Default Seize Share", 0.00f, 2.00f, "0.00", HintText = "share of a defaulter's purse the Bank seizes at once when he defaults (then 25% a day as before)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankDefaultSeizeShare { get; set; } = 0.5f;

        [SettingPropertyBool("Iron Bank Enabled", HintText = "the Iron Bank of Braavos lends to lords (AI and you): wages and war chests on credit, repaid daily with interest and from the spoils of war - and woe to those who do not pay", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool IronBankEnabled { get; set; } = true;

        [SettingPropertyInteger("Iron Bank Capital", 0, 20000000, "0", HintText = "gold the Bank starts with; loans draw it down, repayments with interest fill it up - an empty Bank lends nothing", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankCapital { get; set; } = 5000000;

        [SettingPropertyFloatingInteger("Iron Bank Income Days", 0.00f, 240.00f, "0.00", HintText = "a house may borrow this many days of its income, plus its fiefs as surety", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankIncomeDays { get; set; } = 60f;

        [SettingPropertyInteger("Iron Bank Per Town", 0, 40000, "0", HintText = "surety the Bank counts for every town a house holds", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankPerTown { get; set; } = 10000;

        [SettingPropertyInteger("Iron Bank Per Castle", 0, 20000, "0", HintText = "surety the Bank counts for every castle a house holds", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankPerCastle { get; set; } = 5000;

        [SettingPropertyInteger("Iron Bank Wage Days", 0, 40, "0", HintText = "an AI lord borrows when his gold will not cover this many days of his armies' wages (twice that at war)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankWageDays { get; set; } = 10;

        [SettingPropertyFloatingInteger("Iron Bank Rate King", 0.00f, 80.00f, "0.00", HintText = "yearly interest for a king (percent)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankRateKing { get; set; } = 20f;

        [SettingPropertyFloatingInteger("Iron Bank Rate Landed", 0.00f, 120.00f, "0.00", HintText = "yearly interest for a house with fiefs (percent)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankRateLanded { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Iron Bank Rate Landless", 0.00f, 180.00f, "0.00", HintText = "yearly interest for a house without fiefs (percent)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankRateLandless { get; set; } = 45f;

        [SettingPropertyFloatingInteger("Iron Bank Rate Per Loan", 0.00f, 40.00f, "0.00", HintText = "extra yearly interest when a debt is already running (percentage points)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankRatePerLoan { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Iron Bank Rate After Default", 0.00f, 60.00f, "0.00", HintText = "extra yearly interest for a house that has defaulted before (percentage points)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankRateAfterDefault { get; set; } = 15f;

        [SettingPropertyFloatingInteger("Iron Bank Player Default Renown", 0.00f, 400.00f, "0.00", HintText = "renown you lose when the Bank writes your name among those who did not pay", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public float IronBankPlayerDefaultRenown { get; set; } = 100f;

        [SettingPropertyInteger("Iron Bank Log Per Day", 0, 60, "0", HintText = "how many loans and repayments are written to the log each day (the daily total always is)", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public int IronBankLogPerDay { get; set; } = 15;

        [SettingPropertyBool("Iron Bank Family Pays", HintText = "AI houses only: before the Iron Bank marks an instalment as missed or lends anew, the grown members of the house hand their head what is lacking - only what each holds above 5000 gold or Iron Bank Wage Days (default 10) of his own party's wages, whichever is more", RequireRestart = false)]
        [SettingPropertyGroup("Iron Bank")]
        public bool IronBankFamilyPays { get; set; } = true;

        [SettingPropertyBool("Soldier Pay To Purse", HintText = "the wages a party is actually paid no longer vanish: they go to the purse of its men, who spend them in the towns (mending, missing kit, food and drink) - your own men too; needs Men Purse Enabled", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool SoldierPayToPurse { get; set; } = true;

        [SettingPropertyBool("Garrison Pay To Coffers", HintText = "the wages a garrison is actually paid go to the purse of the town or castle it guards - the soldiers spend them on the spot; your own garrisons too", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool GarrisonPayToCoffers { get; set; } = true;

        [SettingPropertyBool("Crown Wage Refund Enabled", HintText = "a kingdom at war repays its houses a share of the wages they actually paid that day, out of the kingdom treasury and only while there is gold in it (shared out pro rata when it runs short); no refund in peace, to mercenaries or to houses without a kingdom", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool CrownWageRefundEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Wage Refund Percent", 0.00f, 280.00f, "0.00", HintText = "share of the day's wages the treasury of a kingdom at war repays to each of its houses (0-100)", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public float CrownWageRefundPercent { get; set; } = 70f;

        [SettingPropertyBool("Crown Refund By Need", HintText = "the crown repays wages by need: a house whose family gold is below its war reserve gets the full share, a house holding more than twice its war reserve pays for its own war and gets nothing, and in between the share falls evenly the richer the house is. Judged on the house's budget of the day before; your own house the same way. Houses without a budget, in debt or under seizure keep the full share (off = every house gets the full share, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool CrownRefundByNeed { get; set; } = true;

        [SettingPropertyBool("Crown Wage Refund Garrisons", HintText = "the refund counts garrison wages too; off = wages of the parties in the field only", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool CrownWageRefundGarrisons { get; set; } = true;

        [SettingPropertyBool("Town Wage Shield", HintText = "wages spent in a town (garrison pay, the men's spending on leaving) are kept out of reach of the game's daily town-purse regulator, which otherwise deletes a quarter of everything above its target each day: they stay until the lord's rents and the war subsidy draw them out, and what is still there after about two weeks the regulator may take; castles unchanged. Mind the side effect: with it a garrison in one's own town costs its lord next to nothing, for the pay comes back to him in rents. Not needed and idle with Town Purse Regulator on - nothing deletes town coin any more", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's pay")]
        public bool TownWageShield { get; set; } = true;

        [SettingPropertyBool("Castle Purse Enabled", HintText = "a castle's purse holds real coin: the game no longer deletes what lies above its target each day (it still tops a purse up towards the working coin when it runs low), and the goods the castle folk use up no longer pay gold into it from nowhere (the goods are still used up). What the garrison's pay, the builders and the buyers bring in stays there until it is spent or leaves as the dues under the walls. Off = the game's daily regulator and purchases from nowhere, as before", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastlePurseEnabled { get; set; } = true;

        [SettingPropertyInteger("Castle Purse Floor Gold", 0, 40000, "0", HintText = "working coin the sutlers under the castle walls keep before any dues are drawn - the fixed part (the game's own target for a castle purse is 10 000 plus 12 a point of prosperity, about 22 000 for a common castle); the working coin never falls below that target, whatever these two settings say - below it the game tops a purse up from nowhere and the dues would hand that top-up to the lords, so these settings can only raise it", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public int CastlePurseFloorGold { get; set; } = 10000;

        [SettingPropertyFloatingInteger("Castle Purse Floor Per Prosperity", 0.00f, 48.00f, "0.00", HintText = "... and the part of the working coin that grows with the castle's prosperity, in coins a point", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public float CastlePurseFloorPerProsperity { get; set; } = 12f;

        [SettingPropertyFloatingInteger("Castle Dues Share", 0.00f, 1.00f, "0.00", HintText = "share of the castle purse above the working coin that leaves it each day as the dues under the walls: the garrison spends its pay with the lord's own people - alehouse, mill and stalls - as a town pays its rents; nothing is drawn from a besieged castle (0 = nothing is drawn and the purse only grows). Who takes it is set by Castle Dues Split With Crown and Castle Dues Lord Share", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public float CastleDuesShare { get; set; } = 0.07f;

        [SettingPropertyBool("Castle Dues Split With Crown", HintText = "the castle's daily dues are shared with the crown: the lord keeps Castle Dues Lord Share of them (two thirds) and the rest goes to the treasury of his kingdom, which pays it back to the houses as wage refunds in war. A castle held outside any kingdom pays everything to its lord. Towns share theirs by Town Rent Lord Share when Town Purse Regulator is on (the town's purse). Off = the lord takes all of it", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastleDuesSplitWithCrown { get; set; } = true;

        [SettingPropertyFloatingInteger("Castle Dues Lord Share", 0.00f, 1.00f, "0.00", HintText = "of what the castle purse gives up each day its lord keeps this share and the kingdom treasury takes the rest (needs Castle Dues Split With Crown; 1 = all to the lord, 0 = all to the crown). Two thirds to the lord, one third to the kingdom treasury - you and the AI lords alike: a garrison's pay spent in its own castle comes back to its lord at most at two thirds of a coin", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public float CastleDuesLordShare { get; set; } = 0.67f;

        [SettingPropertyBool("Castle Garrison Pay Comes Home", HintText = "in war the crown no longer repays the part of a castle garrison's pay that has come back to the castle's lord through the dues: each day what the lord's own share of his castles' dues brought him is taken off the pay the crown repays him (never more than his castle garrisons were paid). Repaid by the crown as well, that coin would earn him more than the garrison costs - you and the AI lords alike. Whatever the sutlers under the walls spend on goods never comes back, so it is repaid as before, and so is the part the men keep for their own kit. Town garrisons are left as they are until the crown's refund is reworked (stage 2, step C). Off = the crown repays castle garrison pay in full, as before", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastleGarrisonPayComesHome { get; set; } = true;

        [SettingPropertyBool("Castle Purse Trim At Start", HintText = "once per campaign, on its first day: the starting gift in every castle purse (20 000 plus Banner Kings' 40 a point of prosperity) is cut down to the working coin. The game's regulator deleted that gold within two weeks anyway; left in, the castle lords would draw about five million from nowhere. A save a few days old loses only what the regulator had not yet deleted; an old save loses nothing. Turned on later in a campaign that ran the castle purse without it, it removes only what the dues have not yet drawn from the gift (they draw Castle Dues Share of it a day, most of it within a month)", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastlePurseTrimAtStart { get; set; } = true;

        [SettingPropertyBool("Castle Carts Need Coin", HintText = "villagers whose market town lies beyond Market Max Distance sell at their lord's castle only when its purse holds enough above the working coin to pay for the whole cartload; otherwise they take the long road to the market town (off = they haul to the castle whether it can pay or not)", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastleCartsNeedCoin { get; set; } = true;

        [SettingPropertyBool("Castle Pays From Surplus", HintText = "a castle purse pays for its other purchases too only with the coin it holds above the working coin, as it does for cartloads: merchants bringing horses and harness to the castle, cloth and shoes for its garrison, the garrison's spare kit and the old pieces it sells when it buys better, the loot you sell there, and the crown's customs and war tax taken from it. Below the working coin the game tops the purse up from nowhere, so whatever was spent from it was in truth paid from nowhere. Needs Castle Purse Enabled. Off = the castle spends its whole purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("The castle's purse")]
        public bool CastlePaysFromSurplus { get; set; } = true;

        [SettingPropertyInteger("Town Purse Regulator", 0, 2, "0", HintText = "0 = the game's daily town-purse regulator as before; 1 = it never deletes coin from a town or castle purse and tops it up only up to the merchants' working coin, counted in the log; 2 = it does nothing at all - no coin is deleted and none comes from nowhere, in towns and castles alike (castles with Castle Purse Enabled). With 1 or 2 a town purse is real coin: the goods the townsfolk use up no longer pay gold into it from nowhere, its lord and the crown draw the dues from what lies above the working coin, and the wage and court shields are no longer needed. Use 1 if town purses run dry", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public int TownPurseRegulator { get; set; } = 2;

        [SettingPropertyInteger("Town Purse Floor Gold", 0, 40000, "0", HintText = "working coin the merchants of a town keep before any dues or taxes are drawn and below which the town buys nothing for us - the fixed part (the game's own target is 10 000 plus 12 a point of prosperity); never below that target, so these settings can only raise it", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public int TownPurseFloorGold { get; set; } = 10000;

        [SettingPropertyFloatingInteger("Town Purse Floor Per Prosperity", 0.00f, 48.00f, "0.00", HintText = "... and the part of the working coin that grows with the town's prosperity, in coins a point", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public float TownPurseFloorPerProsperity { get; set; } = 12f;

        [SettingPropertyBool("Town Folk Buy Without Minting", HintText = "the goods the townsfolk use up still leave the market, but no longer pay their price into the town purse from nowhere (off with the regulator on: that gold stays and the dues hand it to the lords - for tests only)", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool TownFolkBuyWithoutMinting { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Rent Lord Share", 0.00f, 1.00f, "0.00", HintText = "of what a town purse gives up each day its lord keeps this share and the kingdom treasury the rest - you and the AI alike (a town held outside any kingdom pays everything to its lord). With Castle Lords Even Up while the townsfolk's purse is live, Town Rent Lord Share With Folk is used instead", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public float TownRentLordShare { get; set; } = 0.67f;

        [SettingPropertyBool("Town Purse Trim At Start", HintText = "once per campaign, on its first day: the starting gift in every town purse (20 000 plus Banner Kings' 40 a point of prosperity) is cut down to the working coin - the game's regulator deleted that gold within two weeks anyway; an old save loses nothing", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool TownPurseTrimAtStart { get; set; } = true;

        [SettingPropertyBool("Town Purse No Bk Skim", HintText = "Banner Kings no longer deletes 1% a day from a town purse above its limit (and from a castle purse, with Castle Purse Enabled); a notable still helps an empty purse with 1 000 as before", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool TownPurseNoBkSkim { get; set; } = true;

        [SettingPropertyBool("Town Purse No Bk Skim Villages", HintText = "Banner Kings no longer deletes 1% a day from a village's coin above its limit (10 000 plus 3 a hearth) - half of it from the village and half from one of its notables; a notable still helps an empty village with 1 000 as before", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool TownPurseNoBkSkimVillages { get; set; } = true;

        [SettingPropertyBool("Town Pays From Surplus", HintText = "a town purse buys for us only with the coin it holds above the working coin: loot from outlaws, contract and bulk goods and arrows from caravans, spare kit of garrisons, lords and your men, drill scrap, the armourers' finished wares - as castles do. Below the working coin the game topped a purse up from nowhere, so whatever was bought from it was in truth paid from nowhere. Needs Town Purse Regulator. Off = the whole purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool TownPaysFromSurplus { get; set; } = true;

        [SettingPropertyBool("Alley Cash Probe", HintText = "log only: for the poorest towns whose purse is below the merchants' working coin a daily line splits the change of its purse by where the coin went and came from - our daily reckoning (item by item), villagers' carts, lords, notables, caravans, other parties, villages and the rest - so the cause of an empty purse can be read from the log; changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool AlleyCashProbe { get; set; } = true;

        [SettingPropertyBool("Idle Caravan Disband", HintText = "a caravan without ships that has stood in the same town for 28 days although roads lead to other towns (it finds no trade worth the road - a Thenn merchant's caravan stood there 289 days) is wound up the way a caravan stranded on an island is: its goods are sold to the town only with coin the town has to spare, the rest go to the town's market, its purse goes home to its owner and its men go home (off = it waits, as in the game)", RequireRestart = false)]
        [SettingPropertyGroup("The town's purse")]
        public bool IdleCaravanDisband { get; set; } = true;

        [SettingPropertyBool("Crown Current Income", HintText = "the crown pays out of what comes in each day: the vassals' dues, the war subsidy, customs, its share of the castle dues and whatever else reaches the treasury that day, plus a slow release of the old hoard above Crown Reserve Gold (one part in Crown Reserve Release Days a day). Wage refunds, gifts to other crowns, reparation instalments and mercenary contracts come out of that, in this order; what is not there is not paid (no debt). The refund counts only the parties in the field, not garrisons (their pay comes back through the dues), less what the party's men spent in their own house's towns. Works only together with Clan Budget Enabled (a crown paying from its income without the houses keeping their armies within their means would ruin them). Off = the refund comes out of whatever lies in the treasury, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownCurrentIncome { get; set; } = true;

        [SettingPropertyInteger("Crown Reserve Gold", 0, 2000000, "0", HintText = "gold the treasury keeps untouched as its reserve; only the hoard above it is released, slowly, to pay the crown's dues (about two months of refunds for a common realm)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int CrownReserveGold { get; set; } = 500000;

        [SettingPropertyFloatingInteger("Crown Reserve Release Days", 30.00f, 1440.00f, "0", HintText = "the hoard above the reserve is released over this many days: each day one part in this many of it is added to the day's income (450 = about a fifth of the hoard in a hundred days)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownReserveReleaseDays { get; set; } = 450f;

        [SettingPropertyFloatingInteger("Crown Refund Own Towns Cut", 0.00f, 1.00f, "0.00", HintText = "with Crown Current Income: the share of what a party's men spent in the towns of their own house that is taken off the wages the crown repays (1 = all of it - the coin came back to the house through its town's dues; 0 = nothing taken off); with the town purse valve on, the cut follows the lord's share of the valve", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownRefundOwnTownsCut { get; set; } = 1f;

        [SettingPropertyBool("Crown Reparations Realm", HintText = "with Crown Current Income: war reparations agreed at peace (Diplomacy) become a debt of the paying crown to the receiving crown, paid in daily instalments out of the payer's daily income; the receiving treasury gets exactly the instalment. The houses pay nothing and no house falls into debt to the crown over it; no gold is handed out from nothing to the king and the mercenaries. Off = Diplomacy's own reparations, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownReparationsRealm { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Reparation Share", 0.00f, 1.00f, "0.00", HintText = "the largest share of the paying crown's daily income that goes to reparation instalments each day", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownReparationShare { get; set; } = 0.5f;

        [SettingPropertyBool("Crown Customs Single Take", HintText = "with Crown Current Income: the crown's customs come from the town's toll counter alone - no second take from the town purse for the same customs", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownCustomsSingleTake { get; set; } = true;

        [SettingPropertyBool("Crown Dues From Land", HintText = "with Crown Current Income: the vassal dues are reckoned on the land part of a house's steady income (its villages, towns and castles), not on the money it gets from the crown itself (refunds, rents) - the crown takes no dues from its own payments. Needs Clan Income Book Stable D; without a measured steady income the old base is used", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownDuesFromLand { get; set; } = true;

        [SettingPropertyBool("Clan Budget Enabled", HintText = "AI houses keep only as many men as their steady income allows: each day a house's wage ceiling (its parties, garrisons and caravans together) is set from its steady income - in peace about a quarter of it, in war three fifths plus a share of its war chest above the reserve; garrisons stay full in war and are held at half their war strength in peace. A house above its ceiling for three days sends 15% of the excess home each day (garrison men above the peace target first, then hired mercenaries, then the lowest tier) - the men return to the nearest village of the house, with a share of the party's purse; the game no longer drives men off for wages over the limit. The house also pays its court into the purse of its seat, its grown members top up its head's purse, and its arms purchases and building works come out of their own shares. AI houses in a realm only, not mercenaries; you are never budgeted. Off = armies as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool ClanBudgetEnabled { get; set; } = true;

        [SettingPropertyBool("Ai Wage Limit Desertion Off", HintText = "with Clan Budget Enabled: the game no longer drives men of budgeted AI houses away for wages over the party limit - the budget sends the excess home instead (no one lost to the woods); desertion from an overfull party and from unpaid garrison wages stays", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool AiWageLimitDesertionOff { get; set; } = true;

        [SettingPropertyBool("Clan Budget Stable D", HintText = "the budget reckons on the house's steady income (land of the fiefs it holds today, crown, contract, workshops and caravans); off = the plain 28-day average of all its income", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool ClanBudgetStableD { get; set; } = true;

        [SettingPropertyFloatingInteger("Peace Wage Share", 0.00f, 1.12f, "0.00", HintText = "wage ceiling in peace: this share of the steady income a day (parties, garrisons and caravans together)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float PeaceWageShare { get; set; } = 0.28f;

        [SettingPropertyFloatingInteger("War Wage Share", 0.00f, 2.40f, "0.00", HintText = "wage ceiling at war: this share of the steady income a day, plus the war chest below", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarWageShare { get; set; } = 0.6f;

        [SettingPropertyFloatingInteger("Peace Chest Share", 0.00f, 1.60f, "0.00", HintText = "in peace the wage ceiling also gets this share of the war chest (the house's gold above its war reserve, spent as at war): a house at peace keeps a third of its army and half its garrisons from its savings instead of sending almost everyone home; 0 = the peace ceiling from the steady income alone", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float PeaceChestShare { get; set; } = 0.4f;

        [SettingPropertyFloatingInteger("Household Share Peace", 0.00f, 1.40f, "0.00", HintText = "the court and the food in peace: this share of the steady income (the parties' food is bought by the parties; the rest goes into the seat's purse)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float HouseholdSharePeace { get; set; } = 0.35f;

        [SettingPropertyFloatingInteger("Household Share War", 0.00f, 1.00f, "0.00", HintText = "the court and the food at war", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float HouseholdShareWar { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Gear Share Peace", 0.00f, 1.00f, "0.00", HintText = "arms, armour and horses bought by the lord in peace: at most this share of the steady income a day, kept up to AI Gear Days Cap days", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GearSharePeace { get; set; } = 0.17f;

        [SettingPropertyFloatingInteger("Gear Share War", 0.00f, 1.00f, "0.00", HintText = "arms, armour and horses bought by the lord at war (plus a share of the war chest above the reserve)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GearShareWar { get; set; } = 0.17f;

        [SettingPropertyFloatingInteger("War Chest To Wages", 0.00f, 3.20f, "0.00", HintText = "at war, this share of the house's gold above its war reserve is spent on wages over War Chest Days", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarChestToWages { get; set; } = 0.8f;

        [SettingPropertyFloatingInteger("War Chest Days", 0.00f, 180.00f, "0.00", HintText = "the war chest above the reserve is spread over this many days of war", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarChestDays { get; set; } = 45f;

        [SettingPropertyFloatingInteger("Reserve Days Peace", 0.00f, 240.00f, "0.00", HintText = "in peace a house with less than this many days of its steady income in gold cuts its shares a little (at most a tenth)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float ReserveDaysPeace { get; set; } = 60f;

        [SettingPropertyFloatingInteger("Reserve Cap Days", 0.00f, 480.00f, "0.00", HintText = "in peace a house with more than this many days of its steady income (plus 50 000) spends one part in 180 of the excess a day on its court and building works", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float ReserveCapDays { get; set; } = 120f;

        [SettingPropertyFloatingInteger("War Reserve Days", 0.00f, 80.00f, "0.00", HintText = "war reserve: this many days of steady income (at least War Reserve Floor), plus War Reserve Per Adult for every grown member - kept untouched by the war chest", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarReserveDays { get; set; } = 20f;

        [SettingPropertyFloatingInteger("War Reserve Floor", 0.00f, 80000.00f, "0.00", HintText = "the smallest war reserve of any house", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarReserveFloor { get; set; } = 20000f;

        [SettingPropertyFloatingInteger("War Reserve Per Adult", 0.00f, 20000.00f, "0.00", HintText = "war reserve added for every grown member of the house (the family's own purses)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float WarReservePerAdult { get; set; } = 5000f;

        [SettingPropertyFloatingInteger("Poverty Deep Share", 0.00f, 1.00f, "0.00", HintText = "at war, a house with gold under this share of its war reserve keeps only Poverty Deep Factor of its wage ceiling", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float PovertyDeepShare { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Poverty Deep Factor", 0.00f, 2.00f, "0.00", HintText = "the wage ceiling of a house deep in poverty at war (share of the normal one)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float PovertyDeepFactor { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Budget Hysteresis", 0.00f, 4.40f, "0.00", HintText = "a house is over its budget only when its wages pass this many times the ceiling", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float BudgetHysteresis { get; set; } = 1.1f;

        [SettingPropertyInteger("Budget Hysteresis Days", 0, 12, "0", HintText = "... for this many days in a row before men are sent home", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int BudgetHysteresisDays { get; set; } = 3;

        [SettingPropertyFloatingInteger("Release Per Day", 0.00f, 1.00f, "0.00", HintText = "share of the excess wages sent home each day (as men; who goes first is set by Release Across Tiers)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float ReleasePerDay { get; set; } = 0.15f;

        [SettingPropertyBool("Release Across Tiers", HintText = "men sent home for lack of budget are drawn evenly from the whole party or garrison (every man has the same chance), not lowest tier first - for the same wages fewer men leave, and a poor house keeps more heads instead of a few veterans; tavern mercenaries still go first. Off = lowest tier first, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool ReleaseAcrossTiers { get; set; } = true;

        [SettingPropertyInteger("Min New Party Men", 0, 120, "0", HintText = "a house raises a new party only when its ceiling has room for this many more men (a house with no party at all may always raise one)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int MinNewPartyMen { get; set; } = 30;

        [SettingPropertyFloatingInteger("Garrison Peace Share", 0.00f, 2.80f, "0.00", HintText = "in peace a garrison is held at this share of its average war strength (in wages), paid from the house's own peace ceiling; the crown pays nothing towards it. 0.5 = as before 14.10", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GarrisonPeaceShare { get; set; } = 0.7f;

        [SettingPropertyBool("Garrison War Full", HintText = "at war garrisons keep the game's own limit and are paid first; the parties get the rest of the ceiling. Off = garrisons are held at the peace target in war too", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool GarrisonWarFull { get; set; } = true;

        [SettingPropertyFloatingInteger("Garrison Max Share Of Budget Peace", 0.00f, 3.20f, "0.00", HintText = "in peace all garrisons of a house together take at most this share of its wage ceiling", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GarrisonMaxShareOfBudgetPeace { get; set; } = 0.8f;

        [SettingPropertyFloatingInteger("Ai Gear Days Cap", 0.00f, 120.00f, "0.00", HintText = "unspent arms shares are kept for at most this many days", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float AiGearDaysCap { get; set; } = 30f;

        [SettingPropertyInteger("Family Purse Floor", 0, 20000, "0", HintText = "a grown member tops up the head's purse only from what he holds above this; the court is not paid from the head's purse below it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int FamilyPurseFloor { get; set; } = 5000;

        [SettingPropertyBool("Family Tops Up Head", HintText = "the grown members of an AI house top up its head's purse to this floor or a day of the house's costs, whichever is more - one family purse (Iron Bank Family Pays still runs first, before the bank lends or marks an instalment as missed)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool FamilyTopsUpHead { get; set; } = true;

        [SettingPropertyBool("Watch No Releases", HintText = "the Night's Watch never sends its men home for lack of budget - peace with the Free Folk does not disband the Wall; its ceiling only stops new recruits (off = the Watch is released like any house over its ceiling)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool WatchNoReleases { get; set; } = true;

        [SettingPropertyBool("Unpaid Troops Cap In Men", HintText = "troops without wages (the Night's Watch) are held by the budget in men: the gold ceiling divided by the wage the men would have", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool UnpaidTroopsCapInMen { get; set; } = true;

        [SettingPropertyBool("Household Minimal", HintText = "each AI house pays its court into the purse of its seat (town or castle) every day - the share for the court and food less the parties' own food", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool HouseholdMinimal { get; set; } = true;

        [SettingPropertyBool("Household Shield", HintText = "the court's money paid into a town purse is kept out of the game's purse regulator: it leaves only with the lord's rents and the war subsidy, and never more than the purse holds above its target. Not needed and idle with Town Purse Regulator on - nothing deletes town coin any more", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool HouseholdShield { get; set; } = true;

        [SettingPropertyBool("War Court Yields To Wages", HintText = "at war the court gives way to the army: a house may also spend its court share (less the parties' own food) on wages, and its court gets only what the wages leave of that share. A house with room under its ceiling pays its court in full, as before. Needs Household Minimal. Off = the court takes its full share at war too", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool WarCourtYieldsToWages { get; set; } = true;

        [SettingPropertyBool("Court Gets Lapsed Arms Share", HintText = "arms money a lord's house has not spent within the cap of days goes to its court - the kitchens, stables and servants of its seat - instead of lying idle: each day the arms share older than AI Gear Days Cap days is paid with the court into the purse of the seat (town or castle). Only from the family's gold above the house's reserve (at war its war reserve, in peace Reserve Days Peace days of its steady income), at war only what the wages leave, half for a house in debt; the head always keeps the day's wages in his purse (and at least Family Purse Floor); none for mercenaries. Needs Household Minimal. Off = the unspent arms money stays in the head's purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CourtGetsLapsedArmsShare { get; set; } = true;

        [SettingPropertyFloatingInteger("Court Folk Share", 0.00f, 1.00f, "0.00", HintText = "the share of the court's money that goes to the townsfolk of the seat (servants, cooks, grooms) rather than to its merchants - with Town Folk Live on (the townsfolk's purse live) it goes into their purse, at a castle into the castle folk's purse; with it off the whole court money goes into the seat's purse", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CourtFolkShare { get; set; } = 0.2f;

        [SettingPropertyBool("Lapsed Gear Buys Goods", HintText = "with Court Gets Lapsed Arms Share: the arms money a house did not spend is paid to its seat only for real goods taken from the seat town's stall - linen, velvet and furs, jewels, silver, spice and pottery, never food - and only what lies above the stall's reserve, only goods not dear there, at most a quarter of a stack a day (shared with the court's own buying). What buys nothing stays in the head's purse; a castle seat has no stall, so there it all stays with the house. The townsfolk take no fifth of it - it pays for goods, not for service (off = the whole lapsed arms money goes into the seat's purse in coin, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool LapsedGearBuysGoods { get; set; } = true;

        [SettingPropertyBool("Own Payments Back As Own", HintText = "money a house pays into the coffers of its own town or castle (its court, garrison wages, its men's spending, arms, building wages) comes back through the dues as the house's own money for as many days as it takes, not as income from its land - so it no longer swells the house's steady income and the army it may keep (off = only one day's share counts as its own, the rest as land income, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool OwnPaymentsBackAsOwn { get; set; } = true;

        [SettingPropertyBool("Crown Refund Ignores Own Back", HintText = "in war, the house's own money coming back through the dues of its own castles (your gifts to its coffers, the court, arms, building wages) does not cut the crown's refund of garrison wages - only the garrison wages that came back do (off = all the castle dues cut it, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRefundIgnoresOwnBack { get; set; } = true;

        [SettingPropertyBool("Party Limits Share Free Room", HintText = "the party wage limits of a budgeted house share out what the house has not yet spent: each party may grow by its share of the free room (the head's party 1.5, the others 1) on top of its own wages, so no party is held back while the house has room; a house over its party ceiling has every party limit cut in proportion to its wages. Off = the ceiling is split once, head 1.5 : others 1", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool PartyLimitsShareFreeRoom { get; set; } = true;

        [SettingPropertyBool("Merc Contract Enabled", HintText = "with Crown Current Income: an AI mercenary company is hired on a fixed contract - on the day it enters a realm's service the crown agrees to pay it Merc Contract Factor times its daily wages (wages, food and kit) for the men it brings; in peace it waits on half the money and half the men; every Merc Review Days the contract is cut (never raised) to the wages of the men it still has if those fall below Merc Review Floor of the contracted wages (half of them in peace and in the first review days of a war after peace); no review while the company is not in the field. The crown pays it out of its daily income before the wage refunds; a company left unpaid by more than half for Merc Unpaid Leave Days in a row leaves the service. The house budget holds the company to the wages of the men of its contract. Your own mercenary contract is the game's, as before. Off = the game's mercenary pay for the AI, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool MercContractEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Merc Contract Factor", 0.00f, 5.20f, "0.00", HintText = "the contract a day as a multiple of the company's daily wages on the day it is hired (wages 1.0, food about 0.15, kit about 0.15)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float MercContractFactor { get; set; } = 1.3f;

        [SettingPropertyFloatingInteger("Merc Peace Share", 0.00f, 2.00f, "0.00", HintText = "in peace a hired company waits on this share of its contract and of its men", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float MercPeaceShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Merc Review Days", 0, 112, "0", HintText = "the contract is reviewed this often - only downwards", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int MercReviewDays { get; set; } = 28;

        [SettingPropertyFloatingInteger("Merc Review Floor", 0.00f, 3.00f, "0.00", HintText = "at a review, a company whose wages have fallen below this share of its contracted wages (half of them in peace) has its contract, wages and men cut in proportion to what it has", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float MercReviewFloor { get; set; } = 0.75f;

        [SettingPropertyFloatingInteger("Merc Hire Floor Share", 0.00f, 2.00f, "0.00", HintText = "a company hired after a battle or a peace signs for at least this share of its full size (the sum of its parties' size limits), at today's wage per man - otherwise a contract made on a remnant never lets the company grow back", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float MercHireFloorShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Merc Unpaid Leave Days", 0, 112, "0", HintText = "a company paid less than half its contract for this many days in a row leaves the service", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int MercUnpaidLeaveDays { get; set; } = 28;

        [SettingPropertyBool("Merc Game Contract Ai Off", HintText = "with Merc Contract Enabled: AI companies in service get nothing from the game itself - no gold 'for their tier' from nowhere and no game contract drawn on the realm's mercenary purse (so the vassals no longer pay for the AI companies a second time); your own contract is unchanged", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool MercGameContractAiOff { get; set; } = true;

        [SettingPropertyBool("Merc Contract Pays Men Under Arms", HintText = "with Merc Contract Enabled: each day the crown pays a hired company Merc Contract Factor times the wages of the men it really has under arms that day, never more than its contract (half of it in peace). The contract still sets how far the company may grow, so a company signed after a defeat fills its ranks from its own purse and is paid for the new men from the next day; a company with no men in the field is paid nothing. Off = the full contract every day whatever the company's strength, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool MercContractPaysMenUnderArms { get; set; } = true;

        [SettingPropertyBool("Merc Bk Down Payment Ai Off", HintText = "with Merc Contract Enabled: an AI mercenary company no longer takes BannerKings' earnest-money out of the hiring king's own purse each time it changes its master - the crown's daily contract is its one pay for the service (companies changed masters every few days and drained the purses of the small kings). You still get your earnest-money when you hire out as a mercenary; when you are the king, you pay none to an AI company. Off = BannerKings pays the earnest-money, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool MercBkDownPaymentAiOff { get; set; } = true;

        [SettingPropertyBool("Merc Min Service", HintText = "an AI mercenary company hired by a realm at war serves at least Merc Min Service Days: it neither leaves nor changes masters before that, and the ruler does not dismiss it (Banner Kings). It may still go early if its master is at peace with every realm, if the crown leaves more than half of its contract unpaid for four weeks (Merc Unpaid Leave Days), or if the realm falls. For the same number of days after leaving a master, a company does not hire out to a realm at war with that master - a company dismissed under Banner Kings no longer goes straight over to the enemy, it is only dismissed. Only AI companies: as a mercenary yourself you decide as before, and as a king you may still dismiss companies. Off = AI companies may change masters any day, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool MercMinService { get; set; } = true;

        [SettingPropertyInteger("Merc Min Service Days", 1, 112, "0", HintText = "with Merc Min Service: the shortest service of an AI company with a realm at war, and how many days after leaving a master it will not serve that master's enemies (28 = four weeks)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int MercMinServiceDays { get; set; } = 28;

        [SettingPropertyBool("Crown Gifts", HintText = "with Crown Current Income: the North feeds the Night's Watch and (with Gift Free Cities To Dothraki) the Free Cities pay the Dothraki - each day a share of the giver's daily income goes through the receiving crown to its houses the same day, by fixed weights (the Watch: a stronghold 1, a village a quarter, a house without a fief half; the Dothraki: equal for every house of the khalasar) - never by the number of men. It counts towards their steady income. Off = no gifts", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownGifts { get; set; } = true;

        [SettingPropertyFloatingInteger("Gift Watch North", 0.00f, 1.00f, "0.00", HintText = "share of the North's daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchNorth { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Gift Watch Iron Throne", 0.00f, 1.00f, "0.00", HintText = "share of the Iron Throne's (King's Landing) daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchIronThrone { get; set; } = 0.04f;

        [SettingPropertyFloatingInteger("Gift Watch Dorne", 0.00f, 1.00f, "0.00", HintText = "share of Dorne's daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchDorne { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Gift Watch Reach", 0.00f, 1.00f, "0.00", HintText = "share of the Reach's daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchReach { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Gift Watch Vale", 0.00f, 1.00f, "0.00", HintText = "share of the Vale's daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchVale { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Gift Watch Stormlands", 0.00f, 1.00f, "0.00", HintText = "share of the Stormlands' daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchStormlands { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Gift Watch Riverlands", 0.00f, 1.00f, "0.00", HintText = "share of the Riverlands' daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchRiverlands { get; set; } = 0.02f;

        [SettingPropertyFloatingInteger("Gift Watch Dragonstone", 0.00f, 1.00f, "0.00", HintText = "share of Dragonstone's daily income given to the Night's Watch when the Watch needs it", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchDragonstone { get; set; } = 0.01f;

        [SettingPropertyInteger("Gift Watch Need Days", 0, 240, "0", HintText = "the realms send their gifts only while the Watch's houses hold less gold than this many days of the Watch's costs (wages and food); 0 = always", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int GiftWatchNeedDays { get; set; } = 60;

        [SettingPropertyFloatingInteger("Gift Watch Food Per Man", 0.00f, 4.00f, "0.00", HintText = "the food of one brother a day, counted into the Watch's costs for the need test", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftWatchFoodPerMan { get; set; } = 1.0f;

        [SettingPropertyBool("Gift Free Cities To Dothraki", HintText = "the Free Cities (Braavos, Volantis, Pentos, Myr, Lys, Tyrosh, Norvos, Qohor, Lorath) pay the Dothraki a tribute: each day Gift Free Cities To Dothraki Share of every Free City's daily income goes to the houses of the khalasar, equal for every house (needs Crown Gifts). Off by default: the Dothraki live on what they take - loot, ransoms and raids - and each Free City keeps that share of its daily income for its own houses and treasury. The gifts of Westeros to the Night's Watch are not touched. Takes effect from the next day", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool GiftFreeCitiesToDothraki { get; set; } = false;

        [SettingPropertyFloatingInteger("Gift Free Cities To Dothraki Share", 0.00f, 1.00f, "0.00", HintText = "with Gift Free Cities To Dothraki: share of each Free City's daily income given to the Dothraki (Braavos, Volantis, Pentos, Myr, Lys, Tyrosh, Norvos, Qohor, Lorath); 0.15 since the 120-day test, where the Dothraki at war fell more than a quarter below their old numbers (0.10 before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float GiftFreeCitiesToDothrakiShare { get; set; } = 0.15f;

        [SettingPropertyBool("Watch Unpaid", HintText = "the brothers of the Night's Watch take no wages: troops in the parties and garrisons of the Watch cost nothing a day; food and kit come from the gifts and the Watch's own villages, and the Watch's numbers are held by the house budget in men instead of gold (needs Clan Budget Enabled). Off = the Watch is paid like everyone else", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool WatchUnpaid { get; set; } = true;

        [SettingPropertyBool("Crown Rents", HintText = "with Crown Current Income: what is left of the crown's daily income after the gifts, reparations, mercenary contracts and wage refunds is shared out the same day among the houses of the realm by fixed weights of their fiefs (Crown Rent Weight Town, Castle and Village) - the king's house too, and yours - never by the size of their garrisons. A house gets its share only while it serves: every stronghold it holds keeps at least Crown Rent Garrison Share of the realm's usual garrison for its kind (the average of the last 28 days; a stronghold under siege or held for less than 28 days is not counted), and its lords spent at least Crown Rent Service Days of the realm's last 60 days of war in an army of the realm, at a siege, in battle with the enemy or on enemy land (the nearest settlement belongs to a realm at war with yours) - captivity in the war counts; a house that has seen fewer days of the realm's war needs the same share of the days it has seen. The share of a house that does not serve stays in the treasury. Rents count towards the steady income of the house (its crown part). Off = what is left stays in the treasury, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRents { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Rent Weight Town", 0.00f, 12.00f, "0.00", HintText = "rent weight of a town (a castle 1, a village a quarter by default); with Castle Lords Even Up while the townsfolk's purse is live, Crown Rent Weight Town With Folk is used instead", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownRentWeightTown { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Crown Rent Weight Castle", 0.00f, 4.00f, "0.00", HintText = "rent weight of a castle; with Castle Lords Even Up while the townsfolk's purse is live, Crown Rent Weight Castle With Folk is used instead", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownRentWeightCastle { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Crown Rent Weight Village", 0.00f, 1.00f, "0.00", HintText = "rent weight of a village - the same with Castle Lords Even Up", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownRentWeightVillage { get; set; } = 0.25f;

        [SettingPropertyInteger("Crown Rent Service Days", 0, 60, "0", HintText = "days of service the crown asks of a house out of the realm's last 60 days of war (in an army of the realm, at a siege, in battle with the enemy, on enemy land or in captivity) - half of the old forty days of service", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int CrownRentServiceDays { get; set; } = 20;

        [SettingPropertyFloatingInteger("Crown Rent Garrison Share", 0.00f, 1.00f, "0.00", HintText = "every stronghold of a house must keep at least this share of the realm's usual garrison for its kind (town or castle) for the house to get its rent", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownRentGarrisonShare { get; set; } = 0.5f;

        [SettingPropertyBool("Crown Rent Garrison Norm Kingdom", HintText = "the usual garrison is the average of the realm's own towns or castles over the last 28 days; off = the average of all towns or castles in the world", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentGarrisonNormKingdom { get; set; } = true;

        [SettingPropertyBool("Crown Rent Service Whole Day", HintText = "service is seen over the whole day: a battle, raid or assault against the enemy counts whenever it happens, not only if it is going on at the day's tick, and so do chasing an enemy party and riding to relieve a besieged or raided settlement of the realm (defending your own land). Off = only what a party is doing at the moment of the day's tick, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentServiceWholeDay { get; set; } = true;

        [SettingPropertyBool("Crown Rent War Day Needs Contact", HintText = "a day of war counts towards the service only when the realm really waged the war that day - an army of the realm in the field, a siege, raid or pressing of a village between the realm and its enemy, or a battle with lords on both sides; a war with a realm nobody can reach (across the sea) asks no service while it stays out of reach. Off = every day of a declared war counts, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentWarDayNeedsContact { get; set; } = true;

        [SettingPropertyBool("Crown Rent Contact Only When Called", HintText = "with Crown Rent War Day Needs Contact: a day of war binds a realm to service only when the realm is truly called to it - an army of the realm is in the field, the realm besieges or is besieged, or one of its own settlements is raided, pressed or attacked that day. A battle in the open field and the raids of its own lone lords on enemy villages no longer bind the whole realm, so a war fought only by a few raiding houses asks no service of the rest. Off = any raid, pressing, assault or battle between lords of the two realms binds both realms, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentContactOnlyWhenCalled { get; set; } = true;

        [SettingPropertyBool("Crown Rent Service After Full Days", HintText = "the crown asks a house for service only once that house has seen as many days of real war under this crown as the crown asks days of service (Crown Rent Service Days); before that every house that keeps its garrisons draws its rent - a short clash at the start of a quiet war no longer strips the rent from every house that missed it (off = service is asked from the first day of real war, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentServiceAfterFullDays { get; set; } = true;

        [SettingPropertyBool("Crown Rent Service At Means", HintText = "a house whose wage ceiling cannot pay for parties big enough to be called to an army (the game calls only parties above 60% of their size) serves the crown with what it has: its days of war count as served and the crown does not ask it for more, so it keeps its rent and can raise men again; once it can afford such a party the usual service is asked. Needs Clan Budget Enabled; you are never judged this way. Off = every house must serve its days, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentServiceAtMeans { get; set; } = true;

        [SettingPropertyBool("Crown Rent Held To Serving", HintText = "the rent share of a house that does not serve (garrison or service days) goes to the houses of the same realm that do, by the same fief weights, instead of staying in the treasury; if no house of the realm serves, it stays in the treasury. Off = it stays in the treasury, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentHeldToServing { get; set; } = true;

        [SettingPropertyBool("Crown Rents By Need", HintText = "the crown pays fief rents by need, by the same rule as the wage refund: a serving house whose family gold is below its war reserve gets its full rent, a house holding more than twice its war reserve gets none, and in between the rent falls evenly the richer the house is. What a house does not get stays in the realm's treasury for wars and hard times - it is never shared out to the other houses. Judged on the house's budget of the day before; your own house the same way, in war and in peace. Houses without a budget, in debt or under seizure keep the full rent (off = every serving house gets its full rent, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownRentsByNeed { get; set; } = true;

        [SettingPropertyBool("Need Reserve Uncut", HintText = "with Crown Refund By Need or Crown Rents By Need: the war reserve by which the crown judges a house's need is reckoned from the house's steady income with the wage refund and the fief rents counted in full, as if nothing had been held back. Without it, holding back part of a middling house's refund and rents lowered its steady income, so its war reserve, so the next share again - month by month such a house slid to nothing although its gold never moved. Only this measure of need changes - the house's own budget, court, building and wage ceiling still follow what it really receives. Off = the reserve of need follows the income actually received, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool NeedReserveUncut { get; set; } = true;

        [SettingPropertyBool("Stable D First Day From Save", HintText = "on the first day after loading a save, a house's steady income, the income its debt instalments are measured against, its credit limit at the Iron Bank and its dues to the crown are taken from what the save remembers of the day before. Before, the first day after every load fell back on the house's raw daily income (about twice its steady income), so for that one day wage ceilings, court shares and war credit from the Bank were inflated, and the next day's refund and rents by need were judged on that. Off = the first day after loading uses the raw income, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool StableDFirstDayFromSave { get; set; } = true;

        [SettingPropertyBool("Need Reserve Uncut Saved", HintText = "with Need Reserve Uncut: what the crown held back from each house by need is remembered in the save, so after loading the war reserve of need goes on where it was instead of rebuilding from nothing over four weeks - the days not yet seen in this session count with the remembered average, and on the first day after loading the reserve of need is reckoned the same way. Off = after every load the reserve of need rebuilds from nothing over 28 days, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool NeedReserveUncutSaved { get; set; } = true;

        [SettingPropertyBool("Need Measure All", HintText = "with Crown Refund By Need or Crown Rents By Need: the houses that kept their full wage refund and fief rents because the crown had no measure of them are now judged by their own gold like everyone else. A house in debt to the Iron Bank is judged on its gold against its war reserve. The houses of the Night's Watch and the Free Folk, who pay their men no wages, are judged against a reserve of War Reserve Days of what they really spend - their court, arms and building out of their steady income and the few wages they do pay in coin - at least War Reserve Floor, plus War Reserve Per Adult for each grown member. Houses under seizure, hired companies and houses without a budget keep the full share. Your house the same way. Off = houses in debt and the houses of the Watch and the Free Folk keep the full share, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool NeedMeasureAll { get; set; } = true;

        [SettingPropertyBool("Crown Pays Call To War", HintText = "with Crown Current Income: the price of calling an ally into a war is paid by the calling crown out of its daily income, a day's part at a time over the ally's term of service (after the gifts, reparations and mercenary contracts, before the wage refunds) - the houses of the realm pay nothing towards it, you neither. The ally's houses get only what the crown has really paid. When the crown cannot pay a day's part, the agreement ends and the ally leaves that war (peace between the ally and the enemy). Off = the game's way: the houses pay their share and the ally is paid in full at once", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownPaysCallToWar { get; set; } = true;

        [SettingPropertyBool("Call To War Break Restores Wallet", HintText = "with Crown Pays Call To War: when a crown can no longer pay a day's part and the agreement is broken, the unpaid rest of the price is struck off the calling realm's call-to-war purse at once - nobody owes it and nobody is paid it. Before, the rest came back the next day as an 'old debt' and the treasury paid it off into nothing, a day's part at a time. A debt from before the mod is looked for only once, after loading a save made without this rule. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CallToWarBreakRestoresWallet { get; set; } = true;

        [SettingPropertyBool("Call To War Pays For War", HintText = "with Crown Pays Call To War: the calling crown pays an ally's daily part only for days the ally is really at war with the enemy it was called against. An ally that has not been at war with that enemy for seven days in a row (after three days' grace from the agreement) is released: the agreement ends without any peace and the rest of the price is struck off. Off = the crown pays every day's part while it can, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CallToWarPaysForWar { get; set; } = true;

        [SettingPropertyBool("Call To War No Break", HintText = "with Crown Pays Call To War: when the calling crown has too little of the day's income left for an ally's daily part, that part is simply lost - the agreement goes on and the ally stays in the war; it is never broken off and the ally is never forced into peace because of it. After seven days of war in a row without a part (here or under Call To War After Own Wages), the agreement ends without any peace, so the unpaid ally is free to make peace on its own. A crown that keeps missing its parts cannot call new allies until its call-to-war purse recovers. Off = the agreement is broken and the ally leaves that war, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CallToWarNoBreak { get; set; } = true;

        [SettingPropertyBool("Call To War After Own Wages", HintText = "with Crown Pays Call To War: the calling crown pays an ally's daily part only from what is left of the day's income after it has set aside what its own soldiers needed from the day's income yesterday - the wage refund due to its houses, the war aid pot and the wages its field companies still lacked. A day the crown cannot afford it this way, the ally gets no part, the agreement goes on and the unpaid part is not carried over; after seven such days of war in a row the agreement ends without any peace. Off = the crown pays the ally first while the day's income allows, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CallToWarAfterOwnWages { get; set; } = true;

        [SettingPropertyBool("Crown Borrows", HintText = "with Crown Current Income and Iron Bank Enabled: a crown at war whose day's income cannot cover the wage refunds it owes its houses borrows the missing part from the Iron Bank - only for the refunds, never for gifts or rents; no new loans in peace. The crown owes at most Crown Loan Limit Days of its average taxes and pays the Bank first each day, before any other expense: one part in Crown Loan Repay Days of its largest debt, at most Crown Loan Max Income Share of its taxes, at the Bank's usual interest (like a king: 20% a year, 30% on a running debt, 2% fee). A crown that pays less than half of its instalments over 28 days falls into arrears: the Bank lends nothing more to it or to its houses and lends more to the houses of the realms at war with it, until it has paid in full for 28 days. The debt of a realm that is destroyed is lost to the Bank. You as king borrow by the same rule. Off = no crown borrows, as before", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public bool CrownBorrows { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Loan Limit Days", 0.00f, 728.00f, "0", HintText = "a crown owes the Bank at most this many days of its average taxes (the dues, war subsidy, customs, castle share and ninths of the last 84 days - not the hoard)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownLoanLimitDays { get; set; } = 180f;

        [SettingPropertyFloatingInteger("Crown Loan Repay Days", 30.00f, 728.00f, "0", HintText = "each day the crown repays one part in this many of the largest debt of its loan (half a year, the Bank's usual term), at most Crown Loan Max Income Share of its taxes", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownLoanRepayDays { get; set; } = 182f;

        [SettingPropertyFloatingInteger("Crown Loan Max Income Share", 0.00f, 1.00f, "0.00", HintText = "the crown's instalment to the Bank is at most this share of its average daily taxes", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownLoanMaxIncomeShare { get; set; } = 0.3f;

        [SettingPropertyInteger("Crown Loan Bank Floor", 0, 8000000, "0", HintText = "the Bank lends to crowns only from the capital it holds above this (the rest stays for the houses' war credit)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public int CrownLoanBankFloor { get; set; } = 2000000;

        [SettingPropertyFloatingInteger("Crown Loan Pool Days", 1.00f, 360.00f, "0", HintText = "each day the Bank lends to all crowns together at most one part in this many of its capital above Crown Loan Bank Floor - shared out by need when they ask for more (no sudden end of credit)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownLoanPoolDays { get; set; } = 60f;

        [SettingPropertyFloatingInteger("Crown Arrears Enemy Credit", 1.00f, 3.00f, "0.00", HintText = "the credit limit of houses whose realm is at war with a crown in arrears to the Bank is multiplied by this (the Bank funds the enemies of those who do not pay)", RequireRestart = false)]
        [SettingPropertyGroup("The crown's income (stage 2)")]
        public float CrownArrearsEnemyCredit { get; set; } = 1.5f;

        [SettingPropertyBool("Debt Ladder Enabled", HintText = "with Iron Bank Enabled and Clan Budget Enabled: the Bank lends only to those who can repay, and instead of bankruptcy the creditor takes income. An AI house borrows only for war (War Credit). All instalments of a house come out of its steady income: the Bank at most Iron Bank Max Instalment Share of it a day, all debts together (Bank, unpaid wages, ransoms) at most All Instalments Max Share - the Bank first, then the rest by age. A missed instalment is an arrear (the house pays what it holds above three days of wages, its credit is stopped); after three arrears in a row the creditors seize the income of the house's villages and every coin above Seize Floor Gold in its head's purse, interest frozen, until the debt is paid; only when the seizure brings nothing for Sale After Zero Seize Days or would take longer than Sale Forecast Days are the surplus arms, caravans and workshops sold, once a week. No house ever loses a fief, and no debt is forgiven: the debt of a house that dies passes to the new lords of its villages. Debtors build nothing and keep half a court. Off = the Iron Bank as before (loans for wages, bankruptcy)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool DebtLadderEnabled { get; set; } = true;

        [SettingPropertyBool("War Credit", HintText = "at war, an AI house whose family gold is below its war reserve may spend beyond its wage ceiling on credit from the Iron Bank: its ceiling grows by up to War Credit Max Share D of its steady income a day, within the credit limit, and each day the Bank pays its head what its wages exceed the ceiling without credit. At war half of every windfall of the house (loot, ransoms, purses, its third) goes to the debt first; after the peace the house pays Iron Bank Max Instalment Share of its steady income a day and all its windfalls until the debt is cleared, and its budget sends the surplus men home. No credit to a house in arrears, to a house within Credit After Seizure Days of a seizure, or while the Bank holds less than Bank Free Capital Floor", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool WarCredit { get; set; } = true;

        [SettingPropertyFloatingInteger("War Credit Max Share D", 0.00f, 1.00f, "0.00", HintText = "the most a house may draw on war credit a day, as a share of its steady income", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float WarCreditMaxShareD { get; set; } = 0.4f;

        [SettingPropertyFloatingInteger("War Credit Loot Repay Share", 0.00f, 1.00f, "0.00", HintText = "at war, this share of every windfall of an indebted house goes to the Bank first (after the peace all of it)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float WarCreditLootRepayShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("War Credit Loot Days", 0.00f, 120.00f, "0.00", HintText = "the credit limit counts this many days of the house's average windfalls from real payers over the last 84 days (loot sold, ransoms, purses, its third - not ships or other gold from nowhere)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float WarCreditLootDays { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Debt Limit Land Days", 0.00f, 60.00f, "0.00", HintText = "the credit limit counts this many days of the land part of the house's steady income (its villages, towns and castles), plus Iron Bank Per Town and Per Castle, times the house's credit; the old Iron Bank Income Days stays for the Bank without the debt ladder", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float DebtLimitLandDays { get; set; } = 15f;

        [SettingPropertyInteger("Bank Free Capital Floor", 0, 4000000, "0", HintText = "the Bank gives no war credit while its free capital is below this (armies fall back to their budgets)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int BankFreeCapitalFloor { get; set; } = 1000000;

        [SettingPropertyFloatingInteger("Iron Bank Max Instalment Share", 0.00f, 0.50f, "0.00", HintText = "the Bank's instalment a day is at most this share of the debtor's steady income", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float IronBankMaxInstalmentShare { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("All Instalments Max Share", 0.00f, 0.50f, "0.00", HintText = "all instalments of a house together (Bank, unpaid wages, ransoms) are at most this share of its steady income a day - the Bank first, then the others by age", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float AllInstalmentsMaxShare { get; set; } = 0.15f;

        [SettingPropertyInteger("Seize Floor Gold", 0, 152000, "0", HintText = "under seizure the creditors take every coin above this in the head's purse (about ten days of wages of a retinue of 135 men), besides all the income of the house's villages", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int SeizeFloorGold { get; set; } = 38000;

        [SettingPropertyInteger("Sale Forecast Days", 0, 2912, "0", HintText = "under seizure, the surplus arms, caravans and workshops are sold once a week only if the seizure would take longer than this many days to clear the debt", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int SaleForecastDays { get; set; } = 728;

        [SettingPropertyInteger("Sale After Zero Seize Days", 0, 56, "0", HintText = "... or if the seizure has brought nothing for this many days in a row", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int SaleAfterZeroSeizeDays { get; set; } = 14;

        [SettingPropertyInteger("Credit After Seizure Days", 0, 728, "0", HintText = "a house that has cleared a seizure gets no war credit for this many days", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int CreditAfterSeizureDays { get; set; } = 182;

        [SettingPropertyFloatingInteger("Bank Profit To Braavos Days", 0.00f, 720.00f, "0.00", HintText = "the Bank's capital above Iron Bank Capital flows into the purse of Braavos, one part in this many a day; with Iron Bank Dividends, the Bank's own capital above Iron Bank Capital joins the profit it pays out at this same pace", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float BankProfitToBraavosDays { get; set; } = 180f;

        [SettingPropertyBool("Iron Bank Dividends", HintText = "every Iron Bank Dividend Days the Iron Bank pays out the profit it has really earned - the interest and fees its debtors have actually paid in, less what it lost on debts nobody will ever pay - but only as far as its vaults stay above its reserve: Bank Free Capital Floor or Crown Loan Bank Floor, whichever is higher, plus everything it lent to houses and crowns in the last Iron Bank Reserve Lend Days. The Bank's own capital is paid out only above Iron Bank Capital: one part in Bank Profit To Braavos Days of that surplus joins the profit every day. Iron Bank Dividend Town Share of each payout goes into the city of Braavos as the keyholders' household spending (a part to the townsfolk who serve them, the rest to the merchants' coffer); the rest goes to the heads of the Braavosi houses holding a town or castle of Braavos (a town counts twice), you too if you are one of them. Replaces the old daily flow of Bank Profit To Braavos Days. Off = the Bank keeps its interest and only its capital above Iron Bank Capital flows to Braavos, as before", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool IronBankDividends { get; set; } = true;

        [SettingPropertyInteger("Iron Bank Dividend Days", 1, 364, "0", HintText = "how often the Iron Bank pays out its profit to Braavos, in days (with Iron Bank Dividends)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int IronBankDividendDays { get; set; } = 28;

        [SettingPropertyFloatingInteger("Iron Bank Dividend Town Share", 0.00f, 1.00f, "0.00", HintText = "share of each Iron Bank payout that goes into the city of Braavos (its townsfolk and merchants' coffer); the rest goes to the heads of the Braavosi houses holding a town or castle (with Iron Bank Dividends)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public float IronBankDividendTownShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Iron Bank Reserve Lend Days", 1, 364, "0", HintText = "the Bank's reserve counts everything it lent to houses and crowns in this many past days on top of its floors - it keeps that much for the lending to come before any profit is paid out (with Iron Bank Dividends)", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public int IronBankReserveLendDays { get; set; } = 28;

        [SettingPropertyBool("Wage Debt To Men", HintText = "the debt the game writes to a house for wages it could not pay (debt to the crown) becomes a debt to the men of the parties whose pay was cut: it is paid off by the same instalments into their purses (a party gone - another party of the house, then the nearest town); the game no longer drains the head's purse to pay it in one go. Old crown debts are taken into the same ledger", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool WageDebtToMen { get; set; } = true;

        [SettingPropertyBool("Game Wallets No Advance", HintText = "when a house cannot pay its share of the realm's mercenary, tribute or call-to-war purse, the share stays owed by the realm (shared out again among its houses the next day) instead of the game counting it as paid and writing it to the house as a debt - no advance from nowhere", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool GameWalletsNoAdvance { get; set; } = true;

        [SettingPropertyBool("Player Same Ladder", HintText = "you borrow, repay and fall into arrears, seizure and sale by the same rules as the AI houses (your loans are taken by hand in Braavos; at war they count as war credit; your instalments come out of your steady income in war and peace); never your own equipment or your companions'. Off = your loans run as before the debt ladder", RequireRestart = false)]
        [SettingPropertyGroup("Debts and the war credit (stage 2)")]
        public bool PlayerSameLadder { get; set; } = true;

        [SettingPropertyBool("Lord Ransom By Income", HintText = "with Debt Ladder Enabled: one rule for every ransom of a lord or lady - between AI houses, by courier, through a broker, and your own: the head of a house costs Ransom Head Years of its steady income, any other member Ransom Lord Days of it. The house pays at once at most Ransom Cash Share of what its family holds above 5000, and owes the rest to the captor as a debt paid off with its other debts (all instalments at most All Instalments Max Share of its steady income); the captive goes free as soon as the cash is paid. A house never owes more than Ransom Debt Cap Days of its steady income in ransoms - a ransom above that is smaller. The chance a captor accepts stays 10% a day, and time in captivity changes neither price nor chance. Between AI houses the gold goes from the captive's family to the captor's head (no barter from nowhere). Off = the game's and Realistic Captivity's ransoms, as before", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool LordRansomByIncome { get; set; } = true;

        [SettingPropertyFloatingInteger("Ransom Head Years", 0.00f, 3.00f, "0.00", HintText = "the ransom of the head of a house, in years of its steady income (about 30 days; Jeff 10.10 option 1 - lords are taken captive several times a year in the game, far more often than in history)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomHeadYears { get; set; } = 0.0824f;

        [SettingPropertyFloatingInteger("Ransom Lord Days", 0.00f, 40.00f, "0.00", HintText = "the ransom of any other lord or lady, in days of the house's steady income (Jeff 10.10 option 1)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomLordDays { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Ransom King Days", 0.00f, 80.00f, "0.00", HintText = "a captive king's ransom, in days of his crown's income, paid by the realm's treasury (Jeff 10.10 option 1)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomKingDays { get; set; } = 20f;

        [SettingPropertyFloatingInteger("Ransom Cash Share", 0.00f, 1.00f, "0.00", HintText = "the house pays at once at most this share of its family's gold above 5000; the rest becomes a ransom debt", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomCashShare { get; set; } = 0.5f;

        [SettingPropertyBool("Ransom Queue No Block", HintText = "a new ransom debt queues behind the older ones (the same daily instalment, a longer term) - no lord stays captive because his house is already paying another ransom. Off = a house still paying a ransom gets no new ransom deal between AI houses", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool RansomQueueNoBlock { get; set; } = true;

        [SettingPropertyFloatingInteger("Ransom Debt Cap Days", 0.00f, 1456.00f, "0.00", HintText = "a house owes at most this many days of its steady income in ransoms altogether; a ransom that would go above it is cut down to it (the captor gets less)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomDebtCapDays { get; set; } = 364f;

        [SettingPropertyBool("Ransom King From Treasury", HintText = "a captive king's ransom is paid by his realm's treasury, reckoned on the crown's income (Ransom Head Years of its daily income): what the treasury holds above its reserve pays the cash part, the rest is a debt of the crown paid in instalments out of its daily income, like war reparations. Off = his house pays, like any head of a house", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool RansomKingFromTreasury { get; set; } = true;

        [SettingPropertyBool("Crown Great Captives", HintText = "a captured king or heir to the throne passes to the captor's crown: the whole ransom (cash and instalments) goes to the captor's treasury, and the captor gets Crown Great Captive Reward of the ransom from the treasury at once (out of the day's income, then the hoard above the reserve; what is missing comes out of the first ransom payments). A captor without a realm keeps the ransom, as with any other captive", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool CrownGreatCaptives { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Great Captive Reward", 0.00f, 1.00f, "0.00", HintText = "the captor's reward for a king or heir handed to his crown, as a share of the ransom", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float CrownGreatCaptiveReward { get; set; } = 0.1f;

        [SettingPropertyBool("Crown Thirds", HintText = "the crown of a realm at war takes its third of a third from what its houses win: a ninth of every ransom they receive (cash and instalments, not for a king or heir), a third of a lord's third of the loot his men sold, a ninth of the loot a lord sells in town, a ninth of the coin a lord - or you - takes from the purse of a beaten caravan, village cart party or bandit band (and of what a caravan or village cart party hands you without a fight), and from you a ninth of the purses your men take; settled once a day out of the purse of who received it, like the dues", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool CrownThirds { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Thirds Share", 0.000f, 0.500f, "0.000", HintText = "the crown's share of what the houses win (1/9 - a third of the captain's third, as in the indentures of 1415)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float CrownThirdsShare { get; set; } = 0.111f;

        [SettingPropertyBool("Crown Thirds Player Loot", HintText = "as a vassal of a realm at war you also pay the crown a ninth of the value of the loot you take from the battlefield (at the price the nearest town would pay you), the next day out of your purse", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool CrownThirdsPlayerLoot { get; set; } = true;

        [SettingPropertyBool("Ransom Repeat Cheaper", HintText = "with Lord Ransom By Income: a lord or lady ransomed again within Ransom Repeat Days of their last ransom costs less - Ransom Repeat Floor of the price right after the last ransom, rising evenly to the full price after Ransom Repeat Days. The family has just paid once, and the captor takes what it can still raise. The same for every way of ransoming (between AI houses, by courier, through a broker, from your party screen) and for a king paid by his treasury; your own ransom when you are a captive is unchanged. The coin still goes from the captive's family to the captor - only less of it. Off = every ransom at the full price, as before", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool RansomRepeatCheaper { get; set; } = true;

        [SettingPropertyInteger("Ransom Repeat Days", 1, 364, "0", HintText = "with Ransom Repeat Cheaper: for how many days after a ransom the next ransom of the same person is cheaper (56 = eight weeks)", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public int RansomRepeatDays { get; set; } = 56;

        [SettingPropertyFloatingInteger("Ransom Repeat Floor", 0.00f, 1.00f, "0.00", HintText = "with Ransom Repeat Cheaper: the share of the full price a ransom costs right after the last one (0.25 = a quarter); it rises evenly to the full price over Ransom Repeat Days", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public float RansomRepeatFloor { get; set; } = 0.25f;

        [SettingPropertyBool("Peace Release After Day", HintText = "when two realms make peace, the lords and ladies they hold captive go free a day later instead of at once - and only if the peace still holds by then. If the war is back within that day (Realm of Thrones declares its story wars again the same day), the captives stay captive, to be ransomed, to escape or to be freed in battle as in any war. The peace of a single house (a company leaving its master, a house leaving a realm) is unchanged. You and the AI alike. Off = captives go free the moment peace is made, as before", RequireRestart = false)]
        [SettingPropertyGroup("Ransoms by wealth (stage 2)")]
        public bool PeaceReleaseAfterDay { get; set; } = true;

        [SettingPropertyBool("Gentry No Parties", HintText = "Banner Kings gentry - knights who hold one estate and no town or castle - no longer lead parties of their own. When the banners are called, the knight rides in his lord's party (the lord who holds the village of his estate) as a member of it; if the lord has no party or is not in an army, in the party of the realm's nearest army leader. AI knights answer when their realm is at war and an army of the realm is in the field; your own knights ride only when you call your banners. The men of the estate stay at home - the knight comes alone. When the army breaks up, in peace or if the party changes sides, he goes back to his estate. A knight's party left from before is not reinforced and Banner Kings disbands it at the estate (its men return to the estate village). Off = Banner Kings raises the knight's own party, as before", RequireRestart = false)]
        [SettingPropertyGroup("Knights without fiefs (stage 2)")]
        public bool GentryNoParties { get; set; } = true;

        [SettingPropertyBool("Gentry Banners Need Vassal Party", HintText = "with Gentry No Parties: an AI lord calls his banners only when at least one vassal with a war party of his own can come - his estate knights ride in his own party and alone do not make an army - and only when Strategic Campaign AI would let him lead one (not too weak, not just after an army broke up). Off = Banner Kings formed such an army and broke it up the same day", RequireRestart = false)]
        [SettingPropertyGroup("Knights without fiefs (stage 2)")]
        public bool GentryBannersNeedVassalParty { get; set; } = true;

        [SettingPropertyInteger("Gentry Knight Wage", 0, 96, "0", HintText = "a knight's wage a day (two shillings, a knight's pay in the contracts of 1282-1300), paid by the head of the house whose party he rides in - counted in that house's wage ceiling and in the crown's wage refund at war, like any party wage; the brothers of the Night's Watch take none", RequireRestart = false)]
        [SettingPropertyGroup("Knights without fiefs (stage 2)")]
        public int GentryKnightWage { get; set; } = 24;

        [SettingPropertyBool("Gentry Estate Spend Cap", HintText = "with Clan Budget Enabled: the purchases of a Banner Kings estate (slaves, supplies for the village) come out of the house's arms share of its budget, and never take its head's purse below the Family Purse Floor - a knight without an army does not lose his purse faster than his income allows. Off = the estates buy as before", RequireRestart = false)]
        [SettingPropertyGroup("Knights without fiefs (stage 2)")]
        public bool GentryEstateSpendCap { get; set; } = true;

        [SettingPropertyBool("Army Clothing Enabled", HintText = "every soldier on pay wears out his shoes, clothes and linen: men in a lord's party (yours too) buy leather, felt (woollen cloth) and linen in the towns they leave - piece by piece at the market price, out of their own purse, before they spend the rest on food and drink; a town garrison takes them from its own town's market without paying, for its pay already went into that town's purse; a castle garrison has the castle purse buy them in the town its villages trade with. What cannot be had waits (Army Clothing Max Wait Days), then is only noted in the log. Banner Kings party supplies no longer buy or use up wool, linen or flax for the troops, and their 'Textiles supplies' morale penalty is gone - one rule for clothing, rags carry no penalty (off = no wear, Banner Kings textiles and their morale penalty as before)", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public bool ArmyClothingEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Army Clothing Field Leather Kg", 0.00f, 8.00f, "0.00", HintText = "kg of leather a soldier in a party wears out in a year: four pairs of shoes of about 0.4 kg (a pair lasted a season of marching) and his belts, straps and pouch; a crate of leather on the market is 10 kg", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingFieldLeatherKg { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Army Clothing Field Cloth Kg", 0.00f, 12.00f, "0.00", HintText = "kg of woollen cloth (felt on the market) a soldier in a party wears out in a year: tunic, hood and hose - the yearly livery of a king's archer, two and a half to three yards of cloth - and his share of cloaks and blankets", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingFieldClothKg { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Army Clothing Field Linen Kg", 0.00f, 10.00f, "0.00", HintText = "kg of linen a soldier in a party wears out in a year: two shirts and two pairs of braies (about 1.2 kg) and his share of tents, sacks and bags - a tent for six to ten men lasted a year or two", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingFieldLinenKg { get; set; } = 2.5f;

        [SettingPropertyFloatingInteger("Army Clothing Garrison Leather Kg", 0.00f, 4.80f, "0.00", HintText = "the same for a man of a garrison, who marches little: two pairs of shoes and his belts", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingGarrisonLeatherKg { get; set; } = 1.2f;

        [SettingPropertyFloatingInteger("Army Clothing Garrison Cloth Kg", 0.00f, 8.00f, "0.00", HintText = "woollen cloth a garrison man wears out in a year - tunic and hood last longer behind walls", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingGarrisonClothKg { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Army Clothing Garrison Linen Kg", 0.00f, 4.00f, "0.00", HintText = "linen a garrison man wears out in a year - shirts only, he sleeps under a roof", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public float ArmyClothingGarrisonLinenKg { get; set; } = 1f;

        [SettingPropertyInteger("Army Clothing Max Wait Days", 0, 480, "0", HintText = "how many days of wear the men can put off when the town has no leather, cloth or linen or their purse is empty; beyond that their clothes simply go to rags (noted in the log only, no penalty in the game)", RequireRestart = false)]
        [SettingPropertyGroup("The soldier's clothes")]
        public int ArmyClothingMaxWaitDays { get; set; } = 120;

        [SettingPropertyBool("Supply Demand Enabled", HintText = "arms, armour and horses obey supply and demand in towns and castles: a full stall sells cheap, an empty one dear - for buying AND selling, you and the AI alike (the item's own worth is untouched)", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public bool SupplyDemandEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Supply Demand Base", 0.00f, 16.00f, "0.00", HintText = "pieces of one kind (type and tier) a town of reference prosperity wants on its stalls; fewer for higher tiers", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandBase { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Supply Demand Ref Prosperity", 0.00f, 12000.00f, "0.00", HintText = "prosperity at which a town wants exactly the base amount (0.3x to 3x around it; castles half)", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandRefProsperity { get; set; } = 3000f;

        [SettingPropertyFloatingInteger("Supply Demand Elasticity", 0.00f, 2.00f, "0.00", HintText = "how hard the price reacts: (wanted + 1) / (on the stall + 1) raised to this power", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandElasticity { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Supply Demand Min Factor", 0.00f, 1.00f, "0.00", HintText = "a glutted stall never pays less than this share of the normal price", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandMinFactor { get; set; } = 0.25f;

        [SettingPropertyBool("Retail From Worth", HintText = "the buying price of arms, armour and horses at a market is their worth (with condition) times supply and demand times the merchant's markup - no other mod's surcharges", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public bool RetailFromWorth { get; set; } = true;

        [SettingPropertyFloatingInteger("Retail Markup Percent", 0.00f, 40.00f, "0.00", HintText = "the merchant's markup on what a piece is worth", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float RetailMarkupPercent { get; set; } = 10f;

        [SettingPropertyBool("Horse Sell From Worth", HintText = "what a town or castle merchant pays for a horse or a pack animal starts from its worth (with its condition) and the game's selling terms for the seller (Trade skill, perks, war), and then follows the stall's supply and demand once. Before, the game's own supply factor for horses was already in the price and the stall came on top - one glut counted twice. Buying already works this way; needs Retail From Worth and the historical prices. Off = the price from before stage 8", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public bool HorseSellFromWorth { get; set; } = true;

        [SettingPropertyFloatingInteger("Supply Demand Max Factor", 0.00f, 16.00f, "0.00", HintText = "a starved stall never charges more than this many times the normal price (armour doubled and trebled in wartime shortages)", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandMaxFactor { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Supply Demand Order Weight", 0.00f, 4.00f, "0.00", HintText = "each unmet request (a volunteer who found no armour, a lord who found nothing for his men) adds this much to the town's demand for that kind of piece", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandOrderWeight { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Supply Demand Order Decay", 0.00f, 1.00f, "0.00", HintText = "share of open requests forgotten each day", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandOrderDecay { get; set; } = 0.15f;

        [SettingPropertyFloatingInteger("Supply Demand Order Cap", 0.00f, 240.00f, "0.00", HintText = "at most this many open requests per kind of piece in one town", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandOrderCap { get; set; } = 60f;

        [SettingPropertyInteger("Supply Demand Order Repeat Days", 0, 28, "0", HintText = "one buyer (a garrison, a lord, a notable) places an order for the same kind of gear in a town at most once in this many days - an order is a need, not a count of attempts", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public int SupplyDemandOrderRepeatDays { get; set; } = 7;

        [SettingPropertyFloatingInteger("Supply Demand Trade Percent", 0.00f, 60.00f, "0.00", HintText = "each day traders carry this % of a stall's surplus to the nearest town or castle that lacks it - nothing vanishes, the buyer pays", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandTradePercent { get; set; } = 15f;

        [SettingPropertyFloatingInteger("Supply Demand Trade Range", 0.00f, 1000.00f, "0.00", HintText = "how far (map distance) traders will haul arms to a market that lacks them", RequireRestart = false)]
        [SettingPropertyGroup("Supply and demand")]
        public float SupplyDemandTradeRange { get; set; } = 250f;

        [SettingPropertyBool("Market Glut Enabled", HintText = "a merchant needs only so many of one thing: each extra piece of a type you sell him fetches less. With supply and demand on (and One Scrap Floor) it steps aside - the stall's own supply and demand prices the glut and Min Sell Percent Of Value is the only floor", RequireRestart = false)]
        [SettingPropertyGroup("The glutted market")]
        public bool MarketGlutEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Market Glut Start Percent", 0.00f, 20.00f, "0.00", HintText = "the FLOOR for the first piece: pays at least this % of value - a better trade rate (say 8%) stands as is", RequireRestart = false)]
        [SettingPropertyGroup("The glutted market")]
        public float MarketGlutStartPercent { get; set; } = 5f;

        [SettingPropertyFloatingInteger("Market Glut Drop P P", 0.00f, 1.00f, "0.00", HintText = "each further piece of that type knocks this many percentage points off YOUR rate", RequireRestart = false)]
        [SettingPropertyGroup("The glutted market")]
        public float MarketGlutDropPP { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Market Glut Min Percent", 0.00f, 4.00f, "0.00", HintText = "the rate never falls below this % of the item's value", RequireRestart = false)]
        [SettingPropertyGroup("The glutted market")]
        public float MarketGlutMinPercent { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Market Glut Recover Per Day", 0.00f, 8.00f, "0.00", HintText = "the market digests this many pieces of each type a day - come back later and prices breathe again", RequireRestart = false)]
        [SettingPropertyGroup("The glutted market")]
        public float MarketGlutRecoverPerDay { get; set; } = 2f;

        [SettingPropertyBool("Night Rest Enabled", HintText = "the men must sleep: quiet night hours in camp or under a roof, or the column grows weary", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool NightRestEnabled { get; set; } = true;

        [SettingPropertyBool("Night Rest Every Model", HintText = "the sleep penalties (speed and morale) also work in party models that name the party differently in their code (today: the War Sails morale model, left out before with an error at game start) - still counted once per party; off = those models skip the penalty, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool NightRestEveryModel { get; set; } = true;

        [SettingPropertyInteger("Camp Background", 0, 10, "0", HintText = "picture behind the camp menu: 0 = your culture's riders (old), 1 = an army camp before the walls, 2-10 = Realm of Thrones pictures of army life - try them and keep the one you like", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int CampBackground { get; set; } = 1;

        [SettingPropertyBool("Map Clock Enabled", HintText = "the hour of the day next to the date on the map bar ('Year 299, Day 256, Autumn - 14:30')", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool MapClockEnabled { get; set; } = true;

        [SettingPropertyBool("Readable Date Enabled", HintText = "dates read 'Year 299, Day 256, Autumn': the year, the day of that year (1 to 364) and the season - on the map bar, in the encyclopedia and war logs, in the notices with a scene and in the Iron Bank's terms; the day turns at midnight sharp; off = the old 'Day 3659 of Summer, 299 AC' (which now turns at midnight too)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool ReadableDateEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Fast Forward Multiplier", 0.00f, 32.00f, "0.00", HintText = "how fast the fast-forward button runs (vanilla 4) - a 364-day year and slow marches need a quicker clock; with Map Speed Buttons on, the chosen Fast / Very Fast speed is used instead", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float FastForwardMultiplier { get; set; } = 8f;

        [SettingPropertyFloatingInteger("Sleep Hours Needed", 0.00f, 24.00f, "0.00", HintText = "base hours of sleep per day; sleep debt adds interest on top (1 night owed: +3h, 2: +9h, 3: +15h) and only the full sum clears it", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float SleepHoursNeeded { get; set; } = 6f;

        [SettingPropertyFloatingInteger("Day Rest Factor", 0.00f, 2.40f, "0.00", HintText = "sleep by daylight counts at this rate (camp noise, heat, light) - night hours count in full", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float DayRestFactor { get; set; } = 0.6f;

        [SettingPropertyBool("Quick Camp Key", HintText = "press O on the campaign map to pitch the BannerKings camp on the spot", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool QuickCampKey { get; set; } = true;

        [SettingPropertyBool("Sleep At Sea Free", HintText = "crews sleep in watches - sailing through the night builds no sleep debt", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool SleepAtSeaFree { get; set; } = true;

        [SettingPropertyBool("Ai Camps At Night", HintText = "the world sleeps too: lord parties and caravans halt for the night (camp hours) unless chased or in action", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiCampsAtNight { get; set; } = true;

        [SettingPropertyBool("Ai Camp Fast Scan", HintText = "camping caravans look for enemies only in the map squares around them instead of checking every lord and band in the world - the same alarms, found faster; off = the old full check", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiCampFastScan { get; set; } = true;

        [SettingPropertyInteger("Camp Start Hour", 0, 23, "0", HintText = "hour the world makes camp (lords, armies, caravans, day-hunting bands, your nightfall prompt); 0 and 6 = midnight to six; equal hours = no camp", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int CampStartHour { get; set; } = 0;

        [SettingPropertyInteger("Camp End Hour", 0, 23, "0", HintText = "hour the world breaks camp and marches on; 0 and 6 = midnight to six; equal hours = no camp (your own sleep then still settles at 6)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int CampEndHour { get; set; } = 6;

        [SettingPropertyBool("Ai Bandits Camp Too", HintText = "brigands sleep as well - hideout by day, their own fire in the field by night", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiBanditsCampToo { get; set; } = false;

        [SettingPropertyInteger("Ai Tent Cap", 0, 240, "0", HintText = "at most this many AI camps get a tent icon on the map - the rest still sleep, just without the picture", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int AiTentCap { get; set; } = 60;

        [SettingPropertyFloatingInteger("Ai Tent Radius", 0.00f, 400.00f, "0.00", HintText = "tent icons appear only this close to your party - the world beyond still sleeps, just without the picture", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float AiTentRadius { get; set; } = 100f;

        [SettingPropertyInteger("Ai Camp Skip Percent", 0, 60, "0", HintText = "this share of CARAVANS press on through any given night - not everyone pitches camp; lone lords roll it only while Ai Night March By Reason is off, army leaders never while Army Leaders Always Camp is on", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int AiCampSkipPercent { get; set; } = 15;

        [SettingPropertyBool("Army Leaders Always Camp", HintText = "with Ai Night March By Reason off: army leaders never skip the night camp - the whole host halts (only a nearby enemy, a chase or a siege keeps it marching); off = they roll the skip share like any lord. With March By Reason on a host marches by night only for a reason, like a lone lord", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool ArmyLeadersAlwaysCamp { get; set; } = true;

        [SettingPropertyBool("Bandits Rest By Day", HintText = "every band has a nature: three in four are night hunters (lie low 10-16), one in four hunts by day and beds down at night (camp hours)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool BanditsRestByDay { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Nights Awake In Chase", 0.00f, 4.00f, "0", HintText = "whole sleepless nights owed after which a lord no longer chases or rides to relief at night - the loss would outweigh the gain; fleeing stays allowed until Max Forced Nights orders a rest. 0 = only flight by night, 3 or more = only the collapse stops them", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float AiNightsAwakeInChase { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Ai Camp Danger Radius", 0.00f, 24.00f, "0.00", HintText = "alarm radius: a STRONGER hostile party this close that is awake and coming at a camp (or at a lord resting in a village) rouses it - the lord flees or beds down again; 0 = no alarm at all (with Ai Night March By Reason off: any hostile party this close keeps them marching)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float AiCampDangerRadius { get; set; } = 6f;

        [SettingPropertyBool("Ai Night March By Reason", HintText = "lone lords and army leaders march through the camp hours only for a reason: a chase after an enemy lord, host or a band in a fight that they can finish tonight, the relief of their own village while it is being raided, or flight from a stronger foe - everyone else sleeps, and a lord in a town, castle or village stays under its roof till dawn (in a village a stronger foe coming at him wakes him); off = the old rules (a share of lone lords skips the camp, any enemy near keeps them marching) and the log only counts what would have happened", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiNightMarchByReason { get; set; } = true;

        [SettingPropertyBool("Ai Sleep Debt", HintText = "AI lord parties keep the same sleep ledger as you: a day without the base hours of rest (Sleep Hours Needed) costs speed and morale (-25/-40/-90% and -25/-40/-95%) until slept off, and a dawn met with that debt costs their men's drill until the next dawn (Drill Penalty Ai, Drill Law Ai); one night owed means making camp at 20:00 until the world breaks camp, two or more means sleeping where they stand until paid; off = the ledger is only counted in the log", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiSleepDebt { get; set; } = true;

        [SettingPropertyBool("Ai Night Relief Wider", HintText = "on: lords also march through the night to relieve a BESIEGED town or castle of their realm, and army leaders ride to relief too; off: only a lone lord, and only to stop a raid in progress", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AiNightReliefWider { get; set; } = false;

        [SettingPropertyInteger("Max Forced Nights", 0, 5, "0", HintText = "AI lords march through at most this many sleepless nights in a row: after that - or once they owe this many nights - they must make camp and rest until the debt is fully slept off, with no night chase, relief or flight; only a foe at least twice as strong (who would destroy them) still sends them running. A host rests as one: its leader decides by the most tired party in the army. 0 = no limit (old rules)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int MaxForcedNights { get; set; } = 2;

        [SettingPropertyBool("Camp Tent Icon", HintText = "pitched camps show a tent on the map (yours and theirs)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool CampTentIcon { get; set; } = true;

        [SettingPropertyBool("Course Plotter Enabled", HintText = "clicking a destination reports the route: kilometres, hours in the saddle and days on the road, and flags a settlement target on the map", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool CoursePlotterEnabled { get; set; } = true;

        [SettingPropertyBool("Nightfall Prompt Enabled", HintText = "when the camp hour strikes a marching column is asked to make camp; the popup lets you set always-camp or never-ask (choice lives in the save)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool NightfallPromptEnabled { get; set; } = true;

        [SettingPropertyBool("Night Ledger Clock", HintText = "the sleep ledger keeps the true hour: the night camp, the dawn reckoning and your rest count by the hour each hourly tick was due, not the hour it happened to land in - at high speed no dawn is skipped and no camp night shrinks to five hours (yours and the AI's); off = the old way", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool NightLedgerClock { get; set; } = true;

        [SettingPropertyBool("Player Sleep Guard", HintText = "sleep that is cut short ends properly: when an attack or another menu breaks your bedded-down sleep, the hours slept still count and you are no longer treated as asleep; a sleep that runs past dawn is judged when you wake - rise before the base hours are made up and the night counts as sleepless; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool PlayerSleepGuard { get; set; } = true;

        [SettingPropertyBool("Night March Notice", HintText = "night marches are told plainly: the first camp hour your column is on the move (not only the camp-start hour) brings the nightfall question or your standing order, marching on brings a warning, standing still pitches camp with a note, and each dawn says how long the men rested and why they do or do not owe sleep; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool NightMarchNotice { get; set; } = true;

        [SettingPropertyBool("Town Inns", HintText = "in a town you can take lodgings at an inn: a common room (straw - 1 a man, 1 a horse, 3 for your own room), a decent inn (beds, a warm hearth, ale - 2/2/8) or a good house (rooms, wine, a bath - 4/3/20); the men still eat from their own wagons. Every soldier pays for himself and his horse from his own purse; companions pay from their own purses (with Companion Wage By Level off, the rest from the men's purse, where their pay then goes) (who cannot afford it takes a cheaper bed or the stable, free); you pay for yourself, your horse and the horses that carry nobody (in the baggage or the armoury). Taken in the evening or at night (from 18:00 with the usual camp hours) you sleep until dawn, by day until the men have slept; you wake rested until dusk, at most 12 hours: +5/+10/+12% speed on the map and +2/+5/+8 morale, weighted by how many slept in each kind of bed (only with no sleep debt); a decent inn or a good house also pays off sleep debt a quarter faster, and a good house heals the wounded half again as fast that night. The coin goes to the townsfolk who keep the inns. Needs Night Rest. Off = no inns, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool TownInns { get; set; } = true;

        [SettingPropertyBool("Town Inn Price Bonus", HintText = "after a night in a good house (asleep until dawn) you trade a little better in that same town until dusk, at most 12 hours: you buy up to 3% cheaper and sell up to 3% dearer in the trade screen - never more than half the town's own gap between buying and selling, so buying and selling back never pays - and only until you have gained about 100 denars by it. Off = the good house gives no price bonus", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool TownInnPriceBonus { get; set; } = true;

        [SettingPropertyBool("Roadside Inns", HintText = "inns stand by the roads between the towns and castles - fewer where fewer people live, none beyond the Wall. Click one on the map and your party rides there and goes in (stopping next to one asks you in): take lodgings at the same prices and with the same rest as a town inn - most roadside inns have only a common room, or a common room and a decent inn - and the coin goes to the purse of the village whose lands the inn stands on (its lord takes his usual share, the same rule as for the sutlers - Village Tribute From Sutlers). Lodgings need Town Inns and Night Rest. Off = no roadside inns, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool RoadsideInns { get; set; } = true;

        [SettingPropertyBool("Inn Gossip", HintText = "in a roadside inn and in a town inn you can listen to the gossip: bands of outlaws about and how long they have been robbing, how much they have taken, bandit lairs and the treasure in them, lords' hosts on the march, caravans, prices in the towns nearby and news of the wars - all from what is really happening, but the farther away and the older the news, the less exact it is (numbers grow in the telling, a direction instead of a place). Off = no gossip, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool InnGossip { get; set; } = true;

        [SettingPropertyBool("Inn Gossip Loot Words", HintText = "gossip tells how much a band of outlaws has taken in words - a few stolen coins, a fair haul, rich spoils, a great haul of plunder, a huge hoard - never an exact sum, since nobody has counted a bandit's purse; the treasure in a bandit lair the same way. Far away the tale grows in the telling. Off = sums in denars, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool InnGossipLootWords { get; set; } = true;

        [SettingPropertyBool("Inn Gossip Leader Names", HintText = "gossip names a band of outlaws after its leader - 'Jon Rivers and his bandits' - instead of its kind ('Broken Men'): a band led by a hero goes by the hero's full name, any other band gets a leader with a name from the land it comes from and keeps that name for as long as it lives (kept in the save). Also in the news of burned villages. Off = the kind of band and a nickname, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool InnGossipLeaderNames { get; set; } = true;

        [SettingPropertyBool("Inn Gossip Pages", HintText = "the gossip window never overflows its frame: when there is more talk than fits, it is split into pages - 'Hear more' shows the next one, 'Enough talk' ends it. Off = all the gossip in one window, as before", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool InnGossipPages { get; set; } = true;

        [SettingPropertyBool("Anvil Shift Enabled", HintText = "waiting at the forge runs in day shifts: after AnvilShiftHours of work the smith beds down for his needed sleep (6h, more with sleep debt), then returns to the hammer", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool AnvilShiftEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Anvil Shift Hours", 0.00f, 72.00f, "0.00", HintText = "hours of work at the anvil before the smith must sleep", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float AnvilShiftHours { get; set; } = 18f;

        [SettingPropertyBool("Workshop Night Rest", HintText = "the apprentices sleep too: forge projects make no progress between 23:00 and 5:00 - a day of work is a day at the anvil", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool WorkshopNightRest { get; set; } = true;

        [SettingPropertyFloatingInteger("Armour Kg Per Athletics", 0.00f, 1.33f, "0.00", HintText = "Weight Law: kilograms of armour one Athletics point can carry - the ONLY Athletics requirement of armour (Jeff 09.10: everything from weight): difficulty = weight / this, set exactly (also lowered below the Realm of Thrones values), so gloves, capes, hats and gowns ask almost nothing and the heaviest 50 kg plate asks 150; applied at session start", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float ArmourKgPerAthletics { get; set; } = 0.333f;

        [SettingPropertyInteger("Armour Tier Athletics", 0, 10, "0", HintText = "Armour Tier Law: any piece of armour (helmet, body, boots, gloves, cape) needs at least (tier - 1) x this Athletics, whatever its weight says - tier 4 boots want 105, so a low-Athletics bandit never 'qualifies' for them; 0 turns the law off (default since 09.10 - Jeff: armour by weight only). Applied at session start, after the Weight Law (the higher of the two wins)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public int ArmourTierAthletics { get; set; } = 0;

        [SettingPropertyBool("Hit Scribe Enabled", HintText = "battle log: every missile hit written to Armoury.log (weapon, victim, body part, damage, armor absorbed) - capped per mission", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HitScribeEnabled { get; set; } = true;

        [SettingPropertyBool("Armor Sanity Enabled", HintText = "Armour Sense Law: outliers get levelled to the norm of their type and tier - no more 4 kg chaps outarmouring plate; the world's balance stays put", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool ArmorSanityEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Armor Outlier Percentile", 0.00f, 300.00f, "0.00", HintText = "Armour Sense Law: the norm is this percentile of total protection within (type, tier)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float ArmorOutlierPercentile { get; set; } = 75f;

        [SettingPropertyFloatingInteger("Armor Outlier Tolerance", 0.00f, 5.20f, "0.00", HintText = "Armour Sense Law: pieces above norm x this get trimmed down to it", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float ArmorOutlierTolerance { get; set; } = 1.30f;

        [SettingPropertyBool("Camp Battle Props Enabled", HintText = "attacked while encamped, the field battle gets your camp dressed on it once your men are deployed - tents, a campfire and a fence behind you, torches around you; scenery only (no collision: nobody gets stuck in it, arrows fly through), nothing closer than 6 m to you; missing prefabs are skipped and logged", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool CampBattlePropsEnabled { get; set; } = true;

        [SettingPropertyBool("Hideout Alarm Enabled", HintText = "a fight in a hideout wakes the camp: bandits within earshot come running - no more men ignoring a brawl ten paces away", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HideoutAlarmEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Hideout Alarm Scream Radius", 0.00f, 160.00f, "0.00", HintText = "a wounded man's cry and the ring of steel carry this many meters - bandits inside come at you, further ones sleep on", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float HideoutAlarmScreamRadius { get; set; } = 40f;

        [SettingPropertyFloatingInteger("Hideout Alarm Witness Radius", 0.00f, 48.00f, "0.00", HintText = "a CLEAN one-blow kill alarms only enemies this close to the body - no witnesses, no alarm", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float HideoutAlarmWitnessRadius { get; set; } = 12f;

        [SettingPropertyBool("Hideout Armoury Gear", HintText = "your men storm hideouts in their ARMOURY kit, same as field battles (opens the gate DTE leaves shut in regular hideouts)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HideoutArmouryGear { get; set; } = true;

        [SettingPropertyBool("Hideout Noise Enabled", HintText = "running feet carry in a hideout: bandits within earshot come alarmed - WALK (Left Ctrl) to move quietly", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HideoutNoiseEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Hideout Hear Day", 0.00f, 40.00f, "0.00", HintText = "meters a RUNNING man is heard by day - the camp's own bustle masks a lot", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float HideoutHearDay { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Hideout Hear Night", 0.00f, 80.00f, "0.00", HintText = "meters a RUNNING man is heard at night - silence carries sound, so sneak at a walk", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float HideoutHearNight { get; set; } = 20f;

        [SettingPropertyBool("Hideout Alarm Relay", HintText = "a woken man shouts too: the alarm leaps man to man while each next stands within scream range of the last - never across the whole camp at once", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HideoutAlarmRelay { get; set; } = true;

        [SettingPropertyFloatingInteger("Hideout Noise Per Armor Kg", 0.00f, 1.00f, "0.00", HintText = "every kilogram of worn armour adds this many meters to a RUNNING man's noise - plate thunders, leather whispers", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float HideoutNoisePerArmorKg { get; set; } = 0.2f;

        [SettingPropertyBool("Hideout Alarm Voice", HintText = "the alarm is HEARD: one man in every ring of the relay lets out a real battle yell (the game's own voice line)", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool HideoutAlarmVoice { get; set; } = true;

        [SettingPropertyBool("Sight Cycle Enabled", HintText = "eyes follow the sun: every party sees further by day and shorter after dark", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public bool SightCycleEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Day Sight Factor", 0.00f, 4.60f, "0.00", HintText = "spotting range in daylight, times this", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float DaySightFactor { get; set; } = 1.15f;

        [SettingPropertyFloatingInteger("Night Sight Factor", 0.00f, 2.60f, "0.00", HintText = "spotting range at night - the cut is mild, for you HEAR more after dark: a marching column is loud", RequireRestart = false)]
        [SettingPropertyGroup("A night's rest")]
        public float NightSightFactor { get; set; } = 0.65f;

        [SettingPropertyBool("Map Speed Buttons", HintText = "three speed buttons above the clock on the campaign map: x1 (normal play), Fast and Very Fast. The chosen fast speed is used only while time runs fast - also by the game's own fast-forward button, key 3 and holding space; off = the fast-forward speed comes from Fast Forward Multiplier as before. The buttons are added to the map bar when the game starts: switched off, they are only hidden until you restart the game, and switched back on they come back after a restart (keys 4, 5 and 6 work at once)", RequireRestart = true)]
        [SettingPropertyGroup("Map speed buttons")]
        public bool MapSpeedButtons { get; set; } = true;

        [SettingPropertyInteger("Map Speed Fast", 2, 16, "0", HintText = "the Fast button: how many times faster than normal play", RequireRestart = false)]
        [SettingPropertyGroup("Map speed buttons")]
        public int MapSpeedFast { get; set; } = 4;

        [SettingPropertyInteger("Map Speed Very Fast", 2, 32, "0", HintText = "the Very Fast button: how many times faster than normal play", RequireRestart = false)]
        [SettingPropertyGroup("Map speed buttons")]
        public int MapSpeedVeryFast { get; set; } = 8;

        [SettingPropertyBool("Map Speed Keys", HintText = "keys 4, 5 and 6 on the campaign map pick Normal, Fast and Very Fast speed (keys 1, 2, 3 and space keep their usual jobs)", RequireRestart = false)]
        [SettingPropertyGroup("Map speed buttons")]
        public bool MapSpeedKeys { get; set; } = true;

        [SettingPropertyBool("Map Speed Perf", HintText = "leaner bookkeeping at high map speed, same outcome: AI camp tents near you go up and come down a few per frame instead of all in one frame, the map clock text refreshes at most ten times a second while time runs fast, resting bands look for nearby lords through a map grid; off = the old way", RequireRestart = false)]
        [SettingPropertyGroup("Map speed buttons")]
        public bool MapSpeedPerf { get; set; } = true;

        [SettingPropertyBool("Combat Xp Fix Enabled", HintText = "RBM pays the same XP for an arena tap and a battlefield kill - restore the proportions", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool CombatXpFixEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Arena Xp Percent", 0.00f, 80.00f, "0.00", HintText = "practice bouts teach this share of the battle rate (vanilla 6, RBM 100)", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public float ArenaXpPercent { get; set; } = 20f;

        [SettingPropertyFloatingInteger("Tournament Xp Percent", 0.00f, 200.00f, "0.00", HintText = "tournament bouts teach this share of the battle rate (vanilla 33, RBM 100)", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public float TournamentXpPercent { get; set; } = 50f;

        [SettingPropertyBool("Battle Xp Scales With Damage", HintText = "real battles: XP follows the damage dealt and a kill pays double - not a flat fee per swing", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool BattleXpScalesWithDamage { get; set; } = true;

        [SettingPropertyBool("Skill Ledger Log", HintText = "Writes daily lines telling how much skill experience heroes and troops earned and from what (diagnostics only; nothing in the game changes).", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool SkillLedgerLog { get; set; } = true;

        [SettingPropertyBool("Shot Xp Fair", HintText = "RBM's experience for every loosed arrow, bolt or thrown weapon is paid only in a real battle and at a third (bow 10, crossbow 20, thrown 17, sling 10); in the arena, a tournament or at practice a shot alone teaches nothing - the hit still does.", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool ShotXpFair { get; set; } = true;

        [SettingPropertyBool("Steward Food Xp Fair", HintText = "Steward experience from feeding the party grows with the square root of its size, not with every mouth; a kind of food counts only from half a day's supply for the whole party; winter adds a quarter instead of a half.", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool StewardFoodXpFair { get; set; } = true;

        [SettingPropertyBool("Scout Xp Fair", HintText = "Scouting experience from marching is a flat 10 an hour (16 in forest, desert, dunes or snow; caravans half) for every party on the move - no longer more for a longer column, nothing extra for AI parties, and small parties learn too.", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool ScoutXpFair { get; set; } = true;

        [SettingPropertyBool("Small Xp Fair", HintText = "The fence teaches a flat 25 Roguery per deal instead of 5% of the coin paid; mending a piece with your own hands teaches in proportion to the condition you restore (at least a quarter).", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool SmallXpFair { get; set; } = true;

        [SettingPropertyBool("Rbl Paid Xp Fair", HintText = "Realistic Bannerlord no longer gives Charm or Roguery experience for coin handed over (a bought council vote, a planted spy, hired saboteurs); the relation you gain still teaches Charm.", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public bool RblPaidXpFair { get; set; } = true;

        [SettingPropertyInteger("Attribute Point Every Levels", 0, 12, "0", HintText = "Every this many character levels a hero gains one attribute point - you, your companions and every lord alike, when they level up and when the game creates them at a higher level (3 = levels 3, 6, 9 ... 60, twenty points by level 62; 0 or 4 = as in the game: levels 4, 8 ... 60, fifteen points).", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public int AttributePointEveryLevels { get; set; } = 3;

        [SettingPropertyInteger("Extra Focus Every Levels", 0, 12, "0", HintText = "Every this many character levels a hero gains one more focus point on top of the game's one per level and Banner Kings' one every fifth level - you, your companions and every lord alike, also when the game creates a lord at a higher level (4 = levels 4, 8 ... 60, fifteen more by level 62; 0 = off).", RequireRestart = false)]
        [SettingPropertyGroup("The worth of a lesson")]
        public int ExtraFocusEveryLevels { get; set; } = 4;

        [SettingPropertyBool("Troop Mend Enabled", HintText = "the town smith mends the worn gear on the troop armoury's racks - his apprentices work at a bulk rate", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public bool TroopMendEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Troop Mend Wreck Share", 0.00f, 1.00f, "0.00", HintText = "with Smith Mend From Market off: mending a piece on the men's racks costs this share of the worth it has lost (60% condition = 4% of worth); wrecks themselves are not mended while Wrecks To Scrap is on (off: a WRECK at 1% costs this share of its worth)", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public float TroopMendWreckShare { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Troop Mend Bulk Discount P P", 0.00f, 2.00f, "0.00", HintText = "every piece on the job knocks this many percent off the whole bill - the more racks, the better the rate", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public float TroopMendBulkDiscountPP { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Troop Mend Bulk Discount Max", 0.00f, 120.00f, "0.00", HintText = "the bulk discount never grows past this percent", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public float TroopMendBulkDiscountMax { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Troop Mend Max Hours", 0.00f, 96.00f, "0.00", HintText = "the whole job never takes longer than this - the smith puts every hand he has on it", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public float TroopMendMaxHours { get; set; } = 24f;

        [SettingPropertyBool("Camp Armourer", HintText = "the companion with the best Smithing in your party works as the company armourer: while you camp, besiege or rest outside a town (not on the march, not at night) he mends your men's worn metal kit from the stores - weapons, mail, plate, helms - worst first, slower than a town workshop (more Smithing, quicker hands), with the materials from your baggage (iron, charcoal, leather...) as when you mend it yourself; he learns Smithing only for the hours he really works (8 experience an hour, at most 100 a day); a piece he has begun stays on his anvil until it is done; wrecks, horses, leather, cloth, bows and shields are not his work", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public bool CampArmourer { get; set; } = true;

        [SettingPropertyBool("Troop Order Enabled", HintText = "order missing kit for the men from the town smith - plain pieces of the tier you ask, straight onto the racks", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public bool TroopOrderEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Troop Order Markup", 0.00f, 4.60f, "0.00", HintText = "the smith's fee: each procured piece costs its market worth times this (not used while Troop Order From Shelf is on - then the shelf price plus the smith's legwork)", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public float TroopOrderMarkup { get; set; } = 1.15f;

        [SettingPropertyBool("Troop Order From Shelf", HintText = "the smith procures the men's kit off THIS town's stalls: the cheapest sound piece of the type and tier you ask that is really on sale here, each at the stall's own buying price (the price your men's purse and the lords pay - every further piece dearer as the stall empties), plus his legwork: a fifth of a craftsman's day a piece (3 d a day, as dear as the town is prosperous), all paid into the town's coffers; what the stalls lack is passed to the town's workshops as an order and costs you nothing (off = as before: the cheapest such piece anywhere in the world at its worth times the markup, delivered only if this stall happens to hold it)", RequireRestart = false)]
        [SettingPropertyGroup("The men's gear")]
        public bool TroopOrderFromShelf { get; set; } = true;

        [SettingPropertyFloatingInteger("Smith Repair Hours Per Piece", 0.00f, 6.00f, "0.00", HintText = "hours the smith needs per worn piece of your harness", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float SmithRepairHoursPerPiece { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Self Repair Hours Per Piece", 0.00f, 10.00f, "0.00", HintText = "hours you need per piece working the anvil yourself", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float SelfRepairHoursPerPiece { get; set; } = 2.5f;

        [SettingPropertyFloatingInteger("Mend Loot Hours Per Piece", 0.00f, 2.40f, "0.00", HintText = "hours per battle-worn piece from the bags", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float MendLootHoursPerPiece { get; set; } = 0.6f;

        [SettingPropertyBool("Mend Hours By Guild", HintText = "a repair in town takes as many working hours as it really would, and the right trade does it: smiths for metal, saddlers for leather and saddles, tailors for cloth and padded coats, bowyers for bows and crossbows, shieldmakers for shields. A lightly worn sword is an hour or two, a battered brigandine about 140 hours, so a big haul of loot takes a day or two; hours spent mending yesterday are missing from that trade's workshop work today. Your orders (loot, a single piece, your harness, the men's racks) take as long as the trade's free hands need - what does not fit today goes on tomorrow, so Troop Mend Max Hours no longer cuts the men's racks short. The price of the repair does not change (off = every piece 0.6 hours at the smiths, your harness 1.5 hours a piece, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendHoursByGuild { get; set; } = true;

        [SettingPropertyBool("Auto Mend Half Guild", HintText = "with Mend Hours By Guild on: the repairs nobody orders by hand - the AI lords' men and your own men paying from their purse - together take at most half of each trade's working hours in a town each day, so the workshops never stand idle and some hands stay free for your own orders (off = they may take every free hour)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AutoMendHalfGuild { get; set; } = true;

        [SettingPropertyBool("Mend Bulk Every Order", HintText = "the bulk rate of the men's racks (Troop Mend Bulk Discount: 0.5% off the work per piece, up to 30%) applies to every repair order in a town: your loot from the bags, your harness, your men's daily mending and each AI lord's day at the smiths - the more pieces in one order, the bigger the rate; off the work only, not the materials or the hours (off = only on the men's racks, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendBulkEveryOrder { get; set; } = true;

        [SettingPropertyFloatingInteger("Mend Material Max Share", 0.00f, 1.00f, "0.00", HintText = "mending is NOT forging anew: even a wreck (1%) takes at most this share of the full recipe's materials - and of the days of work that made the piece", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float MendMaterialMaxShare { get; set; } = 0.20f;

        [SettingPropertyBool("Smith Mend From Market", HintText = "the town smiths' rule for every repair in a town (the mending bench, the quartermaster, your men, the lords' men): the work is paid like the making of the piece - its share of the days a master spent forging it, at the master's historical day wage, as dear as the town is prosperous; the mending bench (and, with Mend Material Men And Lords, your men's and the lords' repairs) also charges the materials they take from this market at its prices - iron (crude iron, scrap from wrecks or ore), wood, leather, linen or wool, more the worse the piece; with no such materials on the market the piece waits; wrecks (Mangled, or worn to a tenth of their worth or less - see Wrecks To Scrap) are not restored for coin - mend them yourself with your own materials, or melt them down (off = as before: the smith's price only, no materials, wrecks restored)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool SmithMendFromMarket { get; set; } = true;

        [SettingPropertyBool("Wrecks To Scrap", HintText = "wrecks go to the scrap heap: no town smith restores a wreck for coin on any road - not the mending bench, not 'Pick a piece', not the men's racks (with Smith Mend From Market on or off), not your harness, not your men's or the lords' repairs. A wreck is Mangled loot or any piece worn to a tenth of its worth or less (on your back: worn to 10% or less); it stays a wreck - melt it down (the smiths also take wrecks off the market as scrap iron for their mending), or mend it at your own anvil with your own materials (off = as before: wrecks below a tenth are refused, a piece at exactly a tenth is restored, and with Smith Mend From Market off the men's racks restore wrecks for Troop Mend Wreck Share of their worth)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool WrecksToScrap { get; set; } = true;

        [SettingPropertyBool("Mend Metal By Kind", HintText = "town smiths mending a piece take only the new iron that mending really needs, not a fixed share of a new piece: rivets and a few plates for plate (1% of its iron Plundered, 2% Damaged, 4% Battered), buckles and studs for leather and cloth (2/3/6%), almost none for blades (0/0.5/1.5%) and spear heads (0/0.5/2%), more for shield rims and bosses (4/8/12%) and crossbow locks (3/6/11%); other states (e.g. Dented, Rusty) fall between these points by how much of the piece is lost; the forge fuel follows the iron; mail keeps the old rule (badly cut mail needs many new rings); the work, the wood, leather and cloth are paid as before (off = iron and forge fuel at Mend Material Max Share times the damage, as before: 9/12/15% of the recipe Plundered/Damaged/Battered)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendMetalByKind { get; set; } = true;

        [SettingPropertyBool("Mend Material Men And Lords", HintText = "with Smith Mend From Market on: the repairs your men pay for from their own purse each hour in a town, and the repairs the lords' men pay for, also take the materials from this market at its prices - the same rule and the same price as the mending bench (iron, wood, leather, linen or wool, more the worse the piece); a piece the market has no material for waits, the next goes ahead; off = your men's and the lords' repairs are the work only, as before", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendMaterialMenAndLords { get; set; } = true;

        [SettingPropertyBool("Self Repair Same Rule", HintText = "mending at your own anvil takes materials by the same rule as the town smiths: Mend Material Max Share of the piece's recipe times the damage, the iron and forge coal only as much as mending that kind of piece really needs (as Mend Metal By Kind), the wood, leather and cloth by the damage; a light repair may take no material at all; wrecks still take the full share of iron (off = as before: Self Repair Material Factor of every part of the recipe times the damage, at least one of each when mending all you wear)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool SelfRepairSameRule { get; set; } = true;

        [SettingPropertyBool("Ai Mends Worn Only", HintText = "the lords' men and the garrisons have the town smiths mend only the kit their men actually wear (the same fitting that decides what is spare - the men take the sound pieces first); battered loot beyond their needs is not mended - it goes to the merchants as it is when they sell their spare kit, and the money they keep for repairs covers only the kit they wear (off = as before: every battered piece in their armoury is mended)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiMendsWornOnly { get; set; } = true;

        [SettingPropertyBool("Mend Pay To Folk", HintText = "the work part of what your men and the lords' men pay the town smiths for mending (not the material) goes to the townsfolk's purse as craft wages, the same way as the workshop wages (needs Town Folk Live on); the material part stays in the town's coffer (off = as before: the whole payment goes to the town's coffer)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendPayToFolk { get; set; } = true;

        [SettingPropertyBool("Ai Wear By Intensity", HintText = "the wear of the lords' and garrisons' kit after a battle follows how hard that party fought (its dead and wounded against the men it started with - the rule for your own men in a battle fought without you): a skirmish wears a tenth of the usual share, a slaughter three times as much; the pieces hit are those the men actually wear (the fitting that decides what is spare), and a piece already battered goes one step worse, down to a wreck (off = as before: a fixed Troop Wear Percent of the pieces in use, only sound pieces are hit)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiWearByIntensity { get; set; } = true;

        [SettingPropertyBool("Ai Mend Queue Continue", HintText = "the lords' men and the garrisons have the cheapest repairs done first, and a piece they cannot pay for today waits while the next is tried; buying missing kit no longer spends the coin their purse keeps back for repairs - the lord's own purse pays that part, within the budget he already had for kit; the coin kept back is reckoned at the wages of the town they stand in (off = as before: the worst pieces first, the whole day's mending stops at the first piece the purse cannot pay, purchases take the purse first)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiMendQueueContinue { get; set; } = true;

        [SettingPropertyBool("Ai Ammo Use", HintText = "after a battle the lords' parties and the garrisons use up arrows, bolts and throwing weapons from their armoury - the pieces in use times how hard the party fought; the beaten lose them all, the victors pick most of theirs up again (Ammo Recover Percent + Ammo Repair Percent); they buy more at the markets like any missing kit. In a battle fought on the field with you the arrows are already counted shot by shot, as for your own men, and are not taken a second time (off = as before: the lords and the garrisons lose arrows only in battles fought on the field with you; the daily log only counts what would have been used up)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiAmmoUse { get; set; } = true;

        [SettingPropertyBool("Ai Ammo Order Full", HintText = "when a lord's men, a garrison or your own smith leave a market still short of arrows or bolts and none of the right kind is left on the stall, the order they leave with the town's fletchers is for all they still lack (up to Supply Demand Order Cap), not just 10 - the fletchers see what the armies really need and work their idle hands while it pays (off = at most 10 of a kind from one visit, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiAmmoOrderFull { get; set; } = true;

        [SettingPropertyBool("Ai Skip Fine Goods", HintText = "the lords' men and the garrisons, buying the kit they lack, leave the finer-than-usual pieces on the shelf (Fine, Masterwork and the like): their armoury keeps no record of such quality, so the piece would turn ordinary the moment they paid the higher price for it; those pieces stay for you and for the heroes (off = as before: they buy them and the quality is lost)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiSkipFineGoods { get; set; } = true;

        [SettingPropertyBool("Ai Skip Townsfolk Dress", HintText = "the lords' men and the garrisons, buying the kit they lack, do not buy clothing marked as civilian wear that no soldier of any land has in his kit - gowns, court dress, lordly finery (the same list by which the town workshops do not make such pieces as army kit); the boots, gloves, hoods and tunics that soldiers do wear are bought as before, and so are weapons, arrows and horse harness (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiSkipTownsfolkDress { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Gear Max Price Factor", 0.00f, 5.00f, "0.0", HintText = "the most the lords' men and the garrisons pay for a piece of kit they lack, as a multiple of what that very piece is worth in its condition (3 = at most three times its worth; a value below 1 counts as 1); a dearer piece stays on the shelf and the want goes to the town's workshops as an order. Saddles for riders follow the same ceiling (0 = off, as before: they pay whatever the shelf asks; the daily log line counts what a ceiling of 2 would have stopped)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float AiGearMaxPriceFactor { get; set; } = 3f;

        [SettingPropertyBool("Ai Harness Surplus Sell", HintText = "horse harness lying in a lord's or a garrison's armoury beyond what its riders need - the riders, the men ready to be raised to horse and a tenth to spare, then half as much again - is sold to the merchants of the town or castle like other spare kit: the merchants pay from their coffer, the lord takes his third and the rest goes to the men's purse; the cheapest pieces go first (off = as before: the harness of fallen riders lies in the armoury for ever)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool AiHarnessSurplusSell { get; set; } = true;

        [SettingPropertyBool("Mend Fraction Memory", HintText = "with Self Repair Same Rule on: the bit of each material that a repair at your own anvil uses but that does not make a whole piece is not lost - it is tallied (one tally per material in your bags, kept in the save) and a whole piece comes off your bags once the tally reaches one (several at once if more); when the pieces due are not in your bags the repair waits, as for any missing material (off = as before: each material rounded to whole pieces per repair, a light repair may take none at all)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendFractionMemory { get; set; } = true;

        [SettingPropertyBool("Mend Take By Kind", HintText = "mending a single piece with your own hands takes leather, linen and velvet the way they are counted - from any goods of that kind in your bags (furs and hides for leather, and so on), never below zero; until now only the exact item came off, so with nothing but its varieties in the bags the repair cost no leather at all or left a stack below zero (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool MendTakeByKind { get; set; } = true;

        [SettingPropertyBool("Small Fixes8", HintText = "five small corrections at the smith's: the work part of what you pay the town smiths for mending goes on to the townsfolk's purse as craft wages, like the repairs of your men and the lords' men (needs Mend Pay To Folk on); a worn piece on your back has one smith's price whether you pick it from the list or mend everything you wear; the clan screen shows a workshop's daily keep at its town's wage level - what it really pays; an order off the stalls cut short by your purse still sends word to the workshops of the pieces the stalls lacked; and the smiths' cheapest-first estimate no longer miscounts very light bars (off = all five as before)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool SmallFixes8 { get; set; } = true;

        [SettingPropertyBool("Take Apart Enabled", HintText = "take a finished piece apart at the forge to learn its pattern (the piece is lost either way)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public bool TakeApartEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Take Apart Base Chance", 0.00f, 2.40f, "0.00", HintText = "chance to read the pattern when your Smithing is exactly what the piece requires", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float TakeApartBaseChance { get; set; } = 0.6f;

        [SettingPropertyFloatingInteger("Take Apart Skill Span", 0.00f, 1200.00f, "0.00", HintText = "Smithing points above the requirement that add a full 100% to that chance (below it the chance falls the same way; it always stays between 5% and 95%)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float TakeApartSkillSpan { get; set; } = 300f;

        [SettingPropertyFloatingInteger("Take Apart Salvage", 0.00f, 1.00f, "0.00", HintText = "share of the material that comes back when a piece is taken apart (0 = nothing, 1 = as much as smelting it would give)", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float TakeApartSalvage { get; set; } = 0f;

        [SettingPropertyFloatingInteger("Smelt Hours Per Tier", 0.00f, 2.00f, "0.00", HintText = "crucible hours per tier of the broken-down piece", RequireRestart = false)]
        [SettingPropertyGroup("Time at the forge")]
        public float SmeltHoursPerTier { get; set; } = 0.5f;

        [SettingPropertyBool("Companion Helper Enabled", HintText = "a companion may work the bellows for you", RequireRestart = false)]
        [SettingPropertyGroup("Companion at the bellows")]
        public bool CompanionHelperEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Helper Stamina Relief", 0.00f, 1.60f, "0.00", HintText = "the most they can spare your arms", RequireRestart = false)]
        [SettingPropertyGroup("Companion at the bellows")]
        public float HelperStaminaRelief { get; set; } = 0.4f;

        [SettingPropertyFloatingInteger("Helper Time Relief", 0.00f, 1.20f, "0.00", HintText = "the most they can shorten the work", RequireRestart = false)]
        [SettingPropertyGroup("Companion at the bellows")]
        public float HelperTimeRelief { get; set; } = 0.3f;

        [SettingPropertyInteger("Helper Skill For Full Relief", 0, 600, "0", HintText = "the Smithing at which a helper gives their full worth", RequireRestart = false)]
        [SettingPropertyGroup("Companion at the bellows")]
        public int HelperSkillForFullRelief { get; set; } = 150;

        [SettingPropertyInteger("Forge Parts Free Below Tier", 0, 10, "0", HintText = "only crafting parts BELOW this tier are free at the forge from the start; everything above is unlocked by forging and smelting, lowest tier first (2 = only tier 1 free, 5 = named lore blades locked only, 7 = gate off). A weapon class in which some required slot has no part below this tier stays closed - its Craft button is dead - until you unlock a part for that slot by smelting such a weapon; the CrashScribe log lists these classes at session start. Applied when a session loads", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public int ForgePartsFreeBelowTier { get; set; } = 2;

        [SettingPropertyBool("Book Price Fix", HintText = "Banner Kings books are worth what a manuscript was worth (700 or 1,000 instead of 7 or 10 - a Realm of Thrones patch had divided their worth by 100), and buying one from a Banner Kings bookseller is a real trade: you pay the price shown in the list (Banner Kings took a thousand times that), the coin goes to the bookseller's purse instead of vanishing, and the book leaves his collection instead of appearing out of thin air - a bookseller who has sold all his books has none left. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool BookPriceFix { get; set; } = true;

        [SettingPropertyBool("Book Goal Trade", HintText = "the Banner Kings goal 'Acquire Book' is the same trade as buying from the bookseller: you pay the price of the book (not 30 times as much), the coin goes to the bookseller and the book leaves his collection. Needs Book Price Fix. Switching it on mid-game takes effect after loading a save", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool BookGoalTrade { get; set; } = true;

        [SettingPropertyBool("Craft Orders Historical", HintText = "the smithing orders of lords and notables are a real trade in the world's coin: the reward is reckoned from the historical worth of the ordered weapon (tens or hundreds, not thousands), the client pays it from his own purse instead of out of thin air (a client short of coin pays what he has and you are told), the weapon you forged goes to the lord's baggage or onto the town's stalls instead of vanishing, and a lord no longer gets a free soldier with it. The smithing experience for an order is unchanged. Orders already waiting in a save are repriced once on load. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool CraftOrdersHistorical { get; set; } = true;

        [SettingPropertyBool("Craft Orders Giver Can Pay", HintText = "a smithing order is offered only by a lord or notable who can pay for it: his purse must cover the rewards of all the orders he has placed at once, with a fifth to spare for the bonus a better weapon earns. A client without the coin makes no order, and an order whose client has since spent his coin or died is withdrawn the next day or when the game is loaded (never while you are at the forge). Works together with Craft Orders Historical, where the client pays from his own purse. Quest orders are left alone (a gang leader short of coin still pays only what he has). Off = orders as before (a client short of coin pays what he has and you are told)", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool CraftOrdersGiverCanPay { get; set; } = true;

        [SettingPropertyBool("Craft Order Clan Purse", HintText = "a lord who is not the head of his clan pays a smithing order from the clan purse too: what he cannot pay himself is paid by the head of his clan, from the coin he holds above Ai Gear Gold Reserve (wages come first) and, in a clan with a budget, no more than the clan's unspent allowance for gear - the same purse that buys the clan's horses and arms. You are told who paid how much; only when the head cannot pay either do you get less ('... could pay only N of the agreed M'). The same purse counts when such a lord places an order and when waiting orders are checked (Craft Orders Giver Can Pay). Works together with Craft Orders Historical. Off = the lord pays only from his own purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool CraftOrderClanPurse { get; set; } = true;

        [SettingPropertyBool("Craft Orders Opened Only", HintText = "new smithing orders ask only for weapon classes you can actually forge - every slot of the class must have a part you have unlocked - and for parts at most one tier above your best unlocked part of that class, so no order is impossible because of the forge gate. In a new campaign the starting orders are redrawn once on the first day by the same rule. Off = any class and tier, as before", RequireRestart = false)]
        [SettingPropertyGroup("The forge gate")]
        public bool CraftOrdersOpenedOnly { get; set; } = true;

        [SettingPropertyBool("Quest Reward From Giver", HintText = "a quest reward is paid by the one who asked for the work: the notable, lord or gang leader pays from his own purse instead of the coin appearing out of thin air. A client short of coin pays what he has and you are told ('... could pay only N of the agreed M'). A counter-offer is paid by whoever makes it, and the hourly takings of the tax-farming quest come out of the village's own purse. Off = rewards appear from nowhere as before", RequireRestart = false)]
        [SettingPropertyGroup("Quest rewards")]
        public bool QuestRewardFromGiver { get; set; } = true;

        [SettingPropertyBool("Quest Reward In Wage Days", HintText = "a quest pays for the work in the world's coin: at most the wages of the men the job needs for the days it takes (the game's own numbers for sending a companion; your whole party for the tasks without that option), at your party's wage per man, plus a quarter - clearing a hideout pays about 440 instead of 3,000. The offer in the conversation shows the new sum and it is fixed when you accept. Goods you deliver are still paid at their worth on top of the fee. Off = the game's sums", RequireRestart = false)]
        [SettingPropertyGroup("Quest rewards")]
        public bool QuestRewardInWageDays { get; set; } = true;

        [SettingPropertyBool("Quest Player Pays Someone", HintText = "what you pay inside a quest reaches someone instead of vanishing: the cost of sending a companion to buy what is needed and any bribe go to the treasury of the quest's settlement, the stake at the tavern to the town you stand in, losses and pay-offs of the tax-farming quest to the village, everything else to the quest giver. The sums themselves do not change", RequireRestart = false)]
        [SettingPropertyGroup("Quest rewards")]
        public bool QuestPlayerPaysSomeone { get; set; } = true;

        [SettingPropertyBool("Quest Goods Real", HintText = "goods in quests have an owner: tools, animals and wares you deliver go onto the shelf of the quest's settlement (or into the baggage of the lord who asked) instead of vanishing, goods offered to you in exchange come out of the settlement's stock - what it lacks the quest giver pays in coin - and weapons handed to the gang or kept by the guards end up on the town's shelf", RequireRestart = false)]
        [SettingPropertyGroup("Quest rewards")]
        public bool QuestGoodsReal { get; set; } = true;

        [SettingPropertyBool("Player Tourney Prize From Town", HintText = "the prize you win at a tournament is a real thing: it comes off the shelves of the host town, and when the town has no such piece in its stores it pays you its price from its treasury instead - only from what the treasury can spare, so a poor town pays less and you are told. The prize money and match bonuses of Tournaments XPanded are paid by the host town the same way (off = the prize and the coin appear out of thin air, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool PlayerTourneyPrizeFromTown { get; set; } = true;

        [SettingPropertyBool("Player Bets Counterparty", HintText = "your bets have someone on the other side: a tournament stake goes into the host town's treasury, a lost stake simply stays there, and your winnings are paid out of that treasury - your own stake always comes back, the profit only from what the town can spare. A wager at the tavern board is laid against the house the same way (off = stakes vanish and winnings appear out of thin air, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool PlayerBetsCounterparty { get; set; } = true;

        [SettingPropertyBool("Player Fees Historical", HintText = "small payments are in the world's coin and reach someone: bribing the guards costs about 60 when you are at war with the lord, 36 at war with his realm and 6 otherwise (a guard's pay for 30, 18 and 3 days; your renown and Roguery still count), bribing the gaolers for a prison break costs about a month's pay for every guard on the watch (hundreds, not thousands) - both go to the garrison's own purse; the barber takes 3, the tavern keeper 12 for news of the ruling clan, and a round for your party costs 0.3 a man - these go to the townsfolk (off = the game's sums, and the coin vanishes)", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool PlayerFeesHistorical { get; set; } = true;

        [SettingPropertyBool("Player Small Sources Closed", HintText = "small sums you receive have a payer: the practice-fight reward comes from the town's treasury (from what it can spare), the coin taken with forced supplies comes from the village's own purse - an empty village yields none - and the Coastal Guard Edict of the naval kingdoms no longer refills port garrisons' chests out of thin air (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool PlayerSmallSourcesClosed { get; set; } = true;

        [SettingPropertyBool("Tourney Payer Chain", HintText = "a tournament prize, your bet winnings, the arena purse and winnings at the tavern board are paid in full when the host town's treasury runs short: what the town cannot spare is paid by the lord who holds the town, then by the ruler of its realm - each only from what his house can spare above its reserve, never his men's wages - and you are told who paid how much. In a town of your own you are the host: only its treasury pays and the rest is yours to bear. Off = the town alone pays what it can spare, as before", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool TourneyPayerChain { get; set; } = true;

        [SettingPropertyBool("Tourney Debts", HintText = "what neither the town nor its lords can pay at once becomes that town's debt to you: every day the town, its lord and the ruler of its realm pay it off from what they can spare - a lord no faster than his war chest allows - and you are told each time they pay at least 50 (or the rest); a realm at war with yours pays nothing until peace. Off = the unpaid rest is lost, as before", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool TourneyDebts { get; set; } = true;

        [SettingPropertyBool("Tourney Seagard Catch Up", HintText = "one-time amends for the Seagard tournament of 16 October in Ithauser's campaign: Seagard owes you the 1,300 of prize money and the 222 of your bet it could not pay, and Seagard, its lord and the ruler pay it in the first hour as a prize would be paid; whatever is left is paid off like any other town debt. Only for a save made before this change, with the hero Ithauser, after that tournament - decided once, at the first load (needs Tourney Debts). Off = no amends", RequireRestart = false)]
        [SettingPropertyGroup("Player fees and bets")]
        public bool TourneySeagardCatchUp { get; set; } = true;

        [SettingPropertyBool("Tourney Folk Purse", HintText = "the townsfolk of the town that hosts a tournament put up a purse for the champion: one day of what they spend from their savings on better living - a rich town gives a fat purse, a town with nothing to spare gives none - paid out of their own purses above their reserve for hard times to the head of the champion's house (to you, if you or one of your party win). You are told when the purse is yours or when you are in the town. Works once the start calibration is applied. Off = no purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("Tournament purse of the townsfolk (18.10)")]
        public bool TourneyFolkPurse { get; set; } = true;

        [SettingPropertyFloatingInteger("Tourney Folk Purse Days", 0.00f, 4.00f, "0.00", HintText = "with Tourney Folk Purse: how many days of the townsfolk's spending from their savings go into the purse (1 = one day; at most 4)", RequireRestart = false)]
        [SettingPropertyGroup("Tournament purse of the townsfolk (18.10)")]
        public float TourneyFolkPurseDays { get; set; } = 1.0f;

        [SettingPropertyInteger("Tourney Folk Purse Min", 0, 80, "0", HintText = "with Tourney Folk Purse: a purse smaller than this is not put up - the coin stays with the townsfolk", RequireRestart = false)]
        [SettingPropertyGroup("Tournament purse of the townsfolk (18.10)")]
        public int TourneyFolkPurseMin { get; set; } = 20;

        [SettingPropertyBool("Hideout Flag Enabled", HintText = "a freshly spotted hideout gets a flag on the map and a report: distance, direction, nearest settlement, who nests there", RequireRestart = false)]
        [SettingPropertyGroup("Hideout spotted")]
        public bool HideoutFlagEnabled { get; set; } = true;

        [SettingPropertyInteger("Hideout Flag Days", 0, 12, "0", HintText = "how many days the flag stays on the map", RequireRestart = false)]
        [SettingPropertyGroup("Hideout spotted")]
        public int HideoutFlagDays { get; set; } = 3;

        [SettingPropertyBool("House Levies Enabled", HintText = "in settlements owned by a house with its own troop line (Blackwood, Tully, Karstark, Lannister...) the NOBLE volunteers the game already offers are that house's men of the same tier - same rule and frequency as noble recruits anywhere, no extra dice", RequireRestart = false)]
        [SettingPropertyGroup("House levies")]
        public bool HouseLeviesEnabled { get; set; } = true;

        [SettingPropertyBool("Northern Fare Enabled", HintText = "vineyards in the North and at the Wall (Farsfog, Tumbledown, Olden Oak, Queenscrown) become fishers, cattle and swine farms - grapes do not grow in snow; wine presses in Winterfell and Castle Black turn into breweries. Applied at session start", RequireRestart = false)]
        [SettingPropertyGroup("Northern fare")]
        public bool NorthernFareEnabled { get; set; } = true;

        [SettingPropertyBool("Crop Climate Filter", HintText = "papyrus, a reed of hot marshes, grows only on grain farms of the hot south (Dorne, Ghis, Qarth, Volantis, Lys, Myr, Tyrosh, Valyria, the Summer Isles); Banner Kings gave it to every grain farm, even at the Wall - elsewhere the farm no longer yields it (grain output unchanged)", RequireRestart = false)]
        [SettingPropertyGroup("Northern fare")]
        public bool CropClimateFilter { get; set; } = true;

        [SettingPropertyBool("Woodlot By Climate", HintText = "the village woodlot (Village Woodlot Loads) fells by climate: deserts 0.3, Dothraki steppe 0.5, Mediterranean lands 0.8, forest lands 1.2, the rest 1.0 - scaled so the world as a whole fells as much timber as before", RequireRestart = false)]
        [SettingPropertyGroup("Northern fare")]
        public bool WoodlotByClimate { get; set; } = true;

        [SettingPropertyBool("Village Climate Fix", HintText = "12 villages whose main produce cannot grow where they stand get one that can (no more cotton at the Wall, in Braavos, Norvos, the Vale mountains, the Riverlands, the Kingswood, the Crownlands and Sarnor, no vineyard in Lorath, no dates on Tarth), and 11 warm villages (Qarth, Volantis and the Rhoyne, Myr, Meereen, the old Valyrian lands, the Reach) take up cotton so the world keeps as much cotton as before; the 4 grain farms beyond the Wall turn to hunting and fishing (2 trappers in the forest, 2 fishers by the water) - the Free Folk keep no grain farms (every village still gathers a little grain). Applied at session start, nothing is written to the save (off = the map's own village types after the next load; fishing boats Storrold has already sent out stay)", RequireRestart = false)]
        [SettingPropertyGroup("Northern fare")]
        public bool VillageClimateFix { get; set; } = true;

        [SettingPropertyBool("Climate Before Workshops", HintText = "with Village Climate Fix: in a NEW campaign the villages take their final produce (the climate fix, and also the new flax villages and the southern vineyards and olive groves when Goods Rates By Pattern and Vine Olive By Climate are on) before the game sets up the town workshops, so each town starts with workshops that use what its own villages grow (no velvet looms waiting for cotton the hills around no longer give). A loaded save is not touched; off = the town workshops of a new campaign are chosen from the map's own village types as before (the villages change at session start)", RequireRestart = false)]
        [SettingPropertyGroup("Northern fare")]
        public bool ClimateBeforeWorkshops { get; set; } = true;

        [SettingPropertyBool("Bandit Cheer Enabled", HintText = "villages near your victory over bandits thank you - relations with their notables improve", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool BanditCheerEnabled { get; set; } = true;

        [SettingPropertyInteger("Bandit Cheer Radius", 0, 200, "0", HintText = "how far from the battlefield a village still hears the good news (map distance)", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public int BanditCheerRadius { get; set; } = 50;

        [SettingPropertyInteger("Bandit Cheer Relation", 0, 10, "0", HintText = "relation gained with each notable of those villages", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public int BanditCheerRelation { get; set; } = 2;

        [SettingPropertyBool("Bandit Relief Relation Summary", HintText = "after you beat bandits, the thanks of nearby villages comes as ONE message - how much relation, with how many notables and which villages - instead of a popup for every notable; the relation you gain is the same. Off: one popup per notable, as before", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool BanditReliefRelationSummary { get; set; } = true;

        [SettingPropertyBool("Reinforcement Relation Summary", HintText = "lords who came to your aid in battle (Dynamic Reinforcements) thank you in ONE message - how much relation and with whom - instead of a popup for every lord; the relation you gain is the same. Off: one popup per lord, as before", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool ReinforcementRelationSummary { get; set; } = true;

        [SettingPropertyBool("Log Enabled", HintText = "write a log file in the module folder", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool LogEnabled { get; set; } = true;

        [SettingPropertyBool("Log Keep Open", HintText = "keep the log files open while the game runs instead of opening and closing a file for every line - the same lines, each written out at once (nothing is lost if the game crashes), and the log can still be read during play; saves a little time every day. Off: a file is opened and closed for every line, as before", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool LogKeepOpen { get; set; } = true;

        [SettingPropertyBool("Quiet Log", HintText = "quiet measurement logs: the diagnostic-only measurements (raw goods prices, terrain probes, castle-village market roads, who changes goods in daily ticks, the dry-run clan budget report) are taken on one day in every N instead of daily - errors, events and the daily profile are always written, automatic tests always write everything; off = every day", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool QuietLog { get; set; } = true;

        [SettingPropertyInteger("Quiet Log Every Days", 1, 28, "0", HintText = "with quiet measurement logs: take the measurements on one day in this many (1 = every day, at most 28)", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public int QuietLogEveryDays { get; set; } = 7;

        [SettingPropertyBool("Quiet Log More", HintText = "with quiet measurement logs: 43 more daily diagnostic-only lines that no test tool reads (village woodlots, wandering Banner Kings parties, castle supplies, craftsmen, drill of the player, deserters, clogged villages and the like) are also written on one day in every N; errors and all lines the tests read stay daily, automatic tests always write everything (off = these lines every day, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Grateful villages")]
        public bool QuietLogMore { get; set; } = true;

        [SettingPropertyBool("Save Size Log", HintText = "after every save the log gets one line with the size of every piece of Armoury data in the save, the size of the save file and how long saving took (off = no such line)", RequireRestart = false)]
        [SettingPropertyGroup("Save files")]
        public bool SaveSizeLog { get; set; } = true;

        [SettingPropertyBool("Save Compact", HintText = "off by default. The two largest pieces of Armoury data in the save - wear of the AI lords' gear and the kits that notables hold for their volunteers - are written compressed (about 6 times smaller in memory, a little smaller on disk); every compressed piece is read back and compared before it is written, and anything that does not match is written the old way. Saves made with it still load when it is off. Turn it on only once you no longer expect to go back to an older Armoury version: an older version does not read the compressed pieces (AI gear would count as unworn, notables would hold no kits). To go back anyway, turn it off and save first", RequireRestart = false)]
        [SettingPropertyGroup("Save files")]
        public bool SaveCompact { get; set; } = false;

        [SettingPropertyInteger("Save Compact Min Kb", 8, 4096, "0", HintText = "with Save Compact: only a piece of data larger than this many kilobytes of text is compressed (8 to 4096)", RequireRestart = false)]
        [SettingPropertyGroup("Save files")]
        public int SaveCompactMinKb { get; set; } = 64;

        [SettingPropertyBool("Save Size Log File", HintText = "with Save Size Log: the line written after every save also tells roughly how much of the save FILE the Armoury data takes (the game compresses the whole save; the same compression is measured in memory, a few tens of milliseconds per save). Measurement only - nothing in the save changes (off = no such part in the line)", RequireRestart = false)]
        [SettingPropertyGroup("Save files")]
        public bool SaveSizeLogFile { get; set; } = true;

        [SettingPropertyBool("Army175 Measure", HintText = "measurement only, nothing in the game changes: a daily log line of AI horse upgrades (made, refused or cut for lack of a horse, horses into armouries, purchases, where riders come from) and a line per battle and per day on the balance of the kingdoms (battles won against the odds, assaults, fortresses taken and lost, men in the field), with csv files in the session's log folder. Takes effect at once", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175Measure { get; set; } = true;

        [SettingPropertyInteger("North Home Edge Percent", 0, 25, "0", HintText = "the North is hardier at home: in auto-resolved field battles on snow (anywhere) and in the forests of the North, Northern infantry of tier 3 to 6 (village, noble and house lines) in parties of Northern houses fights this many percent stronger - it strikes harder and is struck less. Never at sieges; it only tips battles that are almost even. 0 = off. Takes effect at once", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public int NorthHomeEdgePercent { get; set; } = 10;

        [SettingPropertyInteger("North Hardy Weapon Bonus", 0, 50, "0", HintText = "Northern infantry of tier 3 to 6 (village, noble and house lines, 43 troop types) gets this many points of its main weapon skill on top of what its own gear demands. 0 = none: after the tier gear fix their main weapon already averages about 131, against about 122 for the infantry of tier 3 and up of the rest of the world (+7%); +10 makes it about +16%, +25 about +28%. Each man is capped one point below the next tier's requirement, so he never outgrows his tier. Works only while Army 175 Tier Gear is at work. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public int NorthHardyWeaponBonus { get; set; } = 0;

        [SettingPropertyInteger("North Hardy Athletics Bonus", 0, 50, "0", HintText = "the same Northern infantry of tier 3 to 6 gets this many points of Athletics on top of what its own gear demands - the men of the North are built sterner and march harder. 5 brings their average Athletics from about 129 to about 134 (the rest of the world about 118: +13% instead of +9%). With armour asking Athletics by its weight only (Armour Tier Athletics 0, the default) there is no tier cap on Athletics; with the Armour Tier Law on, each man is capped one point below the next tier's requirement. Works only while Army 175 Tier Gear is at work. 0 = off. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public int NorthHardyAthleticsBonus { get; set; } = 5;

        [SettingPropertyBool("Army175 Tier Gear", HintText = "every soldier type - all cultures, village and noble lines, house troops, militia, mercenaries and garrisons, never lords, companions or you - carries and wears in its pattern only weapons, shields, ammunition and armour up to its own tier: a piece above it is replaced by the same kind of piece of that tier. A man still uses only the gear his skills allow. Applied by CrashScribe, takes effect on the next load; from then on the Armoury also keeps the battle pattern of your fights within the soldier's tier", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175TierGear { get; set; } = true;

        [SettingPropertyBool("Army175 Lore Armor", HintText = "Pentos and Qarth hire their wars: their infantry of tier 2 to 4 wears armour one step lighter, within its tier. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175LoreArmor { get; set; } = true;

        [SettingPropertyBool("Army175 Lore Armor Extra", HintText = "Qohor, the city of armourers, gives its infantry of tier 4 and 5 the heaviest body armour of their tier, while the Dornish footmen, spearmen and guards of tier 3 and 4 wear body armour one step lighter, within their tier. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175LoreArmorExtra { get; set; } = true;

        [SettingPropertyBool("Army175 Simple Javelins", HintText = "the simplest javelin of the game - the Pine Javelin, a wrought iron head on a pine shaft and the cheapest of them all - counts as tier 2 gear instead of tier 4: it needs only 35 Throwing and is priced as tier 2, so javelin men of tier 2 and 3 (Dornish, Braavosi, Sarnori, sellswords, Ironborn, Northern woodsmen and others) carry javelins in their pattern instead of throwing axes. Works only together with Army 175 Tier Gear. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175SimpleJavelins { get; set; } = true;

        [SettingPropertyBool("Army175 Composition", HintText = "master switch for the troop mix of the realms below (Dothraki, Iron Islands, the North, Volantis and Norvos, the Free Folk and Dragonstone): party templates and upgrade trees as the books have them. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175Composition { get; set; } = true;

        [SettingPropertyBool("Army175 Dothraki Ride", HintText = "the Dothraki fight on horseback: a village recruit still starts on foot, but his only way up is the riding line; Dothraki on foot stay in the militia and those already serving keep their place. Their parties cost more in pay, riders are paid more - this is the switch if the khalasars go bankrupt. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175DothrakiRide { get; set; } = true;

        [SettingPropertyBool("Army175 Dothraki Horse Guard", HintText = "when Realm of Thrones swaps a man in a Dothraki party for a rider, he becomes a rider only if a horse is found for him - one from the baggage (or a free one in the armoury, with Ai Free Armory Horses First); with none he becomes a Dothraki on foot of the same tier (if Realm of Thrones keeps that foot troop in the house's pool). Works only while CrashScribe has the Dothraki riding since the last load (Army 175 Dothraki Ride), so switching that off ends the guard at the next load together with the riding change. Takes effect at once", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175DothrakiHorseGuard { get; set; } = true;

        [SettingPropertyInteger("Dothraki Riding Bonus", 0, 50, "0", HintText = "Dothraki riders of tier 2 to 5 of the village line get this many points of Riding - they ride better than any knight. 0 = off. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public int DothrakiRidingBonus { get; set; } = 30;

        [SettingPropertyBool("Army175 Ironborn Foot", HintText = "the Iron Islands fight on foot and at sea: the Harlaw riders remain their only horse, other Ironborn riders give way to infantry of the same tier in lord parties, patrols and the vassal reward. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175IronbornFoot { get; set; } = true;

        [SettingPropertyBool("Army175 North Foot", HintText = "the North raises more foot, fewer archers and a little more horse; the Mormonts keep their huntresses and stay archers. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175NorthFoot { get; set; } = true;

        [SettingPropertyBool("Army175 Volantis Norvos", HintText = "As in the books: Volantis fields more foot and fewer archers (the tiger cloaks are foot), Norvos more axemen and fewer riders; the Volantene riders and elephants stay as they are. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175VolantisNorvos { get; set; } = true;

        [SettingPropertyBool("Army175 Minor Lore", HintText = "the Free Folk with fewer horsemen, and Dragonstone, Velaryon and Celtigar with horse at about a tenth of their men. Applied by CrashScribe, takes effect on the next load", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175MinorLore { get; set; } = true;

        [SettingPropertyBool("Army Cohesion Year Scale", HintText = "An army's cohesion falls each day at the pace the game meant for its 84-day year, scaled to the long year (84 / 364 = 0.23): a lord's army of five parties holds together about 80 days instead of about 19, and about 45 days instead of 12 deep in enemy land; your own army likewise. Starving, low-morale and weak parties still drain it faster, and a commander can still spend influence to restore it. Off = the game's daily loss", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool ArmyCohesionYearScale { get; set; } = true;

        [SettingPropertyBool("Army175 Golden Bows", HintText = "Golden Company crossbowmen split into thirds as in the books - crossbows, recurve bows and yew longbows - and in battle each man takes the missile weapon of his drawn kit. Their lords buy, keep and train with bows and arrows for two thirds of these men and crossbows and bolts for one third (only these three Golden Company crossbow troops; every other troop counts its first kit, as before). The kits are made by CrashScribe on the next load; the Armoury part acts at once. Off: one kit of crossbows for all of them", RequireRestart = false)]
        [SettingPropertyGroup("Armies of the realms (175)")]
        public bool Army175GoldenBows { get; set; } = true;

        [SettingPropertyBool("Others Steel Rule", HintText = "As in the books: the Others - the White Walkers and the Night King - take full damage only from Valyrian steel, dragonglass and dragonfire; castle-forged steel of tier 6 (the best any smith can make) deals Others Castle Steel Percent of its damage, everything else 15%. A thrown weapon counts by itself, an arrow or bolt by its own tier (the bow or crossbow does not matter); sling stones, thrown stones, boulders, fire pots, shield bashes and anything shot by a siege engine always deal 15%. Common wights still fall to anything. Works in your battles and in auto-resolved ones, both by the gear the troops carry after the Army175 Tier Gear fix (in auto-resolve a troop type counts by its best weapon, or by its best arrows or bolts if it has the bow or crossbow for them). The first time in a battle you or your men strike one of them with steel that only bites, a message says so. Nobody in the world carries dragonglass yet (the only piece, the Dragonglass Axe, has no owner). Off = the old rule on the same gear: any tier 6 weapon deals full damage (in auto-resolve tier 6 ammunition too), the rest 15% - auto-resolve still uses the gear after the Army175 Tier Gear fix, so turning this off does not bring back the old auto-resolve strength against the Others. Dragonfire burns them fully either way. Applied by CrashScribe, takes effect the next day or in the next battle", RequireRestart = false)]
        [SettingPropertyGroup("The Others and Valyrian steel (175c)")]
        public bool OthersSteelRule { get; set; } = true;

        [SettingPropertyInteger("Others Castle Steel Percent", 15, 100, "0", HintText = "share of its damage that castle-forged steel of tier 6 - a tier 6 weapon, or a tier 6 arrow or bolt - deals to the White Walkers and the Night King while Others Steel Rule is on (Valyrian steel, dragonglass and dragonfire always deal full damage; any lesser weapon, stones and siege engines 15%). 100 = tier 6 counts as Valyrian steel, as before. Applied by CrashScribe, takes effect the next day or in the next battle", RequireRestart = false)]
        [SettingPropertyGroup("The Others and Valyrian steel (175c)")]
        public int OthersCastleSteelPercent { get; set; } = 50;

        [SettingPropertyBool("Others Rise Only From Fallen", HintText = "As in the books, the dead rise only where the Others walk: after a battle the Others won beyond the Wall or at the Wall, the slain of the beaten side (by each host's part in the fight) and the captives the Others take rise as wights, up to the room in the host - the rest wait as bodies for new hosts; anywhere else the fallen and the captives are burnt and nobody rises. A beaten host of the Others raises nobody. Living militia of a settlement taken by the Others fall too and rise only beyond or at the Wall, and the wights of a disbanded band no longer join the outlaws. Off = Realm of Thrones as before: the healthy men of every beaten side rise wherever the battle was", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public bool OthersRiseOnlyFromFallen { get; set; } = true;

        [SettingPropertyBool("Others Duel From Fallen", HintText = "when you beat the Night King's host and then fail to slay him in the duel, he raises only the dead of that battle - yours and his - instead of standing his whole host up again from nothing; the duel and the battle that follows stay as in Realm of Thrones. Off = his whole host stands up again, as before", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public bool OthersDuelFromFallen { get; set; } = true;

        [SettingPropertyBool("Others Raid Wights", HintText = "a village raided by the Others gives them wights out of thin air (half its hearths, as Realm of Thrones does). Off (default) = a raid raises only the villagers killed in it, and only beyond the Wall or at it (needs Devastation Enabled; without it nobody rises). Works only with Others Rise Only From Fallen on; with it off, raids work as in Realm of Thrones", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public bool OthersRaidWights { get; set; } = false;

        [SettingPropertyBool("Others Band From Corpse Pool", HintText = "a new host of the Others is raised from the bodies waiting beyond and at the Wall (a new campaign starts with 616 of the old dead): its 53 wights (and the hundred of the first days) come only from that store, nearest first, and with no bodies left the Walker rides out alone. Off = new hosts appear with their wights out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public bool OthersBandFromCorpsePool { get; set; } = true;

        [SettingPropertyInteger("Night King Call Max Host", 0, 6000, "0", HintText = "the Call of the Night King (from day 728) gathers the Others into one host and makes room in it for the slain it raises; it never makes room for a host larger than this many men - about 1,140: a host of 520 able to take a castle of 450 men, with room to grow. Room that Realm of Thrones itself gives its hosts as the days pass (Others Party Size Limit Growth) is not taken away, so a host that has already grown past this is not cut down - the Call only stops adding. As before, the Call also takes back the room a host no longer fills, so a host that loses men in battle shrinks toward this limit and the Call gives it no room back past it. 0 = no limit, as before (the Call keeps every victorious host 15% short of full, so it grows without end). Applied by CrashScribe, takes effect the next day", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public int NightKingCallMaxHost { get; set; } = 1140;

        [SettingPropertyBool("Others Rescued Are Fallen", HintText = "captives the Others free from a beaten party do not join the host as living men: each one is slain - he rises as a wight beyond or at the Wall (up to the room in the host, the rest wait as bodies), elsewhere he is burnt. Off = freed captives march with the Others alive, as before", RequireRestart = false)]
        [SettingPropertyGroup("The Others rise from the fallen")]
        public bool OthersRescuedAreFallen { get; set; } = true;

        [SettingPropertyBool("Same Race Only", HintText = "giants wed and bear children only with giants, men only with men (likewise wights and the Others): no marriage and no child across races. Mixed couples wed before the war stay married, but no child is born to them - a pregnancy across races ends without a birth", RequireRestart = false)]
        [SettingPropertyGroup("Blood and race")]
        public bool SameRaceOnly { get; set; } = true;

        [SettingPropertyInteger("Pregnancy Days", 0, 364, "0", HintText = "A pregnancy lasts this many days - 273 is nine months, as in life (the long year has 364 days). It holds for every pregnancy that begins from now on; one already under way keeps the day of birth it was given. 0 = as in the game: 36 days.", RequireRestart = false)]
        [SettingPropertyGroup("Blood and race")]
        public int PregnancyDays { get; set; } = 273;

        [SettingPropertyBool("Fertility Year Scale", HintText = "The daily chance of a married couple conceiving a child is scaled to the length of the year (84 / 364 = 0.23 with the long year), so a couple has as many children a year as the game meant for its 84-day year - under one child in the first year of marriage instead of two to four. Perks, Banner Kings doctrines and Realm of Thrones blessings still raise the chance as before; marriages are not affected. Off = the game's daily chance, made for an 84-day year.", RequireRestart = false)]
        [SettingPropertyGroup("Blood and race")]
        public bool FertilityYearScale { get; set; } = true;

        [SettingPropertyBool("Map Villages Enabled", HintText = "named villages on the campaign map between the game's own villages, castles and towns - each one a cluster of its district's settlements, standing where a village had reason to stand (bridge, ford, crossroads, road, river, coast); off = none drawn. Nothing is written to the save", RequireRestart = false)]
        [SettingPropertyGroup("Map villages")]
        public bool MapVillagesEnabled { get; set; } = true;

        [SettingPropertyFloatingInteger("Map Villages Hide Above Camera Height", 0.00f, 640.00f, "0.00", HintText = "map villages vanish when the camera rises above this height - from afar only the game's villages, castles and towns remain", RequireRestart = false)]
        [SettingPropertyGroup("Map villages")]
        public float MapVillagesHideAboveCameraHeight { get; set; } = 160f;

        [SettingPropertyBool("Map Village Names On Hover", HintText = "Map Village Names - hover only: point at a map village to see its name, its district, its settlements and people. Labels over burning villages come in a later update", RequireRestart = false)]
        [SettingPropertyGroup("Map villages")]
        public bool MapVillageNamesOnHover { get; set; } = true;

        [SettingPropertyBool("Mill On Bank", HintText = "water mills on rivers stand on the bank, not in the stream: the whole mill village, mill and wheel included, is set half a step back from the river's edge. Mills on the sea coast are unchanged. Off = as before, the wheel a little out in the water", RequireRestart = false)]
        [SettingPropertyGroup("Map villages")]
        public bool MillOnBank { get; set; } = true;

        [SettingPropertyBool("Village Tip Held By", HintText = "the map village tooltip names who holds the land, live from the game: 'A village of the Tumbledown lands, held by House Stark of Winterfell' ('your fief' for your own). Off = 'A village of the X district', as before", RequireRestart = false)]
        [SettingPropertyGroup("Map villages")]
        public bool VillageTipHeldBy { get; set; } = true;

        [SettingPropertyBool("Rot Swap Same Man", HintText = "when Realm of Thrones turns a lord's new recruit into a man of the lord's house, it is still the same man: he keeps the kit he came with and no second kit appears from thin air (off = the swap is treated as a new man from nowhere: what he owns, or a full kit when Recruit Brings What He Has is off)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool RotSwapSameMan { get; set; } = true;

        [SettingPropertyBool("Recruit Brings What He Has", HintText = "an AI recruit whose gear nobody bought - a hireling from a tavern, a volunteer without a record, a man from the roads - brings only what he owns at home (the gear of his line's first rank that his troop also wears; a hireling also his own horse), a captive brings nothing; his lord buys the rest at a market (off = as before: a full kit of his troop from thin air)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool RecruitBringsWhatHeHas { get; set; } = true;

        [SettingPropertyBool("Recruit Own By Kind", HintText = "a volunteer or recruit brings from home every piece of his line's first-rank gear of the same kind as a piece his troop wears (a peasant's padded coat where his troop wears a coat, his spear where it carries a spear, his shield where it carries a shield) - his own, plainer piece, and only for what nobody bought him; off = only the very same pieces as his troop wears, which since the kingdoms' armies wear gear of their own rank is almost nothing", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool RecruitOwnByKind { get; set; } = true;

        [SettingPropertyBool("Fresh Volunteer Kit", HintText = "a volunteer who appears above the first rank (a noble youth) has his notable buy his key gear on the town market, as for a promotion; if the stall or the purse fails, he keeps what he owns and still waits in the pool (off = as before: no record, his kit is decided at recruitment)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool FreshVolunteerKit { get; set; } = true;

        [SettingPropertyBool("House Levies Keep Kit", HintText = "when House Levies makes a noble volunteer a man of the house that owns the land, the gear recorded for him goes with him (off = the record is lost and the notable sells the gear)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool HouseLeviesKeepKit { get; set; } = true;

        [SettingPropertyBool("Volunteer Kit Castles", HintText = "castle volunteers (Banner Kings) rise to a better troop only with the gear their notable buys, like volunteers of towns and villages (off = as before: castle promotions cost nothing)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool VolunteerKitCastles { get; set; } = true;

        [SettingPropertyBool("Garrison Recruit Keeps Kit", HintText = "a volunteer the garrison takes in by auto-recruitment brings his gear into the garrison's armoury - what his notable bought for him, or his own belongings (off = as before: the garrison gets nothing and the notable sells his gear)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonRecruitKeepsKit { get; set; } = true;

        [SettingPropertyBool("Garrison Gear From Town", HintText = "a castle's garrison buys what its men lack (and better kit for its own coin) in the town its villages trade with: the garrison's purse and then the lord of the castle pay that town, the goods leave its stalls and reach the castle by cart in the days the road takes; arms are no longer shipped to castles by traders (horses still are) and lords buy arms only in towns (off = as before: the garrison buys from the castle's own stall)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonGearFromTown { get; set; } = true;

        [SettingPropertyInteger("Garrison Order Days", 0, 12, "0", HintText = "a castle sends an order for arms to its market town at most once in this many days; one order covers all those days (their pieces and their share of the lord's purse); what lies on the castle's own stall it buys every day", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public int GarrisonOrderDays { get; set; } = 3;

        [SettingPropertyBool("Garrison Armory Survives Save", HintText = "garrison armouries are kept in the save game: Dynamic Troop Equipment does not save them, so after every load all garrisons stood empty and their lords bought all their arms again", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonArmorySurvivesSave { get; set; } = true;

        [SettingPropertyBool("Garrison Armory Restore Old Save", HintText = "the first time a save made before this change is loaded, every garrison (yours too) gets its men's kit once, like the stores of a new campaign (Dynamic Troop Equipment never saved garrison stores, and your garrisons never bought any); a garrison fights only with what its stores hold, so without this it would face the first assault bare (off = they stand empty and buy it all again)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonArmoryRestoreOldSave { get; set; } = true;

        [SettingPropertyBool("Kit Moves With Men", HintText = "when a lord leaves men in a garrison or takes men from it, when you move men between your party and a garrison or another party on the party screen (Manage garrison, Manage Troops of your companions' and clan parties, Donate Troops, creating a clan party), or a disbanded party joins a garrison, the men's arms go with them (from your stores only the men's own kit - never yours; a rider takes his horse and harness along only with Troops Fight With Own Kit Only, otherwise horses stay with the stables); men of a disbanded party who go home take their own kit and the spare is sold for their house (off = as before: men move without their arms)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool KitMovesWithMen { get; set; } = true;

        [SettingPropertyBool("Garrison Sells Surplus", HintText = "once a week a garrison sells the arms it holds beyond what its men can use and wear (and a tenth spare; men out on patrol count) to the stall of its own town or castle, at the merchant's buying price; a third of the coin goes to the lord of the place, the rest to the garrison's purse (without garrison purses all of it to the lord); your garrisons too when they keep a purse or with Garrison Buys Gear Player", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonSellsSurplus { get; set; } = true;

        [SettingPropertyBool("Garrison Sell Hourly", HintText = "garrisons take their weekly turn at selling spare arms one or two at a time through the hours of the week, instead of some thirty garrisons all at once at the turn of every day - the same rule and one turn a week for each garrison as before, without that short freeze once a day. Off: all at the turn of the day, as before", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonSellHourly { get; set; } = true;

        [SettingPropertyBool("Garrison Drill Needs Arms", HintText = "a garrison's daily drill (training fields, drills) teaches only the men who have a weapon of their kind and grade in the armoury - the experience is scaled by the share of armed men (AI garrisons; yours when they keep a purse or with Garrison Buys Gear Player; only while AI lords and garrisons buy their gear)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GarrisonDrillNeedsArms { get; set; } = true;

        [SettingPropertyBool("Party Drill Needs Arms", HintText = "an AI lord's daily training of his men needs weapons: each troop's experience is scaled by the share of its men who have a weapon of their kind and grade in the armoury - men with nothing fit for their rank promote slower (only while AI lords buy their gear)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool PartyDrillNeedsArms { get; set; } = true;

        [SettingPropertyBool("Arms Coverage Log", HintText = "every fifth day write a line to the log: how much of the arms and armour AI parties and garrisons need is in their armouries", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool ArmsCoverageLog { get; set; } = true;

        [SettingPropertyBool("Gear Fit Kits", HintText = "a soldier is given only kit he can use: notables buy for a volunteer only pieces his skills carry (weapon and shield skill, Athletics for armour, Riding for horse and barding, a rider's weapon usable from the saddle); a piece a recruit, hireling or transferred man cannot use stays with its owner - the notable sells what he bought, the man sells his own and the coin goes to the men's purse - and he takes his home piece of that kind instead; a first-rank recruit's starting kit swaps such a piece for one of his own troop's (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitKits { get; set; } = true;

        [SettingPropertyBool("Gear Fit Culture", HintText = "kit follows the soldier's people: from his side of the Narrow Sea, or of a style his own people's troops wear in Realm of Thrones; a piece of his own template always fits; used when notables, lords, garrisons and your men buy, when they count what is worn and what is spare to sell, and when battle takes kit from across the sea off a soldier (off = only the side of the Narrow Sea, in battle only)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitCulture { get; set; } = true;

        [SettingPropertyBool("Gear Fit Kin Item Level", HintText = "with Gear Fit Culture: a piece from across the Narrow Sea fits a soldier's people only if their own troops wear that very piece in Realm of Thrones - Dornish troops who wear Dothraki boots and javelins no longer take every Dothraki item, the arakh above all, which stays a khalasar's weapon (off = as before: one shared style opens all items of that foreign people)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitKinItemLevel { get; set; } = true;

        [SettingPropertyBool("Gear Fit Dothraki Only", HintText = "the arakh and the other Dothraki weapons no other people's troops carry in Realm of Thrones are for Dothraki soldiers only: Free Cities, Ghis, Yi Ti and every army of Westeros no longer buy or wear them, battle takes them off such men and gives them a weapon from the stores instead, and a bare-handed man gets one only when the stores hold no other weapon he can wield; lords, wanderers and named items are not touched (off = as before: anyone from the Essos side may carry an arakh)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitDothrakiOnly { get; set; } = true;

        [SettingPropertyBool("Dothraki Arms Census Log", HintText = "log only: in each of your battles write who carries a Dothraki weapon (troop, people, party, side of the sea), and once a week how many Dothraki soldiers serve in parties, sit in outlaw pools and how many Dothraki weapons lie in stores in Westeros - nothing in the game changes (off = no such lines)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool DothrakiArmsCensusLog { get; set; } = true;

        [SettingPropertyBool("Gear Fit Weapon Floor", HintText = "in battle no soldier fights bare-handed while his party's stores hold a weapon he can use: a man left without any weapon after the skill and culture checks takes the best melee weapon he can wield from the stores, of his people's kind first (from across the sea only with Gear Fit Floor Foreign) - nothing from thin air (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitWeaponFloor { get; set; } = true;

        [SettingPropertyBool("Gear Fit Floor Foreign", HintText = "with Gear Fit Weapon Floor: a bare-handed man with no weapon of his people's kind in the stores takes one from across the Narrow Sea he can wield - even the very piece that was just taken off him or a comrade for its foreign style - better a foreign blade than bare hands (off = no foreign weapon in battle: he fights bare-handed when the stores hold nothing of his people's kind)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitFloorForeign { get; set; } = true;

        [SettingPropertyBool("Gear Fit Floor Over Skill", HintText = "with Gear Fit Weapon Floor: when the stores hold no weapon a bare-handed man can wield, he takes the lightest one there even above his skill - better over-armed than bare-handed (off = skills are sacred: no weapon he cannot use, as decided on 14.09)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitFloorOverSkill { get; set; } = false;

        [SettingPropertyBool("Gear Fit Realm From Stores", HintText = "a piece from across the Narrow Sea taken off a soldier in battle is replaced from his party's stores - the best piece of the same kind he can use - not from his template out of thin air (which the nothing-from-nothing guard took away again at spawn, leaving him empty-handed) (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Arming the garrisons")]
        public bool GearFitRealmFromStores { get; set; } = true;

        [SettingPropertyBool("Drill Law", HintText = "your men drill every day out of battle, and so do your clan's parties and lords in your army (the game gave them no daily drill), by the one rule every lord's party follows: each man learns 10 + 2 x his tier a day, x1.5 on a day of rest (moved in fewer than 4 of the last 24 hours - an hour in a settlement, in a siege camp or barely moving rests, as for sleep), x0.9 on the march, not at all when starving or after a night without sleep (they met the dawn with sleep debt - no drill until the next dawn; training perks included); the pace follows the commander's Leadership (170 = normal, from half to one and a half). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillLaw { get; set; } = true;

        [SettingPropertyBool("Drill Needs Arms Player", HintText = "your men's drill needs weapons too: as for AI lords, each troop learns (training perks included) in proportion to the share of its men who have a weapon of their kind and grade in your armoury (off = your men drill at full pace whatever they hold)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillNeedsArmsPlayer { get; set; } = true;

        [SettingPropertyBool("Drill Stock", HintText = "arms and armour you discard, leave on the game's loot screen or leave behind after collecting Spoils trophies go to your men's drill stock while there is room (two sets of one weapon and one piece of armour per three men) instead of being lost; your men's spare arms in the armoury count too. A full stock makes the drill up to 20% faster, Giving Hands and Paid in Promise up to 30%. The stock belongs to the men: it cannot be taken back, it wears out, and the smiths of the next town buy the scrap of worn pieces - the coin goes to the men's purse. Works only with Drill Law and Donation Xp Off on: the stock replaces the experience the game gave for gear you give away (off = discarded gear is lost as before)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillStock { get; set; } = true;

        [SettingPropertyBool("Drill Stock Ai", HintText = "AI lords' men drill with the spare arms and armour of their armoury by the same rule as your men's spare kit (their baggage - loot and Banner Kings supplies - does not count, just as your own packs do not): up to 20-30% faster, the stock wears out and the smiths of the next town buy the scrap - a third to the lord, the rest to the men (off = AI drill without a stock, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillStockAi { get; set; } = true;

        [SettingPropertyBool("Drill Penalty Ai", HintText = "AI lords' men do not drill at all on a day they are starving or after a night without sleep (they met the dawn with sleep debt - no drill until the next dawn; training perks included, and no drill gear wears out) - the same penalty as your men's with Drill Law on (with Drill Law off your men drill by the game's rule, and hunger or lack of sleep takes nothing from them); the sleep debt is the same one that costs them speed and morale (Ai Sleep Debt), so without the AI sleep ledger (Ai Camps At Night off, equal camp hours or Ai Sleep Debt off) no lord loses drill for want of sleep - not even your clan's parties and the lords in your army - while you still do. With Drill Law Ai on the penalty applies anyway, as part of the rule (off = AI drill whatever their state, only while Drill Law Ai is off)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillPenaltyAi { get; set; } = true;

        [SettingPropertyBool("Drill Law Ai", HintText = "AI lords' parties drill by the same rule as yours - base 10 + 2 x tier for every lord, clan leaders included (the game gives a clan leader's men 15 + 3 x tier), the commander's Leadership, rest or march, no drill after a night without sleep (sleep debt at dawn - until the next dawn) or when starving; training perks on top as in the game. Off = the game's flat daily training, with the clan leader's bonus (the starving and sleep penalty then follows Drill Penalty Ai)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillLawAi { get; set; } = true;

        [SettingPropertyBool("Drill Log", HintText = "daily drill lines in Armoury.log: your men's experience today and its parts, the drill stock, and the AI measurement (log only)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillLog { get; set; } = true;

        [SettingPropertyBool("Drill Daily Message", HintText = "once a day, on a day your men drill by Drill Law, a short line in the game tells you what they learned and why: 'Drill today: N XP (n per man) - Leadership, at rest or marching, drill kit, armed share, perks'. A day lost to hunger or lack of sleep is announced as before (off = no daily drill line)", RequireRestart = false)]
        [SettingPropertyGroup("Drill")]
        public bool DrillDailyMessage { get; set; } = true;

        [SettingPropertyBool("Arms Not Household Goods", HintText = "townsfolk do not use up arms, armour, shields and harness: these lie on the stalls until a soldier, a notable or a trader buys them (everyday clothing is still worn out by the townsfolk)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ArmsNotHouseholdGoods { get; set; } = true;

        [SettingPropertyBool("Arms No Stall Decay", HintText = "the game no longer deletes a piece of arms or armour with a quality modifier from town stalls each day: armour does not rot on a stall - its wear is counted by its condition. Horses keep the game's rule; pieces forged by the player are still cleared from stalls (they are unique save objects)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ArmsNoStallDecay { get; set; } = true;

        [SettingPropertyFloatingInteger("Arms Stall Upkeep Man Days Per Piece", 0.00f, 1.00f, "0.00", HintText = "man-days a year a town's smiths spend cleaning and oiling each piece of arms on its stalls (the Tower, 1340s: 11 men oiled 3,200 bows in 5 days) - keeping stock is work, not free", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float ArmsStallUpkeepManDaysPerPiece { get; set; } = 0.02f;

        [SettingPropertyBool("Bk Supplies No Arms", HintText = "Banner Kings supplies of AI parties no longer buy and use up weapons and shields: the wear of an AI army's weapons is counted by Armoury (battle wear and repairs) - one rule, not two", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool BkSuppliesNoArms { get; set; } = true;

        [SettingPropertyBool("Bk Supplies No Arms Player", HintText = "the same for your own party: weapons, shields and arrows wear out by Armoury's rules only, not also by Banner Kings supplies", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool BkSuppliesNoArmsPlayer { get; set; } = true;

        [SettingPropertyBool("Workshop State In Save", HintText = "work in progress at town workshops (pieces begun, raw material already bought, unmet orders) is kept in the save, so a long piece of armour survives saving and loading", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopStateInSave { get; set; } = true;

        [SettingPropertyBool("Workshop Hands Follow Material", HintText = "a workshop's hands go only to lines that can work today - a piece already in hand, or the ore, wood, leather and cloth for a new one on the town's stall (and a piece it can finish within Workshop Plan Days)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopHandsFollowMaterial { get; set; } = true;

        [SettingPropertyBool("Workshop Freed Hands By Shortage", HintText = "hands of a craft that cannot work today (no ore, no cloth) help the other crafts of the town according to what the town lacks most - not by the fixed shares of Paris 1292", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopFreedHandsByShortage { get; set; } = true;

        [SettingPropertyBool("Workshop Choose By Shortage", HintText = "workshops first make what the town lacks most (empty stalls and unmet orders), and only then what pays best - the price cap no longer hides which shortage is worst. Civilian clothes that no soldier wears are left to the tailors of the town, not the armourers' lines", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopChooseByShortage { get; set; } = true;

        [SettingPropertyBool("Workshop Munition Grade", HintText = "when armour of tier 1-3 is short, every second piece begun is the quickest of that kind and tier - munition harness, as Paris made 500 sets in under three months in 1384 beside its better work", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopMunitionGrade { get; set; } = true;

        [SettingPropertyInteger("Workshop Munition Max Tier", 1, 6, "0", HintText = "highest tier made for munition when short (1-6)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public int WorkshopMunitionMaxTier { get; set; } = 3;

        [SettingPropertyFloatingInteger("Workshop Munition Share", 0.00f, 1.00f, "0.00", HintText = "share of the pieces begun in a short kind that are made for munition (0-1)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WorkshopMunitionShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Workshop Line Shortage Share", 0.00f, 1.00f, "0.00", HintText = "share of a craft's hands that follow the shortage of its lines; the rest is spread evenly, and a line with a piece in hand keeps at least an even share until it is finished (0-1)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WorkshopLineShortageShare { get; set; } = 0.75f;

        [SettingPropertyFloatingInteger("Workshop Plan Days", 14.00f, 120.00f, "0", HintText = "a workshop starts no piece it cannot finish within this many days with an even share of its craft's hands, and banks no more than this many days of work (14-120)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WorkshopPlanDays { get; set; } = 60f;

        [SettingPropertyBool("Town Material Orders", HintText = "a town whose smiths, fletchers, weavers or tanners stood idle for want of a raw material hires a caravan in a nearby friendly town that has more than it needs: the caravan buys the load there at the market price and carries it by road - a real party on the map that bandits can rob - and sells it to the town on arrival. Before removing the mod, switch this off and play one day", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrders { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Material Order Range Ore", 0.00f, 800.00f, "0.00", HintText = "farthest (map distance) iron ore is carried - two or three days; ore travelled short, iron came from afar as bars", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float TownMaterialOrderRangeOre { get; set; } = 200f;

        [SettingPropertyFloatingInteger("Town Material Order Range", 0.00f, 2400.00f, "0.00", HintText = "farthest timber, leather, cloth, flax, hides and wool are carried - about ten days on the road", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float TownMaterialOrderRange { get; set; } = 600f;

        [SettingPropertyInteger("Town Material Order Days", 1, 30, "0", HintText = "a town orders the same raw material at most once in this many days", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public int TownMaterialOrderDays { get; set; } = 3;

        [SettingPropertyFloatingInteger("Carter Pence Per Kg Per100", 0.0000f, 0.1500f, "0.0000", HintText = "cost of carrying one kilogram 100 leagues by road, which the caravan must earn before it takes the order (about 1.5 pence a ton a mile in 14th-century England)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float CarterPencePerKgPer100 { get; set; } = 0.0375f;

        [SettingPropertyFloatingInteger("Sea Freight Share", 0.00f, 1.00f, "0.00", HintText = "cost of a sea leg as a share of the same distance by road", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float SeaFreightShare { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Town Material Order Min Load Kg", 0.00f, 1000.00f, "0", HintText = "smallest load (kilograms) worth a caravan leaving its trade for the road; a smaller shortage waits until it grows", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float TownMaterialOrderMinLoadKg { get; set; } = 100f;

        [SettingPropertyBool("Workshop Hands By People", HintText = "a town's arms craftsmen are counted from the people of its market - the town and the villages that sell there, as the realm tables give them - and a richer town keeps more masters; no town has fewer than under the old rule. Off: the old rule only", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopHandsByPeople { get; set; } = true;

        [SettingPropertyFloatingInteger("Workshop Hands Per1000 People", 0.00f, 1.00f, "0.00", HintText = "man-days of arms work a day for each 1000 people of a town's market (fletchers come on top). Estimate from history: 0.3 to 0.6 armourers, weaponsmiths, bowyers, fletchers and saddlers per 1000 people of the realm; raised in steps together with ore and timber", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WorkshopHandsPer1000People { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Workshop Hands Max Per Town", 0.00f, 4000.00f, "0.00", HintText = "safety ceiling on one town's arms craftsmen under the population rule", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WorkshopHandsMaxPerTown { get; set; } = 1000f;

        [SettingPropertyBool("Cold Start Legacy Hands", HintText = "the merchants' starting stock of a new campaign is counted from the old number of craftsmen - more craftsmen do not mean more free stock at the start", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ColdStartLegacyHands { get; set; } = true;

        [SettingPropertyBool("Caravan Bulk Legacy Hands", HintText = "the stock of ore, timber, leather and cloth a town keeps before it sells to caravans is counted from the old number of craftsmen, so towns with many craftsmen do not stop selling their surplus", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool CaravanBulkLegacyHands { get; set; } = true;

        [SettingPropertyFloatingInteger("Mine Output Step", 0.00f, 6.00f, "0.00", HintText = "further step of iron ore digging on top of Mine Output Multiplier - more ore together with more craftsmen; still several times less iron for arms than medieval Europe", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float MineOutputStep { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Woodlot Step", 0.00f, 6.40f, "0.00", HintText = "further step of timber from village woods on top of Village Woodlot Loads - for the charcoal of the smiths (about six loads of wood for every load of ore); one of the steps 1.3 / 1.6 / 1.9, chosen by the smiths' need", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float WoodlotStep { get; set; } = 1.6f;

        [SettingPropertyBool("Bk Raw No Rot", HintText = "Banner Kings no longer deletes 2% a day of large stocks of ore, metal, tools, leather and cloth in towns and castles; large stocks of timber, flax and wool lose 0.2% a day instead of 2% (stores without a roof)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool BkRawNoRot { get; set; } = true;

        [SettingPropertyBool("Ai Any Melee When Short", HintText = "an AI soldier with no melee weapon of his grade, in a party short of melee weapons of any kind, buys any sword, axe or spear of his tier or lower from the stall - a weapon in his hand rather than none (drill and promotion still count only a weapon of his grade); bought only up to the party's real lack, so it is never sold back as surplus", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool AiAnyMeleeWhenShort { get; set; } = true;

        [SettingPropertyBool("Ai Worse Body Armour When Short", HintText = "an AI soldier with no body armour of his grade, in a party short of body armour of any kind, buys a padded coat of his tier or lower, or armour two tiers lower (protection only, not for drill or promotion)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool AiWorseBodyArmourWhenShort { get; set; } = true;

        [SettingPropertyBool("Old Stock To Scrap", HintText = "the town smiths slowly buy up for scrap the old arms and armour lying on their stalls beyond a year of what lords, garrisons and notables buy there - worst pieces first - and smelt their metal back into ore for their forges", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool OldStockToScrap { get; set; } = true;

        [SettingPropertyFloatingInteger("Old Stock Scrap Daily Share", 0.000f, 0.100f, "0.000", HintText = "share of that old surplus scrapped each day (1%)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float OldStockScrapDailyShare { get; set; } = 0.01f;

        [SettingPropertyFloatingInteger("Old Stock Scrap Yield", 0.00f, 1.00f, "0.00", HintText = "share of the ore a piece was forged from that comes back from its scrap", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float OldStockScrapYield { get; set; } = 0.5f;

        [SettingPropertyInteger("Workshop Pieces Per Cycle Max", 0, 256, "0", HintText = "most pieces one workshop line may finish in one cycle of the game (was 8) - a big town's spear-makers are not held back by the counter", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public int WorkshopPiecesPerCycleMax { get; set; } = 64;

        [SettingPropertyBool("Shelf Index Enabled", HintText = "prices of arms in towns count a stall from a remembered tally that is renewed whenever the stall changes, instead of going through the whole stall for every price - the same prices, less work for the game. Off: the old way", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ShelfIndexEnabled { get; set; } = true;

        [SettingPropertyInteger("Shelf Index Self Check Days", 0, 30, "0", HintText = "for this many days after loading, every 64th count is checked against the whole stall (later every 4096th); a difference is written to the Armoury log", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public int ShelfIndexSelfCheckDays { get; set; } = 1;

        [SettingPropertyBool("Shelf Index Own Update", HintText = "when the mod itself takes a piece off a stall or puts one back (what lords, garrisons, stables and builders buy, and the surplus arms the merchants carry between towns), the remembered tally of that stall is corrected by that one piece instead of being counted anew before the next price - the same prices, less work for the game. Off: counted anew after every piece, as before", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ShelfIndexOwnUpdate { get; set; } = true;

        [SettingPropertyBool("Dte Delegates", HintText = "the mod calls the routines of other mods it relies on (the armouries of Dynamic Troop Equipment, the caravans of Banner Kings) directly instead of looking them up anew each time - the same result, a little less work for the game. Off: the old way", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool DteDelegates { get; set; } = true;

        [SettingPropertyBool("Workshop Law Fast", HintText = "the town workshops that make arms and armour do the same reckoning with less work for the game: the pull of the stall is reckoned once for each kind of piece instead of once for every piece, and what a workshop has in hand is looked up directly - the same pieces, prices and wages as before. Off: the old way", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool WorkshopLawFast { get; set; } = true;

        [SettingPropertyBool("Trade Export Fast", HintText = "the merchants who carry surplus arms between towns pick the same buyers with less work for the game: which towns lie within reach of each town is remembered instead of measured anew for every cartload, and what a town wants of each kind of piece is reckoned once for the day's round instead of once for every cartload - the same pieces, buyers and prices as before. Off: the old way", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TradeExportFast { get; set; } = true;

        [SettingPropertyBool("Town Material Order By Sea", HintText = "a town short of a raw material may also hire a merchant ship in a port that has it to spare: the sea leg costs a quarter of the same distance by road, and the ship can be taken by pirates", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrderBySea { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Material Order Sea Max Route", 100.00f, 3000.00f, "0", HintText = "longest sea voyage (map distance) for such an order - about two weeks under sail", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public float TownMaterialOrderSeaMaxRoute { get; set; } = 1000f;

        [SettingPropertyBool("Town Material Order From Packs", HintText = "a caravan that already carries the material may take the order and deliver it, if that pays better than selling it where it stands", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrderFromPacks { get; set; } = true;

        [SettingPropertyBool("Town Material Order Ahead", HintText = "a town that uses a raw material orders it before its stall runs empty - when what it has and what is on the way would last less than the journey plus two days", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrderAhead { get; set; } = true;

        [SettingPropertyBool("Town Material Order Player Caravans", HintText = "the caravans of your clan may take such orders like any other caravan (the profit goes to their purse); your own party never does", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrderPlayerCaravans { get; set; } = true;

        [SettingPropertyBool("Town Material Order By Cart", HintText = "a town short of a raw material that finds no caravan to carry its order sends for it by merchants' cart: it buys the load from the stall of the nearest town or castle that has more than it needs (by road - by road and water where no road runs all the way - or from port to port by sea), pays that town or castle from its own purse above the merchants' reserve, and the goods reach its stall after the days the road takes - a besieged town waits, and after thirty days the cart turns back and the money is returned. With bloomeries at the mines iron then travels as far as the other materials. Off = caravans only, as before", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool TownMaterialOrderByCart { get; set; } = true;

        [SettingPropertyBool("Fletchers Bid For Ore", HintText = "when a town lacks arrows, its iron ore goes to whoever earns more on it - the armourers or the fletchers - as far as the fletchers' hands can use it", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool FletchersBidForOre { get; set; } = true;

        [SettingPropertyBool("Shop Keeps Last Armour", HintText = "buyers for a whole company (lords, garrisons, notables, your own men with their purse, traders shipping surplus) leave the last piece of each kind of armour (body, head, legs, hands; cheap, middling and dear apart) on a town stall for whoever buys in person", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool ShopKeepsLastArmour { get; set; } = true;

        [SettingPropertyInteger("Shop Keep Pieces", 0, 3, "0", HintText = "how many such pieces stay on the stall (0-3)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public int ShopKeepPieces { get; set; } = 1;

        [SettingPropertyBool("Player Workshops Same Rule", HintText = "your own workshops follow the same rules as everyone else's: they make no armour and no arrows out of nothing (the Banner Kings armorsmithy and fletcher lines without any input stay idle), and when a town lacks arrows their iron ore goes to whoever earns more on it - your workshop or the town's fletchers. Off: your workshops as in the game", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool PlayerWorkshopsSameRule { get; set; } = true;

        [SettingPropertyBool("Player Mine Bulk Skip", HintText = "a mining enterprise you own yields as much metal by weight as one owned by a notable: with loads ten times heavier than the old pieces only every tenth cycle brings a load. Until now your own mine skipped this rule and made ten times the metal (off = every cycle yields, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Arms production")]
        public bool PlayerMineBulkSkip { get; set; } = true;

        [SettingPropertyBool("Hist Worth Windows Old Coin", HintText = "tournament prizes (the game's own and Tournaments XPanded's), the modest local prize of Grand Tourney and the cap on lords' armour orders are reckoned from fixed sums of the old coin (a prize worth 1600 to 5000, an order piece worth at most 12000). With historical prices they are compared with what a piece was worth before the repricing, so prizes and orders are again the kinds of goods their makers meant - good swords, helmets, mail and horses, not only the heaviest plate and warhorses - while the piece keeps its historical worth on the market. With RBM's tournament module on, RBM itself picks the main prize by the town's culture and your tier, and the game's and Tournaments XPanded's ranges serve only when its list is empty (needs Historical Prices; off = compared with today's worth, the game's prize range divided by Hist Tournament Scale)", RequireRestart = false)]
        [SettingPropertyGroup("Worth windows in the old coin (3.8)")]
        public bool HistWorthWindowsOldCoin { get; set; } = true;

        [SettingPropertyBool("Bk Supply Buy By Party Stock", HintText = "Banner Kings party supplies (drink, timber, animal products, tools) are bought by what the PARTY carries, not by what the town holds: once a day while a lord's party stays in a town, castle or village, and again on entering a town or castle, its quartermaster tops each supply up to its need - at most Bk Supply Max Pieces pieces - from that settlement's stall at the stall's price, and the coin goes to that settlement's purse. Banner Kings bought nothing whenever the town held enough, and its coin left the world. On the way into a town an AI lord skips the goods the game makes him sell right there - anything that is not food, such as timber, tools and wine (off = Banner Kings as before)", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings coin (stage 3)")]
        public bool BkSupplyBuyByPartyStock { get; set; } = true;

        [SettingPropertyBool("Bk Village Market Pays What It Has", HintText = "a village with a Banner Kings marketplace buys a surplus good from its town only while it has the coin for it, and the town gets exactly what the village paid (Banner Kings let the village pay more than it had and gave the town the full price out of nothing; off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings coin (stage 3)")]
        public bool BkVillageMarketPaysWhatItHas { get; set; } = true;

        [SettingPropertyBool("Bk Village Market No Arms", HintText = "villagers with a Banner Kings marketplace no longer buy arms, armour, shields or horse harness from their town and make them vanish - the same rule as for townsfolk (arms are not household goods); they still buy arrows, clothes and everyday goods, and the coin they would have spent stays in the village purse. Works only with Bk Village Market Pays What It Has (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings coin (stage 3)")]
        public bool BkVillageMarketNoArms { get; set; } = true;

        [SettingPropertyBool("Bk Slave Sale Paid By Town", HintText = "surplus slaves sold off by a settlement's owner (Banner Kings decision to sell surplus slaves) are paid for by the merchants of that town or castle - at most what its purse may spend - instead of with coin out of nothing; the slaves they cannot pay for stay in the settlement (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings coin (stage 3)")]
        public bool BkSlaveSalePaidByTown { get; set; } = true;

        [SettingPropertyBool("Bk Knight Kit Paid To Town", HintText = "when an AI lord raises a new household knight (Banner Kings with the ROT patch), the price of the knight's arms and armour goes to the market of the knight's village instead of vanishing (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings coin (stage 3)")]
        public bool BkKnightKitPaidToTown { get; set; } = true;

        [SettingPropertyBool("Rot Swap No Gold", HintText = "when Realm of Thrones turns an AI lord's soldier into a cheaper man of the lord's house, the lord no longer gets the difference in recruit cost out of thin air: it is the same man, and the kit he lacks is bought on the market as usual. A swap into a dearer man still costs the lord the difference, just as a troop upgrade does (off = Realm of Thrones also pays the lord the difference out of nowhere)", RequireRestart = false)]
        [SettingPropertyGroup("Realm of Thrones without gold from nowhere (3.7)")]
        public bool RotSwapNoGold { get; set; } = true;

        [SettingPropertyBool("Rebel Purse From Town", HintText = "the 50,000 gold a rebel leader gets when a town or castle rebels come out of that settlement's own coffers, as much as they hold - not out of thin air (off = the game's gift from nowhere)", RequireRestart = false)]
        [SettingPropertyGroup("Realm of Thrones without gold from nowhere (3.7)")]
        public bool RebelPurseFromTown { get; set; } = true;

        [SettingPropertyBool("Bk Estate Income From Sales Only", HintText = "Banner Kings estates no longer pay a daily production income out of thin air; an estate earns only its share of the harvest the village carts sell in town (paid by the town). The estate window shows the 28-day average of that share (off = Banner Kings as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool BkEstateIncomeFromSalesOnly { get; set; } = true;

        [SettingPropertyBool("Caravan Wage To Purse", HintText = "the daily wages of caravan guards (notables' and lords' caravans) go to the purse of those men, who spend all of it in the next town they leave - not into thin air. A beaten party's men's purse goes to a victor with a hero as before (a third to him, the rest to his men); a victor without a hero that carries coin (bandits) takes it, otherwise the destroyer's settlement (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool CaravanWageToPurse { get; set; } = true;

        [SettingPropertyBool("Bk Workshop Tax To Lord", HintText = "the Banner Kings tax on a notable's workshop is really paid by the notable to the lord of the town (the town keeps its autonomy share), instead of vanishing on one side and being created from nothing on the other. Banner Kings does not charge the tax on a lord's or your workshop in another lord's town: with Workshop Owner Pays Town Tax on, its owner pays it to the town's lord; with that off - and always for a workshop of the town lord's own house - nobody pays it and the town's lord no longer gets it from nothing either. Needs town rents (Population Rent Enabled, Rent Replaces Town Tax) - otherwise as before (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool BkWorkshopTaxToLord { get; set; } = true;

        [SettingPropertyBool("Bk Lord Fees Have Recipients", HintText = "gold Banner Kings takes from lords goes somewhere: title claims, grants, revocations, usurpations and dilemma levers to the realm's treasury (no realm - the nearest town), court cost changes to the seat's purse, moving the court to the new seat's purse, a new knight's endowment to the knight's new house (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool BkLordFeesHaveRecipients { get; set; } = true;

        [SettingPropertyBool("Dead Hero Gold Stays", HintText = "when nobody inherits a dead hero's gold (a notable, a wanderer, the last of a house), it goes to the purse of his settlement - or the settlement he was in, or the nearest town - instead of vanishing (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool DeadHeroGoldStays { get; set; } = true;

        [SettingPropertyBool("Caravan Profit In Realm Town", HintText = "a lord's caravan (Banner Kings realistic caravan income) deposits its profit above 10,000 with its owner in any town of the owner's realm, not only at his seat or his own fiefs - the same deposit, just sooner (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool CaravanProfitInRealmTown { get; set; } = true;

        [SettingPropertyBool("Garrison Recruit Fee To Seller", HintText = "the fee a house pays off for the recruits its garrisons took from the notables (a fifth of what is owed each day) goes to the notable who raised each man, or to his settlement's coffers if he is gone - it no longer vanishes; only what the house really paid that day is passed on (off = the fee vanishes, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Every coin has a payer (stage 3)")]
        public bool GarrisonRecruitFeeToSeller { get; set; } = true;

        [SettingPropertyBool("Defeat Morale Half", HintText = "a beaten party loses half the morale the game takes for a lost battle (10 instead of 20) and for each lost round of an auto-resolved battle (1.5 instead of 3; 0.5 instead of 1 while retreating) - the same for you and the AI. Men still desert by their tier thresholds, but a defeat now drives away about half as many (off = the game's penalty)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool DefeatMoraleHalf { get; set; } = true;

        [SettingPropertyBool("Band Join Purse To Player", HintText = "when outlaws agree to join your party, the coin they carried is handed to you - it is not a war spoil, so the crown takes no ninth of it (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool BandJoinPurseToPlayer { get; set; } = true;

        [SettingPropertyBool("Workshop Owner Pays Town Tax", HintText = "a lord's or your own workshop in a town of another house pays the Banner Kings workshop tax (the sum shown as 'Taxes from' in the town's taxes) once a day from its owner's purse to the town's lord - the town keeps its autonomy share; an owner with too little coin pays what he has and owes nothing more. Needs BK Workshop Tax To Lord and town rents (off = nobody pays it and the town's lord does not get it, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool WorkshopOwnerPaysTownTax { get; set; } = true;

        [SettingPropertyBool("Bk Supply From Men Purse", HintText = "the Banner Kings party supplies (drink, timber, animal products, tools) are paid for by the soldiers out of their own purse, like their clothes - after what they keep for outstanding repairs; when the purse runs short they buy only what they can afford and the lord does not top it up. The same for your party if your quartermaster buys supplies. Needs Men Purse Enabled (off = the party's leader pays, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool BkSupplyFromMenPurse { get; set; } = true;

        [SettingPropertyBool("Rot Swap Pay To Purse", HintText = "when Realm of Thrones swaps an AI lord's soldier for a dearer man of the lord's house, the difference the lord pays goes to the purse of the men of that party - as with troop upgrades - so they can buy the kit of their new rank in town (bandits and the dead: the nearest town's purse). Off = it vanishes, as before", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool RotSwapPayToPurse { get; set; } = true;

        [SettingPropertyBool("Lord Purse Only To Victor", HintText = "the men's purse of a destroyed lord's party goes only to the leader of the side that beat it in that battle (as before: a third to him, the rest to his men). The game sometimes names the leader of the LOSING side as the destroyer (a party of the winning side left without men) or destroys a party outside battle - then the purse goes to the nearest town's purse instead (off = whoever the game names as destroyer takes it, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool LordPurseOnlyToVictor { get; set; } = true;

        [SettingPropertyBool("Battle Plunder From Loser Only", HintText = "the coin the victors of a battle share out comes only from what the beaten really lose. A beaten lord - or you - hands over his share of it (the game's 5% of his coin, at most 10,000) even when he is taken captive or flees, and the victors never get more than the beaten pay; a beaten leader with no coin gives nothing. What a captor already took from a captive's purse when he was taken (Realistic Captivity going through your baggage) counts toward his share - he is not robbed twice. The Others take no coin (with Beaten Purse To Victor on). In war the crown takes its ninth of what a vassal wins from a beaten lord's purse, as of any plunder (Crown Thirds). The same for you and the AI. Sunk ships at sea are not changed here (off = as before: the victors get the beaten lord's share out of thin air and he keeps his coin)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool BattlePlunderFromLoserOnly { get; set; } = true;

        [SettingPropertyBool("Stragglers Rally", HintText = "of the men who flee when a lord's host is beaten (in battles where the beaten mostly flee, and in your own field battles - your host or the lords you beat), most fear being hanged as deserters and come back: 55% go back to the banner, 30% go home, 15% take to the woods (seasoned men of tier 4 and up 70% back, tier 3 55%, green levies 45%; beaten in their own land more go home, in a foreign land more stay with the banner or turn outlaw; each week of unpaid wages sends 10 points of them to the woods instead, never below 20% back; the Night's Watch 80% back, none home). Those coming back gather at the nearest castle or town of their house (else of their realm) after 3-10 days and wait there for their lord or any host of the house; when one is within reach they march to it (if their castle or town falls, they make for another one); a host takes only as many as it has room for in its size limit and its wage limit. Waiting men draw no pay. Those not taken after the waiting time scatter, half home and half to the woods. Off = as before: the men who flee go home or to the woods. Turned off during a campaign, the stragglers still waiting scatter the next morning, as if their waiting time were over.", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool StragglersRally { get; set; } = true;

        [SettingPropertyInteger("Stragglers Rally Wait Days", 5, 90, "0", HintText = "days the gathered stragglers wait at their castle or town for a host of their house before they scatter (half home, half to the woods)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public int StragglersRallyWaitDays { get; set; } = 30;

        [SettingPropertyFloatingInteger("Stragglers Rally Reach Days", 0.50f, 15.00f, "0.0", HintText = "the gathered stragglers go to a host of their house when it is within this many days of march of the place where they gathered", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public float StragglersRallyReachDays { get; set; } = 5f;

        [SettingPropertyBool("Player Armory Like Ai Lord", HintText = "when you are taken captive your company's armoury (Dynamic Troop Equipment) goes to your captor, as a beaten lord's armoury goes to his victors: a lord's company takes it into its own armoury, a settlement's men into their garrison's armoury or the settlement's stores, a band into its packs; the rest of what you lose is set in Realistic Captivity (Player Loses Like Ai Lord) (off = the armoury stays yours, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Defeats and payers (D11)")]
        public bool PlayerArmoryLikeAiLord { get; set; } = true;

        [SettingPropertyBool("War Tax From Folk", HintText = "in war the crown also taxes the townsfolk's and castle folk's earnings, on top of the war subsidy from the merchants' and villages' spare coin - up to 3%, up to 6% under the War Tax policy, raised each week while the crown has to borrow or spend its old hoard to repay the war wages, lowered when it no longer has to; the higher it is, the less the people buy and the slower prosperity grows. Labourers pay half the rate, craftsmen the full rate, patricians one and a half; a besieged town or castle pays nothing. In peace nothing is taken and the rate falls back to nothing within four weeks. Only while the townsfolk's purse is live and the crown pays from its current income. You and the AI alike. Off = no war tax on the people, as before", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public bool WarTaxFromFolk { get; set; } = true;

        [SettingPropertyFloatingInteger("War Tax Max", 0.000f, 0.100f, "0.000", HintText = "highest war tax on the people's earnings while the realm has no War Tax policy (0.03 = 3%)", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public float WarTaxMax { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("War Tax Max With Policy", 0.000f, 0.200f, "0.000", HintText = "highest war tax on the people's earnings while the realm has the War Tax policy (0.06 = 6%)", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public float WarTaxMaxWithPolicy { get; set; } = 0.06f;

        [SettingPropertyFloatingInteger("War Tax Step", 0.000f, 0.020f, "0.000", HintText = "how much the war tax rises, or falls, at each weekly reckoning of the crown's need (0.005 = half a point)", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public float WarTaxStep { get; set; } = 0.005f;

        [SettingPropertyInteger("War Tax Reserve Days", 0, 364, "0", HintText = "the crown's war reserve is this many days of the wage refunds it has owed over the last 28 days (at least Crown Reserve Gold): a treasury below it raises the war tax, one twice above it - with no loan and no need to dip into the hoard for a week - lets it fall", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public int WarTaxReserveDays { get; set; } = 60;

        [SettingPropertyBool("War Reserve By Need", HintText = "the crown's war reserve is reckoned from the wage refunds it really owes - after the refund by need (Crown Refund By Need) - not from the full refunds it would owe if every house were poor. The crown keeps untouched War Tax Reserve Days of what it actually pays (at least Crown Reserve Gold); everything above is its treasure for war. One reserve for the war tax, the war aid from the treasury, the refunds, the war grant, the treasure taken with a fallen capital and the loans from the towns. Off = the reserve is reckoned from the full refunds, as before", RequireRestart = false)]
        [SettingPropertyGroup("The war tax on the people (stage 5)")]
        public bool WarReserveByNeed { get; set; } = true;

        [SettingPropertyBool("Castle Lords Even Up", HintText = "while the townsfolk's purse is live, the crown evens up what it costs the lords of castles (the villagers then keep most of their market takings and spend them in the towns): a town's lord shares the town's daily dues half and half with the crown (Town Rent Lord Share With Folk) instead of keeping two thirds, and the crown shares out its rents by fixed fief weights that favour castles - a town 2, a castle 1.5, a village a quarter (Crown Rent Weight Town and Castle With Folk) instead of 3, 1 and a quarter. Never by the size of a garrison. You and the AI alike. Without the townsfolk's purse, or off = Town Rent Lord Share and the Crown Rent Weights, as before", RequireRestart = false)]
        [SettingPropertyGroup("Evening up for the castle lords (stage 5)")]
        public bool CastleLordsEvenUp { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Rent Lord Share With Folk", 0.00f, 1.00f, "0.00", HintText = "with Castle Lords Even Up while the townsfolk's purse is live: of what a town purse gives up each day its lord keeps this share and the kingdom treasury the rest (0.5 = half and half; a town held outside any kingdom pays everything to its lord)", RequireRestart = false)]
        [SettingPropertyGroup("Evening up for the castle lords (stage 5)")]
        public float TownRentLordShareWithFolk { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Crown Rent Weight Town With Folk", 0.00f, 8.00f, "0.00", HintText = "with Castle Lords Even Up while the townsfolk's purse is live: rent weight of a town (a castle Crown Rent Weight Castle With Folk, a village Crown Rent Weight Village)", RequireRestart = false)]
        [SettingPropertyGroup("Evening up for the castle lords (stage 5)")]
        public float CrownRentWeightTownWithFolk { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Crown Rent Weight Castle With Folk", 0.00f, 6.00f, "0.00", HintText = "with Castle Lords Even Up while the townsfolk's purse is live: rent weight of a castle", RequireRestart = false)]
        [SettingPropertyGroup("Evening up for the castle lords (stage 5)")]
        public float CrownRentWeightCastleWithFolk { get; set; } = 1.5f;

        [SettingPropertyBool("Ships To Port", HintText = "When a party is destroyed on land or disbanded, the ships its house cannot use are sold to the nearest port of the realm with room in its shipyard (or, if the realm's ports cannot pay, to a port of a realm at peace with the house). The port pays the usual sale price (30% of the value minus repairs) out of its spare money above its merchants' reserve - the same for you and the AI. No buyer: the ships are lost. Off = the game pays the house the full worth of those ships out of thin air (you get 30%), as before", RequireRestart = false)]
        [SettingPropertyGroup("Ships and the ports (stage 3)")]
        public bool ShipsToPort { get; set; } = true;

        [SettingPropertyInteger("Ship Sale Ports Tried", 0, 12, "0", HintText = "how many nearest ports (first of the realm, then of realms at peace with the house) are asked for the full price of a lost or prize ship before the port with the most spare money pays what it can (0 counts as 1)", RequireRestart = false)]
        [SettingPropertyGroup("Ships and the ports (stage 3)")]
        public int ShipSalePortsTried { get; set; } = 3;

        [SettingPropertyBool("Ship Trade Through Port", HintText = "Ships bought from or sold to a port are paid into or out of the port's purse (above its merchants' reserve), and the governor's merchant-prince and shipwright bonuses come out of it too; a port without spare money buys no ship from the AI and pays you at most what it has. Off = the price of a ship bought from a port vanishes and a ship sold to a port is paid out of thin air, as before", RequireRestart = false)]
        [SettingPropertyGroup("Ships and the ports (stage 3)")]
        public bool ShipTradeThroughPort { get; set; } = true;

        [SettingPropertyBool("Ship Prizes To Port", HintText = "After a sea battle, the beaten fleet's ships the victors do not keep are sold to a port (the same choice of port and price as lost fleets) and the port's payment is shared among the victors by their part in the battle, instead of the game paying their full worth out of thin air; no buyer - the ship sinks. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Ships and the ports (stage 3)")]
        public bool ShipPrizesToPort { get; set; } = true;

        [SettingPropertyBool("Ship Ports Buy To Ideal", HintText = "a port buys ships only while its shipyard keeps fewer than it wants (two below its limit) - beyond that the shipyard breaks up the extra hulls the next day, so the port no longer pays for ships it will scrap: an AI captain keeps the ship he wanted to sell, the ships of a beaten or disbanded host go to another port with room or are lost, and you too cannot sell to a full port. Off = ports buy up to the shipyard's limit, as before", RequireRestart = false)]
        [SettingPropertyGroup("Ships and the ports (stage 3)")]
        public bool ShipPortsBuyToIdeal { get; set; } = true;

        [SettingPropertyInteger("Town Folk Mode", 0, 1, "0", HintText = "0 off; 1 = the townsfolk's purse is counted every day from the real flows (wages, services, the basket by the people of each town) and written to the log only - it changes nothing in the game unless Town Folk Live is on (then the purse is real coin); 0 also turns the live purse off", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int TownFolkMode { get; set; } = 1;

        [SettingPropertyBool("Town Folk Live", HintText = "the townsfolk's purse is live: townsfolk, castle folk and villages earn, pay their taxes and dues and buy their goods with their own coin; nothing the townsfolk eat appears or vanishes. Needs Town Purse Regulator (town purses as real coin) and Town Folk Mode 1. The war tax on the people and the lords' share of the town dues follow it. Off = as before stage 5 (their purses go back into the town and castle purses)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkLive { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Folk Service Share", 0.00f, 1.00f, "0.00", HintText = "of what soldiers, caravan men, outlaws and garrisons spend in a town or castle, this share goes to its people - beds, inns, washing, services - and the rest to the merchants", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkServiceShare { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Town Folk Labour Food", 0.00f, 1.00f, "0.00", HintText = "of every sale of food and drink by the merchants, this share is paid to the people who mill, bake, brew and carry", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkLabourFood { get; set; } = 0.2f;

        [SettingPropertyFloatingInteger("Town Folk Labour Goods", 0.00f, 1.00f, "0.00", HintText = "of every sale of cloth, tools, salt and pots by the merchants, this share is paid to the people who carry, sell and finish", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkLabourGoods { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Town Folk Labour Arms", 0.00f, 1.00f, "0.00", HintText = "of every sale of arms, armour, horses and luxuries by the merchants, this share is paid to the people who carry and sell", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkLabourArms { get; set; } = 0.04f;

        [SettingPropertyFloatingInteger("Town Folk Labour Village Buys", 0.00f, 0.50f, "0.00", HintText = "with Folk Earn From Village Buys: of what the merchants pay the village carts for their produce, this share is paid to the people who unload, measure and store it (as for goods off a caravan's wagons; milling and baking are paid from the food sales)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkLabourVillageBuys { get; set; } = 0.1f;

        [SettingPropertyFloatingInteger("Town Folk Craft Wage Share", 0.00f, 1.00f, "0.00", HintText = "the people's wages in every workshop's goods - the merchants pay the rest up to this share of their worth", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkCraftWageShare { get; set; } = 0.35f;

        [SettingPropertyFloatingInteger("Town Folk Merchant Draw", 0.000f, 0.200f, "0.000", HintText = "the merchant families' living out of their trade - a share of the merchants' daily sales", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkMerchantDraw { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Town Folk Merchant Profit Share", 0.00f, 1.00f, "0.00", HintText = "of what a town purse gives up each day above the merchants' working coin, this share first goes to its clerks, coopers and the merchant families; the lord and the crown share the rest", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkMerchantProfitShare { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Town Folk Castle Profit Share", 0.00f, 1.00f, "0.00", HintText = "of what a castle purse gives up each day, this share goes to the castle folk under its walls", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkCastleProfitShare { get; set; } = 0.15f;

        [SettingPropertyFloatingInteger("Town Folk Excise", 0.000f, 0.200f, "0.000", HintText = "the town's excise on what its people buy - it pays the town's walls, streets and clerks, and a third goes to the lord as the town's farm", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownFolkExcise { get; set; } = 0.02f;

        [SettingPropertyInteger("Town Folk Reserve Days", 1, 60, "0", HintText = "days of their needs the labourers keep in hand; above that they buy better food, ale and cloth (craftsmen keep 21, merchant families 30, castle folk 10, villages 15)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int TownFolkReserveDays { get; set; } = 10;

        [SettingPropertyBool("Town Folk Anchor Basket", HintText = "the townsfolk buy at most what the people of the town need and can pay for - when they run short they buy less, cloth and luxuries first, bread last", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkAnchorBasket { get; set; } = true;

        [SettingPropertyBool("Town Folk Castle Court Feeds", HintText = "the lord's kitchen feeds part of his castle folk: the court's money spent at a castle pays for the food its people eat beyond what they can pay themselves", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkCastleCourtFeeds { get; set; } = true;

        [SettingPropertyBool("Town Folk Satisfaction From Basket", HintText = "the townsfolk's contentment with their goods follows what they could really buy, not the market alone", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkSatisfactionFromBasket { get; set; } = true;

        [SettingPropertyBool("Bread For The Poor", HintText = "when the townsfolk or castle folk have been unable to afford their food for a week (the same hunger that hurts their contentment; it can start from day 120 of the campaign), the realm's crown tops up the purses of the poor to two days of food, out of the rest of its daily income after the wage refunds and before the rents; if the crown has nothing left, the lord of the place pays from his gold above his war reserve, but only from the part of his war chest that does not go to wages (at war this comes out of his equipment money), so in all he spends no faster than his war chest; a lord in debt never pays. The poor spend their purse as always - food first, then the rest of their basket - so in effect the bread covers what their earnings lack. Your own purse is never used. A place leaves the bread after a week of affording two days of food on its own. Off = the poor buy only what their purse allows, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool BreadForThePoor { get; set; } = true;

        [SettingPropertyBool("Town Folk Hunger Hurts", HintText = "when the townsfolk cannot afford their bread for a week, their contentment with food falls - not in the first 120 days of a campaign and only while there is food in the market; a town with no food at all is already punished by its empty granary, so its contentment is not cut twice. Off = as before: contentment with food follows what they could buy every day (needs Town Folk Satisfaction From Basket)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkHungerHurts { get; set; } = true;

        [SettingPropertyBool("Town Folk Start Reserves", HintText = "in a new campaign the townsfolk, castle folk and villages start with a few days of their needs out of the towns' and castles' starting purses (in an old save - out of the merchants' spare coin, at most half)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownFolkStartReserves { get; set; } = true;

        [SettingPropertyFloatingInteger("Village Lord Scale", 0.00f, 1.00f, "0.00", HintText = "the lord takes this share of what Banner Kings would give him from a village's market takings (70% under the usual tax policy, 50% low, 90% high), and Village Lord Extra Share of the takings on top - 45% usual, 35% low, 55% high; the village keeps the rest. Replaces the old daily rent of a fifth of the village purse (with Town Folk Live on)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float VillageLordScale { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Village Purchase Per Head", 0.00f, 1.00f, "0.00", HintText = "coins a day each free villager spends in the market town on salt, tools, cloth, pots and ale (with Town Folk Live on)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float VillagePurchasePerHead { get; set; } = 0.07f;

        [SettingPropertyFloatingInteger("Village Dues Per Head Year", 0.00f, 50.00f, "0.0", HintText = "coins a year each free villager pays his lord in court, mill and market dues (with Town Folk Live on)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float VillageDuesPerHeadYear { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Village Lord Extra Share", 0.00f, 1.00f, "0.00", HintText = "on top of Village Lord Scale the lord takes this share of a village's market takings - 45% under the usual tax policy, 35% low, 55% high; the owners of Banner Kings estates take their part out of the lord's share as before (with Town Folk Live on; 0 = 35% usual, 25% low, 45% high)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float VillageLordExtraShare { get; set; } = 0.10f;

        [SettingPropertyBool("Temple Tithe", HintText = "The tithe: a village gives the priest of its village Tithe Village Share of its market takings, and townsfolk give the priest of their town 1% (labourers), 2% (craftsmen) or 3% (merchant families) of what they earn. Half goes back as alms to the poor of the same town or village, half pays for building septs - three quarters as wages to the townsfolk who build (for a village, those of its market town) and a quarter for stone and timber paid to the town's merchants. A town without a priest pays its tithe into the town's coffers, a village without one keeps it (with Town Folk Live on; off = no tithe)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TempleTithe { get; set; } = true;

        [SettingPropertyFloatingInteger("Tithe Village Share", 0.00f, 0.20f, "0.00", HintText = "share of a village's market takings it gives as tithe, out of the village's own part of them (with Temple Tithe on)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TitheVillageShare { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Folk Surplus Spend Share", 0.00f, 1.00f, "0.00", HintText = "share of their coin above their reserve that townsfolk and villages spend each day - labourers on better food, ale and cloth, craftsmen and merchant families mostly as wages, villages in their market town; the reserve is Town Folk Reserve Days for labourers, 21 days for craftsmen, 30 for merchant families and 15 days of purchases for a village (castle folk spend 7% as before; 0.07 = as before). With Folk Luxury List on, only the wages of craftsmen and merchant families and the villages' spending on their usual goods follow this share (with Wards And Villages Shop on, the villages spend it only on salt and tools)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkSurplusSpendShare { get; set; } = 0.15f;

        [SettingPropertyBool("Folk War Aid", HintText = "in war, while the crown is in need (the same weekly reckoning that sets the war tax on the people's earnings), the townsfolk and castle folk give the kingdom's treasury a part of the coin they hold above their reserve for hard times - Folk War Aid Share a day at the full war tax, less while the need is small, twice that under the War Tax policy. The reserve itself (Town Folk Reserve Days of their needs for labourers, 21 days for craftsmen, 30 for merchant families, 10 for castle folk) is never touched, so a poor town pays nothing. The crown spends the aid the same day on repaying war wages and on its rents to the houses. A besieged town or castle pays nothing, a town held outside any kingdom pays no one, in peace nothing is taken (except the Folk Peace Tribute: in a long peace, only what the crown spends on bread for its hungry towns). Villages are not changed - they already pay the war subsidy. You and the AI alike: in your kingdom the aid goes to the realm's treasury, not to your purse. Needs War Tax From Folk. Off = no war aid, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkWarAid { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk War Aid Share", 0.000f, 0.100f, "0.000", HintText = "part of their coin above the reserve that townsfolk and castle folk give the crown each day of war at the full war tax (0.025 = one part in forty a day; scaled by the realm's current war tax against War Tax Max, so twice as much at the top rate under the War Tax policy)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkWarAidShare { get; set; } = 0.025f;

        [SettingPropertyBool("Folk War Aid Loyalty", HintText = "with Folk War Aid: a town or castle whose people gave the crown war aid at dawn grows less loyal to its lord that day - up to Folk War Aid Loyalty Cost a day, in proportion to how much of all the people's coin the aid took (the full cost when it took one part in forty of it). The loss never draws loyalty below Folk War Aid Loyalty Floor: it shrinks as loyalty nears the floor and stops there, and what the lord's own war levy (Lord War Levy) cost the town that day counts against the same limit. A town or castle with loyalty at or below Folk War Aid Min Loyalty pays no war aid at all - the tax gatherers leave a town so close to revolt. You see the loss as 'War aid from the people's savings' in the loyalty tooltip. Off = no loss of loyalty and no such limit, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkWarAidLoyalty { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk War Aid Loyalty Cost", 0.00f, 5.00f, "0.00", HintText = "with Folk War Aid Loyalty: loyalty a town or castle loses in a day when the war aid took one part in forty of all the coin its people hold (1 = about ten points lower in the long run, since the game draws loyalty back towards 50 by a tenth of the distance each day); less in proportion when the aid took less, never more", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkWarAidLoyaltyCost { get; set; } = 1.0f;

        [SettingPropertyFloatingInteger("Folk War Aid Loyalty Floor", 0.00f, 100.00f, "0", HintText = "with Folk War Aid Loyalty: the war aid never draws a town's loyalty below this - it may cost at most a tenth of a point a day for each point the town stands above this floor, less what the lord's war levy cost it that day, so it stops at the floor (60 keeps towns clear of 50, below which the lord's taxes begin to slip)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkWarAidLoyaltyFloor { get; set; } = 60f;

        [SettingPropertyInteger("Folk War Aid Min Loyalty", 0, 100, "0", HintText = "with Folk War Aid Loyalty: a town or castle with loyalty at or below this pays no war aid (the game's unrest begins at 25)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int FolkWarAidMinLoyalty { get; set; } = 30;

        [SettingPropertyBool("Folk Peace Tribute", HintText = "in a long peace (the realm at war with no other realm for at least 91 days) the crown takes back from the labourers' savings in its towns - the coin they hold above their reserve for hard times - only as much as it spent the day before on bread for its own hungry towns and castles (Bread For The Poor), and never more than one part in two hundred of those savings a day. It goes the same way as the war aid: the reserve is never touched, a besieged town pays nothing, a town too close to revolt pays nothing, and the same loss of loyalty (Folk War Aid Loyalty) applies, shown as 'Peace tribute from the people's savings'. You and the AI alike: in your realm it goes to the treasury, not to your purse. Needs Folk War Aid and Bread For The Poor. Off = nothing is taken in peace, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkPeaceTribute { get; set; } = true;

        [SettingPropertyBool("Folk Hoard Tax", HintText = "the lords tax the townsfolk's hoard: whatever the labourers, craftsmen, merchant families and castle folk hold above the normal level of their savings (Folk Hoard Normal Times their reserve for hard times - about what they held at the start of a campaign), part of it goes each day to the lord of the town or castle and to its purse, in peace and in war alike - coin that finds nothing to buy goes back to the lords and the towns instead of piling up. The crown's war aid or peace tribute paid the same day counts towards it, so nobody pays twice. A besieged place pays nothing. You and the AI alike: the lord's share from your own towns and castles goes to your purse. Off = the people's savings pile up as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkHoardTax { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Hoard Tax Rate", 0.000f, 0.050f, "0.000", HintText = "with Folk Hoard Tax: the part of the hoard above the normal level that goes to the lord and the purse each day (0.01 = one part in a hundred a day: a hoard halves in about ten weeks and the people then keep about two months of living)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkHoardTaxRate { get; set; } = 0.01f;

        [SettingPropertyFloatingInteger("Folk Hoard Normal Times", 1.00f, 10.00f, "0.0", HintText = "with Folk Hoard Tax: the normal level of the people's savings, as a multiple of their reserve for hard times (3 = 30 days of their needs for labourers and castle folk, 63 for craftsmen, 90 for merchant families); nothing below it is taxed", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkHoardNormalTimes { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Folk Hoard Tax Lord Share", 0.00f, 1.00f, "0.00", HintText = "with Folk Hoard Tax: of the hoard tax the lord of the town or castle takes this share and the town's or castle's purse the rest (a place with no living lord - all to its purse)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkHoardTaxLordShare { get; set; } = 0.67f;

        [SettingPropertyBool("Folk Hoard Villages", HintText = "with Folk Hoard Tax: the villages pay the same tax on their hoard - what a village holds above Folk Hoard Normal Times its fifteen days of purchases goes, one part in a hundred a day (Folk Hoard Tax Rate), to the lord of the village and to the purse of its town or castle. A village that is being raided or lies looted pays nothing, nor one whose town or castle is besieged. Off = the villages' coin piles up as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkHoardVillages { get; set; } = true;

        [SettingPropertyBool("Folk Circulation Guard", HintText = "with Folk Hoard Tax: a steward of the realm's coin watches each day how much all the common folk - townsfolk, castle folk and villagers - hold against their normal level of savings. While they hold more than Folk Guard Band High times it, the hoard tax rises a little each day (up to Folk Guard Max Times the usual rate); while they hold less than Folk Guard Band Low times it, it falls a little each day (down to a quarter). It never takes more in a day than about one part in seven hundred of all the coin in the world, or twice what flows into the people's purses in a day, whichever is more, so an old hoard comes back slowly. Folk Guard Crown Share of every hoard tax goes to the treasury of the realm the place belongs to. Off = the hoard tax stays at Folk Hoard Tax Rate and goes only to the lord and the purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkCirculationGuard { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Guard Band Low", 1.00f, 3.00f, "0.00", HintText = "with Folk Circulation Guard: below this many times their normal level of savings the common folk pay less hoard tax each day", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkGuardBandLow { get; set; } = 1.25f;

        [SettingPropertyFloatingInteger("Folk Guard Band High", 1.00f, 5.00f, "0.00", HintText = "with Folk Circulation Guard: above this many times their normal level of savings the common folk pay more hoard tax each day", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkGuardBandHigh { get; set; } = 1.75f;

        [SettingPropertyFloatingInteger("Folk Guard Max Times", 1.00f, 10.00f, "0.0", HintText = "with Folk Circulation Guard: the hoard tax never rises above this many times Folk Hoard Tax Rate", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkGuardMaxTimes { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Folk Guard Crown Share", 0.00f, 0.80f, "0.00", HintText = "", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkGuardCrownShare { get; set; } = 0.35f;

        [SettingPropertyFloatingInteger("Folk Guard Crown Target", 0.00f, 0.50f, "0.00", HintText = "with Folk Circulation Guard: when the realms' treasuries together hold less than this part of all the gold in the world, the treasury's part of every hoard tax grows (by five times the shortfall, up to 0.8), so the crowns win back what they pay out - the lords and the town and castle purses share the rest; the crowns' own payments to the houses are not touched          // with Folk Circulation Guard: the part of every hoard tax (towns, castles and villages) that goes to the treasury of the realm the place belongs to; the lord and the purse share the rest as before (a place outside any realm - nothing to a treasury)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkGuardCrownTarget { get; set; } = 0.22f;

        [SettingPropertyBool("Folk Loans", HintText = "the lords borrow from their own people: an AI house at war whose coin has run below its reserve for war may borrow, before it goes to the Iron Bank, from what the townsfolk, castle folk and villagers of its own towns, castles and villages hold above their normal level of savings - at most Folk Loan Max Share Of Income of its daily income a day, at most Folk Loan Limit Days of its daily income plus 20000 for a town and 10000 for a castle in all. The people earn Folk Loan Rate Year a year on it. In war the house pays only the interest; in peace it repays Folk Loan Repay Share Of Income of its daily income a day (at least a year's share) back into the purses it borrowed from. A house that cannot pay in peace for Folk Loan Default Days days running defaults: the rest of the debt is lost to the people, every town and castle of that house that lent to it loses 10 loyalty, and it may not borrow from its people for half a year. Not your house. Off = the lords borrow only from the Iron Bank, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkLoans { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Loan Rate Year", 0.00f, 0.50f, "0.00", HintText = "with Folk Loans: the interest a year the people earn on what their lord borrowed (0.12 = twelve parts in a hundred a year)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLoanRateYear { get; set; } = 0.12f;

        [SettingPropertyFloatingInteger("Folk Loan Max Share Of Income", 0.00f, 1.00f, "0.00", HintText = "with Folk Loans: the most a house may borrow from its people in a day, as a part of its daily income", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLoanMaxShareOfIncome { get; set; } = 0.60f;

        [SettingPropertyFloatingInteger("Folk Loan Limit Days", 0.00f, 120.00f, "0", HintText = "with Folk Loans: the most a house may owe its people, in days of its daily income (plus 20000 for each town and 10000 for each castle it holds)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLoanLimitDays { get; set; } = 60f;

        [SettingPropertyFloatingInteger("Folk Loan Repay Share Of Income", 0.00f, 0.50f, "0.00", HintText = "with Folk Loans: the part of its daily income a house at peace repays its people each day, on top of the interest", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLoanRepayShareOfIncome { get; set; } = 0.10f;

        [SettingPropertyInteger("Folk Loan Default Days", 7, 364, "0", HintText = "with Folk Loans: days in a row in peace without the full instalment after which a house defaults on its debt to its people", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int FolkLoanDefaultDays { get; set; } = 90;

        [SettingPropertyBool("Folk Guard Crown To Reserve", HintText = "with Folk Circulation Guard: the treasury's part of the hoard tax is laid by in the treasury's reserve instead of being spent with the day's income - the crown pays it out slowly, like the rest of its reserve, instead of handing it to the houses the same day. Off = the treasury's part is spent with the day's income, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkGuardCrownToReserve { get; set; } = true;

        [SettingPropertyBool("Crown Town Loans", HintText = "the crowns borrow from their towns: a realm at war whose treasury has fallen below its reserve for war (60 days of the wages it pays back to its houses, at least 500000) borrows what it lacks from the towns of the realm - at most half of what a town's purse holds above the merchants' stock and of what its labourers, craftsmen and merchant families hold above their normal savings, the richest first (not besieged towns, not your towns). The borrowed coin is kept in the treasury, not handed out. The towns earn Crown Town Loan Rate Year a year on it. In war the crown pays only the interest; in peace it repays the debt within about half a year, and it pays back early whenever its treasury is above its reserve for war. A crown that cannot pay in peace for Crown Town Loan Default Days days running defaults: the rest is lost to the towns, every town that lent loses 10 loyalty and the crown may not borrow from its towns for half a year. Off = the crowns do not borrow from their towns, as before (a debt already owed waits in the save)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownTownLoans { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Town Loan Rate Year", 0.00f, 0.50f, "0.00", HintText = "with Crown Town Loans: the interest a year the towns and townsfolk earn on what their crown borrowed (0.10 = ten parts in a hundred a year - less than a house pays its people, far less than the Iron Bank asks of a king)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float CrownTownLoanRateYear { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Crown Town Loan Limit Days", 0.00f, 364.00f, "0", HintText = "with Crown Town Loans: the most a crown may owe its towns, in days of its own daily income (dues, war levies, tolls, its share of the purses), plus 50000 for each town of the realm", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float CrownTownLoanLimitDays { get; set; } = 90f;

        [SettingPropertyInteger("Crown Town Loan Default Days", 7, 364, "0", HintText = "with Crown Town Loans: days in a row in peace without the full instalment after which a crown defaults on its debt to its towns", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int CrownTownLoanDefaultDays { get; set; } = 90;

        [SettingPropertyBool("Crown Town Loan No Write Off", HintText = "with Crown Town Loans: a crown that does not pay its towns for Crown Town Loan Default Days in peace is in DEFAULT - its towns lose loyalty and lend it nothing for a while, but the debt is NOT written off: it stays and is paid from the crown's income (Jeff 17.10: debts must be paid); off = the old write-off", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownTownLoanNoWriteOff { get; set; } = true;

        [SettingPropertyBool("Town Loan", HintText = "a lord at war whose coin has run below his war reserve borrows first from the council of his own town or the folk of his own castle, before the Iron Bank: the labourers, craftsmen and merchant families lend what they hold above Town Loan Folk Reserve Times their reserve days, the merchants' coffer what it holds above Town Loan Coffer Reserve Times its stock (at most half of each in a day), the castle folk what they hold above their reserve. The debt to one place is at most Town Loan Rent Days of the rent that place pays him, at Town Loan Rate a year; the town and the Bank together lend him at most War Credit Max Share D of his steady income a day. He pays the interest out of his steady income and the debt from his windfalls (the Bank first) and after the peace by instalments, within All Instalments Max Share; whoever misses three instalments falls under the same arrears and seizure as with the Bank, and every coin of interest and debt goes back to the purses that lent it. You may borrow from your own town or castle in its menu. Replaces the lords' loans from their people (Folk Loans); with Town Loan Takes Folk Loans their old debts move here. Off = no new town loans (debts already owed are still paid back), as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownLoan { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Loan Rate", 0.00f, 0.50f, "0.00", HintText = "with Town Loan: the interest a year the town council or the castle folk earn on what their lord borrowed (0.10 = ten parts in a hundred a year - less than the Iron Bank asks)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownLoanRate { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Town Loan Rent Days", 0.00f, 364.00f, "0", HintText = "with Town Loan: the most a lord may owe the council of one town or the folk of one castle, in days of the rent that place pays him (average of the last 28 days)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownLoanRentDays { get; set; } = 120f;

        [SettingPropertyFloatingInteger("Town Loan Folk Reserve Times", 1.00f, 5.00f, "0.0", HintText = "with Town Loan: the townsfolk and castle folk lend only what they hold above this many times their reserve days (labourers and castle folk 10 days of their needs, craftsmen 21, merchant families 30); 1 = everything above their bread money", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownLoanFolkReserveTimes { get; set; } = 1.0f;

        [SettingPropertyFloatingInteger("Town Loan Coffer Reserve Times", 1.00f, 5.00f, "0.0", HintText = "with Town Loan: the merchants' coffer of a town lends only what it holds above this many times the merchants' stock", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float TownLoanCofferReserveTimes { get; set; } = 1.5f;

        [SettingPropertyBool("Town Loan Takes Folk Loans", HintText = "with Town Loan and Folk Loans: the debts the lords already owe their people from the old Folk Loans move into the town loans (same purses, ten parts in a hundred a year, the instalments and arrears of the debt ladder instead of the write-off) - one rule for both. Every lord who owed his people becomes a debtor of the debt ladder at once. Off (default) = the old debts run on by the Folk Loans rules until they are paid; only new loans come from the councils", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool TownLoanTakesFolkLoans { get; set; } = false;

        [SettingPropertyBool("Crown War Aid By Need", HintText = "in war the crown spends the day's war aid from the people's savings first on the wages of houses whose own wage ceiling cannot keep their field companies up to Crown War Aid Fill Target of their size, the weakest first; only what is left goes out as rents by fiefs. The crown pays only for men who stand in the companies today - a house that does not recruit gets nothing more - and the wages it pays this way are not repaid a second time. Only houses that hold fiefs and meet the crown's rent terms (garrisons and service); not the Night's Watch, not hired companies, and your house only with Scutage Player Clan. Needs Folk War Aid, Crown Rents and Clan Budget Enabled. Off = all the war aid goes out as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownWarAidByNeed { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown War Aid Fill Target", 0.00f, 1.00f, "0.00", HintText = "how full the crown helps a house keep its field companies with Crown War Aid By Need, as a part of their size limit (0.60 = up to six men in ten - about what houses with coin to spare keep on their own)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float CrownWarAidFillTarget { get; set; } = 0.60f;

        [SettingPropertyFloatingInteger("Crown War Aid Recruit Step", 0.00f, 1.00f, "0.00", HintText = "with Crown War Aid By Need: how many new men a day, as a part of the companies' size limit, a helped house may take on ahead of the crown's coin (the crown starts paying for them the day after they join)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float CrownWarAidRecruitStep { get; set; } = 0.10f;

        [SettingPropertyBool("Scutage", HintText = "shield money: in war a house of the realm that holds fiefs, keeps coin above its war reserve and could pay for more field troops than it keeps (more than Crown War Aid Fill Target of its companies' size) pays the crown Scutage Rate of the wages it spares that way. The crown takes only as much as its war aid by need still lacks after the people's war aid, and pays it out the same day to the houses whose companies it helps - coin goes from rich houses that field little to the houses that fight. Never more a day than one part in War Chest Days of the coin above the war reserve, never from the reserve itself. A house that takes the crown's help pays nothing, and a house rebuilding its companies up to the fill target is not charged for the men it has yet to recruit. Not the Night's Watch, not hired companies, not houses in debt; your house only with Scutage Player Clan. A realm that takes no war aid from its people still fills the pot from scutage alone. Needs Crown War Aid By Need. Off = no scutage, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool Scutage { get; set; } = true;

        [SettingPropertyFloatingInteger("Scutage Rate", 0.00f, 1.00f, "0.00", HintText = "with Scutage: the part of its spare wage ceiling a house pays the crown each day of war (0.25 = a quarter of the wages its lands could carry beyond its companies at the fill target and does not pay)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float ScutageRate { get; set; } = 0.25f;

        [SettingPropertyBool("Scutage Player Clan", HintText = "your house too: in war, while you hold a town or a castle and serve a king as his vassal (not as the ruler and not as a mercenary), your house pays scutage and receives the crown's war aid by need on the same terms as the lords of the realm. Your lands are measured as theirs are - what your income and coin above the war reserve could pay for in wages, less your garrisons and caravans; this is only a measure and never limits your recruiting. If you keep fewer men than your lands could pay for, you pay the crown a part of the wages you spare; if your companies cost more than your lands can carry, the crown pays part of the wages of men already in your companies (only while you keep the crown's terms for rents). Never both on the same day. A short note the first time, then one sum a week. Needs Crown War Aid By Need (and Scutage for paying). Off = your house neither pays nor is paid, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool ScutagePlayerClan { get; set; } = true;

        [SettingPropertyBool("War Aid Follows Lords Shortfall", HintText = "in war the people's war aid from their savings also rises when the lords of the realm cannot pay for their companies: while the houses the crown helps (Crown War Aid By Need) still lack wages that the day's war aid, the crown's spare treasure and the shield money together do not cover - on average over a week, and more than War Aid Lords Shortfall Share of the wage refunds the crown owes - the share the townsfolk and castle folk give of their coin above the reserve rises by one step of the war tax each week, up to the same ceiling (3%, 6% under the War Tax policy), whatever the crown's own accounts say. It falls back step by step once the aid would cover the lack even at the lower share, and within four weeks in peace. Only the aid from savings rises: the war tax on the people's earnings is reckoned as before, and the reserve for hard times is never touched, so a poor town pays nothing more. You and the AI alike. Needs Folk War Aid and Crown War Aid By Need. Off = the war aid follows the crown's own need only, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool WarAidFollowsLordsShortfall { get; set; } = true;

        [SettingPropertyFloatingInteger("War Aid Lords Shortfall Share", 0.00f, 0.50f, "0.00", HintText = "with War Aid Follows Lords Shortfall: the lords' lack of wages counts once it is larger than this part of the wage refunds the crown owes in a day (0.05 = one part in twenty), and never while it is under 250 coins a day", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float WarAidLordsShortfallShare { get; set; } = 0.05f;

        [SettingPropertyBool("Need Aid From Rents", HintText = "in war, when the day's war aid, the crown's spare treasure and the shield money still leave houses of the realm short of wages for their field companies (Crown War Aid By Need), the crown pays those wages from the rest of its daily income before it shares out rents by fiefs - only for men who stand in the companies today; the rents get what is left. Off = the rest of the day's income goes out as rents, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool NeedAidFromRents { get; set; } = true;

        [SettingPropertyBool("Crown Surplus Feeds Need Aid", HintText = "in war, when the day's war aid from the people does not cover the wages of the houses the crown helps (Crown War Aid By Need), the crown adds coin from its own treasury - but only from what it holds above its war reserve (the larger of Crown Reserve Gold and War Tax Reserve Days of wage refunds) and above what it owes the Iron Bank, never more in a day than one part in Crown Surplus Aid Days of that surplus and never more than is still lacking. The crown pays before the rich houses are asked for shield money and, like the rest of that aid, only for men who stand in the companies today. A treasury at or below its war reserve gives nothing. You and the AI alike: in your kingdom the coin comes from the realm's treasury, not from your purse. Needs Crown War Aid By Need. Off = the aid by need is paid from the day's war aid and shield money only, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownSurplusFeedsNeedAid { get; set; } = true;

        [SettingPropertyInteger("Crown Surplus Aid Days", 1, 360, "0", HintText = "with Crown Surplus Feeds Need Aid: each day the crown spends at most one part in this many of its treasure above the war reserve (30 = a month's worth; the reserve itself is never touched)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int CrownSurplusAidDays { get; set; } = 30;

        [SettingPropertyBool("Crown War Aid Middle", HintText = "in war the realm's treasury also helps the houses of modest means, not only the poor: above the crown's war aid by need (which keeps companies up to Crown War Aid Fill Target of their size), the treasury pays a share of the wages a house still lacks for its companies up to their full size - the whole lack while the house's gold is below its war reserve, a smaller share the richer the house, and nothing above twice the reserve (the same measure of need as the wage refund and the fief rents). Paid only from what the treasury holds above its war reserve and its debts, together with Crown Surplus Feeds Need Aid never more in a day than one part in Crown Surplus Aid Days of that surplus; coin only for men already in the companies, and room in the wage ceiling to recruit a step more. Never in peace, never to a house with spare room under its own ceiling or that paid scutage that day, and these wages are not repaid by the crown a second time. Your house the same way. Needs Crown Surplus Feeds Need Aid. Off = the crown helps only up to Crown War Aid Fill Target, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownWarAidMiddle { get; set; } = true;

        [SettingPropertyBool("Crown War Aid Cash By Need", HintText = "in war the crown pays the coin of its war aid by need (Crown War Aid By Need - from the people's war aid, from its spare treasure with Crown Surplus Feeds Need Aid and from the rest of its daily income with Need Aid From Rents) by the same measure as the wage refund and the fief rents: a house whose family gold is below its war reserve gets the whole coin, a house holding more than twice its war reserve gets none, and in between the share falls evenly the richer the house is. The room in the wage ceiling stays as before - such a house keeps its companies and pays the rest of their wages from its own gold. What a house does not get stays in the realm's treasury for war - it is never shared out to the other houses nor paid out as rents. A house in debt is judged on its own gold; your house the same way. The shield money and the aid for houses of modest means keep their own rules. Off = every helped house gets the whole coin, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool CrownWarAidCashByNeed { get; set; } = true;

        [SettingPropertyBool("Scutage By Need", HintText = "the shield money the crown passes on to the houses it helps is paid by the same measure as the rest of its war aid: a helped house whose family gold is below its war reserve gets the whole coin, a house holding more than twice its war reserve gets none, and in between the share falls evenly the richer the house is. What a helped house does not get is never collected - it stays with the houses that would have paid the shield money. The room in the wage ceiling stays as before. Needs Scutage and Crown War Aid Cash By Need. Off = every helped house gets the whole shield money coin, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool ScutageByNeed { get; set; } = true;

        [SettingPropertyBool("Lord War Levy", HintText = "in war a lord whose own wage ceiling cannot keep his field companies up to Crown War Aid Fill Target of their size, and whom the crown's war aid by need (the people's war aid, the spare treasure and the shield money) did not fully help that day, raises a war levy in his own towns, castles and villages: up to Lord War Levy Rate a day of the coin the townsfolk, castle folk and villagers still hold above their reserve after the crown's war aid and war subsidy. The coin goes to his purse for the wages of the men already in his companies and raises his wage ceiling by as much; for men he has yet to recruit he gets only room in his ceiling, as with the crown's aid. Never more than the house still lacks, never from the reserve, never in peace, and these wages are not repaid by the crown a second time. Each fief pays in loyalty and prosperity in proportion to how hard it is taxed; a town or castle with loyalty under Lord War Levy Min Loyalty, in revolt or under siege pays nothing (nor do its villages), nor does a looted village. Not your house - see Player War Levy. Needs Crown War Aid By Need and the people's purses (Town Folk Live). Off = no war levy, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool LordWarLevy { get; set; } = true;

        [SettingPropertyBool("Player War Levy", HintText = "Levy a war tax in your own fiefs on the same terms as the lords: in war, while your lands cannot keep your companies up to Crown War Aid Fill Target of their size and the crown's war aid falls short, your towns, castles and villages give you up to Lord War Levy Rate a day of the coin they hold above their reserve, toward the wages of the men in your companies - at a loyalty and prosperity cost to each fief, as for the lords. Works only while the crown measures your house for war aid (Scutage Player Clan: a vassal holding a town or a castle, not the ruler). Off = your fiefs pay you no war levy (default)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool PlayerWarLevy { get; set; } = false;

        [SettingPropertyFloatingInteger("Lord War Levy Rate", 0.000f, 0.100f, "0.000", HintText = "with Lord War Levy: the part of the coin above their reserve that a lord's townsfolk, castle folk and villagers give him each day of war at the full rate (0.03 = three parts in a hundred a day; less when the house lacks less)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float LordWarLevyRate { get; set; } = 0.03f;

        [SettingPropertyFloatingInteger("Lord War Levy Loyalty", 0.00f, 5.00f, "0.00", HintText = "with Lord War Levy: loyalty a town or castle loses each day it is taxed at the full rate, its villages included (less in proportion when taxed less; with the game's drift of loyalty towards 50, half a point a day settles about five points lower)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float LordWarLevyLoyalty { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Lord War Levy Prosperity", 0.00f, 10.00f, "0.00", HintText = "with Lord War Levy: prosperity a town or castle loses each day it is taxed at the full rate, its villages included (1 = what the War Tax policy costs a day; less in proportion when taxed less)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float LordWarLevyProsperity { get; set; } = 1.0f;

        [SettingPropertyInteger("Lord War Levy Min Loyalty", 0, 100, "0", HintText = "with Lord War Levy: a town or castle with loyalty below this pays no war levy, nor do its villages", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public int LordWarLevyMinLoyalty { get; set; } = 40;

        [SettingPropertyBool("People Menu Shows Savings", HintText = "'People of this land' also tells for how many days of living the people of the town, castle or village you are in hold coin, how much of it lies above their reserve for hard times and how much war aid they gave the crown at the last dawn (off = no such line, as before)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool PeopleMenuShowsSavings { get; set; } = true;

        [SettingPropertyBool("Folk Ladder Measure Log", HintText = "writes daily and weekly lines that measure where the people's savings could go - the loyalty of towns and castles, what the townsfolk bought with their spare coin and what found no goods, what luxuries would cost if the market saw their purses, the merchants' margin on goods brought by caravans, towns with luxury workshops, the savings of towns that have something to build, the gold of houses with room under their wage ceiling and what each town earns from - to the log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkLadderMeasureLog { get; set; } = true;

        [SettingPropertyBool("Folk Luxury List", HintText = "townsfolk live better from what they hold above their reserve for hard times: each day they offer one part in Folk Surplus Spend Days of it (labourers all of it, craftsmen and merchant families the three tenths they do not pay out as wages, which they still pay at Folk Surplus Spend Share) for goods from their own town's market at market prices - cloth and clothes 55%, silver, jewels and spices 25%, a better table 12%, household goods 8%; castle folk the same with their own coin above 10 days. What is not on the shelves is not bought and the coin stays in their purses. Off = the old offer of Folk Surplus Spend Share a day on eight kinds of food, ale, linen, velvet and pots, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkLuxuryList { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Surplus Spend Days", 10.00f, 365.00f, "0", HintText = "with Folk Luxury List: the townsfolk spread what they hold above their reserve over this many days of better living (60 = one part in sixty a day)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkSurplusSpendDays { get; set; } = 60f;

        [SettingPropertyBool("Market Sees Purse", HintText = "with Folk Luxury List: the market sees the people's purses - what the townsfolk (and with Wards And Villages Shop the castle folk and villagers who shop there) offer each day for cloth, clothes, silver, jewels, spices and household goods counts in the town's demand, so these goods grow dearer where the people have coin and caravans may sell more there. Their offer never lifts a price above Folk Ladder Price Ceiling times the usual one, and they do not buy such goods from their savings while the price stands higher. Food, ale, linen and leather are not touched. Off = demand from the number of people only, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool MarketSeesPurse { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Ladder Price Ceiling", 1.00f, 5.00f, "0.00", HintText = "with Market Sees Purse: the highest price, as a multiple of the usual one, the people's offer may lift fine goods to and that they will pay from their savings (1.5 = half again the usual price)", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLadderPriceCeiling { get; set; } = 1.5f;

        [SettingPropertyBool("Folk Ladder Ceiling By Wealth", HintText = "with Market Sees Purse: townsfolk who hold far more than their normal level of savings will pay more for fine goods - the price they accept rises with the square root of how many times over their normal level they hold (four times the normal level - twice Folk Ladder Price Ceiling), up to Folk Ladder Ceiling Max, so a rich town bids for the jewels, velvet, silk, furs, silver and spice that reach the market. Felt, linen and leather, which the armies need, keep Folk Ladder Price Ceiling. Off = one ceiling for all towns, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkLadderCeilingByWealth { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Ladder Ceiling Max", 1.00f, 10.00f, "0.0", HintText = "with Folk Ladder Ceiling By Wealth: the highest price, as a multiple of the usual one, the richest townsfolk will pay for fine goods from their savings", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public float FolkLadderCeilingMax { get; set; } = 8f;

        [SettingPropertyBool("Folk Predict Bought", HintText = "with Folk Luxury List: the townsfolk reckon their reserve for hard times from what their spare coin actually bought the day before, not from what they offered (an offer that found no goods is not part of their living) - so towns whose people live well keep a full reserve; their share of the bill likewise counts only the part of the offer that found goods. Off = the reserve and the share count the whole offer, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkPredictBought { get; set; } = true;

        [SettingPropertyBool("Wards And Villages Shop", HintText = "with Folk Luxury List: castle folk (in the nearest town) and villagers (in their market town) spend what they hold above their reserve (10 days of needs for castle folk, 15 days of purchases for a village) the same way - one part in Folk Surplus Spend Days a day on the same goods, from the shelves of that town, leaving the last five pieces of each for its people. A village keeps buying its salt, tools, linen, pots and ale for its daily needs as before, and still spends Folk Surplus Spend Share of its spare coin a day on salt and tools. Off = castle folk spend their share in the castle itself and villages spend Folk Surplus Spend Share a day on all their usual goods, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool WardsAndVillagesShop { get; set; } = true;

        [SettingPropertyBool("Village Cloth Above Reserve", HintText = "villagers who shop for their daily basket in their market town (salt, tools, linen, pots, beer) buy linen only from what lies on the stall above what the town keeps for its soldiers, armourers and for towns that lack it (the same mark as Folk Cloth Above Reserve); what they meant to spend on linen and could not stays in the village purse, the rest of the basket is bought as before. Off = they buy linen down to the last five pieces on the stall, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool VillageClothAboveReserve { get; set; } = true;

        [SettingPropertyBool("Folk Cloth Above Reserve", HintText = "linen and leather are what the soldiers' clothing and the armourers' workshops use, so the townsfolk (and the castle folk and villagers who shop in town) buy them from their savings only from what lies on the stall above what the town keeps for itself and for towns that lack it (what the town will not sell to other towns, and as much again - at least one cart load - for carrying out), and never above Folk Ladder Price Ceiling times the usual price, like the other fine goods; and the part of the cloth meant for velvet, cotton, fur or felt that are too dear does not go to linen and leather. What they do not buy stays in their purses. Their everyday buying for their homes is not touched. Off = they buy linen and leather from their savings down to the last pieces on the stall, as before", RequireRestart = false)]
        [SettingPropertyGroup("The townsfolk's purse")]
        public bool FolkClothAboveReserve { get; set; } = true;

        [SettingPropertyBool("Stage6 Measure Log", HintText = "counts every piece of arms and every horse from where it came to where it went, and what each realm's smiths would make - written to the log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool Stage6MeasureLog { get; set; } = true;

        [SettingPropertyBool("Arms Book Bk Village Sink", HintText = "the arms book also counts the pieces villagers buy on a Banner Kings village market (they leave the world there) - written to the log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool ArmsBookBkVillageSink { get; set; } = true;

        [SettingPropertyBool("Workshop Craft By Realm", HintText = "each realm's smiths make the arms and armour of their own land - their own patterns first, then a kindred realm's, then those common to their region and their side of the sea, never a great house's livery from another realm and never a unique piece; what a realm cannot make, the traders bring. The realm of a town is the one of its land, not of its current lord. Your own forge is not limited (off = town workshops make anything of the town's culture and, when they have none, any foreign pattern, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool WorkshopCraftByRealm { get; set; } = true;

        [SettingPropertyBool("Plain Saddle Every Realm", HintText = "with Workshop Craft By Realm: the saddlers of every realm make the plain saddle that belongs to no land - a common riding harness with next to no armour for the horse - beside their own patterns, so a realm whose only own horse gear is a house caparison or an elephant's harness still has saddles for its riders (off = only the realm's nearest pattern, as before; takes effect on the next load)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool PlainSaddleEveryRealm { get; set; } = true;

        [SettingPropertyBool("Workshops Follow Inputs", HintText = "a town's trade workshop is the kind its own villages feed - no wine press where no grapes grow: when the game picks the trade of a workshop (at the start of a new campaign, after a bankruptcy, when you lose a workshop) a trade whose raw goods neither grow in the town's villages nor come by a materials contract is all but never chosen, unless no trade has them. Workshops already working and your own workshops are not changed (off = the game's choice, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool WorkshopsFollowInputs { get; set; } = true;

        [SettingPropertyBool("Sand Steeds In Dorne", HintText = "new campaign only: camels are bred only in Qarth - the desert studs of Dorne and of the Free Cities breed horses of the same kind (riding, war, pack) in their place, and the studs of Qarth breed camels in place of some of their horses; the same number of animals in all (off = the game's studs, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool SandSteedsInDorne { get; set; } = true;

        [SettingPropertyBool("Camels Only Qarth", HintText = "camels belong to Qarth alone: only the men of Qarth (and troops whose own kit has a camel) ride them and only the markets of Qarth keep them - Dorne rides its sand steeds; works together with Sand Steeds In Dorne in a new campaign (off, or an older campaign = Dorne may ride and sell camels too, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool CamelsOnlyQarth { get; set; } = true;

        [SettingPropertyBool("Exotic Mounts Never Vanish", HintText = "camels, chariots, elephants and mammoths are never struck off a market shelf: merchants do not haul them to a market that does not keep them, and one that a caravan or a lord sold there is bought by the nearest market that keeps it - that market pays the price and the beast goes there by the merchants' cart - or stays on the shelf; one in a troops' armoury of men who may not ride it goes to the party's baggage as goods, and the player keeps such beasts in the bags as goods (off = struck off, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool ExoticMountsNeverVanish { get; set; } = true;

        [SettingPropertyBool("Qarth Stables Buy Camels", HintText = "a lord whose camel riders have no camel in the troops' armoury buys camels for them at a market that keeps camels (Qarth), with his own gold - no bigger share of his purse than he spends on horses at one stop, and no more head than he buys at one stop (off = camel riders get no camels from the market, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool QarthStablesBuyCamels { get; set; } = true;

        [SettingPropertyBool("Spare Horses Carry Footmen", HintText = "every spare horse in the baggage - also a worn or lame one from the spoils - and every free horse in the troops' armoury carries a footman on the march; the game counts such horses the same way everywhere", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool SpareHorsesCarryFootmen { get; set; } = true;

        [SettingPropertyBool("Fodder From Horse State", HintText = "winter fodder is eaten by the horses a party really has - in the baggage, under its riders and free in the armoury - not by riders who have lost theirs", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool FodderFromHorseState { get; set; } = true;

        [SettingPropertyBool("Hamlet Kinds In District", HintText = "the hamlets of a district shape what it sends to market: fishing hamlets land fish in place of part of the grain (the same number of loads), mills and granaries keep it grain. Needs Village Book Enabled (off = the district sends grain as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HamletKindsInDistrict { get; set; } = true;

        [SettingPropertyBool("Horses Die Only Killed", HintText = "a horse dies only when it is killed: in your battles as it falls, in battles between AI lords along with its killed rider at the rate seen in real battles; a horse that lives through a lost battle is the victors' spoil", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HorsesDieOnlyKilled { get; set; } = true;

        [SettingPropertyInteger("Horse Death Ratio Min Battles", 0, 200, "0", HintText = "how many of your own battles with fallen riders are needed before their rate of dead horses per dead rider is used for battles between AI lords (until then one horse for each killed rider who had one)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public int HorseDeathRatioMinBattles { get; set; } = 50;

        [SettingPropertyBool("Spoils Non Food To Town", HintText = "goods other than food left behind by a broken party - iron, timber, wool, hides and the like - go to the market of the nearest friendly town instead of the nearest castle, where nobody uses them and no trader calls (food, horses, harness and arms go where they went before; needs Spoils Of Broken Parties)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool SpoilsNonFoodToTown { get; set; } = true;

        [SettingPropertyBool("Lord Discard To Shelf", HintText = "goods a lord's party throws away because it carries more than it can - most often loot taken from a broken cart or caravan - are left at the market of the nearest friendly town instead of vanishing (food and livestock too; horses and arms are not touched). The lord loses exactly what he lost before. Off = the goods vanish, as in the base game", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool LordDiscardToShelf { get; set; } = true;

        [SettingPropertyBool("Spoils Of Broken Parties", HintText = "what a broken or disbanded party carried - goods and horses - goes to the victors by their share in the battle (over their carrying limit, and with no victor, to the market of the nearest friendly town or castle); it no longer vanishes", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool SpoilsOfBrokenParties { get; set; } = true;

        [SettingPropertyBool("Veteran Takes Kit", HintText = "a soldier who leaves service for a tavern takes his own arms and armour from his lord's armoury, as he takes his horse; a mercenary hired at that tavern brings that kit to his new master in place of what he owns at home, and the kit of a veteran who gave up and went home is left at the town's market; your own armoury is not touched (off = the kit stays in the lord's armoury and a hireling brings only his home gear, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool VeteranTakesKit { get; set; } = true;

        [SettingPropertyBool("Veteran Keeps Horse", HintText = "a mounted soldier who leaves service for a tavern takes his own horse along; a mounted mercenary hired there rides that horse - with no horse left in the tavern he is offered as a footman", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool VeteranKeepsHorse { get; set; } = true;

        [SettingPropertyBool("New Party Horses From Seat", HintText = "a new lord's party gets its first horses and food from the shelves of its seat, paid by the house - or none", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool NewPartyHorsesFromSeat { get; set; } = true;

        [SettingPropertyBool("Troop Swap Needs Horse", HintText = "when a realm's troop rules turn a soldier into a mounted trooper, he rides only if his party has a horse for him, as for an upgrade; otherwise he becomes a footman of the same rank from his house's list", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool TroopSwapNeedsHorse { get; set; } = true;

        [SettingPropertyBool("Ai Sells Spare Horses", HintText = "a lord keeps a tenth more horses of each kind than his riders need - never fewer than Ai Mount Spare Buffer - and buys up to that; the horses of his fallen riders beyond half as many again he sells at the next market. The game no longer buys or sells lords' horses itself (off = lords buy for the men waiting to be raised to horse, as before, and the game trades their horses)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool AiSellsSpareHorses { get; set; } = true;

        [SettingPropertyFloatingInteger("Ai Spare Horse Share", 0.00f, 1.00f, "0.00", HintText = "the spare horses an AI lord keeps of each kind, as a share of his riders of that kind (never fewer in all than Ai Mount Spare Buffer)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public float AiSpareHorseShare { get; set; } = 0.10f;

        [SettingPropertyBool("Garrison Horses To Lords", HintText = "an AI lord stopping at a town or castle of his own realm takes the garrison's spare horses - those beyond its own riders, the riders of its patrols and a few kept for losses - for his riders who have no horse and for his men ready to be raised to horse; from his own house's stronghold for nothing, from another house's for the market price paid to that house's head, out of the same budget as his other horses. The market is not touched (off = garrison horses stay in the garrison, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool GarrisonHorsesToLords { get; set; } = true;

        [SettingPropertyBool("Garrison Harness To Lords", HintText = "with Rider Needs Harness on, the same lord also takes the garrison's spare saddles and harness that fit a horse - beyond what its own mounted men use and a few kept for losses - up to what he lacks, before he buys any; same terms as the horses: free from his own house, at the market price from another house of his realm. The market is not touched (off = only the horses)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool GarrisonHarnessToLords { get; set; } = true;

        [SettingPropertyBool("Pack Animals From Market", HintText = "a new caravan buys its pack animals at the market of its home town with its own trade money (up to half of it) instead of getting them from nothing; what the market lacks it buys later on the road (off = the game gives a new caravan half as many pack animals as men, from nothing)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool PackAnimalsFromMarket { get; set; } = true;

        [SettingPropertyBool("Villager Packs From Herd", HintText = "a new villager party takes its pack animals from the village's own herd instead of getting half as many pack animals as men from nothing; what the herd lacks, the party goes without and picks up from the herd on its next trips from home - villagers who carry their whole store are not slowed by it (off = the game gives them from nothing)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool VillagerPacksFromHerd { get; set; } = true;

        [SettingPropertyBool("Dte Convoy Packs Stay With Convoy", HintText = "the pack animals of a supply convoy (Dynamic Troop Equipment) carry its load and leave with it - they are no longer copied into the armoury of the party it supplies, where they stayed on as horses from nothing (off = copied, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool DteConvoyPacksStayWithConvoy { get; set; } = true;

        [SettingPropertyBool("Dte Convoy No Free Packs", HintText = "a lord's supply convoy (Dynamic Troop Equipment) no longer sets out with pack animals made out of thin air - neither the 17 pack horses DTE gave it to carry its 17 sacks of every food nor the pack animals the game gives every new caravan; the convoy does not trade, and its few pieces of gear are carried by its men. Works together with Dte Convoy No Free Food - while that food still rides along, so do the pack animals (off = as before: the pack animals appear from nothing and vanish with the convoy when it reaches the army)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool DteConvoyNoFreePacks { get; set; } = true;

        [SettingPropertyInteger("Spare Horse Carry Kg", 20, 100, "0", HintText = "how many kilograms a spare horse carries when no footman or prisoner rides it (the game gives every spare horse 20; 20 = as in the game)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public int SpareHorseCarryKg { get; set; } = 60;

        [SettingPropertyBool("Bloomery At Mine", HintText = "new campaigns only: the mining village smelts its ore on the spot and sends out iron blooms (15 kg) instead of 100 kg loads of ore; the bloomery burns real wood - from the woods of the district first, then bought at its market town - and without wood the mine yields less; the town forge burns only smith's charcoal, and scrap and wrecks are smelted back into blooms", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool BloomeryAtMine { get; set; } = true;

        [SettingPropertyFloatingInteger("Bloomery Cart Range", 0.00f, 2400.00f, "0.00", HintText = "with Bloomery At Mine: farthest (by road) a mining village's cart goes for wood when the woods of its district and its own market town give too little - it buys only what a friendly town holds above its own needs, pays that town from the village's gold, and the wood arrives after the days the road takes (about ten days at 600); 0 = no such carts, as before", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public float BloomeryCartRange { get; set; } = 600f;

        [SettingPropertyBool("Bloomery Wood Demand", HintText = "with Bloomery At Mine: a town's own need for wood (its stock target, what it will sell and the price) counts the smiths' charcoal alone plus the wood the mines' bloomeries really buy from its market, instead of the old rate measured when the ore was smelted in town (off = the old rate)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool BloomeryWoodDemand { get; set; } = true;

        [SettingPropertyBool("Bloomery Coal Before Lord Share", HintText = "with Bloomery At Mine: what a mining village paid for the wood of its bloomery comes out of its cart's market takings first, and the lord takes his share only of what is left - the difference moves from the lord's tax on those takings to the village's purse when the cart comes home, so no gold is made; the owners of Banner Kings estates keep their part (needs Village Takings Whole; off = the lord's share is counted on the whole takings, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool BloomeryCoalBeforeLordShare { get; set; } = true;

        [SettingPropertyBool("Tools By Use", HintText = "a town's tool makers work only while the market holds less than thirty days of the town's demand for tools; past that the iron stays on the shelf for the armourers and fletchers (off = tools are made whenever it pays, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool ToolsByUse { get; set; } = true;

        [SettingPropertyBool("Ai Buys Barding", HintText = "AI lords buy horse harness for their mounted men of tier 4 and above whose kit includes one, after everything else they lack, from what is left of the day's budget (off = AI lords never buy harness)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool AiBuysBarding { get; set; } = true;

        [SettingPropertyBool("Arms Trade By Cart", HintText = "the arms, harness and horses traders carry between towns leave the seller's shelf when bought and reach the buyer by cart after the days the road takes (the buyer pays at purchase; a besieged town waits, after thirty days the goods go back); off = they move the same day, as before", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool ArmsTradeByCart { get; set; } = true;

        [SettingPropertyBool("Workshop Recipes By Value", HintText = "the weavers' and tanners' workshops take as much wool, flax or raw hides as the worth of their goods calls for - 60% of the worth of the cloth or leather, never less than the goods weigh and never more than the craft can yield: about 3 sacks of wool for 2 bolts of woollen cloth, 6 of flax for 2 of linen, 5 hides for 2 leathers (the same rule as the town's own weavers and tanners), never less than the game's recipe; needs Historical Prices, takes effect at the next load (off = the game's recipes, one sack or hide for two pieces)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool WorkshopRecipesByValue { get; set; } = true;

        [SettingPropertyBool("Harvest Valve", HintText = "every four weeks a village makes less of a good the world does not use up and more of a good it does - instead of the stock rotting away on the stalls; the stock stays between one and two months of use (food is not touched, livestock for slaughter only with Animals Under Valve; off = villages make what the game says and unsold stock rots as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HarvestValve { get; set; } = true;

        [SettingPropertyBool("Valve Hold While Short", HintText = "the village regulator does not cut back a raw material that more than Valve Short Towns towns have none of: so many empty stalls mean the goods are not reaching the towns, not that the villages make too much - a stock lying where nothing carries it away no longer starves the rest of the world. A good already cut back returns to its normal output step by step while the shortage lasts (never above normal). Off = the regulator counts the whole stock, as before", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool ValveHoldWhileShort { get; set; } = true;

        [SettingPropertyInteger("Valve Short Towns", 0, 60, "0", HintText = "how many towns may have none of a raw material before the regulator stops cutting it back (needs Valve Hold While Short)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public int ValveShortTowns { get; set; } = 15;

        [SettingPropertyFloatingInteger("Village Output Step", 1.00f, 2.00f, "0.00", HintText = "the most a village can make of a good the world is short of, as a multiple of its normal output (1 = never more than normal; a cut-back good first returns to normal)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public float VillageOutputStep { get; set; } = 1.3f;

        [SettingPropertyInteger("Valve Stock Days Low", 7, 120, "0", HintText = "a village makes more of a good once the stock across the world falls below this many days of use", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public int ValveStockDaysLow { get; set; } = 30;

        [SettingPropertyInteger("Valve Stock Days High", 14, 240, "0", HintText = "a village makes less of a good once the stock across the world grows beyond this many days of use", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public int ValveStockDaysHigh { get; set; } = 60;

        [SettingPropertyBool("Horse Breeding By Demand", HintText = "every four weeks the stud farms breed more of a kind of horse the world is short of (up to the same step as other village goods), and while war horses are short and plain horses pile up they put up to a quarter of their plain-horse breeding to war horses; breeding below normal needs Horse Breeding Cut Live; works only with Harvest Valve on (off = stud farms breed what the game says)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HorseBreedingByDemand { get; set; } = true;

        [SettingPropertyBool("Townsfolk Buy Only Work Horses", HintText = "townsfolk and castle folk no longer buy horses of every kind out of their daily basket: a town or castle keeps one work horse for every 25 people, a work horse lives about 15 years, and its people buy only the cheapest pack horse on their own market (a plain riding horse when there is none) to replace one that died; war horses and noble horses stay on the market for the armies; needs the live townsfolk purse; turn on together with Horse Breeding Cut Live (off = the people buy horses of every kind as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool TownsfolkBuyOnlyWorkHorses { get; set; } = true;

        [SettingPropertyBool("Horse Breeding Cut Live", HintText = "the stud farms also breed fewer horses of a kind the world does not use up (down to a tenth of normal, at most halved every four weeks) instead of only reporting it; works only with Horse Breeding By Demand and Harvest Valve on (off = breeding never falls below what the game says)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HorseBreedingCutLive { get; set; } = true;

        [SettingPropertyBool("Horse Breeding Cut Over Stock", HintText = "when a kind of horse already piles up past the upper stock band, the stud farms trim its breeding as soon as the world uses fewer than they breed, not only when it uses under nine in ten (off = they trim only below nine in ten)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool HorseBreedingCutOverStock { get; set; } = true;

        [SettingPropertyBool("Cavalry Share By Template", HintText = "an AI lord's party grows its horse to the share of riders in the army its realm fields by the books - all riders among the Dothraki, almost none on the Iron Islands, about one in five in most realms - and upgrades men on foot once it has enough; a man bound for the saddle waits for his horse and the lord buys it. Works only with Ai Sells Spare Horses on; your own parties are not touched (off = the game picks the upgrade path, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool CavalryShareByTemplate { get; set; } = true;

        [SettingPropertyBool("Knight Horse From House", HintText = "a knight's horse is bought by his house - from the herds of its villages by the place where he stops first, then at the market - and goes into his own armoury; the house pays from its arms budget, and lords with men waiting for a horse no longer wait days between purchases while the game does not sell their horses. Works only with Ai Sells Spare Horses on (off = knights' horses are bought like any other)", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public bool KnightHorseFromHouse { get; set; } = true;

        [SettingPropertyFloatingInteger("Knight Horse Market Share", 0.00f, 1.00f, "0.00", HintText = "the share of the horses on a town's shelf a house may buy for its knights in one visit (other horses: Ai Mount Market Share Percent); the last few always stay on the shelf", RequireRestart = false)]
        [SettingPropertyGroup("Crafts, raw materials and horses (stage 6)")]
        public float KnightHorseMarketShare { get; set; } = 0.5f;

        [SettingPropertyBool("Stage7 Measure Log", HintText = "counts wars and peaces with their cause, army members riding to the muster at night and tournaments by week of the season - written to the log only, changes nothing in the game", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool Stage7MeasureLog { get; set; } = true;

        [SettingPropertyBool("Sleepers Hold Orders", HintText = "a party asleep in camp takes no marching orders until dawn - the last order it was given waits and is carried out at first light; its own thinking sleeps till dawn too (a lord sleeping off a sleep debt: until he wakes). Off = sleepers are only put back to bed after someone has moved them, as before", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool SleepersHoldOrders { get; set; } = true;

        [SettingPropertyBool("Terrain Ease Exact", HintText = "a culture or a scout that halves the game's forest or desert penalty halves ours too - the penalty shrinks, it never turns into a bonus (off = the whole game penalty is given back, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool TerrainEaseExact { get; set; } = true;

        [SettingPropertyBool("Tournaments All Season", HintText = "towns hold tournaments in every week of the season, each town every third week - as often per day as in the short calendar (off = only in the first three weeks of each season, as in the game)", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool TournamentsAllSeason { get; set; } = true;

        [SettingPropertyBool("Diplomacy Year Long", HintText = "alliances last a year and calls to war half a year, and after a peace the lords wait about 87 days before proposing a new war on that realm - 364, 182 and 87 days of the long calendar instead of the game's 84, 42 and 20 (off = the game's days)", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool DiplomacyYearLong { get; set; } = true;

        [SettingPropertyBool("Raid By Settlement Enabled", HintText = "villages are raided settlement by settlement: each takes days, and the loot comes only from what the village really has", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool RaidBySettlementEnabled { get; set; } = true;

        [SettingPropertyInteger("Raid Detachment Men", 20, 2000, "0", HintText = "raiders split into bands of this many men, each band burning its own settlement at the same time - a lord with 112 men burns one settlement in about four and a half days, an army of 2000 burns ten together", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public int RaidDetachmentMen { get; set; } = 200;

        [SettingPropertyInteger("Raid Alert Max Days", 1, 60, "0", HintText = "after a raid has burned its settlements the village stays looted and does not start to mend for 1 day plus 1 for each hundredth of its district's people struck, at most this many days", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public int RaidAlertMaxDays { get; set; } = 17;

        [SettingPropertyBool("Raid Player Step Popup", HintText = "your raid stops after each settlement and asks: raid the next one (about N days) or end the raid (off = your raid burns one settlement and ends, as the lords' raids do)", RequireRestart = false)]
        [SettingPropertyGroup("Roads, camps and villages (stage 7)")]
        public bool RaidPlayerStepPopup { get; set; } = true;

        [SettingPropertyBool("Twins Crossing Count", HintText = "counts the parties crossing the bridge at the Twins each day and what a toll would have brought - log only, nobody pays anything", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool TwinsCrossingCount { get; set; } = true;

        [SettingPropertyBool("Twins Toll", HintText = "the lord of the Twins takes a toll at his bridge: 2 denars a man (prisoners too) and 1 a beast, never more than one day of that party's wages - what the long way round would cost it; merchants, village carts, lords of other realms and you pay it into his purse, while lords of his own realm, his own caravans and carts and outlaws cross free, and no toll is asked of those at war with him. Needs Twins Crossing Count (off = nobody pays, the toll is only counted)", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool TwinsToll { get; set; } = true;

        [SettingPropertyInteger("Village Raid Messages", 0, 2, "0", HintText = "who hears that a village is burning, has been burned or plundered: 0 nobody, 1 your own fiefs (and your own raids), 2 your whole kingdom", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public int VillageRaidMessages { get; set; } = 1;

        [SettingPropertyBool("Village War Memory", HintText = "a village remembers who burned or plundered it, when, and how many fled and died", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageWarMemory { get; set; } = true;

        [SettingPropertyBool("Village Tip Lore", HintText = "the village tooltip shows the lord's banner, the knight who keeps the village and its faith from Banner Kings; hold Alt for its trade, history and war memory", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageTipLore { get; set; } = true;

        [SettingPropertyBool("District Menu Enabled", HintText = "'Look over the district' in a village menu lists the villages of its district with the banners of their keepers", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool DistrictMenuEnabled { get; set; } = true;

        [SettingPropertyBool("Village Pennants", HintText = "the lord's pennant flies over villages close to the camera", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillagePennants { get; set; } = true;

        [SettingPropertyBool("Burned Village Look", HintText = "a village shrinks as its settlements empty, and a burned one stands dark", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool BurnedVillageLook { get; set; } = true;

        [SettingPropertyBool("Burned Village Labels", HintText = "'X has been burned' over burned villages, close up only", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool BurnedVillageLabels { get; set; } = true;

        [SettingPropertyBool("Village Banner Per Holder", HintText = "every map village flies the banner of the house that keeps it - a knight with a Banner Kings estate there, the knight who holds the village's Banner Kings title, the village's own knight, or another house of the lord's realm - and its tooltip and 'Look over the district' name him and the lord he is sworn to. Off = every village of a district shows its lord's banner, as before", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageBannerPerHolder { get; set; } = true;

        [SettingPropertyBool("Village Canon Houses", HintText = "the villages are kept by the houses of A Song of Ice and Fire from their own land - a house seated nearby, a house sworn to the lord, or another house of that land - each under its own arms, and 'Look over the district' tells their arms and words. Off = the village knights of the local lore, as before", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageCanonHouses { get; set; } = true;

        [SettingPropertyBool("Village Two Pennants", HintText = "a village kept for its lord by another house flies two pennants: the keeper's and, beside it, the lord's. Off = one pennant, the keeper's", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageTwoPennants { get; set; } = true;

        [SettingPropertyBool("Village Pennant Small Texture", HintText = "village pennants use small banner textures and free the textures of pennants far from the camera, so every village keeps its own house's banner however long you travel the map without a battle. Off = large textures kept until the next battle, and after long travel some villages show their lord's banner instead, as before", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillagePennantSmallTexture { get; set; } = true;

        [SettingPropertyBool("Village Layout V5", HintText = "a fifth fewer map villages, none crowded against its neighbour, and each of its own size - from about 1,500 souls in a farm by the fields to 9,000 at a crossroads; the people of a district stay the same. It takes effect when a campaign is loaded. Off = the earlier layout, 2,446 villages of about 4,000 souls each. Used only when Village Layout V6 is off", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageLayoutV5 { get; set; } = true;

        [SettingPropertyBool("Village Layout V6", HintText = "some villages of the most crowded clusters move out to the empty land of their own district as small hamlets - shepherds and goatherds in the hills and on the steppe, woodcutters and charcoal burners in the forest, trappers, fishers on a lonely shore. The people of every district stay the same. It takes effect when a campaign is loaded. Off = the layout before the hamlets. Used only when Village Layout V7 is off", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageLayoutV6 { get; set; } = true;

        [SettingPropertyBool("Village Layout V7", HintText = "map villages spread over the whole land of their district - by rivers, lakes and the sea, among their fields, at the edge of the woods and in the hills - instead of crowding along the roads, aiming at twice the old spacing. A village stays on the land of its own district or just past its border, never deep in a neighbour's land or on the land of another culture; where a crowded region has no room for twice the spacing, its villages stand as evenly as the land allows. The villages and the people of every district stay the same. It takes effect when a campaign is loaded; with Start Calibration armed or applied, switching it restarts the calibration plan. Off = the layout with hamlets", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageLayoutV7 { get; set; } = true;

        [SettingPropertyBool("Village Hamlet Ks Land", HintText = "with Start Calibration, the people of a hamlet - and of every village the newest layout moved - work the land where it stands - the sheep of the hills, the timber of the forest, the fish of the shore - by the same yields as everywhere else. Changing it after Start Calibration is applied drops the applied calibration and starts the plan again. Off = they count as working the fields of the village they came from", RequireRestart = false)]
        [SettingPropertyGroup("The map and its crossings (stage 7)")]
        public bool VillageHamletKsLand { get; set; } = true;

        [SettingPropertyBool("Map Roads Probe Enabled", HintText = "TEST ONLY: unpaved roads drawn as path decals in two small map areas (around Fairmarket and Winterfell), read from the file arm_map_roads_probe.tsv in the module's ModuleData folder. Visual only - roads do not change speed or routes. Off = nothing drawn", RequireRestart = false)]
        [SettingPropertyGroup("Map roads (test)")]
        public bool MapRoadsProbeEnabled { get; set; } = false;

        [SettingPropertyBool("Map Side Roads", HintText = "dirt lanes on the campaign map lead from the main painted roads to the villages that lie farther away - a village close to a main road gets no lane of its own, villages behind it join its lane, and the lanes wind along the land around water, mountains and towns. With Map Side Roads All Villages on, every village gets a lane - see that option. Lanes do not change routes; with Map Side Road Speed Bonus on, a party travelling on a lane goes a little faster - yours and the AI's alike. Turned on, the lanes appear on the map within a few seconds; turned off, they are taken away. Off = no lanes are drawn and nobody gets the lane speed bonus", RequireRestart = false)]
        [SettingPropertyGroup("Side roads to far villages")]
        public bool MapSideRoads { get; set; } = false;

        [SettingPropertyBool("Map Side Roads All Villages", HintText = "with Map Side Roads on, every village of the map gets a lane of its own, however deep in a forest or a plain it lies: lanes lead from the main roads, the towns, the castles and the game's own villages, a village behind another joins its lane, and a village close to a main road gets a short lane that leaves the road at a gentle angle - only a village standing right on the road paint has none. Changed on the map, the lanes are drawn anew within a few seconds. Off = lanes lead only to the villages that lie farther from a main road, as before", RequireRestart = false)]
        [SettingPropertyGroup("Side roads to far villages")]
        public bool MapSideRoadsAllVillages { get; set; } = true;

        [SettingPropertyBool("Map Side Roads Chunks", HintText = "with Map Side Roads on, only the lanes around the part of the map the camera is looking at are laid on the map: the map is split into squares, the lanes of a square are laid down as it comes into view and taken away when the camera leaves it behind - the same lanes where you look, far less for the game to draw every frame. Off = every lane of the whole map stays laid down all the time and is only hidden when the camera rises high, as before", RequireRestart = false)]
        [SettingPropertyGroup("Side roads to far villages")]
        public bool MapSideRoadsChunks { get; set; } = true;

        [SettingPropertyInteger("Map Side Roads Chunk Radius Cap", 40, 400, "0", HintText = "with Map Side Roads Chunks on, the farthest distance from the camera, in map units, at which lanes are laid down when the camera is tilted lower than usual. At the game's usual camera angles the whole screen is always covered whatever the value - the limit never comes closer than the farthest corner of the screen; it only cuts the lanes far towards the horizon when the camera is tilted low. Higher = lanes reach farther towards the horizon, more to draw (40 to 400)", RequireRestart = false)]
        [SettingPropertyGroup("Side roads to far villages")]
        public int MapSideRoadsChunkRadiusCap { get; set; } = 160;

        [SettingPropertyBool("Perf Valyrian Census", HintText = "the daily count of Valyrian steel skips heroes and baggage that hold no Valyrian blade before building the description of where a blade lies - the same count and the same blades, found much faster; off = every hero, party and market is described first, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfValyrianCensus { get; set; } = true;

        [SettingPropertyBool("Perf Town Tax Skip Bk", HintText = "with town rents replacing the town tax (Population Rent Enabled and Rent Replaces Town Tax), the Banner Kings tax sum of a town is no longer worked out only to be replaced by the rent - the same tax, the same council wages, less work each time a clan's income is counted; it stands aside on its own (and says why in the log) when another mod changes that tax; off = Banner Kings works it out first, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfTownTaxSkipBk { get; set; } = true;

        [SettingPropertyBool("Perf Sutler Wage Once", HintText = "the sutlers in the field read a band's daily wage once instead of two or three times - the same coin, less work; off = the wage is worked out at each step, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfSutlerWageOnce { get; set; } = true;

        [SettingPropertyBool("Perf Town Tax Fast Hooks", HintText = "the town tax with rents (the lines somebody really pays, the council wages) asks Banner Kings directly instead of through slow reflection - the same numbers, less work each time a town's tax is counted; off = through reflection, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfTownTaxFastHooks { get; set; } = true;

        [SettingPropertyBool("Perf Sutler Wage Exact", HintText = "with Perf Sutler Wage Once, the wage is kept only for bands whose wage comes out the same every time it is worked out: a band carrying companions or kin besides its leader (Banner Kings rounds their pay up or down by a dice roll each time) or one whose wage rolled any dice is worked out at every step, as without the shortcut - the same coin and the same dice as before the shortcut; off = every band's wage is kept after the first count, even when it rolled dice", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfSutlerWageExact { get; set; } = true;

        [SettingPropertyBool("Perf Probe Each Place", HintText = "the spot checks of the faster town tax (Perf Town Tax Fast Hooks: every 64th time the old slow way is worked out beside it and compared) are counted for each of its places on its own - the lines somebody really pays, the notables' lines, the owners' lines and the council wages; before, one shared count always landed on the council wages and the other three were never checked. Checks only - the tax is the same; off = one shared count, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool PerfProbeEachPlace { get; set; } = true;

        [SettingPropertyBool("Day Tick Smooth", HintText = "less work in the one frame where the day ends, the same game: the mod's log file is written by a background thread (the game thread only queues the line; errors are written at once), and the daily arms and horse books count the world's stocks in one pass instead of two - the same numbers. Adds one diagnostic line a day with the split. Off = the log is written on the game thread and the books count twice, as before", RequireRestart = false)]
        [SettingPropertyGroup("Speed of the day (night 17/18.10)")]
        public bool DayTickSmooth { get; set; } = true;

        [SettingPropertyBool("State Hygiene Enabled", HintText = "starting or loading a campaign clears what the mod still remembered from the previous one in the same game run (hideout search, camp, AI stable purchases, crossing guard), and a single hiccup no longer switches the long seasons or a waiting hideout search off for the whole session. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("A clean slate between campaigns (stage 8)")]
        public bool StateHygieneEnabled { get; set; } = true;

        [SettingPropertyBool("Mid Day Load Keeps Day", HintText = "a save loaded in the middle of a day keeps what that day already paid for: the building work lords and townsfolk paid for this morning still goes up in the towns and castles that have not yet built today, and the crown still leaves out of tomorrow's wage refund the wages it already helped to pay (war aid, scutage, war levy). Off = as before: after loading, the rest of the day builds nothing that was paid for, and the next refund counts that aid a second time", RequireRestart = false)]
        [SettingPropertyGroup("A clean slate between campaigns (stage 8)")]
        public bool MidDayLoadKeepsDay { get; set; } = true;

        [SettingPropertyBool("Stage8 Measure Log", HintText = "Writes daily lines that measure the AI's gear for stage 8: wear and repairs of garrisons and lords' parties and why repairs wait, arrows the AI would have used up, the prices the AI pays against the worth of the piece, loot copied to victors while the beaten keep it, and the crown's workshop monopolies (diagnostics only; nothing in the game changes).", RequireRestart = false)]
        [SettingPropertyGroup("Diagnostics (stage 8)")]
        public bool Stage8MeasureLog { get; set; } = true;

        [SettingPropertyBool("Stage8 Profile Log", HintText = "Writes one daily line with the time each part of the mod takes (diagnostics only).", RequireRestart = false)]
        [SettingPropertyGroup("Diagnostics (stage 8)")]
        public bool Stage8ProfileLog { get; set; } = true;

        [SettingPropertyBool("Stage8 World Log", HintText = "Writes daily lines that measure the world for stage 8: the village production model, caravan stays in towns, mercenary clans, sheep villages, villages without a cart (diagnostics only).", RequireRestart = false)]
        [SettingPropertyGroup("Diagnostics (stage 8)")]
        public bool Stage8WorldLog { get; set; } = true;

        [SettingPropertyBool("A17 Bk Party No Free Mounts", HintText = "Banner Kings parties (slave and food caravans, patrols, militia, estate retinues, free companies, travellers) no longer get spare horses and pack animals out of thin air when they set out, and the horses they do have go to the market of the settlement where they end their journey instead of vanishing with them. Off = as in Banner Kings", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17BkPartyNoFreeMounts { get; set; } = true;

        [SettingPropertyBool("A17 Fish From Hands", HintText = "where the start calibration is in force, fish come only from the hands of fishing villages and fishing boats: the Night Raider governor perk no longer conjures fish into the town's villages and Banner Kings harbours no longer pull fish out of nowhere for coin that vanishes; a crew fishing at sea is booked as a catch. Off = as in the naval DLC and Banner Kings", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17FishFromHands { get; set; } = true;

        [SettingPropertyBool("A17 Uniques Not Outlaw Kit", HintText = "outlaw bands no longer buy a renowned piece (Renly's armour, Lyanna's armour, a famous steed) from their fence, or take it from their own loot, to kit out a man they promote - the piece stayed lost inside the bandit for good; it now stays on the market or in the band's packs as loot. Off = bands may use renowned pieces, as before", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17UniquesNotOutlawKit { get; set; } = true;

        [SettingPropertyBool("A17 Siege Commit Rescue", HintText = "when the game stumbles while settling the outcome of a battle (seen when a besieging host is beaten in a sally or under the walls), the victors still get their experience, renown, influence, morale and gold, and the stumble is written to the log; the wounded the game failed to take are captured as before. Off = the outcome stays half-settled, as before", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17SiegeCommitRescue { get; set; } = true;

        [SettingPropertyBool("A17 Shipyard Builds From Timber", HintText = "a port's shipyard builds a new ship only while the port keeps fewer than it wants (two below its limit), only from timber on the town's market and only if the town's purse can pay the shipwrights from what it holds above the merchants' reserve - the wages go to the townsfolk; without timber or coin no ship is built. Off = shipyards make ships out of nothing up to their limit, as before", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17ShipyardBuildsFromTimber { get; set; } = true;

        [SettingPropertyFloatingInteger("Shipyard Timber Per1000", 0.00f, 10.00f, "0.0", HintText = "logs of timber a shipyard uses for every 1,000 of a hull's worth (a plank counts as a fifth of a log) - a light boat worth 8,000 takes 8 logs, a heavy war galley worth 80,000 takes 80", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public float ShipyardTimberPer1000 { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Shipyard Labour Share", 0.00f, 1.00f, "0.00", HintText = "share of a hull's worth the town pays its shipwrights for building it (paid from the town's purse above the merchants' reserve to the townsfolk)", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public float ShipyardLabourShare { get; set; } = 0.1f;

        [SettingPropertyBool("A17 Port Fish Pays Folk", HintText = "outside the start calibration, the coin a Banner Kings harbour town pays for its daily catch goes to the townsfolk as the fishermen's wages instead of vanishing (works together with the fish setting above); off = the coin vanishes, as in Banner Kings", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17PortFishPaysFolk { get; set; } = true;

        [SettingPropertyBool("A17 Author Lines", HintText = "with the horse and fish diagnostics: also write which game or mod behaviour adds or removes horses and fish outside the known flows (read from the call stack, at most 2,000 times a day) - written to the log only, changes nothing in the game; off = not traced", RequireRestart = false)]
        [SettingPropertyGroup("Old loose ends (A17)")]
        public bool A17AuthorLines { get; set; } = true;

        [SettingPropertyBool("Rbl Peace Needs Quiet", HintText = "Realistic Bannerlord's 'Extended Peace' prosperity bonus goes only to a town or castle that has seen no attack on itself or on any of its villages for 30 days (as Realistic Bannerlord means it); off = as before, when it reached almost every town and castle all through a war, because the game forgets the last attacker a day after the attack", RequireRestart = false)]
        [SettingPropertyGroup("Signals from the long runs (A16)")]
        public bool RblPeaceNeedsQuiet { get; set; } = true;

        [SettingPropertyBool("Bk Prosperity Layer Once", HintText = "Banner Kings' prosperity layer (its population, stability and food deltas and its prosperity growth multiplier) counts once instead of twice when Realistic Bannerlord's prosperity model is in play (off = as before: twice, which slows prosperity growth more than Banner Kings means) (takes effect after loading a save)", RequireRestart = false)]
        [SettingPropertyGroup("Signals from the long runs (A16)")]
        public bool BkProsperityLayerOnce { get; set; } = false;

        [SettingPropertyBool("Bk Returns To Origin Village", HintText = "A soldier of known origin who comes home - fled from a lost battle, freed, or dismissed for want of pay - goes back to the same village (or town) in Banner Kings' population that he returns to in the mod's own count of people; off = as before: in Banner Kings he joined the nearest settlement of his realm and culture to the battle, a castle or town among them, or a village of his lord's house", RequireRestart = false)]
        [SettingPropertyGroup("Signals from the long runs (A16)")]
        public bool BkReturnsToOriginVillage { get; set; } = true;

        [SettingPropertyBool("A16 Signals Log", HintText = "Writes daily lines that measure what drives town and castle prosperity, the births, deaths and coming of age of lords, and every change of Banner Kings' population by kind of settlement (diagnostics only)", RequireRestart = false)]
        [SettingPropertyGroup("Signals from the long runs (A16)")]
        public bool A16SignalsLog { get; set; } = true;

        [SettingPropertyBool("Valve Raise While Short", HintText = "a raw material that more than Valve Short Towns towns have none of may be raised by the village regulator above Village Output Step - step by step every four weeks, up to Valve Short Ceiling - as long as the world uses up all that is made and the stock stays low: the same villages put more of their work into it (flax for the weavers stood at the ordinary ceiling all year while nine towns in ten had no linen). Off = the ordinary ceiling holds, and a good already above it returns to it at the next decision", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool ValveRaiseWhileShort { get; set; } = false;

        [SettingPropertyFloatingInteger("Valve Short Ceiling", 1.00f, 8.00f, "0.00", HintText = "the most a village can make of a raw material the towns are short of, as a multiple of its normal output (needs Valve Raise While Short)", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public float ValveShortCeiling { get; set; } = 4f;

        [SettingPropertyBool("Valve Step Follows Use", HintText = "a village good raised above its normal output is brought back to what the world really uses once a full eight-week window shows it is made faster than it is used - without waiting for two months of stock to pile up - and close to the lower stock limit it is raised by small steps instead of a third at once (timber piled up all year after one such step). Never below normal output: the woodcutters go back to the village's other work. Off = a raised good stays raised until the stock exceeds Valve Stock Days High, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool ValveStepFollowsUse { get; set; } = true;

        [SettingPropertyBool("Animals Under Valve", HintText = "the village regulator (Harvest Valve) also looks after the hogs, cattle and sheep raised for slaughter: when the world slaughters every animal the villages raise and the herds on the market hold less than Valve Stock Days Low days of use, the villages raise more of them, up to Village Output Step - more meat for the towns and more hides for the tanners; a step that proves too large is taken back as for any other good. Horses, mules and camels are not touched (see Horse Breeding By Demand). Works only with Harvest Valve on. Off = villages raise the animals the game says, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool AnimalsUnderValve { get; set; } = true;

        [SettingPropertyBool("Slaughter Keeps Hides", HintText = "the town craftsmen who slaughter a sheep or a pig for meat alone keep its hide as well, as the other butchers do: one raw hide from every animal, sold on the town's stall like the meat (about a fifth of all livestock was slaughtered with the hide thrown away while the tanners stood idle). Takes effect at the next load. Off = the game's recipes, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool SlaughterKeepsHides { get; set; } = true;

        [SettingPropertyFloatingInteger("Workshop Hands Step", 1.00f, 3.00f, "0.00", HintText = "further step of arms craftsmen on top of Workshop Hands Per 1000 People, now that ore and timber are plentiful: every town has this many times the armourers, weaponsmiths, bowyers and saddlers (and with them its weavers, tanners and fletchers) - still below medieval Europe. Needs Workshop Hands By People. 1 = off, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public float WorkshopHandsStep { get; set; } = 1.3f;

        [SettingPropertyBool("Civil Works Away From Front", HintText = "in a kingdom at war, civil buildings are built again in towns and castles the war does not reach: no siege, no enemy lord's party, no battle between lords and no raid within Civil Works Front Range, and none of its own villages raided or burned, for Civil Works Calm Days. Near the front only walls, barracks and other military works go on, as before, and a house with a military work in hand finishes it first. The lord pays from his building allowance as always. Off = no civil building anywhere in a kingdom at war, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool CivilWorksAwayFromFront { get; set; } = true;

        [SettingPropertyInteger("Civil Works Calm Days", 1, 60, "0", HintText = "days without any sign of war near a town or castle before civil building may go on there (needs Civil Works Away From Front)", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public int CivilWorksCalmDays { get; set; } = 14;

        [SettingPropertyFloatingInteger("Civil Works Front Range", 10.00f, 300.00f, "0", HintText = "how near (map distance) a siege, an enemy lord's party, a battle between lords or a raid must be to stop civil building in a town or castle - about a day's ride, the town's own villages and its nearest neighbours", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public float CivilWorksFrontRange { get; set; } = 60f;

        [SettingPropertyBool("Civil Works Need Wage Room", HintText = "with Civil Works Away From Front: a lord pays for civil works in wartime only while his troops' wages stay under 95% of what his house can afford - a house that cannot pay more soldiers keeps its gold for them (your own works are yours to decide). Off = every lord away from the front builds", RequireRestart = false)]
        [SettingPropertyGroup("Goods after the yearly run (N5)")]
        public bool CivilWorksNeedWageRoom { get; set; } = true;

        [SettingPropertyBool("Sack Measure Log", HintText = "Writes a log line each time a siege ends in mercy, pillage or devastation: what lay in the town (the merchants' coin and their reserve, the townsfolk's purses, goods and horses on the shelves), what the sack would take under each choice, how many men won it, whether their army was short of pay, and for thirty days after: the town's coin, its people's bread, the pay and camp followers' coin it received and the prisoners it bought. Log only - nothing in the game changes", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackMeasureLog { get; set; } = true;

        [SettingPropertyFloatingInteger("Sack Share Pillage", 0.000f, 1.000f, "0.000", HintText = "the part of all coin in a stormed town or castle that the victors take when they pillage it - from the merchants' coin and from the townsfolk's purses alike, their reserves included (a third; mercy takes nothing)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float SackSharePillage { get; set; } = 0.333f;

        [SettingPropertyFloatingInteger("Sack Share Devastate", 0.000f, 1.000f, "0.000", HintText = "the part of all coin in a stormed town or castle that the victors take when they devastate it (two thirds)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float SackShareDevastate { get; set; } = 0.667f;

        [SettingPropertyBool("No Sack Without Capture", HintText = "a battle won by the besiegers outside the walls, after which the town or castle does not fall, brings no sack: the game no longer burns its prosperity, buildings and loyalty, nobody is paid plunder and Banner Kings kills nobody there - only a stormed town is sacked (off = the game's rule: such a battle sacks the place it did not take)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool NoSackWithoutCapture { get; set; } = true;

        [SettingPropertyBool("Beaten Garrison Purse To Victor", HintText = "a garrison broken in battle - outside the walls, in a sally or on the walls - leaves its pay chest to the victor, as any beaten party without a lord does: to the victorious lord (a vassal at war owes his crown a ninth of it), or to a victorious party without a lord; when no victor can carry it (the Others, a militia) the chest stays in the garrison's own town (off = the chest vanished with the garrison)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool BeatenGarrisonPurseToVictor { get; set; } = true;

        [SettingPropertyBool("Sack Takes Real Coin", HintText = "the sack takes what really lies in a stormed town or castle: under pillage a third, under devastation two thirds of every coin there - the merchants' coin and the townsfolk's purses alike, their reserves included (Sack Share Pillage / Devastate); mercy takes nothing. The plunder is shared among the victorious parties by their men; in each party the soldiers put two thirds in their purses and the captain takes one third, of which a crown at war claims a third the next morning. The game's sum of 15 coins per point of burnt prosperity is gone, and so is all gold from nowhere (off = the game's sum, paid by the town from what it holds above its reserve)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackTakesRealCoin { get; set; } = true;

        [SettingPropertyBool("Sack Scar Only When Sacked", HintText = "with Sack Scar Enabled: the scar of the sack (Sack Prosperity Cut Percent of the prosperity left and Sack Loyalty Hit loyalty) falls only on a town that is pillaged or devastated, at the moment of that choice - mercy is mercy, the town keeps only the game's own loss (off = the scar falls on every town taken by siege, also when spared, when its lord changes)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackScarOnlyWhenSacked { get; set; } = true;

        [SettingPropertyBool("Sack Scar Enabled", HintText = "a settlement taken by siege loses prosperity and loyalty - conquest is a ruin you must rebuild", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackScarEnabled { get; set; } = true;

        [SettingPropertyInteger("Sack Prosperity Cut Percent", 0, 60, "0", HintText = "prosperity lost when a settlement falls to siege", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public int SackProsperityCutPercent { get; set; } = 15;

        [SettingPropertyInteger("Sack Loyalty Hit", 0, 60, "0", HintText = "loyalty lost when a settlement falls to siege", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public int SackLoyaltyHit { get; set; } = 15;

        [SettingPropertyBool("Sack Window Real Coin", HintText = "with Sack Takes Real Coin: when you take a town or castle, the hints of Devastate, Pillage and Show Mercy show the real coin - what the merchants and the townsfolk hold, what the army takes, your party's part (your men's, yours and the crown's) and what is left - and after your choice the summary says what was taken; 'Prosperity Lost' counts from this town; for thirty days 'People of this land' says how much a sacked town lost (off = the game's lines)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackWindowRealCoin { get; set; } = true;

        [SettingPropertyBool("Ai Sacks From Need", HintText = "how a lord who storms a town chooses its fate: a town of his own realm's culture is spared as before; a town with less to take than one day's pay of his army is spared too (nobody burns a place for nothing); a lord whose army has wages owed that his house cannot meet, or whose house's purse holds less than two weeks' pay for all its parties, pillages it - a cruel one devastates it when he can; any other lord chooses by his nature, as before (off = the game's choice by the lord's nature only)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool AiSacksFromNeed { get; set; } = true;

        [SettingPropertyBool("Sack No Spending", HintText = "after a pillage or devastation the soldiers of the conquering realm take what they want in the sacked town and pay for nothing for Sack No Spending Days: their pay stays in their purses and is spent later in other towns - neither their days in town nor their camp followers leave coin there, nor do they buy clothing from its shelves. Mercy - they pay as in any town (off = they pay there as anywhere, so a sacked town grew richer the day after)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackNoSpending { get; set; } = true;

        [SettingPropertyInteger("Sack No Spending Days", 0, 30, "0", HintText = "with Sack No Spending: the days the victors spend nothing in the town they sacked (also the window the sack log measures)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public int SackNoSpendingDays { get; set; } = 3;

        [SettingPropertyBool("Sack Killed In People Book", HintText = "the townsfolk Banner Kings kills when a town is pillaged or devastated are gone from the town's own count of people as well (the same share), so they no longer eat, earn and pay as if alive (off = only Banner Kings' population loses them)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackKilledInPeopleBook { get; set; } = true;

        [SettingPropertyBool("Sack Burns Buildings", HintText = "fire in a sacked town or castle: under pillage a third, under devastation two thirds of its building levels burn (the same share as the coin), mercy burns nothing; the walls stand - stone does not burn and the conqueror means to hold them. A burnt level leaves its foundations and stone: rebuilding it costs only Sack Ruin Rebuild Share of the work, and a lord's town puts its ruins first in the building queue (in war its civil ruins only away from the front, as for any civil work). Off = the game's random razing, which grows with the army. Turned off during a campaign, what has burnt stays burnt and its ruins give no more help - rebuilding costs the full price and lords no longer put them first - until it is turned on again.", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackBurnsBuildings { get; set; } = true;

        [SettingPropertyFloatingInteger("Sack Ruin Rebuild Share", 0.000f, 1.000f, "0.000", HintText = "with Sack Burns Buildings: the part of a level's cost that rebuilding it from the ruins costs (a quarter - in peace a devastated town of today's typical size stands again in about three years, two with its townsfolk building, a pillaged one in half that; in war its civil works wait away from the front; a town sacked every half year never recovers)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float SackRuinRebuildShare { get; set; } = 0.25f;

        [SettingPropertyBool("Sack Takes Goods", HintText = "the sack empties the shelves too: the same part as the coin (a third under pillage, two thirds under devastation, nothing under mercy) of every stack of goods, horses and arms in the market of a stormed town or castle. Unique pieces go to the army's leader, horses and beasts walk off with the parties (as many as their men can herd), food only up to ten days of rations for each party, the rest as far as the wagons can carry - most valuable by weight first; what they cannot carry stays under pillage and burns under devastation (food never burns). Lords put the arms they took in their armouries (off = the shelves are left untouched)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SackTakesGoods { get; set; } = true;

        [SettingPropertyBool("Capital Treasury Seized", HintText = "when an enemy storms the capital of a realm (the seat of its court in Banner Kings; without Banner Kings its first seat), the conquerors carry off part of the royal treasury kept there - Capital Treasury Share of what it holds above its war reserve and its debt to the Iron Bank - into the treasury of their own realm (a conqueror without a realm takes it into his own purse); a capital lost by peace, gift or revolt gives nothing; off = the treasury stays untouched", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool CapitalTreasurySeized { get; set; } = true;

        [SettingPropertyFloatingInteger("Capital Treasury Share", 0.000f, 1.000f, "0.000", HintText = "with Capital Treasury Seized: the part of a fallen capital's royal treasury - above the realm's war reserve and its Iron Bank debt - that the conquerors carry off (a third)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float CapitalTreasuryShare { get; set; } = 0.333f;

        [SettingPropertyBool("Fallen Crown Treasury", HintText = "when a realm falls and is no more, its royal treasury does not vanish with it: first the crown's debt to the Iron Bank is paid out of it, then what is left goes to whoever brought the realm down - the realm that stormed its last stronghold, or the realm it had just made peace with when it was ended at the peace table (to that realm's treasury; a conqueror with no realm - to the head of his house); when the realm ended some other way (its ruler's death, a rebellion that came to nothing) it goes to the head of the house that ruled it, which carries the treasury away into exile. If no one is left to take it, it goes to the Iron Bank. Off = as before: the treasury of a fallen realm is lost and its debt to the Bank written off", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool FallenCrownTreasury { get; set; } = true;

        [SettingPropertyBool("Enemy Caravans Seized", HintText = "caravans of the conqueror's enemies that stand inside a town or castle when it is stormed are seized instead of riding away: their coin goes to the victorious commander (the crown takes its ninth from a vassal, as with any beaten caravan), their goods, horses and pack animals into his baggage, their master into captivity, and their guards go home; caravans with ships in harbour still sail away; off = they leave with everything, as in the game", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool EnemyCaravansSeized { get; set; } = true;

        [SettingPropertyBool("Enemy Caravans Siege Trapped", HintText = "with Enemy Caravans Seized: an enemy caravan that left the besieged walls during the last day of the siege and has not reached another town, castle or village is taken as well, as if it were still inside; off (the default, since caravans now stay inside the walls until their siege ends - Siege Caravans Stay In Walls) = only caravans inside the walls at the moment of capture are taken", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool EnemyCaravansSiegeTrapped { get; set; } = false;

        [SettingPropertyBool("Siege Caravans Stay In Walls", HintText = "caravans shut inside a besieged town or castle stay there until that place's own siege ends; Banner Kings let every caravan held in any besieged place ride out whenever any siege anywhere ended, so caravans slipped out of places still under siege and enemy caravans were never inside when a town fell; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeCaravansStayInWalls { get; set; } = true;

        [SettingPropertyBool("Siege Ransom Measure Log", HintText = "Writes a log line each time a besieging lord decides to storm a town or castle: the coin lying in it, the ransom it could pay, his army's daily pay, the besiegers' strength against what the walls make of the defenders, whether his army is short of pay, and whether the town would pay and the lord would take it. Log only - nothing in the game changes", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeRansomMeasureLog { get; set; } = true;

        [SettingPropertyFloatingInteger("Siege Ransom Share", 0.000f, 1.000f, "0.000", HintText = "the ransom a besieged town or castle pays to see the besiegers gone: this part of every coin lying in it - the merchants' coin and the townsfolk's purses alike (a quarter; a sack takes a third or two thirds). No ransom when it would be less than one day's pay of the besieging army", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float SiegeRansomShare { get; set; } = 0.25f;

        [SettingPropertyFloatingInteger("Siege Ransom Bloody Ratio", 0.00f, 5.00f, "0.00", HintText = "a besieging lord takes a ransom instead of storming when the assault would be bloody: his strength is less than this many times what the walls make of the defenders (the game's own reckoning, without its dice; 0 = this reason never counts). He also takes it when his army is short of pay or an assault on these walls has already failed", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public float SiegeRansomBloodyRatio { get; set; } = 1.5f;

        [SettingPropertyBool("Siege Ransom Repel Needs Weak Edge", HintText = "after an assault on the walls has failed, a besieging lord takes a ransom only when his edge has melted below Siege Ladder Min Ratio (four to one); a host still that much stronger waits and storms again. Off = one failed assault is reason enough", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeRansomRepelNeedsWeakEdge { get; set; } = true;

        [SettingPropertyBool("Siege Ransom Ai", HintText = "a town or castle about to be stormed may buy the besiegers off: when the walls will not hold and a quarter of all its coin (Siege Ransom Share) is worth at least a day's pay of the besieging army, the town offers it, and a lord takes it when his army is short of pay, when an assault on these walls has already failed, or when the assault would be bloody (Siege Ransom Bloody Ratio). The ransom is shared like plunder - two thirds to the soldiers' purses, a third to the captains, of which the crown claims its third - and the besiegers leave and do not besiege that place again for Siege Ransom Truce Days. Never at a realm's capital, at the places of the great sieges of the story, by or against the Others. Off = every assault goes ahead as before", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeRansomAi { get; set; } = true;

        [SettingPropertyInteger("Siege Ransom Truce Days", 0, 364, "0", HintText = "with Siege Ransom Ai: the days a realm whose army took a ransom will not besiege that town or castle again (0-364)", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public int SiegeRansomTruceDays { get; set; } = 60;

        [SettingPropertyBool("Siege Ransom Player Defender", HintText = "when besiegers are about to storm a town or castle of yours, or one you are in, and would take a ransom, you are asked first: pay them a quarter of the town's coin (its merchants' and townsfolk's, not yours) to lift the siege for Siege Ransom Truce Days, or refuse and face the assault. If you cannot answer within a day (in battle, in a conversation, in captivity), the town decides as any other would and you get word of it. Off = your towns decide like the others and you only get word", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeRansomPlayerDefender { get; set; } = true;

        [SettingPropertyBool("Siege Ransom Player Besieger", HintText = "when you command a siege and your engines are ready, you may demand a ransom instead of storming: if the walls would not hold against you and a quarter of the town's coin is worth at least a day's pay of your army, its people offer it - your men put two thirds in their purses, you take a third (the crown claims its third of yours) - and you lift the siege and may not besiege that place again for Siege Ransom Truce Days. Never at a realm's capital or the places of the great sieges of the story. Off = no such option", RequireRestart = false)]
        [SettingPropertyGroup("The sack of towns and castles")]
        public bool SiegeRansomPlayerBesieger { get; set; } = true;

        [SettingPropertyBool("People Scale Dry Run", HintText = "Writes a daily line with how many people stand behind each village, each town's market and each castle's villages compared with the average of the world (the measure the coming rules - goods follow the people - will use), every seventh day a table by kingdom and the file skale-ludzi.csv (diagnostics only; nothing in the game changes)", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool PeopleScaleDryRun { get; set; } = true;

        [SettingPropertyBool("Watch Keeps Flat Output", HintText = "The Night's Watch stands outside the rules that tie goods to the number of people: the villages of the Gift keep today's output, and Castle Black and the Watch's castles keep a market of ordinary size, although only some twenty thousand people live there - the Watch lives on the men and gifts of all Westeros. Off = the Watch's lands are measured by their people like any other", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool WatchKeepsFlatOutput { get; set; } = true;

        [SettingPropertyBool("Village Output By People", HintText = "Each village on the map stands for all the villages of its district: its fields, herds, mines and woods yield by the number of people living there - a village of a crowded land brings forth several times what a village of an empty land does, while the world as a whole makes as much of every good as before (the hearth no longer sets the yield; winter, raids, war and the world's demand still do). The village tooltip shows 'People of this land' and the village's 'People of this land' window tells why it yields more or less. Off = village output follows the hearth thresholds, as before. Turned off during a campaign, villages yield by the hearth again (the regulator of village output starts measuring anew); turned back on, the measure taken at the start of the campaign is used again.", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool VillageOutputByPeople { get; set; } = true;

        [SettingPropertyBool("Sarnor People Raised", HintText = "Sarnor counts a quarter of a million people instead of a hundred thousand - as thickly settled as the Iron Islands - so its villages and towns are not left almost empty once goods follow the people. Takes effect in a new campaign only (a campaign already begun keeps the people it was reckoned with). Off = a hundred thousand, as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool SarnorPeopleRaised { get; set; } = true;

        [SettingPropertyBool("Market By People", HintText = "A town is the market of its whole district: the number of townsfolk who buy (and their purses' needs), what they eat and use each day, the working coin its merchants keep and the hands in the notables' workshops all follow the people of the town and of the villages that trade there, compared with the average market of the world (a castle's folk follow the people of its villages). The food stores of the keep count the townsfolk's purchases as before. Off = every town buys and keeps coin as today, by its prosperity", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool MarketByPeople { get; set; } = true;

        [SettingPropertyBool("Village Heads By People", HintText = "The fixed dues a village pays its lord and the salt, tools, cloth, pots and ale it buys in its market town follow the number of people of the village's district, and the folk below a castle follow the people of the castle's villages. Off = every village and castle counts its heads as today", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool VillageHeadsByPeople { get; set; } = true;

        [SettingPropertyBool("Start Gold By People", HintText = "New campaigns only: once the starting gifts are handed out, the coin of the town merchants, of the townsfolk's and the villagers' purses and of the royal treasuries is moved from place to place so that each lies where the people are (the world's sum stays the same; every crown keeps at least one million). A saved game already under way is never touched. Turning it off later changes nothing: the coin already moved stays where it went.", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool StartGoldByPeople { get; set; } = true;

        [SettingPropertyBool("Levy By People", HintText = "Volunteers come forward by the number of people: an empty place at a notable fills faster in a crowded land and slower in an empty one (from a tenth to three times, never above certain), and warrior peoples - the ironborn, the Free Folk and the Dothraki - send more of their men. Off by default: notables in crowded lands already have their places full, so the world got a third fewer volunteers. Off = every notable's empty places fill as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool LevyByPeople { get; set; } = false;

        [SettingPropertyBool("Militia By People", HintText = "The militia of a village, town or castle grows, and is capped, by the number of people of its land and by how many of them bear arms - more defenders in crowded lands and among the warrior peoples, fewer in empty ones; the world keeps as many militiamen as before. Off = every settlement raises its militia as before", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool MilitiaByPeople { get; set; } = true;

        [SettingPropertyBool("Goods Rates By Pattern", HintText = "Salt pans yield more than they did (three and a half times with Salt Rate Raised, twice without it), and sixteen villages of the crowded lands - cotton growers, silver miners and fishers of the Reach, Volantis, Qarth, King's Landing, Braavos and the Stormlands, where cotton and silver lie unsold and every market keeps another village that feeds it - grow flax instead (36 flax villages instead of 20), so the world has the linen its people and soldiers wear. The flax villages come with a new campaign begun with this option and stay for that whole campaign, since each village's yield is measured with them; a campaign already under way keeps its villages. Off = salt as before (and no flax villages in a new campaign). Turned off during a campaign, only the salt pans go back to their old yield; the flax villages stay.", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool GoodsRatesByPattern { get; set; } = true;

        [SettingPropertyBool("Flax Villages Without Climate Fix", HintText = "in a campaign begun with Goods Rates By Pattern, the flax villages stay flax villages even when Village Climate Fix is turned off: five of them (Berrybush, Lanthas, Sagora, Shirosi, Port Yhos) were cotton growers only because of that fix, and with it off they used to fall back to cattle, sheep and woodcutting for good - while the harvest of the world was still reckoned with them growing flax. Takes effect the next time a save is loaded. Off = as before (with Village Climate Fix off those five go back to the map's trade)", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool FlaxVillagesWithoutClimateFix { get; set; } = true;

        [SettingPropertyBool("Vine Olive By Climate", HintText = "Vineyards, olive groves and date palms of the south stand where their climate and the old tales put them: two olive groves of the Reach (Dunstonbury, inland in the north where frost kills the olive, and Redwyne Bay) become vineyards - the Reach is wine country, olives come chiefly from Dorne; the date palms high in the passes of the Red Mountains (Boneway, Vulture's Roost) become Dornish vineyards, and the palms of the Free Cities give way to the vineyards of Lys (Mussum) and Volantis (Krysaro), where they press their sweet wines, and to olive groves (Asmait in Lys, Waltas in Tyrosh). 29 vineyards instead of 23, as many olive groves as before (19), 8 palm orchards instead of 14. Like the flax villages, this comes with a new campaign begun with the option and stays for that whole campaign; a campaign already under way keeps its villages. Off = the villages of the map", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool VineOliveByClimate { get; set; } = true;

        [SettingPropertyBool("Folk Earn From Village Buys", HintText = "The townsfolk also earn when the merchants buy the villages' produce - unloading, measuring and storing it (a tenth of what the carts are paid, by Town Folk Labour Village Buys) - so a town whose district brings in more grain, wool and ore feeds more of its people's wages. Off = they earn only from what the merchants sell", RequireRestart = false)]
        [SettingPropertyGroup("Goods follow the people (GL)")]
        public bool FolkEarnFromVillageBuys { get; set; } = true;

        [SettingPropertyBool("Reaver Iron Price", HintText = "the iron price: when the Ironborn or the Free Folk raid a village (the AI lords and you as their vassal alike), they carry off at least Reaver Iron Price Share of the village's purse and of its storehouse for a full raid of a district (a raid broken off takes its part), not only the share of the people they struck - once per raid: further steps of your own raid take the share of the people struck, from what is left. A raid from the sea (a raiding party at sea) on a village of a port also takes, once per raid, Reaver Waterfront Share of what the labourers of that port hold above their reserve for hard times (Town Folk Reserve Days of their needs). Every coin comes from the village and the waterfront - nothing from nowhere. The Dothraki are not touched. Off = the raiders take only the share of the people they struck, as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool ReaverIronPrice { get; set; } = true;

        [SettingPropertyFloatingInteger("Reaver Iron Price Share", 0.00f, 1.00f, "0.00", HintText = "with Reaver Iron Price: the least share of a village's purse and storehouse that a full raid by the Ironborn or the Free Folk carries off (0.50 = half; taken once per raid - further steps of your own raid take only the share of the people struck)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float ReaverIronPriceShare { get; set; } = 0.50f;

        [SettingPropertyFloatingInteger("Reaver Waterfront Share", 0.00f, 1.00f, "0.00", HintText = "with Reaver Iron Price: the share of the port labourers' coin above their reserve that a raid from the sea on one of the port's villages takes, once per raid (0.10 = a tenth; the reserve itself is never touched)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float ReaverWaterfrontShare { get; set; } = 0.10f;

        [SettingPropertyBool("Reaver Loot To Crews", HintText = "the iron price pays the crews: the gold an Ironborn house takes as the iron price beyond the share of the people struck, from the waterfronts and as the corsairs' tithe raises, coin for coin, what the house may spend on the wages of its companies in the field - spread over 28 days - and goes neither to its garrisons nor to its court, equipment or buildings, so the crown's war aid for that house falls by as much. The Free Folk take no wages (Free Folk Unpaid) and sellswords are paid by contract, so for them the iron price counts as income of the house, as before. Your house as an Ironborn vassal is measured the same way for the crown's war aid. Needs Reaver Iron Price, Clan Budget Enabled, Clan Budget Stable D and Clan Income Book Stable D. Off = the iron price counts like any other loot in the house's income, as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool ReaverLootToCrews { get; set; } = true;

        [SettingPropertyBool("Reaver Raid By Profit", HintText = "the lords of the Iron Islands and the Free Folk weigh a raid by its gain: a village whose iron price would pay Reaver Raid Pay Days of the company's wages and food tempts them twice as much as before, a rich one up to three times, a poor one no more than before. They still raid only enemies at war and within reach, with the food the game asks for, so no new targets appear. Needs Reaver Iron Price. Off = they weigh raids as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool ReaverRaidByProfit { get; set; } = true;

        [SettingPropertyFloatingInteger("Reaver Raid Pay Days", 1.00f, 28.00f, "0", HintText = "with Reaver Raid By Profit: how many days of a company's wages and food the iron price of a village must pay to double the lords' wish to raid it (4 = about the days of a raid and the voyage there and back)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float ReaverRaidPayDays { get; set; } = 4f;

        [SettingPropertyBool("Reaver Raid By Profit Free Folk", HintText = "with Reaver Raid By Profit: the chiefs of the Free Folk weigh a raid by its gain as well, not only the Ironborn lords. Off = only the Ironborn lords do; the Free Folk weigh raids as before (the first step back if the Gift or the Night's Watch suffer too much)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool ReaverRaidByProfitFreeFolk { get; set; } = true;

        [SettingPropertyBool("Sea Raiders Iron Harbour", HintText = "the Sea Raiders find a harbour on the Iron Islands: a band of the Sea Raiders within 600 of an Ironborn port sells its loot to the fence there as to the town at its gates (the best terms; buying gear goes on as before, at the nearest towns) and spends its coin there, and gives the lord of that port Sea Raiders Harbour Tithe of what the fence pays it - in peace too, and the same for you if you hold the port. Off = the Sea Raiders deal with the nearest towns, as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool SeaRaidersIronHarbour { get; set; } = true;

        [SettingPropertyFloatingInteger("Sea Raiders Harbour Tithe", 0.00f, 1.00f, "0.00", HintText = "with Sea Raiders Iron Harbour: the share of what an Ironborn port's fence pays a band of the Sea Raiders that goes to the lord of the port (0.25 = a quarter; the band keeps the rest)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float SeaRaidersHarbourTithe { get; set; } = 0.25f;

        [SettingPropertyBool("Ironborn Half Wage In Plunder", HintText = "the crews of the Iron Islands take half their pay in plunder - the iron price: the companies in the field of the Ironborn lords, and yours and your companions' as their vassal, cost half their wages in gold each day; the other half the men take from what they raid and win. Garrisons, caravans and sellswords in Ironborn pay are paid in full. The crown's war aid and the house budgets count the lower wages. Off = the Ironborn are paid like everyone else", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool IronbornHalfWageInPlunder { get; set; } = true;

        [SettingPropertyBool("Free Folk Unpaid", HintText = "the Free Folk fight for their people, not for coin: troops in the parties and garrisons of the Free Folk take no wages, as the brothers of the Night's Watch (only Banner Kings' least upkeep remains), and the knights who ride with their companies serve unpaid too. The crown pays them no war aid and the house budget holds their numbers in men instead of gold (one host for all the Free Folk, apart from the Watch), and nobody is sent home - the limit only stops recruiting (volunteers, prisoners taken into the ranks, new companies). Sellswords in their pay are paid by their contract, as before. The same for you as their vassal: your companies and garrisons count in their host and serve unpaid while the whole host stays within what their people can field; while it is more than that by a twentieth (your recruiting has no such limit), your men take ordinary wages. Needs Clan Budget Enabled. Off = the Free Folk are paid like everyone else", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool FreeFolkUnpaid { get; set; } = true;

        [SettingPropertyBool("Free Folk Men From People", HintText = "with Free Folk Unpaid: the whole host of the Free Folk is held by their people, not by gold - at most all their grown men and women (with Free Folk All Adults Fight; off: Free Folk Levy Share) of the people of the lands they hold, so it shrinks when their people die or flee. Their garrisons grow only while all of them hold less than Free Folk Garrison Pool Share of the host; the rest of it goes into the field. Nobody is sent home: the limit only stops recruiting, new companies and the growth of garrisons. Off = their numbers are held by gold, as for the Night's Watch", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool FreeFolkMenFromPeople { get; set; } = true;

        [SettingPropertyFloatingInteger("Free Folk Levy Share", 0.000f, 0.050f, "0.000", HintText = "only with Free Folk All Adults Fight off (on: all their grown men and women may fight, this share is not used): the Free Folk under arms at most, as a share of the people of their lands (0.018 = about 5,000 of 280,000 - as many as they kept in their first half year, before gold began to hold them back)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float FreeFolkLevyShare { get; set; } = 0.018f;

        [SettingPropertyBool("Free Folk All Adults Fight", HintText = "with Free Folk Men From People: every grown man and woman of the Free Folk can fight - the spearwives too. Their host may hold all their grown men and women between 16 and 60 (about 54% of their people - some 158,000 of 293,000), so their numbers no longer hold it back. It is then held by what holds every host: how many men each chief can lead, the gold a chief needs before he takes on recruits, food, the number of chiefs and the losses of war - in practice far fewer take up arms. Their garrisons grow as before (Free Folk Garrison Pool Share). Off = at most Free Folk Levy Share of their people, as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool FreeFolkAllAdultsFight { get; set; } = true;

        [SettingPropertyFloatingInteger("Free Folk Garrison Pool Share", 0.00f, 1.00f, "0.00", HintText = "with Free Folk Men From People: the garrisons of the Free Folk grow only while all of them hold less than this share of the host (0.50 = half; garrisons above it stay, they only stop growing)", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public float FreeFolkGarrisonPoolShare { get; set; } = 0.50f;

        [SettingPropertyBool("Free Folk Recruit Needs Food", HintText = "a chief of the Free Folk leads only as many as he can feed: an AI company of the Free Folk takes on new men only while its food would last, with all the men it could take on at that place, the days the game asks for before a raid. Food and coin come from raids, battles and the granaries of the lands they burn. Needs Free Folk Unpaid. Off = they recruit without regard to food, as before", RequireRestart = false)]
        [SettingPropertyGroup("Reavers and the Free Folk")]
        public bool FreeFolkRecruitNeedsFood { get; set; } = true;

        [SettingPropertyBool("Fair Fief Grants", HintText = "Fair Fief Grants: a conquered castle or town goes to the house that earned it - the one whose lord led the army that took it (+50), houses that fought in the assault (+25), houses that lost all their lands (+50), the rightful de jure holder (+100) - and a house's claim halves once it holds as much as its tier allows (tier - 1 points; a town counts 2, a castle 1). No house is granted a fief beyond tier + 1 points. The king's house gets no conqueror's share and only a small bonus (+25) while the crown holds less than a fifth of the realm; King's Landing stays with the crown. Council votes follow these claims, and the king can no longer cancel the vote. A human king still chooses from the three best claims. Off = as before (every claim scored 0, so the first three houses on the realm's list always stand).", RequireRestart = false)]
        [SettingPropertyGroup("Grants of conquered fiefs")]
        public bool FairFiefGrants { get; set; } = true;

        [SettingPropertyInteger("Fair Fief Conqueror Bonus", 0, 200, "0", HintText = "With Fair Fief Grants: claim points for the house whose lord led the army that took the fief (participants in the assault get half).", RequireRestart = false)]
        [SettingPropertyGroup("Grants of conquered fiefs")]
        public int FairFiefConquerorBonus { get; set; } = 50;

        [SettingPropertyInteger("Fair Fief Cap Extra", 0, 10, "0", HintText = "With Fair Fief Grants: a house may hold at most (tier - 1 + this) points of castles and towns from grants (town 2, castle 1).", RequireRestart = false)]
        [SettingPropertyGroup("Grants of conquered fiefs")]
        public int FairFiefCapExtra { get; set; } = 2;

        [SettingPropertyBool("Besieged Relief First", HintText = "When an enemy army besieges a town or castle of a realm, the lords of that realm within the game's own reach of it (about eight days' march) put its relief above every other aim - raiding, plundering, chasing parties, patrolling, visiting towns, and for a capital or a town also their own sieges elsewhere (a lord besieging an enemy fortress is not called off it for a castle) - until the lords and armies already marching to its relief are strong enough (Besieged Relief Capital, Town or Castle Force times the besiegers' strength). The capital comes first, then the towns, then the castles. They gather near the walls and fall on the siege camp once together they are stronger than it, as the game does. A lord whose men are starving goes for food first. The same rule for every realm, yours included; your own party is never moved. Off = the game's own judgement, in which a lone lord rarely rides against a large army", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public bool BesiegedReliefFirst { get; set; } = true;

        [SettingPropertyFloatingInteger("Besieged Relief Capital Force", 0.00f, 8.00f, "0.00", HintText = "with Besieged Relief First: the relief a besieged capital calls for, as a multiple of the besiegers' strength (2 = twice their strength, the most the game's own reckoning of a fight rewards); 0 = capitals are left to the game", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public float BesiegedReliefCapitalForce { get; set; } = 2.0f;

        [SettingPropertyFloatingInteger("Besieged Relief Town Force", 0.00f, 6.00f, "0.00", HintText = "with Besieged Relief First: the relief a besieged town calls for, as a multiple of the besiegers' strength; 0 = towns are left to the game", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public float BesiegedReliefTownForce { get; set; } = 1.5f;

        [SettingPropertyFloatingInteger("Besieged Relief Castle Force", 0.00f, 4.80f, "0.00", HintText = "with Besieged Relief First: the relief a besieged castle calls for, as a multiple of the besiegers' strength (1.2 = just enough for the relief to attack the siege camp, by the game's own rule); 0 = castles are left to the game", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public float BesiegedReliefCastleForce { get; set; } = 1.2f;

        [SettingPropertyBool("Besieged Relief Kings Army", HintText = "with Besieged Relief First: the ruler of a realm whose town or castle is besieged, when he is free, within reach and has lords he can call, raises an army to relieve it - the same call to arms as for a siege, at the same cost of influence - unless an army of the realm is already gathering for it or marching to it. Off = only the armies the game and Banner Kings raise on their own", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public bool BesiegedReliefKingsArmy { get; set; } = true;

        [SettingPropertyBool("Besieged Relief Only When Reachable", HintText = "with Besieged Relief First: the lords are held to the relief of a besieged town or castle only while their realm can gather a relief the game will lead against the siege camp - all the lords of the realm within reach of it together (those already marching included) must be at least as strong as the smaller of the relief it calls for and 1.2 times the besiegers' strength (the game's own rule before a relief falls on a camp). A realm that cannot gather that much leaves its lords to their own judgement - they go to recruit, buy food or relieve another besieged fortress of the realm within reach - and calls them again once it is strong enough. Checked from the thirteenth hour of the siege, when every lord within reach has weighed it once. The same rule for every realm. Off = the lords stay by the besieged walls until the full relief is gathered, however long that takes", RequireRestart = false)]
        [SettingPropertyGroup("Relief of besieged towns")]
        public bool BesiegedReliefOnlyWhenReachable { get; set; } = true;

        [SettingPropertyBool("Siege Phantom Lift", HintText = "A siege camp in which fewer than Siege Phantom Min Men men are able to fight (all its parties together, the wounded not counted), or whose parties together have a strength below 1 in the game's own reckoning, for Siege Phantom Lift Days days in a row breaks up: its parties leave the siege, as when peace is made, and choose a new aim. Not a camp with the player's own party, the player's army or a party of the player's clan, not a siege with the player inside the walls, not the sieges of the Realm of Thrones story, not the Others, never during a battle. The count of days is not saved - after loading a game it starts again. Off = such a camp stays until something else ends the siege", RequireRestart = false)]
        [SettingPropertyGroup("Siege camps without fighting men")]
        public bool SiegePhantomLift { get; set; } = true;

        [SettingPropertyInteger("Siege Phantom Lift Days", 1, 30, "0", HintText = "with Siege Phantom Lift: how many days in a row a siege camp must be without enough fighting men before it breaks up (1-30)", RequireRestart = false)]
        [SettingPropertyGroup("Siege camps without fighting men")]
        public int SiegePhantomLiftDays { get; set; } = 3;

        [SettingPropertyInteger("Siege Phantom Min Men", 1, 50, "0", HintText = "with Siege Phantom Lift: a siege camp whose parties together have fewer healthy men than this counts as without fighting men (1-50)", RequireRestart = false)]
        [SettingPropertyGroup("Siege camps without fighting men")]
        public int SiegePhantomMinMen { get; set; } = 5;

        [SettingPropertyBool("Clan Leave Log", HintText = "Writes a log line each time a clan holding a town or castle leaves or joins a realm: the clan, the old and the new realm, the reason the game gives, its leader's relation with both rulers, its coin and its fiefs. Log only - nothing in the game changes", RequireRestart = false)]
        [SettingPropertyGroup("Clans changing realms")]
        public bool ClanLeaveLog { get; set; } = true;

        [SettingPropertyBool("Fix Bkrot Model Chains", HintText = "Fleets sail by the rules of War Sails again. The Banner Kings - Realm of Thrones patch puts its own party speed on top and counts every party, at sea too, by the land formula: no speed from ships and crew, no open sea, river or wind bonus, no penalty for too few sailors or too many ships. On = its blessings stay, and beneath them the speed rules of Realm of Thrones, War Sails and Living Economy run again (ships, crew, wind and sea; an enlisted party +20%; a caravan's mounted escort) and the Banner Kings sea perks with them. Realistic Bannerlord's speed is left out, as now (its seasons are off and it would cut the chain again). Each rule counts once. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixBkrotModelChains { get; set; } = true;

        [SettingPropertyBool("Fix Bkrot Map Model Chains", HintText = "The smaller rules of War Sails on the campaign map run again under the patch's blessings: sight at sea (+30%, storms -40%, sea perks), raids (the Nord feat, sea perks), healing at sea and morale in port (boatswain perks), and the Banner Kings sea perks on them. Realistic Bannerlord's healing and morale stay left out, as now. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixBkrotMapModelChains { get; set; } = true;

        [SettingPropertyBool("Fix Bkrot Battle Morale Chain", HintText = "The War Sails starting morale in battle runs again under the patch's blessings: the Lion figurehead and the Commodore perk, the sea perks in naval battles, and +20% for realms with the Fraternal Fleet Doctrine policy (on land too). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixBkrotBattleMoraleChain { get; set; } = true;

        [SettingPropertyBool("Fix Bkrot Wage Chain", HintText = "Wages by the rules of Realm of Thrones again (the patch's wage model cut them off): the Unsullied take no wage (only Banner Kings' least upkeep of 1 is left), troops of the Others cost their tier, and the companies and garrisons of the Others are paid nothing. The price of hiring stays as before - the Unsullied are still bought at their full price. Living Economy's guard against broken wage sums works again. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixBkrotWageChain { get; set; } = true;

        [SettingPropertyBool("Fix Bkrot Wage Sea Cut", HintText = "With Fix Bkrot Wage Chain: the War Sails wage cut at sea counts again - a company at sea pays a fifth less, a caravan at sea pays nothing, and the boatswain perks count. No company's wage goes below zero. Off = the same wage at sea as on land", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixBkrotWageSeaCut { get; set; } = true;

        [SettingPropertyBool("Fix Princely Arbiter Wage", HintText = "The Princely Arbiter blessing lowers your party's wages by 15%, as its description says. The patch took 15% for every kind of troop in the party, so from about seven kinds on your men paid you. No party's wage goes below zero. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool FixPrincelyArbiterWage { get; set; } = true;

        [SettingPropertyBool("Patch Target Guard", HintText = "Fix hooks aimed at an inherited rule: when Armoury, CrashScribe, Realistic Captivity, Grand Tourney or ForgeView hooks a game rule by hand after Armoury has loaded, through a mod's model that only inherits that rule (like the Banner Kings smithing cost), the hook and its later removal are moved onto the class that really holds the rule, and a hook already in place there is not added a second time. Without it the game's patching tool refuses such a hook, the Banner Kings - Realm of Thrones patch hides the refusal, and the feature silently does nothing (this is how wood at the anvil failed). Hooks of other mods are only counted in the log, never changed. Off = only report such hooks in the log", RequireRestart = false)]
        [SettingPropertyGroup("Model chains under the BKROT patch")]
        public bool PatchTargetGuard { get; set; } = false;

        [SettingPropertyBool("Gentry Names Fallback", HintText = "New gentry houses (locals who take up a vacant estate) rise in every realm again. Banner Kings names a new house with the first name on its culture's list that no house of the SAME culture bears, and the game then refuses a name any house bears. Realm of Thrones gives one list to many cultures, so the realm that founded the first house took that name for good and no gentry ever rose again in Braavos, Lys, Myr, Tyrosh, Norvos, Qohor, Volantis, the Reach, the Riverlands, the Stormlands, Dragonstone and others; the short lists of the North, the Vale, Dorne, the Free Folk and the Ghiscari ran out too. On = the first name on the list that no house in the world bears; when the list is used up, a name from the village (the village itself, or a name from the list of the village). A knight founding his house gets a free name the same way, but only where Banner Kings would have given him one. Lorath, Ibben, Qarth, the Night's Watch and the Summer Isles still have no gentry (Banner Kings has no gentry for their cultures). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Banner Kings gentry")]
        public bool GentryNamesFallback { get; set; } = true;

        [SettingPropertyBool("Combat Ai Realistic", HintText = "every time the campaign is loaded the battle AI of the campaign options (Combat AI) is set to Realistic, the highest level of the game, when it stands lower - the AI then blocks, parries and picks its blows as well as its skill allows. Your other campaign options (map speed, damage to your men, recruitment and the rest) stay as they are (off = Combat AI stays as set in the campaign options)", RequireRestart = false)]
        [SettingPropertyGroup("Combat AI level (16.10)")]
        public bool CombatAiRealistic { get; set; } = true;

        [SettingPropertyFloatingInteger("Charcoal Weight Kg", 0.00f, 10.00f, "0.00", HintText = "a lump of charcoal weighs this many kilograms (0 = the game's own 5 kg brick). With the game's weight a load of hardwood (100 kg) burns down to 4 lumps (a fifth of its weight), each refining step takes one 5 kg lump, armour from your forge needs the same kilograms of charcoal per kilogram of iron as before (in whole lumps), and with Smith Coal Kg a weapon forged or smelted on the smithing screen still burns half a kilogram, taken from the lump burning in the forge (without it one whole 5 kg lump per weapon - a load of hardwood would make charcoal for 4 weapons instead of 40); 0.5 = the old half-kilo lump (a load of wood worth 4 pence gave 40 lumps worth 40 pence). Takes effect when a game is next loaded", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public float CharcoalWeightKg { get; set; } = 0f;

        [SettingPropertyBool("Smith Coal Kg", HintText = "a weapon forged or smelted on the smithing screen burns half a kilogram of charcoal, as when a lump weighed half a kilo: it is taken from the lump already burning in your forge, and a new lump (5 kg) is taken from your bags only when the fire runs short - a load of hardwood still makes charcoal for 40 weapons, not 4. Hover the charcoal counter on the smithing screen to see what is left in the fire (off = one whole lump for every weapon, as the game does)", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool SmithCoalKg { get; set; } = true;

        [SettingPropertyBool("Salt Rate Raised", HintText = "with Goods Rates By Pattern, salt pans yield three and a half times their old rate instead of twice: salt has cost eight times its worth for years and the 97 towns together hold a few dozen sacks (off = twice, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool SaltRateRaised { get; set; } = true;

        [SettingPropertyBool("Fur Rate Raised", HintText = "trappers' villages bring in three times the furs they did: the whole world made about 40 packs a day while townsfolk sought about 150, and furs cost two to five times their worth (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool FurRateRaised { get; set; } = true;

        [SettingPropertyBool("Helm One Rule", HintText = "plate helmets of every tier are priced by one rule: days of work = weight x Helm Days Per Kg plus half a day for each tier above the third, and the weight that counts is never more than the usual weight of a plate helmet with that much head armour (the median of all plate helmets) - a tier 3 helmet no longer costs more than a tier 4 one. The same weight counts at the workshop, at your forge and in repairs (off = tiers 1 to 3 priced like a breastplate, by the game's weight). Takes effect when a game is next loaded", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool HelmOneRule { get; set; } = true;

        [SettingPropertyBool("No Town Mines", HintText = "Banner Kings no longer turns a town workshop into a mine (one time in three when the town would get a second workshop of a kind) - town mines never worked a single cycle. The town gets instead the kind of workshop that earns most at its own market prices (outputs less inputs) and that it does not have yet; mines already standing stay until the workshop changes hands (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool NoTownMines { get; set; } = true;

        [SettingPropertyBool("Bulk Unit Per Campaign", HintText = "the load of ore and timber (Hist Bulk Unit Factor) is fixed for the whole campaign and kept in the save: moving the slider later changes nothing in a running campaign, where it would have counted every stack of wood and ore in the world anew (a save from before keeps 10, the load it has; off = the slider counts at every load, as before). Takes effect when a game is next loaded", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool BulkUnitPerCampaign { get; set; } = true;

        [SettingPropertyBool("Smith Wood On Screen", HintText = "with Smith Wood Kg: hover the hardwood counter on the smithing screen to see how many kilograms are left of the open load of hardwood", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool SmithWoodOnScreen { get; set; } = true;

        [SettingPropertyBool("Self Mend Wood Kg", HintText = "with Smith Wood Kg: mending at your own anvil takes wood by the kilogram of the repair from the open load - a new load of hardwood is asked for only when the open one runs short (off = a share of whole loads, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods and prices (night 16.10)")]
        public bool SelfMendWoodKg { get; set; } = true;

        [SettingPropertyBool("Folk Craft Wage On Sale", HintText = "the merchants top up the craftsmen's wages (Town Folk Craft Wage Share of the worth of every workshop good) only for goods that leave the town's stalls - bought by caravans, lords, soldiers, builders or the townsfolk themselves; approximately - the workshop's own goods count as the newest on the stall, so goods others sold to the town go first. A sword that lies unsold on a glutted stall earns the craftsmen nothing more until somebody buys it; the coin stays in the town's purse (off = the top-up is paid for every piece made, sold or not, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Coin flow (night 16.10)")]
        public bool FolkCraftWageOnSale { get; set; } = true;

        [SettingPropertyBool("Sutlers By Purse", HintText = "the men in the field spend with the sutlers by how full their purse is: the daily share (Sutler Daily Share) times their free coin in days of pay divided by ten, at most three times the share - men with a month of pay to spare spend three times as fast, men with five days half as fast. A company that has bought no kit for two weeks (nothing better on the stalls) keeps at most half of its usual savings for better kit (Men Gear Save Days) - the rest goes to the sutlers in the field or on food and drink in town. Starts gently over Sutler Ramp Days in a running campaign. The coin goes where it went before: the nearest friendly town and village (off = the same share of the free purse every day, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Coin flow (night 16.10)")]
        public bool SutlersByPurse { get; set; } = true;

        [SettingPropertyBool("Folk Guard No Memory", HintText = "DECYZJA CLAUDE noc 15/16.10: test 60 dob - lud 8.0 -> 10.4% zlota swiata, korony szybciej w dol; najpierw ujscia (audyt P1-P6), potem N7              // the steward of the realm's coin (Folk Circulation Guard) sets the hoard tax each day from how much the common folk hold right now, without memory: the usual rate times 1 + 8 x (their savings against the normal level - 1.5), between a quarter and Folk Guard Max Times - at 1.5 times the normal level the usual rate, at 1.75 three times, at 2 five times. Before, the rate crept up 3% a day and stayed up long after the hoards had shrunk (off = the slow rate with memory, as before; the save keeps both)", RequireRestart = false)]
        [SettingPropertyGroup("Coin flow (night 16.10)")]
        public bool FolkGuardNoMemory { get; set; } = false;

        [SettingPropertyBool("Folk Loan Before Guard", HintText = "with Folk Loans: a house at war may borrow from what its own people held before the steward's hoard tax took its part that day, and the next day's hoard tax of every place that lent is lowered by what it lent - the people lend first, the lord's gift from the hoard comes second (off = the house borrows only from what is left after the tax, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Coin flow (night 16.10)")]
        public bool FolkLoanBeforeGuard { get; set; } = true;

        [SettingPropertyBool("Village Eggs From Bk", HintText = "farming villages (wheat farms, olive groves, vineyards, date farms, flax and silk fields) lay eggs: the Banner Kings list of village goods gives them chickens and geese with their culture's weight, but no eggs, and the game counted the birds as nothing - eggs came only from cattle ranches and from fowl carried in parties, so 88 of 97 towns had none and they cost ten times their worth. The eggs follow the weight of the village's chickens and geese together, grown the way the game grows any crop (the weight times the village's size step plus one, halved, each day); an extra crop - the village's own crops stay as they were (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool VillageEggsFromBk { get; set; } = true;

        [SettingPropertyBool("No Maker Budget To Luxury", HintText = "the townsfolk's money for goods that no village or workshop in the world makes - garum, dyes, gems, ink and gold ore where none is on the stall - goes to the nearest kind of better goods that does lie on the stall in plenty: garum to the better table (meat, cheese, butter, wine), dyes to cloth and clothing, gems and gold ore to jewellery and silver, ink to household goods. Each kind takes at most half of what its stall holds beyond its own buyers. What finds no room stays in the purse, as before; the townsfolk still pay for all of it themselves (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool NoMakerBudgetToLuxury { get; set; } = true;

        [SettingPropertyBool("Village Fibre To Market", HintText = "a village cart carrying flax, wool or hides goes to the village's own market town and sells there, even below the usual price, when the village holds more than six days of its own output of that good (cart and storehouse together) - instead of a long haul to the best-paying town while the storehouse fills and the village stops working. From the market town the merchants carry it on to the weavers and tanners of other towns (off = the cart always seeks the best price, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool VillageFibreToMarket { get; set; } = true;

        [SettingPropertyBool("Town Folk Firewood", HintText = "the townsfolk buy firewood: a tenth of a load of hardwood (100 kg) a day for each thousand townsfolk in spring and autumn, half that in summer (cooking only), in the winter of Westeros more, by the same measure as every other bite of winter: about twice across most of the realm (more in the far north, less towards Dorne), about a third more in the warm south, nothing extra in the Summer Isles, and no extra at all when Winter Bite is off, taken from their own town's stall only above what the smiths and bloomeries need, and paid from the townsfolk's purse only out of money beyond tomorrow's basket (the excise to the commune, the rest to the town's merchants). In summer little wood is to spare, so they burn little; in winter, when wood piles up, they burn their fill (off = wood only in the Banner Kings basket, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool TownFolkFirewood { get; set; } = true;

        [SettingPropertyBool("Firewood Ks Season", HintText = "with Town Folk Firewood under the start calibration (the townsfolk's basket of the estates): the season counts the same way as without it - in summer the townsfolk burn half (cooking only), in winter more by the bite of winter - instead of the full winter-and-spring measure all summer long (off = summer burns as much as spring, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool FirewoodKsSeason { get; set; } = true;

        [SettingPropertyBool("Firewood Ks Supply Cap", HintText = "with Town Folk Firewood under the start calibration: the townsfolk want only as much firewood as the villages really bring to their town's market (the wood sold there by village carts and grown on the townsfolk's own fields, the last 7 days; days not yet seen after loading are filled from the plan of the districts), beyond what the town's smiths, bloomeries and workshops use each day, plus a seventh of the wood already lying on the stall above the craftsmen's stock - their wish grows only with the wood that truly comes (off = the full measure of a kilo and a half a head whether the wood comes or not, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool FirewoodKsSupplyCap { get; set; } = true;

        [SettingPropertyBool("Firewood Ks Price Demand", HintText = "with Town Folk Firewood under the start calibration: the price of wood in a town counts the townsfolk's firewood by the season - half in summer, more in winter by the bite of winter - instead of the same full measure all year; it does not follow the wood that comes, so a town short of wood still pays well for it and draws the carts (off = the full measure in the price all year, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool FirewoodKsPriceDemand { get; set; } = true;

        [SettingPropertyBool("Firewood Mine Wood Keep", HintText = "with Bloomery At Mine under the start calibration: the stock of wood a town keeps for its own craftsmen, below which neither firewood nor building works take any, counts the wood the bloomeries of the mines trading at this town need beyond the woods of their district, and not only what they managed to buy - the townsfolk's fires and the builders no longer take the mines' charcoal (off = only what the bloomeries bought, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods for the townsfolk (night 16.10, part 2)")]
        public bool FirewoodMineWoodKeep { get; set; } = true;

        [SettingPropertyFloatingInteger("Folk Guard Normal Share Max", 0.000f, 0.200f, "0.000", HintText = "with Folk Circulation Guard: when the steward of the realm's coin decides whether the hoard tax should rise or fall, the common folk's normal savings count as at most this part of all the gold in the world (0.064 = 6.4%). New goods to buy raise the folk's normal savings, and without this limit the steward grew lenient while their purses kept swelling. What each class pays is still counted above its own normal level (0 = no limit, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public float FolkGuardNormalShareMax { get; set; } = 0.064f;

        [SettingPropertyFloatingInteger("Folk Guard Share Fuse", 0.000f, 0.300f, "0.000", HintText = "with Folk Circulation Guard: a safety fuse - while the common folk and the villagers together hold more than this part of all the gold in the world, the hoard tax rises a little each day (3%) even inside its usual band, up to 3.7 times the usual rate (where the steward stood before the fuse existed - an emergency tax, not a new level); the fuse never lowers the tax and does nothing while Folk Guard No Memory is on (0 = off)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public float FolkGuardShareFuse { get; set; } = 0.09f;

        [SettingPropertyBool("Crown Keeps Valve Share", HintText = "emergency lever, off by default: while the realms' treasuries hold less than Folk Guard Crown Target of all the gold in the world, part of the crown's share of the town purses' surplus (five times the shortfall, at most half) is laid by in the treasury's reserve instead of being handed to the houses as rents the same day. It is taken only from what is left for the rents - never from the wage refund, the aid to houses or any other payment - and not on a day the crown borrows from the Iron Bank (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool CrownKeepsValveShare { get; set; } = false;

        [SettingPropertyBool("Village Tribute From Sutlers", HintText = "the coin soldiers in the field spend with the sutlers of a nearby village is split the way all village takings are: the lord of the village takes his tax by his decree (the same rule as when the village cart comes home), the rest stays in the village purse; a village of the soldiers' own house keeps all of it (off = all of it to the village purse, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool VillageTributeFromSutlers { get; set; } = true;

        [SettingPropertyBool("Town Market Toll", HintText = "a market toll: when a village cart or a caravan sells its goods to a town or a castle it pays a small part of the takings - half to the head of the house that holds the town, half to the reserve of the realm's treasury (no realm - all to the lord; no living lord - his half to the town's purse). One rule for every cart and caravan, the player's own included; caravans on a material contract are free (their dues are paid at the source), and so is a caravan selling out before it is broken up (off = no toll, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool TownMarketToll { get; set; } = true;

        [SettingPropertyFloatingInteger("Town Market Toll Rate", 0.000f, 0.200f, "0.000", HintText = "with Town Market Toll: the toll on a village cart's takings (0.04 = 4%)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public float TownMarketTollRate { get; set; } = 0.04f;

        [SettingPropertyFloatingInteger("Town Market Toll Caravan Rate", 0.000f, 0.200f, "0.000", HintText = "with Town Market Toll: the toll on a caravan's takings (0.02 = 2%; caravans already pay duty when they buy, so their margin is thin)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public float TownMarketTollCaravanRate { get; set; } = 0.02f;

        [SettingPropertyBool("Town Ground Rent", HintText = "a third of the rent the working folk and the craftsmen pay for their houses goes to the head of the house that holds the town as ground rent; the other two thirds still go to the townsmen who own the houses (off = all of it to the townsmen, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool TownGroundRent { get; set; } = true;

        [SettingPropertyBool("Caravan Sell Where Dear", HintText = "a caravan sells its trade goods where it makes a profit: entering a town it sells, a few pieces at a time and at most half of each stack, every piece whose price there is above what the caravan paid for it plus its share of the caravan's wages for the days on the road. The price counts after the market toll. Goods it carried before the game was loaded are valued at the most the merchants could have paid for them (their worth times the average price level of the realm's towns, or the price in the merchants' own trade log if higher). It sells at a loss only when it has no way out: the goods have lain in its packs for over 30 days, food is going off (over 7 days), it has no coin left for three days of wages, its packs are over their load - and then only as much as brings them under it - or it is being broken up. Unless it is being broken up or has no coin for wages, it sells at a loss only a little at a time: in one town on one day the price level of those goods may fall by at most 30% from where it stood before the first such sale, and no piece goes for less than 0.6 of its worth - the rest waits for the next town. It does not buy back at the same visit what it has just sold, the town pays only from its purse above the merchants' reserve and at most a twentieth of that in a day, and bulk raw goods, animals and horses keep their own rules (off = Banner Kings sells one or two pieces a visit, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool CaravanSellWhereDear { get; set; } = true;

        [SettingPropertyBool("Caravan Profit To Owner", HintText = "once a day a caravan without a hero at its head hands its owner - the notable, the lord or you - all the coin it holds above what it keeps for trade: 10,000, or a month of its wages if that is more. It works only with the Banner Kings realistic caravan income, which otherwise pays the owner only when the caravan calls at his home; a caravan being broken up or in a battle keeps its purse, and a notable's gold above his usual band still goes to his market town for influence, as before (off = the profit reaches the owner only when the caravan calls at his home, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool CaravanProfitToOwner { get; set; } = true;

        [SettingPropertyBool("Village Cart Brings Goods", HintText = "what a village could not buy in its own market town - salt, tools, flax and linen, pots, beer - it buys when its cart sells the village's produce in another town or castle: up to seven days of the village's need from that stall, paid from the village purse (off = only the market town, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool VillageCartBringsGoods { get; set; } = true;

        [SettingPropertyBool("Village Cloth Half Reserve", HintText = "with Village Cloth Above Reserve: where linen is cheap in the market (its price below the usual), the villagers may buy linen above half of the stock the town keeps for the army's clothing instead of only above all of it (off = above all of it, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Trade pays its way (night 16.10, part 3)")]
        public bool VillageClothHalfReserve { get; set; } = true;

        [SettingPropertyBool("Workshop Pace By Market", HintText = "a trade workshop in a town (a notable's or a lord's) works at the pace of its market: more hands where the town has more people than the usual town (at most four times, at least a third), and a little faster where what it makes is dear in that town, slower where it is cheap (the square root of the price, between 0.7 and 1.4); the whole at most four times the usual pace. More cycles take more raw goods from the stall and pay more wages, as if more men were hired. Weapon and armour lines, lines without raw goods, the town's hidden artisans, castles and your own workshops keep the usual pace (off = the usual pace everywhere, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool WorkshopPaceByMarket { get; set; } = true;

        [SettingPropertyBool("Workshop Retool By Price", HintText = "a notable's trade workshop that has lost money for 60 days or more changes its trade to the one that earns most at its own town's prices after wages - only a trade whose raw goods grow in the town's villages, lie on its stall or come by a materials contract, only if it earns clearly more (by 30%, and at least 10 a day; a trade the town already has counts a fifth less for each such workshop), and the owner pays the new tools to the town's craftsmen from his own purse. At most three workshops a day in the world, one a town in 30 days; a smithy may be chosen (it is the only maker of tools). When a workshop goes bankrupt or is taken from you, the new trade is the best one at the town's prices when it earns a quarter more than the game's pick. Your own workshops, smithies and mines never change by this rule (off = trades change only by bankruptcy, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool WorkshopRetoolByPrice { get; set; } = true;

        [SettingPropertyBool("Workshop Retool Fair Score", HintText = "with Workshop Retool By Price (and No Town Mines): a trade is judged the way its workshop will really be paid - the town pays for a cycle's wares at most their raw goods and wages plus the master's margin - and only for as many cycles a day as the raw goods really made and lying in the market's region (the town and its neighbours within a few days) allow, shared among all the region's workshops that use them. Where the region already has workshops of that trade, what they really earned over at least 60 days caps the judgement, and each one already in the region counts a fifth less. The first week after loading an older save the rule only measures and changes nothing (off = the trade is judged by the middle price of its goods in the town, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool WorkshopRetoolFairScore { get; set; } = true;

        [SettingPropertyBool("Village Hands Follow Price", HintText = "the villagers move their hands to what is dear: where eggs, fruit or honey fetch far more in the village's market town than its other crops, the village yields up to twice as much of them (the square root of how many times dearer, between 1 and 2), and as much less of its other crops by worth at the usual price - the same hands, the same work, at most 15% less of the other crops and at most 5% less grain; timber and ore (iron, silver, salt, clay) are never cut, a village with nothing else to give keeps its yield (off = the usual yields, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool VillageHandsFollowPrice { get; set; } = true;

        [SettingPropertyBool("Court Buys Goods", HintText = "a lord's household living in a town lives off its market: up to 60% of what the head of the house spends on his court buys wine, beer, cheese, meat, fish, bread, fruit and oil (half), linen above the army's reserve, velvet and furs (a fifth) and jewels, silver, spice and pottery (the rest) from that town's stall at its price - only goods that are not dear there (price at most one and a half times the usual), never below the last few pieces, at most a quarter of a stack a day. The townsfolk get their fifth of what the court spends only from the part that pays for service, not for goods (off = the court pays the town in coin only, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool CourtBuysGoods { get; set; } = true;

        [SettingPropertyBool("Crown Court Goods", HintText = "the king's household in the capital buys the same goods from the capital's stall, paid by the treasury from what is left for the rents that day (never from the wage refund or the reserve); what it does not spend goes to the rents as before (off = no royal household purchases, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool CrownCourtGoods { get; set; } = true;

        [SettingPropertyFloatingInteger("Crown Court Share", 0.00f, 0.50f, "0.00", HintText = "with Crown Court Goods: the part of what is left for the rents that the king's household may spend on goods each day (0.05 = 5%)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public float CrownCourtShare { get; set; } = 0.05f;

        [SettingPropertyBool("Men Upgrade Orders", HintText = "when soldiers who could carry better kit find no better piece on the stall although their rank allows one, they order it: one order a band a day for the next tier from that town's smiths, at most five pieces, the same order not again for a week (off = no orders, as before). The daily line also tells apart soldiers already at the ceiling of their rank and soldiers held back by an empty stall", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool MenUpgradeOrders { get; set; } = true;

        [SettingPropertyBool("Build Wood Half Reserve", HintText = "with Build Wood Above Craft Stock: where timber is cheap in the town (its price below the usual), building works may buy timber down to half of the stock the smiths and bloomeries need (at least 20 loads) instead of only above all of it; where timber is dear the whole stock stays for the crafts (off = above all of it, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool BuildWoodHalfReserve { get; set; } = true;

        [SettingPropertyBool("Town Crafts After Workshops", HintText = "the town's own fullers, weavers and tanners (Town Crafts Enabled) work up what is left on the stalls after the town's trade workshops have run their day, not before them: a notable's weavery or tannery, which pays for its flax, hides or wool, its wages and its upkeep, buys first at the morning price, and the town's craftsmen take the rest - they have hands to spare and lose nothing by waiting. The food crafts of Start Calibration keep their place. Off = the town's craftsmen take first, as before", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool TownCraftsAfterWorkshops { get; set; } = true;

        [SettingPropertyBool("Cloth Demand From Offtake", HintText = "the price of leather and linen in a town (Raw Price By Use) also counts what really leaves its stalls each day for the army's clothing, the smiths' repairs, the villages buying in their market town and the lords' courts (average of about two weeks, read from the goods ledger - needs Goods Ledger Enabled and the log on; with either of them off the measure stops and leather and linen prices go back to the old rule within about a week), not only what the townsfolk and the armourers use: leather and linen are dear where they are worn out, so the tanners and weavers can pay for their hides and flax. Where Start Calibration already prices the villages' basket and the courts, only the army's clothing and the repairs are added there, so nothing is counted twice. Only the price changes - the stock caravans keep and the stall reserves stay as they are. Off = only the townsfolk and the armourers count, as before", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool ClothDemandFromOfftake { get; set; } = true;

        [SettingPropertyBool("Build Clay For Potters", HintText = "building works (the lord's, the townsfolk's and the commons') take clay off the market only above what the town's pottery workshops use in Caravan Bulk Stock Days; below it the works buy the other materials or wait, so the potters are not left without clay. The town's own potters of Start Calibration, who work before the workshops, also take clay only above it. Off = the works and the town's potters take clay down to the last pieces, as before", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool BuildClayForPotters { get; set; } = true;

        [SettingPropertyBool("Cloth Export In Price", HintText = "with Cloth Demand From Offtake: the price of leather and linen in a town also counts what merchants really carry away from its stalls each day - caravans buying there (hired ones included) and the merchants' carts sent from other towns (average of about two weeks, read from the goods ledger - needs Goods Ledger Enabled and the log on). Once a week of it is measured, the town's own tanners and weavers (Town Crafts Enabled) work for what their own market pays - the merchants who carry leather and linen away pay the town's price, and that price now holds what they carry away - instead of the best price of a town short of them far away, which none of them is paid and which every tanner and weaver around counted for himself. Only the price and the craftsmen's reckoning change - no coin or goods move differently. Off (or Goods Ledger off) = tanners and weavers reckon the export price (Tanner Export Price, Weaver Export Price) and the town price does not count the merchants, as before", RequireRestart = false)]
        [SettingPropertyGroup("Production follows price and people (night 16.10, part 3, second half)")]
        public bool ClothExportInPrice { get; set; } = true;

        [SettingPropertyBool("Daily Life Measure", HintText = "Daily life (a measure only): every day the people of each village and town are reckoned by estate - slaves, peasants, labourers, craftsmen, merchants, gentry and the great houses - with their daily table in kilograms (own fields and the market) and their Livelihood: how many times over they can afford the bare survival basket of bread, pottage, salt and fuel at local prices, for each estate, village, town, district, realm and the whole world, with the income per head. Written to the log and to stany-dostatek.csv only - nothing in the game changes (no coin, goods, prices, prosperity or AI). Off = no measure, as before", RequireRestart = false)]
        [SettingPropertyGroup("Daily life, estates and livelihood (measure only)")]
        public bool DailyLifeMeasure { get; set; } = true;

        [SettingPropertyInteger("Daily Life Market Scale", 28, 73, "0", HintText = "with Daily Life Measure: how many real sacks one sack on a market stall stands for in the people's trade (28-73). Taken into the save once, at the first load with Daily Life Measure, and kept for the whole campaign - changing it later does not change a campaign already begun", RequireRestart = false)]
        [SettingPropertyGroup("Daily life, estates and livelihood (measure only)")]
        public int DailyLifeMarketScale { get; set; } = 37;

        [SettingPropertyBool("Daily Life Estates", HintText = "with Daily Life Measure: the estates of every town and village - slaves, peasants, labourers, craftsmen, merchants, gentry - are kept in the land's book and in the save (an old save gets them at the first dawn from the land's customs and its Banner Kings classes), and you can see them: the map tooltips of towns, castles (their region), villages and the villages of a district show the estates and their Livelihood, 'Estates and livelihood' in village, town and castle menus lists every estate of the place with its Livelihood, income and daily table, 'Look over the district' shows the district's estates, and 'Realm ledger' in town and castle menus lists the realm, its regions and the whole world. On its own it only labels and shows - nothing in the economy changes; but Daily Life Mobility, Freedom, Prosperity Link and War Scar (group 'Daily life - rise, fall and war') work only with it and do change the game (off = the estates are reckoned afresh each day for the log only, as before, the book kept in the save stays untouched, and those four stop too)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life, estates and livelihood (measure only)")]
        public bool DailyLifeEstates { get; set; } = true;

        [SettingPropertyBool("Daily Life Mobility", HintText = "with Daily Life Estates: people rise and fall between the estates once a week in every town and village, by the Livelihood of their estate and the savings in their purse - a peasant takes up a craft, a labourer joins a guild (paying its fee to the craftsmen), a craftsman turns merchant, a merchant buys land from the lord of the land and joins the gentry; when an estate cannot keep itself for weeks it falls a step down, and gentry who fall sell their land back to the lord at the same price (as much as he can spare). The money goes with the people, nothing is made or lost; owners free a few slaves each year and the newcomers from the villages swell the town's labourers. Land bought or sold back in your own fiefs is told in one message a day. Slow: about 3% of the way up a year, at most 0.2% of a place's people a week (off = the estates stand still, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life - rise, fall and war")]
        public bool DailyLifeMobility { get; set; } = true;

        [SettingPropertyBool("Daily Life Freedom", HintText = "with Daily Life Estates: when a stronghold of a slaving land is won by a realm whose ruler is not of a slaving culture, a tenth of its region's slaves are set free every 28 days - to the labourers in the town and to the peasants in the villages. Places already under such a ruler on the day this is switched on are left as they are (off = the slaves stay slaves under any ruler)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life - rise, fall and war")]
        public bool DailyLifeFreedom { get; set; } = true;

        [SettingPropertyBool("Daily Life Prosperity Link", HintText = "with Daily Life Estates: the prosperity of towns and castles follows the changes in the Livelihood of their region from the day this is switched on - on that day nothing moves; a region that grows richer pulls its stronghold's prosperity up, one impoverished by war or want pulls it down, by 1% of the gap and at most 2 points a day, shown as 'Livelihood of the region' in the prosperity tooltip; while the Livelihood stays where it was, the game's own prosperity leads. Off until it has passed a long test (off = prosperity as before)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life - rise, fall and war")]
        public bool DailyLifeProsperityLink { get; set; } = false;

        [SettingPropertyBool("Daily Life War Scar", HintText = "with Daily Life Estates: war leaves a scar on the people. When a town is sacked a tenth of its merchants fall to a craft and a tenth of its craftsmen to day labour at once (a fifth of each when it is devastated), and for a month after more of them fall; when raiders or a foraging army strike a village's countryside, the people struck lose their living at once, the district counts its people driven from home in its Livelihood with no income until they come back, and some of its craftsmen lose their trade. In peace the ruined win their trades back slowly. Their savings go with them, nothing is made or lost (off = war takes coin, crops and lives as before, but the estates and their Livelihood carry no scar)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life - rise, fall and war")]
        public bool DailyLifeWarScar { get; set; } = true;

        [SettingPropertyBool("Debt Slavery", HintText = "with Daily Life Estates and Daily Life Mobility (under which owners also free a few slaves each year), only in the slaving lands of Essos that know coin and debt (Slaver's Bay, Volantis, Lys, Myr, Tyrosh, Qohor, Norvos, Valyria, Qarth - not the Iron Islands, not the Dothraki): the poorest free people of a place - peasants in a village, labourers in a town - whose Livelihood stays below 0.8 and who have less than a week of savings fall into debt slavery, about 1% of them a year, and become slaves of the same place. Their few coins go to their creditors, the craftsmen and merchants of the town who own its slaves; as slaves they work for their owners and are fed by them. Only under the start calibration and while the region is ruled by a slaving realm. No one is made or lost, and Westeros is never touched (off = no one falls into slavery for debt, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Daily life - rise, fall and war")]
        public bool DebtSlavery { get; set; } = true;

        [SettingPropertyBool("Start Calibration", HintText = "Start calibration (the plan only): once a week the hands and the land of every district - the game village, its side villages and the fields of the townsfolk - are reckoned with one table of what a worker makes on his land, and who does what is chosen the way families choose it: where the work pays best after the cost of the herd, the boat or the grove. The plan itself only writes the log and ks-plan.csv; the game changes only once the calibration is started - by itself after about five weeks of survey with Start Calibration Auto Arm (on), or with Arm This Save and Confirm. On a save where the calibration was already applied, off = from the next day the villages produce as before (the state stays in the save)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibration { get; set; } = true;

        [SettingPropertyFloatingInteger("Start Calibration Map Inertia", 1.00f, 2.00f, "0.00", HintText = "with Start Calibration: how much better another work must pay before a block of land leaves the work the map gives it (1.25 = 25% better, Jeff's threshold; 1.0-2.0)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public float StartCalibrationMapInertia { get; set; } = 1.25f;

        [SettingPropertyBool("Start Calibration Town Fields", HintText = "with Start Calibration: the peasants of a town, half the work of its slaves and a fifth of its labourers at harvest till the fields around the stronghold (the town's own land, like the agro-towns of old); off = towns have no fields of their own", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationTownFields { get; set; } = true;

        [SettingPropertyBool("Start Calibration Switch Rule", HintText = "with Start Calibration applied: a village part changes its work only when another work has paid at least 25% better for about 60 days, one part of a district at a time, within the land of that part and at most 5% of the region's hands a season; the village pays for the timber, tools and stone really bought at its market town's stall and for the town craftsmen who make the new gear (no coin or no material on the stall - the change waits) and the hands move over 60 days (vineyards, groves, orchards and date palms a year). Off (default for the first season) = the works stay as the calibration set them and the pressure to change is only measured in the log", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationSwitchRule { get; set; } = false;

        [SettingPropertyBool("Start Calibration Autotest Apply", HintText = "FOR THE AUTOTEST ONLY: at the first finished plan built on 28 days of the goods ledger the calibration is applied to the running game (village output from hands and land, town fields, the switching rule, the granary floor, the people's daily basket at the market and the town food crafts). Works only while the CrashScribe autotest is running; in a normal game it does nothing", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationAutotestApply { get; set; } = false;

        [SettingPropertyBool("Start Calibration Arm This Save", HintText = "Step 1 of 2 (Ironman safe): marks THIS save for the start calibration. The next day the save remembers it (campaign id, day, plan, land file) and this switch turns itself off again, so another save is never touched. Needs a plan built on 28 days of the goods ledger in this session, Daily Life Measure, Bk Recipe Yield By Workshop and Whale Meat From Whalers Only, and not in winter (unless Ks Land Gate is on and Ks Granary No Floor is off). Nothing in the game changes yet", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationArmThisSave { get; set; } = false;

        [SettingPropertyBool("Start Calibration Confirm", HintText = "Step 2 of 2: on a save marked with Arm This Save (a later day, the same plan and land file) and after at least 7 days of weekly plans on it, the calibration starts the next day: for 14 days the villages move from today's output to what their hands make on their land, then the people's daily basket comes to the market over 14 days, and the stalls get their starting prices. In a campaign it also needs the famine gate (Ks Land Gate) and the hard safeguards (Ks Hard Gates); with Start Calibration Auto Arm the save starts by itself and this switch is not needed. Cannot undo goods already made and sold, nor gold that changed hands in trade. To undo later switch Start Calibration off (from the next day output and demand are as before)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationConfirm { get; set; } = false;

        [SettingPropertyBool("Start Calibration Auto Arm", HintText = "with Start Calibration: the calibration arms itself on a running campaign the first time it is loaded with this version and only surveys at first - 28 days of the goods ledger, then 7 days of finished weekly plans (the survey is kept in the save from one session to the next) - and checks its safeguards (the famine gate of every land, no goods from nowhere in the ledger, the village layout, not in winter unless the old granary floor is on). When all pass it starts by itself with the usual ramp: 14 days in which the villages move to what their hands make on their land, then 14 days in which the people's daily basket comes to the markets. Nothing changes before that. Off = only Arm This Save and Confirm start it. To undo at any time switch Start Calibration off (from the next day output and demand are as before)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationAutoArm { get; set; } = true;

        [SettingPropertyBool("Ks Land Gate", HintText = "with Start Calibration applied: the famine gate of every land - when a village of a land starts to run out of food because of the calibration (its granary is nearly empty and it eats a tenth less, it is not being raided, looted or besieged right now, and the old harvest rule would have fed it better), or the land's granaries fall by more than 1% of its need a day for 7 days in a row once they have lost Ks Land Gate Loss Days under the calibration or hold less than Ks Land Gate Reserve Days, that land alone - and the villages that trade in its towns - goes back to the old village output, granary, market and food carts from the next day; the rest of the realm keeps the calibration. A second try comes only by hand: switch Start Calibration off and on again (the whole realm ramps in again). Off = the calibration cannot start in a campaign (as before); once it has started in a campaign the gate keeps working - deaths from hunger cannot be undone, so only Start Calibration off stops it", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsLandGate { get; set; } = true;

        [SettingPropertyInteger("Ks Land Gate Reserve Days", 0, 728, "0", HintText = "with Ks Land Gate: a land whose granaries hold less than this many days of its need counts a fall from the first day (full granaries hold two years; 364 = half of them - lands already emptied by war). 0 = always - then almost every land would go back within a week, because honest granaries without the old floor fall slowly where the land cannot feed itself", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public int KsLandGateReserveDays { get; set; } = 364;

        [SettingPropertyInteger("Ks Land Gate Loss Days", 0, 364, "0", HintText = "with Ks Land Gate: how many days of a land's need its granaries may lose under the calibration before a fall of more than 1% a day for 7 days sends that land back - counted from the day the calibration started, only on days it fed the land less than the old harvest rule would have (granaries filling up again count back; losses to raids do not count). 91 = one season of the land's two-year store, so the winter reserve stays nearly whole. 0 = any loss (the strict rule)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public int KsLandGateLossDays { get; set; } = 91;

        [SettingPropertyBool("Ks Land Gate Exact Loss", HintText = "with Ks Land Gate: on days the calibration fed a land less than the old harvest rule would have, count as the land's granary loss only what the calibration itself took - in each village, the fall of its granary up to how much less the calibration fed it that day than the old harvest rule would have; spoilage, winter and poor soil that the old rule would not have covered either do not count, and the fall of more than 1% a day over 7 days uses the same measure. Off = the whole fall of the land's granaries on days the calibration fed the land less than the old rule (as before)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsLandGateExactLoss { get; set; } = true;

        [SettingPropertyBool("Ks Hard Gates", HintText = "with Start Calibration: before the calibration starts in a campaign (by itself or with Confirm) the goods ledger must show at most 2 pieces a day of any good appearing from nowhere (daily ticks of unknown origin) and of food lost with removed parties over the last 7 full days, and the free food of supply convoys and Banner Kings parties must be shut off; until then it keeps waiting and the log says why. Off = only the older checks", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsHardGates { get; set; } = true;

        [SettingPropertyBool("Ks No Fish From Perk", HintText = "with Start Calibration: the Night Raider perk of a town's governor (War Sails) conjures fish each day for every village trading with that town (about 100 to 150 fish a day across the world, from no boat and no fisherman). While the calibration only surveys, those fish are written in the goods ledger as a known source and the game is unchanged; once it is applied the perk no longer makes them - fish come only from fishermen's hands (in a land sent back by the famine gate the perk works as before). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsNoFishFromPerk { get; set; } = true;

        [SettingPropertyBool("Start Calibration Auto Arm Autotest", HintText = "FOR THE AUTOTEST ONLY: while the CrashScribe autotest runs, the calibration takes the same self-arming path as a normal campaign (Start Calibration Auto Arm: arm on the first day, survey, safeguards, then start by itself) instead of starting at the first finished plan; the same as the file armoury-ks-auto.flag. In a normal game it does nothing", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationAutoArmAutotest { get; set; } = false;

        [SettingPropertyBool("Ks Patrol Grain From Town", HintText = "with Start Calibration: the 15 to 30 grain the game gives every new town patrol from nothing. While the calibration only surveys, that grain is written in the goods ledger as a known source and the game is unchanged; once it is applied the grain comes out of the home town's food stocks (nothing from nothing; a town without the stock still gives it, written as such; in a land sent back by the famine gate as before). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsPatrolGrainFromTown { get; set; } = true;

        [SettingPropertyBool("Ks Bk Ports In Ledger", HintText = "with Start Calibration: the fish that Banner Kings' town ports and harbours catch each day (paid from the town's gold) are written in the goods ledger under their own name instead of 'daily ticks of unknown origin', so the safeguard before the calibration starts counts only goods that truly come from nowhere. Ledger only - nothing in the game changes. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsBkPortsInLedger { get; set; } = true;

        [SettingPropertyBool("Ks Arm Mature From Use", HintText = "with Start Calibration Auto Arm: the 7 days of finished weekly plan the calibration waits before it starts by itself are counted from the first day that finished plan is actually in use, not from the last day of the data it was made from - so it starts at the earliest 28 + 7 days after it armed itself, as announced when it arms (off = 2 days earlier, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsArmMatureFromUse { get; set; } = true;

        [SettingPropertyBool("Ks Food Carts", HintText = "with the calibration applied: a town short of food buys grain, fish, meat, cheese, salt and the other foods in a town of the same market that has more than it needs, and the cart goes for as many days as the road (by sea a ship is four times faster and much cheaper than a cart). The buying town pays the selling town for every piece and the carters of the seller's villages (by sea - its dock hands) for the haul, only when the merchants gain on it, and never below half of the town merchants' reserve. Fish, meat, fruit and the other perishables go at most 7 days and lose a little on the way; off = no new food carts (carts on the road still arrive)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsFoodCarts { get; set; } = true;

        [SettingPropertyBool("Ks Food Carts Consign", HintText = "with Ks Food Carts: town merchants carry food on their own credit - the goods leave the selling town unpaid and the seller pays the carters or the ship's crew; on arrival the buying town pays what it has above half of its merchants' reserve at the price of its own stall, and the rest is written down as a bill it pays off day by day, oldest first. A town with a bill older than Ks Consign Overdue Days gets no new food carts until it pays; a war between the two towns cancels the bill (the merchants lose it). Gold only moves between the two towns and the carters - nothing is made or lost; off = the buying town pays everything when the cart sets out, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsFoodCartsConsign { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Consign Floor Share", 0.00f, 1.00f, "0.00", HintText = "with Ks Food Carts Consign: a town pays for food on arrival and pays off its food bills only from gold above this share of its merchants' reserve", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public float KsConsignFloorShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Ks Consign Source Exposure", 0.00f, 1.00f, "0.00", HintText = "with Ks Food Carts Consign: a selling town lets out on credit (goods on the road, their haul and bills not yet paid) at most this share of its gold", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public float KsConsignSourceExposure { get; set; } = 0.5f;

        [SettingPropertyInteger("Ks Consign Overdue Days", 1, 364, "0", HintText = "with Ks Food Carts Consign: a town whose oldest food bill is older than this many days gets no new food carts until it has paid it", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public int KsConsignOverdueDays { get; set; } = 30;

        [SettingPropertyBool("Ks Ship By Days", HintText = "with Ks Food Carts: a food cart goes by ship whenever the ship arrives sooner in days (the sea route counted at ship speed plus a day in port), not only when the sea route is shorter; the weekly plan reads the same days; off = by ship only when the land road is much longer, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsShipByDays { get; set; } = true;

        [SettingPropertyBool("Ks Far Always", HintText = "with Ks Food Carts: a town short of food also asks up to 8 towns further away that have food to sell (within the days a cart may travel), not only when none of the 12 nearest can sell; off = further towns only when the nearest have nothing, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsFarAlways { get; set; } = true;

        [SettingPropertyBool("Ks Rel Keep", HintText = "with Ks Food Carts: when the whole market is short of a food, a selling town keeps only about as many days of it as the market's middle town has (never less than half of its target) and sells the rest of its grain and salt and two thirds of the rest of its spare food; off = it always keeps a quarter more than its target and sells half of the rest, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsRelKeep { get; set; } = true;

        [SettingPropertyBool("Ks Dest Value", HintText = "with Ks Food Carts: the merchants judge a cart and the buying town pays for it at one price - the stall price of the buying town as it falls with every piece put on the stall, never more than three times the starting price; off = today's stall price for every piece, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsDestValue { get; set; } = true;

        [SettingPropertyBool("Ks Carts Budget By Need", HintText = "with Ks Food Carts: the food every town needs most - the shortest stock in days of its target - is served first, whatever the food, so a town's purse and a seller's credit are not eaten up by grain and fish before cheese, butter, grapes, olives and salt get a turn; off = food by food in a fixed order, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsCartsBudgetByNeed { get; set; } = true;

        [SettingPropertyBool("Ks Famine Priority", HintText = "with Ks Food Carts: a town whose grain, fish or meat stall holds less than half of its target in days (the North and the Wall in a hard winter, a besieged land's neighbours) gets the first claim on every seller in reach, by land or by sea - still paid for in full, on credit like every other cart; off = no famine priority", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsFaminePriority { get; set; } = true;

        [SettingPropertyBool("Ks Corridors Credit", HintText = "with Ks Land Gradient and Ks Food Carts Consign: the weekly plan counts the land routes as the merchants run them on credit - the days from the towns that need food to the three towns with most to spare, what the buying towns can pay above half of their reserve, and what the selling towns can carry on credit; off = the gates between lands and one purse per buying land, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsCorridorsCredit { get; set; } = true;

        [SettingPropertyBool("Ks Lot Price Pow", HintText = "with Ks Food Carts: the price of a whole cart load is reckoned from the game's own price formula piece by piece with two price checks instead of three sampled prices (the same money, closer to the exact sum); off = three sampled prices, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsLotPricePow { get; set; } = true;

        [SettingPropertyBool("Ks Carts Min Lot True Demand", HintText = "with Ks Food Carts: the smallest food cart the merchants send is half a day of what the buying town really buys (at least 5), also where its stall stands empty - before, a hungry town asking for up to two and a half times its daily need for a while also refused every offer below one and a quarter days of its need, so small sellers never served the towns that lacked most; off = the smallest cart grows with the town's extra order, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsCartsMinLotTrueDemand { get; set; } = true;

        [SettingPropertyBool("Ks Land Gradient", HintText = "with Start Calibration: the weekly plan sees the road - where food must come from far away it is dearer by the cost of the haul, so the peasants there grow more of it and their basket costs more, and where it cannot be sold it is cheaper. It counts what people there really pay for, and one purse per land for all its imports. The work of a hand stays the same, only how many hands work at each thing changes; off = the plan prices every market as one place", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsLandGradient { get; set; } = true;

        [SettingPropertyBool("Ks Alpha Net", HintText = "with Start Calibration: the plan gives each village only the money it really has for its basket - its takings plus haulage pay, less the war levy, dues and taxes on its savings - and what it cannot buy and cannot grow itself it makes at home from its own staple that feeds best (grain, fish, game or dates), as much as its hands and free land really yield; eggs, honey, carrots, apples and farm animals nobody buys stay on the village's own table; off = takings only and the plan's market correction as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsAlphaNet { get; set; } = true;

        [SettingPropertyBool("Ks Village Paid First", HintText = "with the calibration applied: a village first buys the part of its basket the plan says it can pay for (bread and salt first, then drink, meat and the rest), and the rest only from money beyond a week of its basket and only while the stall price is low (at most 4/5 of the starting price); its old daily shopping list beyond the basket stops and the Banner Kings village market buys no food and spends only money beyond a week of the basket; off = the whole basket along the ladder and the old list, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsVillagePaidFirst { get; set; } = true;

        [SettingPropertyBool("Ks Own Food First", HintText = "with the calibration applied: a village that could not buy the food the plan counted on eats from its own store waiting for the cart (grain first, at most half of each good a day) instead of sending it to market; off = it sells everything and goes without", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsOwnFoodFirst { get; set; } = true;

        [SettingPropertyBool("Ks Perish Reach", HintText = "with Start Calibration: fish, meat, fruit and the other goods that spoil are not counted on in a town that has none of its own and no town with plenty within 7 days by cart - its people buy other food instead; off = every town counts on every food", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsPerishReach { get; set; } = true;

        [SettingPropertyBool("Ks Real Offtake", HintText = "with the calibration applied: the stall price of a town counts what lords and courts really buy in that town (not a share of the whole world's armies and castles), and the town's bakers and brewers only what their hands can make; they keep 6 days of the grain and fruit people buy and make at most 4 days of bread and beer ahead; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsRealOfftake { get; set; } = true;

        [SettingPropertyBool("Ks Market Control", HintText = "with the calibration applied: from two to seven weeks after the start the weekly plan sends to market what people really bought and wanted (not what they bought from their savings), so that the stalls hold their starting stock; a land whose stalls fill up and keep filling (no way out - war or no buyer) moves a tenth of that work to home work each week. After seven weeks this steering fades out over two weeks and a village changes its home work by at most 2% of its hands a week - prices and profit move the hands; off = the plan keeps its own reckoning", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsMarketControl { get; set; } = true;

        [SettingPropertyBool("Ks Village Buy Every2", HintText = "with the calibration applied: villages shop for their basket every second day for two days at once (half the work for the game); off = every day", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsVillageBuyEvery2 { get; set; } = true;

        [SettingPropertyBool("Ks Granary Release", HintText = "with the calibration applied: a village's granary floor (the old harvest formula as the least it gets) comes off after 14 days in a row in which the village bought and ate what it needed, and comes back after 3 days of short rations; the granary then counts what the village bought and ate from its store, and beer and the better table are counted the same way on both sides; off = the floor stays on, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool KsGranaryRelease { get; set; } = true;

        [SettingPropertyBool("Start Calibration Town Crafts", HintText = "with the calibration applied: the town's craftsmen bake bread and pies and brew beer from the grain on the stall, press wine from grapes and oil from olives, make mead from honey, pots from clay and (in Lys, Volantis, Myr, Tyrosh and Pentos) garum from fish and salt - only while the product pays for its goods and work and the stall wants it (at most a week of what the town buys); off = only the workshops do it, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration (KS)")]
        public bool StartCalibrationTownCrafts { get; set; } = true;

        [SettingPropertyBool("Ks Self Feed First", HintText = "with Start Calibration: in every land (with Ks Self Feed Everywhere; off = only the cold lands - the North, beyond the Wall, the Night's Watch lands, Skagos, the Iron Islands, Ib) a village whose people go hungry first puts its hands to the food work that feeds the most mouths per hand on its own land - barley and oats, the byre, sheep and goats, fishing, the hunt - until its own people are fed, as far as its land and hands allow; only the hands left over follow the market (furs, wool, timber). A village that buys more food with its furs than its land would grow (after its lord's and the crown's share) keeps its trappers. What is still missing comes by cart and ship, as tribute to the Wall, or not at all. Off = every hand follows the price", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsSelfFeedFirst { get; set; } = true;

        [SettingPropertyBool("Ks Self Feed Everywhere", HintText = "with Ks Self Feed First: the same rule for every village in the world, not only in the cold lands (a silk, flax or horse village that cannot buy its bread grows its own bread first); off = only the villages of the cold lands, the villages of the warm lands sell their crop and buy their bread at market", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsSelfFeedEverywhere { get; set; } = true;

        [SettingPropertyBool("Ks Self Feed Own Food Only", HintText = "with Ks Self Feed First: the rule word for word - a hungry village of the cold lands counts only the food it grows itself and puts its hands to food first, even where its furs, wool or flax would buy more grain than its fields give (in the plan: more of the Free Folk fed from their own herds, but the North, the Iron Islands and Ib a little hungrier and less meat at market); off = a village counts what its goods buy after its lord's, the church's and the crown's share, and keeps its trappers where they feed more mouths", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsSelfFeedOwnFoodOnly { get; set; } = false;

        [SettingPropertyBool("Ks Self Feed Staples", HintText = "with Ks Self Feed First: a village counts only the food its people live on - bread grain, fish, meat, cheese and butter - as feeding it; its olives, grapes, oranges, apples, honey and eggs it sells like furs, and the bread it buys is reckoned at the usual price of its land (a village of olive groves or vineyards that cannot buy its bread puts hands to grain, fish or herds, not to more olives). Off = every food counts, at the plan's price of grain", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsSelfFeedStaples { get; set; } = true;

        [SettingPropertyBool("Ks Self Feed Slow", HintText = "with Ks Self Feed First: from one weekly plan to the next the share of a village's hands that the rule moves to food grows by at most 7 in 100, and falls by at most 7 in 100 wherever those hands can stay at food without taking them from work that feeds the village better (the first plan after loading a save - without this limit), so a village does not jump from the market to its fields and back every week. Off = the full move in every plan", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsSelfFeedSlow { get; set; } = true;

        [SettingPropertyBool("Ks Plan Markets Clear", HintText = "with Start Calibration: the weekly plan settles each market - when a market as a whole has fewer hands than its townsfolk pay for and the villages have no more home work to give up, the goods it lacks grow dearer in the plan for its townsfolk (at most 7 in 100 per round of the plan, at most three times the usual price) and the plan sets the villages' hands to what is really bought. This is only the plan's reckoning: the towns' demand in the game stays what their people pay for at the usual prices, so a real shortage still shows as dear prices, empty stalls and hunger (no coin is made or lost). The plan also takes smaller price steps for a good whose price keeps swinging back and forth. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsPlanMarketsClear { get; set; } = true;

        [SettingPropertyBool("Ks Plan Markets Clear Villages", HintText = "with Ks Plan Markets Clear: in the plan the villages buying at a market that lacks hands pay the same dearer price as its townsfolk, and grow more of their own food at home instead (one price for every buyer in the plan's reckoning; in the game there is always one price - the market's). Off = in the plan only the townsfolk see the dearer price; villages buy at the usual price and fall back on home work as before", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsPlanMarketsClearVillages { get; set; } = false;

        [SettingPropertyBool("Ks Cold Land", HintText = "with Start Calibration: the one table of what a worker makes on his land gets real yields for cold land - barley and oats on snowy ground at about a third of a lowland harvest, dairy cattle kept in the byre on hay through the winter, hardy sheep and goats, rich salmon rivers and lakes - and a hunter in the cold lands needs fifteen square kilometres of wild land, because game is only as plentiful as the land (the Free Folk cannot all live by the hunt; hunters of the warm lands as before). Off = the old table", RequireRestart = false)]
        [SettingPropertyGroup("KS round 4: feed yourself first and the yields of cold land (night 17/18.10)")]
        public bool KsColdLand { get; set; } = true;

        [SettingPropertyBool("Ks Hunger Unrest", HintText = "with the calibration applied: when a town's market holds less food than its townsfolk eat in a day (any food counts - the hungry eat the cheaper food first) or the town's granary is empty, the shortfall shows as Hunger in the town's loyalty and security, in proportion to the share of the people left unfed - a starving town drifts towards revolt by the game's own rules. The game's own penalty for an empty granary is not counted twice, and the 'well fed' bonus does not apply while people go hungry. Off = only the game's own food rules", RequireRestart = false)]
        [SettingPropertyGroup("Hunger and the town lord (KS round 4)")]
        public bool KsHungerUnrest { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Hunger Loyalty Max", 0.00f, 16.00f, "0.00", HintText = "with Ks Hunger Unrest: loyalty a town loses in a day when none of its people can eat (4 = about forty points lower in the long run, since the game draws loyalty back towards 50 by a tenth of the distance each day); less in proportion to the share left unfed", RequireRestart = false)]
        [SettingPropertyGroup("Hunger and the town lord (KS round 4)")]
        public float KsHungerLoyaltyMax { get; set; } = 4f;

        [SettingPropertyFloatingInteger("Ks Hunger Security Max", 0.00f, 8.00f, "0.00", HintText = "with Ks Hunger Unrest: security a town loses in a day when none of its people can eat; less in proportion to the share left unfed", RequireRestart = false)]
        [SettingPropertyGroup("Hunger and the town lord (KS round 4)")]
        public float KsHungerSecurityMax { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Ks Hunger Tolerance", 0.00f, 1.00f, "0.00", HintText = "with Ks Hunger Unrest or Ks Lord Funds Food: the share of the people's food a market may lack before anyone counts as hungry (0.1 = up to a tenth missing is made up in kitchens and gardens); above it the penalty grows in proportion", RequireRestart = false)]
        [SettingPropertyGroup("Hunger and the town lord (KS round 4)")]
        public float KsHungerTolerance { get; set; } = 0.1f;

        [SettingPropertyBool("Ks Lord Funds Food", HintText = "with the calibration applied: when a town goes hungry and its purse cannot pay the food merchants, the lord of the town pays them for the food they bring - from his gold above his war reserve and only from the part of his war chest that does not go to wages (the same pace as the bread for the poor), so he never spends faster than his war chest. The lord's coin goes only to what the merchants really deliver; the town's purse pays its own share first. Your own purse is never used. Off = the town pays alone, as before", RequireRestart = false)]
        [SettingPropertyGroup("Hunger and the town lord (KS round 4)")]
        public bool KsLordFundsFood { get; set; } = true;

        [SettingPropertyBool("Ks Consign Deposit", HintText = "with Ks Food Carts Consign: when a selling town has no more room to let food out on credit, the merchants of the buying town pay earnest money when the cart sets out - a share of what the load is worth at their own stall, only from gold above the floor of their reserve - and the seller carries only the rest on credit; on arrival the earnest money counts towards the price, anything paid in excess goes back (what the seller cannot repay at once becomes a bill he owes), and a cart that turns back returns it. The weekly plan counts the routes the same way. Gold only moves between the two towns - nothing is made or lost; off = the seller carries the whole load on credit or the cart does not go, as before", RequireRestart = false)]
        [SettingPropertyGroup("Food merchants: earnest money (KS round 5)")]
        public bool KsConsignDeposit { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Consign Deposit Share", 0.00f, 1.00f, "0.00", HintText = "with Ks Consign Deposit: the share of what the load is worth at the buying town's stall paid as earnest money when the cart sets out (0.5 = half now, half on arrival, as in a medieval grain contract)", RequireRestart = false)]
        [SettingPropertyGroup("Food merchants: earnest money (KS round 5)")]
        public float KsConsignDepositShare { get; set; } = 0.5f;

        [SettingPropertyBool("Ks Corridors War Cut", HintText = "with Ks Corridors Credit: the weekly plan does not count a land route on which every town with food to spare is at war with every town that needs it - the merchants cannot trade across the war - instead of taking the nearest pair of towns of the two lands that are at peace, and it counts the sellers' credit on a route only from the towns that are at peace with the buyers; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Food merchants: earnest money (KS round 5)")]
        public bool KsCorridorsWarCut { get; set; } = true;

        [SettingPropertyBool("Whale Meat From Whalers Only", HintText = "slaughter in town workshops (the hidden craftsmen and the butchers) yields meat, not whale meat - until now half of all the meat in the world was whale meat cut from pigs, cows and sheep, even in towns far from any sea. Whale meat now comes only from the whalers' villages: step by step over 60 days, up to about a third of what their boats bring in is whale meat instead of fish (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool WhaleMeatFromWhalersOnly { get; set; } = true;

        [SettingPropertyBool("Bk Recipe Yield By Workshop", HintText = "the hidden craftsmen of a town brew two jugs of beer from a sack of grain, as a brewery does, instead of one - step by step over 60 days (bread stays one loaf from a sack). The second jug is bought by the town merchants at the town's price only from the coin they have to spare, otherwise it is not brewed (off = one jug from a sack, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool BkRecipeYieldByWorkshop { get; set; } = true;

        [SettingPropertyBool("Silk To Weavers", HintText = "craftsmen first: the townsfolk buy raw silk for their homes only from what lies on the stall beyond two days of work for the town's velvet weavers, so the weavers always find their silk (until now the townsfolk took about 43 of the 47 bales the world brings in each day and the weavers 3). Comes in step by step over 60 days; what lies beyond the weavers' share still goes to the homes as before, so the silk farms keep their market. The coin the townsfolk do not spend on silk stays in their purse (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool SilkToWeavers { get; set; } = false;

        [SettingPropertyBool("Velvet Town Log", HintText = "every seventh day write a line to the log with velvet town by town: whether the town has a velvet weavery, the price and how much lies on its stall, and how far the nearest weavery is - only a measure, nothing in the game changes (off = no such line)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool VelvetTownLog { get; set; } = true;

        [SettingPropertyBool("Silver Ore To Smiths", HintText = "craftsmen first: the townsfolk buy silver ore only from what lies on the stall beyond two days of work for the town's workshops that work it, so they find their ore first. Comes in step by step over 60 days. Where no workshop works silver ore (there is no mint or silversmith line yet in most towns), the townsfolk buy it as before, so the silver mines keep their market; the coin they do not spend stays in their purse (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool SilverOreToSmiths { get; set; } = true;

        [SettingPropertyBool("Planks To Building", HintText = "sawn planks go to building works: step by step over 60 days the townsfolk stop using them up at home, and the works buy planks before their other materials (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool PlanksToBuilding { get; set; } = true;

        [SettingPropertyBool("Charcoal Burners", HintText = "the woodcutters' villages burn charcoal from the wood in their own store (6.5 kg of wood for 1 kg of charcoal) whenever the charcoal from a load fetches more in their market town than the load of wood itself - when charcoal piles up it gets cheap and they stop; at most one load of wood a village a day and one village a town a day (off = nobody makes charcoal, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool CharcoalBurners { get; set; } = true;

        [SettingPropertyBool("Iron Ingots Off Shelf", HintText = "iron bars of every grade lying on the stall of a town or castle (sold there by you - nobody else makes them) are taken by the town's smiths once a day and worked back into iron for the forges, at the same worth; the smiths' repairs then use ore and wood instead of the bars from the stall. The bars in your own bags stay yours (off = they lie on the stall, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool IronIngotsOffShelf { get; set; } = true;

        [SettingPropertyBool("Bk Side Goods Origin", HintText = "the side goods Banner Kings gives some villages come from where they belong, step by step over 60 days: the marble of the silver mines moves to the clay and limestone pits (the world keeps as much marble), and the woodcutters make less mead only by as much mead as the towns brewed from honey the day before - in its place they bring in wild forest honey (half as much by weight, mead is honey and water). While no town brews mead, the woodcutters keep making it, so mead never runs out. Papyrus already grows only in the hot south and the gold of the West stays exhausted (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool BkSideGoodsOrigin { get; set; } = false;

        [SettingPropertyBool("Cart Price By Destination", HintText = "a village cart gets the town's going price for as much of its salt, tools, linen, pots and beer as the villages trading in that town really bought there the day before, and for as much iron bloom as the town's smiths and bloomeries use in a day; only what is beyond that sells cheaper and cheaper as the stall fills up (until now every sack was priced as if nobody would ever buy it, and a salt cart got a fraction of the town's price). Comes in step by step over 60 days (off = every piece cheaper as the stall fills, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool CartPriceByDestination { get; set; } = true;

        [SettingPropertyBool("Bulk Clay Lime Charcoal", HintText = "NEW campaign only: clay and limestone come in loads of 100 kg, like ore and timber - a load is worth ten old sacks, so their price is no longer rounded up to a whole penny (two and five times their worth); potters still take the same kilograms of clay for a pot. Charcoal keeps its lump, because smithing burns it by the lump. A campaign started without it never changes (off = sacks of 10 kg, as before). Takes effect only when a new campaign is started", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool BulkClayLimeCharcoal { get; set; } = true;

        [SettingPropertyBool("Dte Convoy No Free Food", HintText = "a lord's supply convoy (Dynamic Troop Equipment) no longer sets out with 17 sacks of every kind of food made out of thin air - convoys do not eat on the road, and the food vanished with the convoy when it reached the army (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool DteConvoyNoFreeFood { get; set; } = true;

        [SettingPropertyBool("Bk Caravan No Free Food", HintText = "Banner Kings parties that never eat on the road - slave and food caravans, militias, estates and free companies - no longer get food made out of thin air when they set out (it was never eaten and was lost with the party, or added to the granary of the town a food caravan reaches). Travellers are already handled by Travellers Real Goods; bandit chiefs eat and keep theirs (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool BkCaravanNoFreeFood { get; set; } = true;

        [SettingPropertyBool("Goods Ledger Horses", HintText = "the goods ledger in the log also counts horses, camels and pack animals as capital: one line a day by kind of horse - how many there are, who holds them, where they come from and where they go (log only, changes nothing in the game; a change takes effect after loading a save; off = not counted)", RequireRestart = false)]
        [SettingPropertyGroup("Goods paths (ZC1, 16.10)")]
        public bool GoodsLedgerHorses { get; set; } = true;

        [SettingPropertyBool("Ks Ledger Current Recipes", HintText = "with Start Calibration applied and Ks Real Recipes: the goods ledger in the log counts the town craftsmen's meat and ale against the recipes in force (by weight) - until now it remembered the game's old recipes and showed some 1,700 pieces a day of meat and ale 'from nothing' that were never made, so a real leak could hide in that noise (log only; off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: goods ledger and slaughter hides (night 17/18.10)")]
        public bool KsLedgerCurrentRecipes { get; set; } = true;

        [SettingPropertyBool("Ks Hides By Table", HintText = "with Start Calibration applied and Ks Real Recipes: a beast slaughtered in a town - by the hidden craftsmen or at a butcher's - gives as many raw hides as the one world table counts for the same beast slaughtered in a village: 1.6 hides for a cow, 0.6 for a hog, 0.4 for a sheep (8, 5 and 10 kg of raw hide for each 100 kg of the beast). The fractions are tallied town by town and kept in the save; a whole hide reaches the stall each time a town's tally fills up. Until now a town sheep gave a whole hide (two and a half times a village sheep) and a butcher's cow five, and raw hides piled up unsold on every stall. Needs Artisan Own Inputs for the town craftsmen. Off = the recipes' round numbers, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: goods ledger and slaughter hides (night 17/18.10)")]
        public bool KsHidesByTable { get; set; } = true;

        [SettingPropertyBool("Dues Medieval", HintText = "the villages pay their lords and their king as they did in the Middle Ages: the lord's share, the tithe and - in war - the crown's share are taken from what the carts bring home, the moment they bring it, and a small fixed rent is paid first; nothing is taken any more as 'a share a day of whatever the village has saved' (the crown's war levy on village savings, the hoard tax, the lords' war levy from villages, the 5 percent Banner Kings village market). A village keeps three weeks of its needs and rent in its chest and spends on finer goods only what lies beyond it. The old takings fade out over Ds Ramp Days from the first day with this on (needs Town Folk Live; off by default until it is tested together with the village basket of the start calibration; off = the old rules from the next day)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public bool DuesMedieval { get; set; } = true;

        [SettingPropertyBool("Ds Village Cart Dues", HintText = "with Dues Medieval: the tithe (Tithe Village Share of the takings, half of it back as alms for the village poor, half to build septs) and, in war, the crown's share are taken at the cart, from the village's part of the takings, the moment the cart comes home; the crown's share is also taken from what soldiers pay a village for lodging and services. Off = the tithe is taken from the village purse once a day as before and the crown takes no share from villages", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public bool DsVillageCartDues { get; set; } = true;

        [SettingPropertyFloatingInteger("Ds War Share Village", 0.00f, 0.50f, "0.00", HintText = "with Dues Medieval: the crown's share of the village's part of the takings (after the tithe) for each step of war grant - one step in war (one and a half with the War Tax policy), none in peace; 0.10 = a tenth in war, as the 'ninth' of sheaves, fleeces and lambs was granted to Edward III. Nothing is taken from a village that is raided or looted, whose town or castle is besieged, or whose people go hungry", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public float DsWarShareVillage { get; set; } = 0.10f;

        [SettingPropertyBool("Ds Rent Arrears", HintText = "with Dues Medieval: the village's fixed rent (Village Dues Per Head Year) is paid first each day; what the purse cannot pay is written in the lord's book of arrears and paid first on the days after, instead of being lost. Off = unpaid rent is lost as before", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public bool DsRentArrears { get; set; } = true;

        [SettingPropertyInteger("Ds Rent Forgive Days", 0, 728, "0", HintText = "with Ds Rent Arrears: arrears older than this many days of rent are forgiven by the lord - the oldest debt goes first (0 = never forgiven)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public int DsRentForgiveDays { get; set; } = 364;

        [SettingPropertyBool("Ds Rent Remit Raided", HintText = "with Dues Medieval: on a day when the village's town or market town is besieged, or its people go hungry, the lord lets the day's rent go (a raided or looted village pays no rent anyway); the arrears wait. Off = the rent is due on those days too", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public bool DsRentRemitRaided { get; set; } = true;

        [SettingPropertyInteger("Ds Village Chest Days", 0, 90, "0", HintText = "with Dues Medieval: the village keeps this many days of its daily purchases and its rent in its chest for a black day - nothing beyond its daily needs and rent is spent below it, and the village lends to lords only from what lies above it", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public int DsVillageChestDays { get; set; } = 21;

        [SettingPropertyInteger("Ds Surplus Spend Days", 0, 120, "0", HintText = "with Dues Medieval: a village spends each day one part in this many of what its purse holds beyond its chest on finer goods - half on the townsfolk's list of finer goods in its market town, half at its Banner Kings village market (0 = it spends nothing beyond its daily needs)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public int DsSurplusSpendDays { get; set; } = 15;

        [SettingPropertyFloatingInteger("Ds Surplus Bk Share", 0.00f, 1.00f, "0.00", HintText = "with Dues Medieval: the share of a village's spending beyond its chest that goes to its Banner Kings village market; the rest goes to the finer goods in its market town (without the Banner Kings village market - all of it)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public float DsSurplusBkShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Ds Ramp Days", 0, 112, "0", HintText = "with Dues Medieval: over how many days the old takings from village savings fade out and the crown's share at the cart and the spending beyond the chest come in, from the first day with Dues Medieval on - a running campaign (an old save) changes over step by step (0 = at once)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public int DsRampDays { get; set; } = 28;

        [SettingPropertyBool("Ds Communal Works", HintText = "with Dues Medieval: what a village means to spend beyond its chest but finds no goods for on the shelves of its market town is spent on communal works - the church fabric, the mill, a bridge, the roads: three quarters as wages to the masons and carpenters of the market town, a quarter as material bought from its merchants (as the septs are built from the tithe). Off = what finds no goods stays in the village purse", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public bool DsCommunalWorks { get; set; } = true;

        [SettingPropertyInteger("Ds Rent Arrears Pay Days", 0, 364, "0", HintText = "with Ds Rent Arrears: a village pays off its rent arrears at one part in this many a day (at least one day's rent), and only from what its purse holds beyond the day's needs - the arrears never take its bread (0 = all at once, as far as the purse goes)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: villages (DS F1, 17.10)")]
        public int DsRentArrearsPayDays { get; set; } = 28;

        [SettingPropertyBool("Ks Bk Village Needs", HintText = "the Banner Kings village market of a village under the medieval dues or the start calibration buys what villagers really need - salt, tools (or iron for the smith), linen, woollen cloth and pots - and only as much as they use (Village Need Cover Days at most in the house); wine, spices, jewellery, velvet and furs only when the village is rich (Ks Bk Rich Chests); it pays only from what the purse holds beyond its chest for a black day, from a real daily budget that shrinks with every purchase (no longer one piece of everything the town has too much of, at 5 percent of the purse for each piece); a village buying its basket from the calibration plan buys no food and none of its basket goods there (the basket already buys them). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public bool KsBkVillageNeeds { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Bk Rich Chests", 1.00f, 20.00f, "0.0", HintText = "with Ks Bk Village Needs: a village counts as rich, and may buy wine, spices, jewellery, velvet and furs at its Banner Kings market, when its purse holds at least this many chests for a black day", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public float KsBkRichChests { get; set; } = 3.0f;

        [SettingPropertyInteger("Village Need Cover Days", 1, 91, "0", HintText = "with Ks Bk Village Needs or Ds Surplus Need Limit: a village keeps at most this many days of its salt, tools, linen, woollen cloth and pots in the house (by what its people use each day: a pinch of salt a day, a tool worn out in a year, a shirt and a pot every year or two) - it buys more of them beyond its daily shopping only when the house runs below that", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public int VillageNeedCoverDays { get; set; } = 7;

        [SettingPropertyBool("Ks Surplus Skips Basket", HintText = "with Start Calibration applied and Dues Medieval: a village that buys its daily basket from the plan at the stalls does not spend what lies beyond its chest again on the village list (salt, tools, linen, pots and ale) - its basket already buys all five as far as it needs them and at a fair price, and the extra buying stripped the stalls of salt down to five pieces at any price (one rule for one thing). What it would have spent on them stays in its purse; what finds no finer goods goes to communal works. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public bool KsSurplusSkipsBasket { get; set; } = true;

        [SettingPropertyBool("Ds Surplus Need Limit", HintText = "with Dues Medieval: a village without the calibration basket spends what lies beyond its chest on salt and tools only up to what its people use (Village Need Cover Days), no longer stripping the market stall to the last five sacks at any price; the coin meant for a need already met stays in its purse (only coin for a need still open that finds no goods goes to communal works). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public bool DsSurplusNeedLimit { get; set; } = true;

        [SettingPropertyBool("Ds Surplus Ledger Frame", HintText = "with Dues Medieval: the salt and tools a village buys from what lies beyond its chest are counted in the goods ledger as bought in its market town (until now as bought 'nowhere', so the start calibration saw too little salt eaten in the markets and too much salt left over). Without the start calibration it changes the count only; with it, these purchases also count as village demand in the market town, so the calibration's merchants bring that much more. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public bool DsSurplusLedgerFrame { get; set; } = true;

        [SettingPropertyBool("Ks Chest Paid Basket", HintText = "with the start calibration: a village's chest for a black day is three weeks of the basket the plan pays for (plus its rent), instead of three weeks of the old daily shopping list - the village keeps what it really has to spend each day. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public bool KsChestPaidBasket { get; set; } = true;

        [SettingPropertyInteger("Ks Granary Emergency Days", 0, 364, "0", HintText = "with Ks Granary No Floor: only when a village's granary has fallen below this many days of food does it get the game's harvest formula as a floor again (food from nothing, counted in the log as an emergency) - a hungry village eats its store down first (0 = never)", RequireRestart = false)]
        [SettingPropertyGroup("Village needs and the Banner Kings village market (KS round 4, 17.10)")]
        public int KsGranaryEmergencyDays { get; set; } = 60;

        [SettingPropertyBool("Ds Towns", HintText = "towns, castles and the crown pay as they did in the Middle Ages: after Ds Farm Measure Days of watching what the town and castle purses give up today, each town and castle owes its lord and its king a fixed farm (paid every week); the daily valve, the war aid from the people's savings, the hoard tax on the people and the purses, the war levy on town purses and the lords' war levy on the people stop; in war the realm grants the king a war grant each quarter (aids on sales, a tax on earnings, a tenth of movables, double customs, a larger vassal aid), and a king short of money for the wage refunds spends his treasure above the war reserve, then borrows from his burghers against the grant, and only then from the Iron Bank (needs Town Folk Live and Crown Current Income; off = the old rules from the next day)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsTowns { get; set; } = true;

        [SettingPropertyBool("Ks Real Recipes", HintText = "with Start Calibration applied: the workshops (and the hidden town artisans) turn food by weight, as the Plan counts it - 5 kg of olives for 1 kg of oil, 1.3 kg of grapes for 1 kg of wine, 1 kg of grain for 2.5 kg of ale or 1 kg of bread, half a beast's weight as meat - instead of the game's round numbers (1 olive -> 2 oil); off = the game's recipes", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool KsRealRecipes { get; set; } = true;

        [SettingPropertyBool("Ks Granary No Floor", HintText = "with Start Calibration applied: a village's granary gets only what its people really grow at home, buy and take from their own store - no longer the game's formula as a floor (food from nothing); a shortfall eats into the granary's store (about two years) and shows slowly, as a hungry spring; off = the old floor", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool KsGranaryNoFloor { get; set; } = true;

        [SettingPropertyInteger("Ds Farm Measure Days", 7, 91, "0", HintText = "with Ds Towns: for how many days the old valve of every town and castle (with the lord's part of the hoard tax and the lords' war levy on the people) is watched before the farms are set at what it gave on average - the farm is the old sum in a new form", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsFarmMeasureDays { get; set; } = 28;

        [SettingPropertyInteger("Ds Farm Renew Days", 0, 728, "0", HintText = "with Ds Towns: every this many days a farm is renewed towards the same share of what the merchants of the town or castle have taken in over the last 28 days as when it was set (0 = never renewed). Used only when Ds Farm Review Days is 0", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsFarmRenewDays { get; set; } = 364;

        [SettingPropertyFloatingInteger("Ds Farm Renew Max", 0.00f, 0.50f, "0.00", HintText = "with Ds Towns: a renewal moves a farm by at most this share up or down", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsFarmRenewMax { get; set; } = 0.15f;

        [SettingPropertyInteger("Ds Farm Distraint Terms", 1, 8, "0", HintText = "with Ds Towns: after a town has owed part of its farm over this many quarter days in a row, its lord and king take the arrears from the commune's purse (at most two thirds of it on a farm day)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsFarmDistraintTerms { get; set; } = 2;

        [SettingPropertyInteger("Ds Farm Forgive Weeks", 0, 156, "0", HintText = "with Ds Towns: arrears of a farm beyond this many weekly instalments are forgiven (0 = never forgiven)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsFarmForgiveWeeks { get; set; } = 52;

        [SettingPropertyFloatingInteger("Ds Farm Floor Share", 0.00f, 1.00f, "0.00", HintText = "with Ds Towns: a town or castle pays its farm, the aids and its tenth from its purse only down to this share of the merchants' working coin; what it cannot pay is written in the book of arrears", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsFarmFloorShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Ds Merchant Draw Days", 0, 120, "0", HintText = "with Ds Towns: each day the merchants take one part in this many of what the purse holds beyond one and a half times their working coin as their own earnings (in a town 70 percent to the patricians, 30 to the craftsmen; in a castle to the castle folk) - in place of the people's share of the old valve (0 = nothing)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsMerchantDrawDays { get; set; } = 28;

        [SettingPropertyFloatingInteger("Ds Merchant Draw P Share", 0.00f, 1.00f, "0.00", HintText = "with Ds Towns: the patricians' share of the merchants' draw in a town; the craftsmen get the rest", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsMerchantDrawPShare { get; set; } = 0.7f;

        [SettingPropertyFloatingInteger("Ds Aides Rate", 0.000f, 0.100f, "0.000", HintText = "with Ds Towns: the war aid on sales (the aides, the alcabala) for each step of war grant - a share of what the town or castle purse sold that day", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsAidesRate { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Ds Aides Max", 0.00f, 0.30f, "0.00", HintText = "with Ds Towns: the highest war aid on sales", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsAidesMax { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Ds Tallage Rate", 0.000f, 0.100f, "0.000", HintText = "with Ds Towns: the war tax on the people's earnings for each step of war grant (labourers pay half of it, craftsmen all of it, patricians one and a half times it; castle folk all of it) - set once a quarter in place of the weekly step", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsTallageRate { get; set; } = 0.05f;

        [SettingPropertyFloatingInteger("Ds Tallage Max", 0.00f, 0.30f, "0.00", HintText = "with Ds Towns: the highest war tax on earnings without the War Tax policy", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsTallageMax { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Ds Tallage Max Policy", 0.00f, 0.30f, "0.00", HintText = "with Ds Towns: the highest war tax on earnings with the War Tax policy", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsTallageMaxPolicy { get; set; } = 0.15f;

        [SettingPropertyFloatingInteger("Ds Movables Rate", 0.00f, 0.30f, "0.00", HintText = "with Ds Towns: the tenth of movables - for each step of war grant, this share of the people's savings above their reserve days (and of the purse above one and a half times the merchants' working coin) is granted for the quarter and paid in 13 weekly instalments", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsMovablesRate { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Ds Customs War Multiplier", 1.00f, 6.00f, "0.0", HintText = "with Ds Towns: in war the customs are this many times heavier (the maltolt; with Crown Duty on top)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsCustomsWarMultiplier { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Ds Vassal Aid War Percent", 0.00f, 33.00f, "0.0", HintText = "with Ds Towns: the vassal aid owed to the crown in war, as a share of a house's daily income from its lands (in peace - Crown Dues Peace Percent)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsVassalAidWarPercent { get; set; } = 10f;

        [SettingPropertyFloatingInteger("Ds Grant Max", 0.50f, 4.00f, "0.0", HintText = "with Ds Towns: the highest war grant a realm may get in a quarter", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsGrantMax { get; set; } = 2f;

        [SettingPropertyFloatingInteger("Ds Grant Step", 0.10f, 1.00f, "0.0", HintText = "with Ds Towns: war grants are whole steps of this size, and a grant changes by at most one step from one quarter to the next (the first grant of a war is set freely)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsGrantStep { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("Ds Grant Rents Keep", 0.00f, 1.00f, "0.00", HintText = "with Ds Towns: when the crown reckons what it will need in the quarter, it counts this share of the rents it paid its houses before the farms were set", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsGrantRentsKeep { get; set; } = 0.5f;

        [SettingPropertyInteger("Ds Grant Session Days", 1, 91, "0", HintText = "with Ds Towns: after this many days of peace the war grant ends, and after this many days of a new war the realm grants a first war grant, without waiting for the next quarter day", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsGrantSessionDays { get; set; } = 14;

        [SettingPropertyBool("Ds Refund Treasury First", HintText = "with Dues Medieval or Ds Towns: a crown short of money for the wage refunds first spends its treasure above the war reserve, before it borrows (debts are not taken off the treasure - only the Iron Bank instalments due in the next 28 days are kept back)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsRefundTreasuryFirst { get; set; } = true;

        [SettingPropertyBool("Ds War Grant Treasury First", HintText = "with Ds Towns: a king with a full treasury first pays for his war from his own treasure. What the treasury holds above its war reserve and above its debts to the Iron Bank and the towns pays the wage refunds and the war aid to the houses before the people are taxed (how it is spent - Ds War Grant Treasury To Reserve); while it does, the war grant may be nothing and the people pay no war aids, war tax on earnings or tenth that quarter (with the War Tax policy one step is still granted). Mercenary contracts, the Iron Bank's instalments, gifts, reparations and the price of allies called to war are paid from the day's income, so the people still grant what that income lacks for them (on a day the income falls short of them, see Ds War Grant Treasury Pays Dues). A grant changes by at most one step a quarter as before. When such a treasury falls to its war reserve, the realm grants a war grant the next day - unless the quarter day is no more than Ds Grant Session Days away, then on the quarter day. Off = the war grant follows the lack alone, as before", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsWarGrantTreasuryFirst { get; set; } = true;

        [SettingPropertyBool("Ds War Grant Treasury To Reserve", HintText = "with Ds War Grant Treasury First: the king pays for his war from his treasure for as long as it holds more than his war reserve and his debts, and the people give no war grant until the treasury falls to that reserve. A treasure that would not last Ds Grant Session Days of what the crown lacks counts as already at the reserve. Off = the treasure above the reserve is spread over the quarter, and each quarter the people pay the part of the lack it does not cover", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsWarGrantTreasuryToReserve { get; set; } = true;

        [SettingPropertyBool("Ds War Grant Treasury Pays Dues", HintText = "with Ds War Grant Treasury First: while a king pays for his war from his treasure and the realm gives no war grant, what the day's income lacks for the Iron Bank's instalments, the mercenary contracts and the price of allies called to war is paid from the treasure above the war reserve and the debts, so nothing goes unpaid while the treasury has money. Off = these are paid only from the day's income, as before", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsWarGrantTreasuryPaysDues { get; set; } = true;

        [SettingPropertyBool("Ds War Grant Treasury Covers Dues", HintText = "with Ds War Grant Treasury To Reserve and Ds War Grant Treasury Pays Dues: the treasure above the war reserve and the debts also carries the Iron Bank's instalments, the mercenary contracts and the price of allies called to war, so a king whose ordinary income does not cover them still asks the people for no war grant while his treasury can carry them; the war grant comes back when the treasury falls to the war reserve. Gifts and reparations are still paid only from the day's income. Off = these dues are left to the war grant whenever the ordinary income does not cover them, as before", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsWarGrantTreasuryCoversDues { get; set; } = true;

        [SettingPropertyBool("Ds Anticipation Loans", HintText = "with Ds Towns: then the burghers of the realm lend the crown against the instalments of the war grant not yet paid (Crown Town Loan Rate Year a year); the loan is repaid first from those instalments, and what is left after the quarter becomes ordinary crown debt to the towns (needs Crown Town Loans)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsAnticipationLoans { get; set; } = true;

        [SettingPropertyFloatingInteger("Ds Crown Loan Limit Days Pledged", 0.00f, 728.00f, "0", HintText = "with Ds Towns: a crown borrowing from the Iron Bank pledges its customs - it may owe the Bank this many days of its average taxes, and while it is in arrears the Bank takes its customs until it has paid in full for 28 days (the Bank never forgives)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public float DsCrownLoanLimitDaysPledged { get; set; } = 365f;

        [SettingPropertyInteger("Ds Folk Surplus Spend Days", 0, 120, "0", HintText = "with Ds Towns: townsfolk spend each day one part in this many of what they hold above their reserve days (in place of Folk Surplus Spend Share), coming in over Ds Ramp Days after the farms are set (0 = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public int DsFolkSurplusSpendDays { get; set; } = 15;

        [SettingPropertyBool("Ds Farm Folk From Savings", HintText = "with Ds Towns: the part of a town's or castle's farm that stands for what the lord used to take from the people's savings (his part of the hoard tax and his war levy on the people) is raised from the people's savings above their reserve days, as a commune raised its farm from its burgesses (scot and lot); the merchants' purse pays only the part that stands for the old valve. Off = the merchants' purse pays the whole farm", RequireRestart = false)]
        [SettingPropertyGroup("Medieval dues: towns, castles and crown (DS F3, 17.10)")]
        public bool DsFarmFolkFromSavings { get; set; } = true;

        [SettingPropertyInteger("Ds Farm Review Days", 0, 364, "0", HintText = "with Ds Towns: every this many days (a quarter) each farm of a town or castle is reviewed up or down towards the same share of what its merchants have taken in over the last 28 days as when it was set, by at most Ds Farm Renew Max - a town that does well pays more, a town that does badly pays less. A town that still owes part of its farm is never raised. 0 = the old renewal every Ds Farm Renew Days", RequireRestart = false)]
        [SettingPropertyGroup("Town purses and food merchants (economy review 18.10)")]
        public int DsFarmReviewDays { get; set; } = 91;

        [SettingPropertyInteger("Ds Farm Arrears Review Terms", 0, 8, "0", HintText = "with Ds Farm Review Days: a town or castle that has owed part of its farm over this many quarter days in a row, and still owes it, has its farm lowered by the full Ds Farm Renew Max at its next review, whatever its merchants have taken in - or already on a quarter day, if its own review is further off and a quarter has passed since the last one. A farm never changes more than once a quarter (0 = it is reviewed like any other)", RequireRestart = false)]
        [SettingPropertyGroup("Town purses and food merchants (economy review 18.10)")]
        public int DsFarmArrearsReviewTerms { get; set; } = 2;

        [SettingPropertyFloatingInteger("Ks Lord Food Bills Early Share", 0.00f, 1.00f, "0.00", HintText = "with Ks Lord Funds Food and Ks Food Carts Consign: the lord of a town pays the town's food bills that are older than this share of Ks Consign Overdue Days (0.67 of 30 days = 20 days), oldest first, from his gold above his war reserve and at the same pace as before - for every town of his, not only a hungry one - so that a bill never grows old enough to stop the food carts. Your own purse is never used. 0 = he pays only a hungry town's bills once they are overdue, as before", RequireRestart = false)]
        [SettingPropertyGroup("Town purses and food merchants (economy review 18.10)")]
        public float KsLordFoodBillsEarlyShare { get; set; } = 0.67f;

        [SettingPropertyBool("Ks Food Carts Return Keeps Goods", HintText = "a food merchants' cart that turns back (war, a lost town, too long on the road) puts its whole load back on the stall of the selling town; whatever of the price the selling town cannot hand back at once becomes a bill it owes the buying town, paid off day by day like any bill. A cart whose buying and selling towns are both gone unloads at the nearest town. Nothing paid for is lost. Off = the goods the selling town cannot repay are lost, as before", RequireRestart = false)]
        [SettingPropertyGroup("Town purses and food merchants (economy review 18.10)")]
        public bool KsFoodCartsReturnKeepsGoods { get; set; } = true;

        [SettingPropertyBool("Ks Cheap Basket", HintText = "with Start Calibration applied: a household that cannot pay for its whole basket first buys enough of the cheapest food on its market (grain, bread, pie or fish - whichever gives the most calories for a coin and is on the stall) to feed everyone, then salt, protein (cheapest first), drink (cheapest first) and the rest; meat, wine and cheese come only from what is left. The market and the plan see the basket really bought, so prices and fields follow it. Off = the old basket ladder", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: cheaper basket and wages by hands (r4-koszyk)")]
        public bool KsCheapBasket { get; set; } = true;

        [SettingPropertyBool("Ks Wage By Hands", HintText = "with Start Calibration applied: in a town whose employers lack hands (the region has lost its free men to war and service, or the town's food crafts work at full stretch) the townsfolk's wages rise a little each week; where hands are plentiful they drift back. The extra pay comes out of the town's coffer (the merchants and masters who hire), never from nothing. Off = wages as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: cheaper basket and wages by hands (r4-koszyk)")]
        public bool KsWageByHands { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Wage Hands Step Percent", 0.00f, 10.00f, "0.0", HintText = "with Ks Wage By Hands: how much the town's wage level moves in a week (percent), up where hands are short and back down where they are plentiful", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: cheaper basket and wages by hands (r4-koszyk)")]
        public float KsWageHandsStepPercent { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Ks Wage Hands Max", 1.00f, 2.00f, "0.00", HintText = "with Ks Wage By Hands: the highest wage level a shortage of hands can bring (times the usual wage of the town)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: cheaper basket and wages by hands (r4-koszyk)")]
        public float KsWageHandsMax { get; set; } = 1.3f;

        [SettingPropertyBool("Ks Wage Hands Down", HintText = "with Ks Wage By Hands: where hands are plentiful (the region's figures show many free men and the town's food crafts stand half idle) the labourers' wage level keeps falling each week by the same step below the usual wage, down to Ks Wage Hands Floor - the other side of the same rule: the merchants pay the labourers less and keep the difference. Works only together with the quarterly farm review of the towns (Ds Farm Review Days above 0, Ds Towns on and the town farms already fixed after Ds Farm Measure Days), so that what the merchants keep goes on to the lord and the crown through the farm; until then wages do not fall below the usual wage. A town without such figures is never cut. Craftsmen's pay is not cut, and labourers with less than Ks Labour Basket Low Days of their basket saved are always paid at least the usual wage; the cut comes in step by step between Ks Labour Basket Low Days and Ks Labour Basket High Days. Off = wages never fall below the usual wage", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public bool KsWageHandsDown { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Wage Hands Floor", 0.30f, 1.00f, "0.00", HintText = "with Ks Wage Hands Down: the lowest wage level plentiful hands can bring for the labourers (times the usual wage of the town)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsWageHandsFloor { get; set; } = 0.6f;

        [SettingPropertyBool("Ks Labour To Basket", HintText = "with Start Calibration applied: the town sets the labourers' wage by what their basket costs on its market, as medieval towns set wages by the price of bread. While the labourers hold no more than Ks Labour Basket Low Days of their basket in savings they get the full rate; the more they hold above that, the lower the rate the merchants, the masters and the wealthy households pay them, down to Ks Labour Basket Min of the rate at Ks Labour Basket High Days. The employers keep what they do not pay - nothing comes from nothing. Off = the labourers get the full rate however much they hold", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public bool KsLabourToBasket { get; set; } = true;

        [SettingPropertyBool("Ks Labour Basket Households", HintText = "with Ks Labour To Basket: the craftsmen and patricians who pay labourers from their savings above their reserve pay them at the same assessed rate as the merchants do, and keep the rest for their own spending (off = they pay labourers the full rate)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public bool KsLabourBasketHouseholds { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Labour Basket Low Days", 1.00f, 120.00f, "0", HintText = "with Ks Labour To Basket: up to this many days of their basket in savings the labourers get the full rate (and below it no wage cut of any kind applies)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsLabourBasketLowDays { get; set; } = 15f;

        [SettingPropertyFloatingInteger("Ks Labour Basket High Days", 2.00f, 240.00f, "0", HintText = "with Ks Labour To Basket: at this many days of their basket in savings and above, the labourers get Ks Labour Basket Min of the full rate", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsLabourBasketHighDays { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Ks Labour Basket Min", 0.00f, 1.00f, "0.00", HintText = "with Ks Labour To Basket: the lowest share of the full rate the labourers get when they hold Ks Labour Basket High Days of their basket or more (the rate settles where the labourers' purse stops growing, usually well above this floor)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsLabourBasketMin { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Ks Labour Basket Step Percent", 0.50f, 20.00f, "0.0", HintText = "with Ks Labour To Basket: how much the labourers' rate may change in one day (percent of the full rate), so a cheaper basket does not cut wages overnight", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsLabourBasketStepPercent { get; set; } = 3f;

        [SettingPropertyFloatingInteger("Ks Labour Basket Hoard Rate", 0.000f, 0.100f, "0.000", HintText = "with Ks Labour To Basket and Ds Hoard Due: in a town where the labourers' wage follows their basket, the lord's tallage on the labourers' hoard above their normal level falls from Ds Hoard Due Rate to this share a day as the labourers' rate falls to Ks Labour Basket Min (never more than Ds Hoard Due Rate) - an occasional tallage, since the wage no longer fills their purses; the lord's income does not drop overnight. Craftsmen, patricians, castle folk and villages pay Ds Hoard Due Rate as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: labourers' wages follow their basket (18.10)")]
        public float KsLabourBasketHoardRate { get; set; } = 0.01f;

        [SettingPropertyBool("Ks Folk Income All Kinds", HintText = "with Ks Labour To Basket: in a town under the start calibration the labourers' other earnings - serving soldiers, caravans and bands, the court, building work, mines and craft wages - follow their basket too, by the same rule as their wages from the merchants (its own rate, moving at most Ks Labour Basket Step Percent a day, so nothing changes overnight). What the labourers are not paid stays with the town's merchants. Off = only the merchants' wages and the households' wages follow the basket, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFolkIncomeAllKinds { get; set; } = true;

        [SettingPropertyBool("Ks Folk Income R P", HintText = "with Ks Labour To Basket: in a town under the start calibration the craftsmen and the patricians earn by their own baskets as well - their share of the merchants' work, of the merchants' draw, of the turnover and of the town's outside earnings falls once they hold more than their low days of savings, down to Ks Folk Income Min at their high days; the merchants (or the patrician who pays a craftsman from his savings) keep the rest. Below their low days they always get the full rate. Off = craftsmen and patricians earn at the full rate however much they hold", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFolkIncomeRP { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Folk Income R Low Days", 1.00f, 120.00f, "0", HintText = "with Ks Folk Income R P: up to this many days of their basket in savings the craftsmen get the full rate (21 = their reserve for hard times)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomeRLowDays { get; set; } = 21f;

        [SettingPropertyFloatingInteger("Ks Folk Income R High Days", 2.00f, 240.00f, "0", HintText = "with Ks Folk Income R P: at this many days of their basket in savings and above, the craftsmen get Ks Folk Income Min of the full rate", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomeRHighDays { get; set; } = 42f;

        [SettingPropertyFloatingInteger("Ks Folk Income P Low Days", 1.00f, 120.00f, "0", HintText = "with Ks Folk Income R P: up to this many days of their basket in savings the patricians get the full rate (30 = their reserve for hard times)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomePLowDays { get; set; } = 30f;

        [SettingPropertyFloatingInteger("Ks Folk Income P High Days", 2.00f, 240.00f, "0", HintText = "with Ks Folk Income R P: at this many days of their basket in savings and above, the patricians get Ks Folk Income Min of the full rate", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomePHighDays { get; set; } = 60f;

        [SettingPropertyFloatingInteger("Ks Folk Income Min", 0.00f, 1.00f, "0.00", HintText = "with Ks Folk Income R P: the lowest share of the full rate craftsmen and patricians get when they hold their high days of savings or more (the rate settles where their purse stops growing, usually above this floor)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomeMin { get; set; } = 0.10f;

        [SettingPropertyFloatingInteger("Ks Folk Income Step Percent", 0.50f, 20.00f, "0.0", HintText = "with Ks Folk Income R P: how much the craftsmen's and patricians' rate may change in one day (percent of the full rate)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFolkIncomeStepPercent { get; set; } = 3f;

        [SettingPropertyBool("Ks Folk Income Hoard Falls", HintText = "with Ks Folk Income R P and Ds Hoard Due: in a town where craftsmen and patricians earn by their basket, the lord's tallage on their hoard above the normal level falls from Ds Hoard Due Rate to Ks Labour Basket Hoard Rate as their rate falls to Ks Folk Income Min - an occasional tallage, as for the labourers. Off = they pay Ds Hoard Due Rate as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFolkIncomeHoardFalls { get; set; } = true;

        [SettingPropertyBool("Ks Folk Income Zero Need", HintText = "with Ks Labour To Basket: in a town under the start calibration whose market sets no basket at all for a class (the day's reckoning is done, but that class needs nothing there - frontier camps, khalasars), that class counts as fully provided and its rate falls to the lowest, instead of being paid the full rate into a purse it cannot spend. Off = such a class keeps the full rate, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFolkIncomeZeroNeed { get; set; } = true;

        [SettingPropertyBool("Ks Farm Follows Surplus", HintText = "with Ds Towns and the start calibration applied in a town: when the town's purse holds more than one and a half times the merchants' working coin, its farm is raised every Ks Farm Surplus Review Days by what the purse grew since the last raise (at most Ks Farm Surplus Review Max of the farm at a time), and the regular review does not lower the farm while that surplus lasts (unpaid farm still lowers it). A town whose craftsmen or patricians hold less than their low days of savings gets no such raise - the merchants' surplus goes to their households first, through the merchants' draw. What the townsfolk are no longer paid thus goes on to the lord and the crown through the farm instead of piling up in the purse. Off = only the regular review, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFarmFollowsSurplus { get; set; } = true;

        [SettingPropertyInteger("Ks Farm Surplus Review Days", 7, 91, "0", HintText = "with Ks Farm Follows Surplus: how many days the town's purse is watched before its farm is raised by what the purse grew (7 at the least)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public int KsFarmSurplusReviewDays { get; set; } = 14;

        [SettingPropertyFloatingInteger("Ks Farm Surplus Review Max", 0.00f, 1.00f, "0.00", HintText = "with Ks Farm Follows Surplus: the largest raise of a town's farm at one such review (share of the farm)", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public float KsFarmSurplusReviewMax { get; set; } = 0.25f;

        [SettingPropertyBool("Ks Farm Surplus Net Of Dues", HintText = "with Ks Farm Follows Surplus: the regular review counts a town's purse as holding a surplus only above the coin it already holds for its dues: the part of the next farm instalment gathered since the last payday (the whole instalment on payday, a seventh of it the day after), unpaid farm and sales aid, the next war tithe instalment and the rest of a catch-up. So the coin gathered for the next instalment does not keep a farm the town cannot carry from being lowered. Off = the whole purse counts, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: every town class earns by its basket (18.10)")]
        public bool KsFarmSurplusNetOfDues { get; set; } = true;

        [SettingPropertyBool("Ks Farm Catch Up", HintText = "with Ks Farm Follows Surplus: when a town's farm is reviewed for its merchants' surplus and the purse kept growing, the town also pays once - to its lord and the crown, in the shares of its farm - Ks Farm Catch Up Share of the coin that lay in the purse the whole review period above one and a half times the merchants' working coin plus Ks Farm Catch Up Keep Days of the farm (open food bills of the town are counted first). Like an entry fine when a farm is renewed at a higher rate: the yearly farm itself is not raised by it, so a good season does not become a lasting due. Not in towns whose craftsmen or patricians are short, not under siege, not with unpaid farm. Off = the merchants' surplus stays in the purse, as before", RequireRestart = false)]
        [SettingPropertyGroup("Town purses: the farm catches up with the merchants' idle coin (18.10)")]
        public bool KsFarmCatchUp { get; set; } = true;

        [SettingPropertyFloatingInteger("Ks Farm Catch Up Share", 0.05f, 1.00f, "0.00", HintText = "with Ks Farm Catch Up: the share of the idle coin above the merchants' keep that the town pays at one such review (the rest stays for the next review)", RequireRestart = false)]
        [SettingPropertyGroup("Town purses: the farm catches up with the merchants' idle coin (18.10)")]
        public float KsFarmCatchUpShare { get; set; } = 0.5f;

        [SettingPropertyInteger("Ks Farm Catch Up Keep Days", 0, 182, "0", HintText = "with Ks Farm Catch Up: how many days of its farm a town's merchants always keep in the purse above one and a half times their working coin, out of reach of the catch-up", RequireRestart = false)]
        [SettingPropertyGroup("Town purses: the farm catches up with the merchants' idle coin (18.10)")]
        public int KsFarmCatchUpKeepDays { get; set; } = 28;

        [SettingPropertyBool("Ks Farm Catch Up One Off", HintText = "with Ks Farm Catch Up: the catch-up a town pays its lord and crown is counted as a one-off payment, not as steady income from the land: it no longer raises the lord's steady income (and with it his war reserve, wage ceiling, court, dues and credit limit) for the following weeks, and the crown does not count it among its usual income when it asks its lords and towns for a war grant. The coin paid is the same. Off = the catch-up is counted like the town's yearly farm, as before", RequireRestart = false)]
        [SettingPropertyGroup("Town purses: the farm catches up with the merchants' idle coin (18.10)")]
        public bool KsFarmCatchUpOneOff { get; set; } = true;

        [SettingPropertyBool("Ks Price Restart", HintText = "with Start Calibration applied: the towns' 28-day price averages start again when the new basket demand has fully come in (two weeks after the start shelves), so the weeks after measure the new market and not the old prices; a line with today's prices is written every week; off = the averages start only at the start shelves", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsPriceRestart { get; set; } = true;

        [SettingPropertyBool("Ks Gap Margin", HintText = "with Start Calibration applied (needs Ks Market Control): from the plan that switches the calibration on until four weeks after the start shelves, the plan counts up to a quarter more market demand for each food whose town stalls hold less than their starting stock, so villages take hands off home work and grow more for the market (the towns buy it) until the stalls are full; the village works themselves are not reset for it, so nothing is overgrown once the stalls are full; off = 3% more of everything", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsGapMargin { get; set; } = true;

        [SettingPropertyBool("Ks Ctl Per Town", HintText = "with Start Calibration applied (needs Ks Market Control): the weekly market steering counts what the towns with nearly empty stalls wanted and could not buy, town by town (not against the whole market's stalls), and never cuts a food while a quarter of its buyers sit at nearly empty stalls - empty stalls are a carting problem, not a reason to grow less; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsCtlPerTown { get; set; } = true;

        [SettingPropertyBool("Ks Land Glut Guard", HintText = "with Start Calibration applied: a land whose stalls fill up and keep filling has its work cut only when the market's towns in the middle hold their starting stock; while half the market's towns are short, the full land is a carting problem and nothing is cut; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsLandGlutGuard { get; set; } = true;

        [SettingPropertyBool("Ks Made7 Derived", HintText = "with Start Calibration applied (needs Ks Real Offtake): the town price of grain, grapes, olives, honey, clay and beasts counts as the bakers', vintners', pressers' and butchers' input only what they really made over the last week (plus what refills their stall), not what they could make; off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsMade7Derived { get; set; } = true;

        [SettingPropertyBool("Ks Ctl Own Food", HintText = "with Ks Market Control: the weekly market steering counts the food a village ate from its own store waiting for the cart (when it bought less than the plan paid for) as eaten from that market - it was grown for the market and it fed the market's buyers, it only never reached the stall; the part of a village's paid basket missing at the stall that it covered with the same food from its own store no longer counts as missing as well. Before, the plan's market supply held it but the market's use did not, so the steering cut foods the villages ate at home (Essos fish about 7%). Off = only what was bought at the stalls counts, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsCtlOwnFood { get; set; } = true;

        [SettingPropertyBool("Ks Ctl Own Same Food", HintText = "with Ks Ctl Own Food: the market steering counts as eaten from the market only the food a village ate from its own store in place of the same food missing at the stall (its own fish for the fish it could not buy). Food it ate in place of another missing food (its fish because there was no grain) no longer counts as fish eaten - the missing grain already counts as missing, so the same hunger was counted twice and the steering grew more fish while fish piled up on the stalls; off = all the food a village ate from its store counts, as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsCtlOwnSameFood { get; set; } = true;

        [SettingPropertyBool("Ks Cloth Demand", HintText = "with Start Calibration applied: the Plan counts the linen, felt and leather that army clothing, arms workshops and smiths' repairs use up, so villages grow enough flax and wool and keep enough hides for them (the town weavers' own flax and wool are already counted in the cloth); off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration, round 4: prices and market steering")]
        public bool KsClothDemand { get; set; } = true;

        [SettingPropertyBool("Wall Grain Tribute", HintText = "with Start Calibration applied: the lords of the North send the Night's Watch part of their grain as a duty in kind - carts take it from the granaries of their villages (only from what lies beyond their own reserve, never from a hungry village) and bring it after the days of the road to the granaries of the Watch's villages, as much as the Watch's people lack each day; nobody pays for it, and a little spoils on the road. Off = no tribute (carts already on the road still arrive)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public bool WallGrainTribute { get; set; } = true;

        [SettingPropertyInteger("Wall Tribute Target Days", 0, 728, "0", HintText = "with Wall Grain Tribute: besides the daily shortfall the North sends enough to bring each Watch village's granary up to this many days of its people's food (over Wall Tribute Refill Days)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int WallTributeTargetDays { get; set; } = 365;

        [SettingPropertyInteger("Wall Tribute Refill Days", 1, 364, "0", HintText = "with Wall Grain Tribute: over how many days a Watch granary below Wall Tribute Target Days is filled up again", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int WallTributeRefillDays { get; set; } = 60;

        [SettingPropertyInteger("Wall Tribute Giver Reserve Days", 0, 728, "0", HintText = "with Wall Grain Tribute: a village of the North gives only from what its granary holds beyond this many days of its own people's food", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int WallTributeGiverReserveDays { get; set; } = 364;

        [SettingPropertyFloatingInteger("Wall Tribute Giver Share Percent", 0.00f, 10.00f, "0.00", HintText = "with Wall Grain Tribute: at most this share (percent a day) of what a Northern granary holds beyond its reserve goes to the Wall; lands that cannot feed themselves give less, in proportion to how much of their food they grow", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public float WallTributeGiverSharePercent { get; set; } = 1f;

        [SettingPropertyFloatingInteger("Wall Tribute Spoil Percent Per Day", 0.00f, 2.00f, "0.00", HintText = "with Wall Grain Tribute: the share of the grain on the road that spoils each day (damp, rats); the rest reaches the Wall", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public float WallTributeSpoilPercentPerDay { get; set; } = 0.25f;

        [SettingPropertyBool("Free Folk Hunger Raids", HintText = "with Start Calibration applied: when the Free Folk go hungry (their fields feed only part of them and their granaries run low), more and bigger bands of hungry men leave their villages and go south across the Wall to raid the Night's Watch and the North; they are real men taken from the villages (the villages lose them), they live off what they rob, and after Free Folk Raid Days they go home with their plunder (gold to the village purse, goods to its stores) - unless they die on the way. Off = no new raids (bands already out still come home)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public bool FreeFolkHungerRaids { get; set; } = true;

        [SettingPropertyInteger("Free Folk Raid Max Parties", 0, 20, "0", HintText = "with Free Folk Hunger Raids: the most raiding bands out at the same time (a hard limit, for the map's sake)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int FreeFolkRaidMaxParties { get; set; } = 6;

        [SettingPropertyInteger("Free Folk Raid Max Men", 1, 120, "0", HintText = "with Free Folk Hunger Raids: the most men in one raiding band (a band never takes in more men on the way)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int FreeFolkRaidMaxMen { get; set; } = 40;

        [SettingPropertyInteger("Free Folk Raid Min Men", 1, 120, "0", HintText = "with Free Folk Hunger Raids: the fewest men a raiding band sets out with; the hungrier the land, the closer a band comes to Free Folk Raid Max Men", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int FreeFolkRaidMinMen { get; set; } = 12;

        [SettingPropertyInteger("Free Folk Raid Days", 1, 120, "0", HintText = "with Free Folk Hunger Raids: how many days a band raids in the south before it turns home (a band that lost more than half of its men turns home at once)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public int FreeFolkRaidDays { get; set; } = 30;

        [SettingPropertyFloatingInteger("Free Folk Raid Daily Chance", 0.00f, 1.00f, "0.00", HintText = "with Free Folk Hunger Raids: the chance a day that a new band sets out when the Free Folk are as hungry as they can be; it falls with their hunger (half as hungry - half the chance)", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: grain tribute and Free Folk hunger (r4-mur, 17.10)")]
        public float FreeFolkRaidDailyChance { get; set; } = 0.5f;

        [SettingPropertyBool("Wall Tribute District Room", HintText = "with Wall Grain Tribute: a Watch castle stores the tribute in whichever of its villages' granaries has room - the same way the carts unload - so a village whose own granary is full eats from it while the grain goes to its neighbours; off = each village orders only what fits in its own granary", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: fixes after the first test (fix-mur, 18.10)")]
        public bool WallTributeDistrictRoom { get; set; } = true;

        [SettingPropertyBool("Free Folk Raid Kin Peace", HintText = "with Free Folk Hunger Raids: the Free Folk do not attack their own hungry raiders (and the raiders leave Free Folk parties alone) on the way to the Wall - only the Night's Watch and the North stand in their way; off = the raiders are outlaws to everyone, their own lords included", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: fixes after the first test (fix-mur, 18.10)")]
        public bool FreeFolkRaidKinPeace { get; set; } = true;

        [SettingPropertyBool("Free Folk Raid Climb Wall", HintText = "with Free Folk Hunger Raids: a raiding band climbs the Wall away from the manned towers, as in the books - while it crosses the belt under the Wall near a Night's Watch castle no other party spots it; below the Wall, in the Gift, the Watch and the North can catch it again; off = the band walks past the Watch's gates in plain sight", RequireRestart = false)]
        [SettingPropertyGroup("The Wall: fixes after the first test (fix-mur, 18.10)")]
        public bool FreeFolkRaidClimbWall { get; set; } = true;

        [SettingPropertyBool("Ds Hoard Due", HintText = "with Ds Towns: once the farms are set, the lord again takes a share each day of what the townsfolk and the castle folk hold above their normal level (three times their reserve days) - a tallage on movables, paid in peace and in war, as medieval lords tallaged their burgesses. What the people already paid that day (the tenth of movables, the war aid) and the part of the town's farm raised from their savings count as paid, so the same savings are never taken twice; two thirds go to the lord, the rest to the town or castle purse, nothing to the crown. Without it the labourers' purses only grew (off = no hoard tax once the farms are set, as before)", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public bool DsHoardDue { get; set; } = true;

        [SettingPropertyFloatingInteger("Ds Hoard Due Rate", 0.000f, 0.100f, "0.000", HintText = "with Ds Hoard Due: the share a day of the hoard above the normal level taken by the lord (it comes in step by step over Ds Ramp Days after the farms are set, from Folk Hoard Tax Rate). A higher rate keeps less idle coin in the people's purses; in the long run the lord takes about what the people cannot spend", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public float DsHoardDueRate { get; set; } = 0.03f;

        [SettingPropertyBool("Ds Works Real Material", HintText = "a village does its communal works with its own hands - nobody is paid a coin for the villagers' own labour; its purse pays only for real material bought from the stall of its market town (timber, limestone, clay, tools, marble, planks - after the lords and the townsfolk have bought for their own works that day) and for hired town craftsmen, at most Ds Works Wage Per Material times the material. No material on the stall - no works, the coin stays in the village. The septs built from the tithe follow the same rule (real material or nothing; the craftsmen at most three times the material). Until now three quarters went as wages to the townsfolk and a quarter was paid for 'material' that never left any stall (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public bool DsWorksRealMaterial { get; set; } = true;

        [SettingPropertyFloatingInteger("Ds Works Wage Per Material", 0.00f, 3.00f, "0.00", HintText = "with Ds Works Real Material: the most a village pays hired town craftsmen for its communal works, as a multiple of the material it really bought", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public float DsWorksWagePerMaterial { get; set; } = 0.5f;

        [SettingPropertyBool("Ds Hoard Due Villages", HintText = "with Ds Works Real Material: a village that finds neither goods nor material for what it means to spend beyond its chest also pays its lord the Ds Hoard Due Rate a day of what its purse holds above three times its chest (two thirds to the lord, the rest to its town or castle) - one rule for hoards in towns and villages. The rate comes in step by step over Ds Ramp Days from the first day this is on, so village purses that grew while it was off are not taxed at the full rate on the first day. Off = village purses are never taxed on their savings, as the medieval dues of the villages first had it", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public bool DsHoardDueVillages { get; set; } = true;

        [SettingPropertyBool("Folk Better Table", HintText = "with Start Calibration applied: townsfolk with savings above their reserve may buy a better table - meat, cheese, butter, beer, wine, mead, oil, honey - beyond what their basket holds, as long as the price stays at or below the price ceiling of Market Sees Purse (above it the rich do not outbid the poor for food). Until now the basket took all of it and the coin stayed in the purse (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public bool FolkBetterTable { get; set; } = true;

        [SettingPropertyBool("Crown Windfall To Reserve", HintText = "a one-off windfall that falls into a crown's treasury (more than three times what the crown usually gets from outside in a day over the last 28 days - a ransom, a gift, plunder) goes into the treasury's reserve and is spent from there slowly, as the rest of the reserve, instead of being paid out to the houses as rents the same day (off = as before)", RequireRestart = false)]
        [SettingPropertyGroup("Money that cannot be spent (18.10)")]
        public bool CrownWindfallToReserve { get; set; } = true;

        [SettingPropertyBool("Ks Town Fields Every2", HintText = "with Start Calibration applied: the townsfolk's own fields bring their crop to the town stall every second day (two days' crop at once, each town on its own day, paid in full by the town purse as before) instead of every day - half the daily work, the same crop and money over time; off = every day", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: day cost")]
        public bool KsTownFieldsEvery2 { get; set; } = false;

        [SettingPropertyBool("Ks Cost Fast", HintText = "with Start Calibration: the daily work of the calibration is done in quicker ways that give exactly the same results - the weekly plan's market totals are counted on the plan's own thread, prices, stall rows and price thresholds are looked up once a day instead of again for every village, and road distances from villages to nearby towns are remembered for the session; off = the old, slower way", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: day cost")]
        public bool KsCostFast { get; set; } = true;

        [SettingPropertyBool("Ks Cost Fast2", HintText = "with Start Calibration applied: the weekly work-rule check and the weekly work rule itself are counted in a quicker way that gives exactly the same numbers - each district part's land and rent are looked up once instead of once for every set of prices, and the rule reuses the incomes the check counted the same day; off = the old, slower way", RequireRestart = false)]
        [SettingPropertyGroup("Start calibration: day cost")]
        public bool KsCostFast2 { get; set; } = true;

        [SettingPropertyBool("Side Village Crafts", HintText = "each side village of a district works at its own craft - fishing hamlets fish, mill and granary villages grow grain, the others what their land, water and climate suit best (no olives, vines or grain in the snow); the district makes the sum of all its villages. With Start Calibration applied this comes from the start calibration itself; this setting governs villages outside it. On the first day the world makes as much of every good as the day before (the change only shifts which villages make what). Off = the district makes only the goods of its game village's type, as before", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageCrafts { get; set; } = true;

        [SettingPropertyFloatingInteger("Side Village Craft Switch", 1.00f, 3.00f, "0.00", HintText = "with Side Village Crafts: a side village turns to another craft only when that craft would earn at least this many times its present one at its market town (land suitability x prices)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float SideVillageCraftSwitch { get; set; } = 1.25f;

        [SettingPropertyInteger("Side Village Craft Hold Days", 7, 364, "0", HintText = "with Side Village Crafts: ... and only when that has held without a break for this many days", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int SideVillageCraftHoldDays { get; set; } = 60;

        [SettingPropertyInteger("Side Village Craft Change Days", 7, 364, "0", HintText = "with Side Village Crafts: how many days the change takes - the old goods fade while the new ones grow; meanwhile the village pays for the timber, tools and stone really bought at its market town's stall and for the town craftsmen who make the new gear (no coin or no material on the stall - the change waits)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int SideVillageCraftChangeDays { get; set; } = 60;

        [SettingPropertyInteger("Side Village Craft Tree Days", 7, 728, "0", HintText = "with Side Village Crafts: the same for vineyards, olive groves, date palms and orchards, which take longer to bear", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int SideVillageCraftTreeDays { get; set; } = 364;

        [SettingPropertyFloatingInteger("Side Village Craft Region Share", 0.000f, 1.000f, "0.000", HintText = "with Side Village Crafts: at most this share of the side villages' hands of one region (a stronghold and its villages) may change craft in one season (91 days); at most one village per district changes at a time", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float SideVillageCraftRegionShare { get; set; } = 0.05f;

        [SettingPropertyBool("District Icon From Sum", HintText = "the main village's map icon shows the good of the craft that earns the whole district (main village and side villages) the most money; the settlement tooltip lists the district's goods. Off = the icon of the game village's type, as before", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool DistrictIconFromSum { get; set; } = true;

        [SettingPropertyFloatingInteger("District Icon Margin", 0.00f, 1.00f, "0.00", HintText = "with District Icon From Sum: the icon changes only when another craft earns the district this much more than the shown one (0.10 = 10%)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictIconMargin { get; set; } = 0.10f;

        [SettingPropertyBool("District Works", HintText = "'Invest in the district's works' in the village menu (and BetterEconomy's village menu, whose 5,000 / 15,000 / 30,000 investments are hidden): pay the villagers of one village of the district for boats, herds, ploughs or tools - the coin goes to people (wages to the village purse, real goods bought at the market town), that village makes more of its own goods, and half of what the extra sells for is yours each time the district's carts come back from market. Raiders burn the works in the homesteads they empty. Off = no new works and no pay; works already bought stay, frozen", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool DistrictWorks { get; set; } = true;

        [SettingPropertyFloatingInteger("District Works Share", 0.00f, 1.00f, "0.00", HintText = "with District Works: the investor's share of what the extra goods sell for (the lord and the village share the rest as usual)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksShare { get; set; } = 0.5f;

        [SettingPropertyFloatingInteger("District Works Bonus Side", 0.00f, 2.00f, "0.00", HintText = "with District Works: how much more a side village makes with a full kit (0.30 = +30%); the first coins add the most", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksBonusSide { get; set; } = 0.30f;

        [SettingPropertyFloatingInteger("District Works Bonus Main", 0.00f, 2.00f, "0.00", HintText = "with District Works: the same for the main village, where the lord's mill and ploughs already stand", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksBonusMain { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("District Works Kit Years", 0.10f, 10.00f, "0.0", HintText = "with District Works: a full kit for one homestead costs this many years of what that homestead makes of its craft", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksKitYears { get; set; } = 1.0f;

        [SettingPropertyInteger("District Works Min Gold", 0, 10000, "0", HintText = "with District Works: the smallest payment for works", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int DistrictWorksMinGold { get; set; } = 200;

        [SettingPropertyInteger("District Works Rebuild Days", 1, 728, "0", HintText = "with District Works: how many days after people return to burned homesteads you may still rebuild your works there (afterwards the right is gone)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int DistrictWorksRebuildDays { get; set; } = 91;

        [SettingPropertyBool("District Works Auto Rebuild", HintText = "with District Works: rebuild burned works at once when people return, as long as District Works Keep Wage Days of your party's wages stay in your purse (can also be switched in the works window)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool DistrictWorksAutoRebuild { get; set; } = true;

        [SettingPropertyInteger("District Works Keep Wage Days", 0, 364, "0", HintText = "with District Works Auto Rebuild: the days of party wages that must stay in the purse after paying for a rebuild", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int DistrictWorksKeepWageDays { get; set; } = 30;

        [SettingPropertyBool("District Works Ai", HintText = "with District Works: AI lords invest in the works of their own districts from gold beyond their war reserve when the next coin pays enough (Jeff 16.10: not yet - off until its test passes)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool DistrictWorksAi { get; set; } = false;

        [SettingPropertyFloatingInteger("District Works Ai Min Return", 0.01f, 2.00f, "0.00", HintText = "with District Works Ai: the yearly return the next coin must bring (at today's season and prices)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksAiMinReturn { get; set; } = 0.20f;

        [SettingPropertyFloatingInteger("District Works Ai Surplus Share", 0.00f, 1.00f, "0.00", HintText = "with District Works Ai: the share of a lord's gold beyond his reserve that he may put into works every 28 days", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksAiSurplusShare { get; set; } = 0.05f;

        [SettingPropertyInteger("District Works Ai Reserve Days", 0, 364, "0", HintText = "with District Works Ai: a lord keeps this many days of his party's wages ...", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int DistrictWorksAiReserveDays { get; set; } = 60;

        [SettingPropertyInteger("District Works Ai Reserve Flat", 0, 200000, "0", HintText = "with District Works Ai: ... plus this much gold, before he invests", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public int DistrictWorksAiReserveFlat { get; set; } = 20000;

        [SettingPropertyFloatingInteger("District Works Ai World Pace", 0.000f, 0.100f, "0.000", HintText = "with District Works Ai: all AI works together at most this share of the world's yearly village production every 28 days", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public float DistrictWorksAiWorldPace { get; set; } = 0.005f;

        [SettingPropertyBool("Side Village Fief Start", HintText = "Banner Kings start 'Indebted Lord': instead of the lordship title of a main village (which stays with its lord), you are given one side village of the realm you join, close to where you start - it is yours, it flies your banner on the map and pays you its share of the lord's taxes. Off = Banner Kings gives the main village title, as before", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefStart { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Income", HintText = "with a side village of your own: every day the lord's tax on what your side village makes (its goods at market prices, taxed at the lord's rate) is paid to you instead of the lord - out of the lord's tax on the district, or his purse when that is empty. Nothing at war with the lord's realm or while the district lies raided. Shown as a line in your daily gold tooltip and in the clan screen. Off = the lord keeps it all", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefIncome { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Menu", HintText = "with a side village of your own: click it on the map (or choose 'Visit ... (your village)' in its main village) to ride in - rest the night there for free, invest in its works, look over what it makes and pays you. Off = no menu", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefMenu { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Lodging", HintText = "with Side Village Fief Menu: 'Rest the night here' in your own village puts the men under your villagers' roofs for free - like the common room of an inn: nobody stirs before dawn and the men wake rested (a little faster and in better spirits until dusk). Needs Town Inns and Night Rest. Off = the men camp by the village, as anywhere on the map", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefLodging { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Clan Tab", HintText = "with a side village of your own: the clan screen's Fiefs tab lists it under 'Side villages', with its district and its income of the day. Takes effect after restarting the game. Off = the Fiefs tab as before", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefClanTab { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Trade", HintText = "with Side Village Fief Menu: 'Trade' in your village - buy and sell at the market of its main village: its goods, its prices, and the coin goes to that village's purse (as 'Buy products' in a village). Off = no trade option", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefTrade { get; set; } = true;

        [SettingPropertyBool("Side Village Fief House", HintText = "with Side Village Fief Menu: 'Your house' in your village - sleep in your own bed for free (the best rest there is: like the good house of an inn, wounded heal faster while you sleep) and keep things in the house chest. Needs Town Inns and Night Rest for the bed. Empty the chest before switching Armoury off or going back to an older version - only this version keeps it in the save. Off = no house (the chest stays in the save)", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefHouse { get; set; } = true;

        [SettingPropertyBool("Side Village Fief Walk", HintText = "with Side Village Fief Menu: 'Take a walk' in your village - walk the lands of its main village on foot (your village has no scene of its own). Works when you come in through the main village ('Visit ... (your village)'). Off = no walk option", RequireRestart = false)]
        [SettingPropertyGroup("District works and side-village crafts (18.10)")]
        public bool SideVillageFiefWalk { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Neutral Goods", HintText = "with Side Village Crafts: on the first day the balance that keeps every good's world output unchanged is worked out on the goods themselves - each village's own output with its buildings, perks, people, hands and prices, and what each side village adds in its own district - instead of on head counts alone (head counts missed up to a quarter on raw silk). Off = by head counts, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: neutral start and icon (18.10)")]
        public bool SideVillageCraftNeutralGoods { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Neutral Fix", HintText = "with Side Village Crafts: the day after the first day, what the first day really produced is compared good by good with the day before, and any craft still off by more than half a percent is set right once (by at most 10%); the check is then repeated and written to the log. Off = no second look", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: neutral start and icon (18.10)")]
        public bool SideVillageCraftNeutralFix { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Adds Winter", HintText = "with Side Village Crafts: goods a side village makes outside its district's own type are cut by winter like every other village good (the game leaves goods it does not list for a village type out of its winter cut). Off = those goods are not cut in winter, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: neutral start and icon (18.10)")]
        public bool SideVillageCraftAddsWinter { get; set; } = true;

        [SettingPropertyBool("District Icon Part Crafts", HintText = "with District Icon From Sum and Start Calibration applied: each part of a district counts only its own craft - the main village its game type, each side village the craft of its land - valued at what that part sells of it at its market town (food the district eats itself is not money). Without it the whole calibrated output counted, home-grown bread and all, and over half the icons turned to grain or timber. Off = the whole calibrated output, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: neutral start and icon (18.10)")]
        public bool DistrictIconPartCrafts { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Neutral Per Good", HintText = "with Side Village Crafts: the first-day balance is kept for every good on its own, not only for every craft as a whole - a craft that makes several goods (grain farms also raise some cattle, sheep, pigs and papyrus; cattle farms make butter, cheese and eggs) keeps each of them at the day before's world total. Off = one balance per craft, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: every good neutral, icon by crafts (18.10)")]
        public bool SideVillageCraftNeutralPerGood { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Measure Now", HintText = "with Side Village Crafts: on the first day, right after the side villages take up their crafts, every village's output of every good is checked at once against the day before, and any good still off by more than a tenth of a percent (half a percent for a whole craft when Side Village Craft Neutral Per Good is off) is set right before the day's harvest - nothing waits for the next day and every village whose goods the crafts change is checked. Off = the check runs the next day on the villages the game happened to tick, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: every good neutral, icon by crafts (18.10)")]
        public bool SideVillageCraftMeasureNow { get; set; } = true;

        [SettingPropertyBool("Side Village Craft Crop Filter", HintText = "with Side Village Crafts: goods a side village's craft adds to its district obey the crop climate filter - a grain-farming hamlet outside the hot south grows no papyrus, just like the grain farms there, and the district's worth (icon, description, works prices) no longer counts papyrus its villages cannot grow. Off = the craft's papyrus grows wherever the hamlet is and is counted in the district's worth, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: every good neutral, icon by crafts (18.10)")]
        public bool SideVillageCraftCropFilter { get; set; } = true;

        [SettingPropertyBool("Side Village Craft New Layout Balance", HintText = "with Side Village Crafts: when the map village layout differs from the one the first-day balance was worked out on (for example after Village Layout V7 is switched on or off, or a new layout comes with an update), the balance is worked out again on the first day after loading, so the world still makes as much of every good as the day before (only which villages make what shifts). Off = the old balance stays and the world's output of some goods jumps on that day", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: every good neutral, icon by crafts (18.10)")]
        public bool SideVillageCraftNewLayoutBalance { get; set; } = true;

        [SettingPropertyBool("District Icon Craft Value", HintText = "with District Icon From Sum and Start Calibration applied: the icon follows the same rule as without the calibration - each part counts the craft of its land (the main village its game type), valued by the people at home, the craft's rates and the market town's prices (without the first-day balance factors, which the calibration does not use) - so the icon changes only where another craft of the district's own villages truly earns more (about 80 districts), not wherever the calibration grows bread for the village itself. Off = by District Icon Part Crafts, as before", RequireRestart = false)]
        [SettingPropertyGroup("District crafts: every good neutral, icon by crafts (18.10)")]
        public bool DistrictIconCraftValue { get; set; } = true;

        [SettingPropertyBool("Measure Craft Rule", HintText = "log only, nothing in the game changes: once a week, and on the day the start calibration fills the stalls, the log gets a diagnosis of the rule that would let village parts change their work under the start calibration - how many parts would want to change at today's prices, at base prices and at the calibration's own prices, the ten most wanted changes with their hands, and a plain note that works are frozen while that rule is off; side villages outside the calibration get the same numbers in their daily line (off = no such lines)", RequireRestart = false)]
        [SettingPropertyGroup("Economy measurements (18.10)")]
        public bool MeasureCraftRule { get; set; } = true;

        [SettingPropertyBool("Measure Regale Shelf", HintText = "log only: every 28 days, when the hands at mines, salt pans, quarries and woods move with prices, the log also counts how many of those moves agree with the market town's stall (stall below its target - more hands, above twice the target - fewer hands) (off = no such line)", RequireRestart = false)]
        [SettingPropertyGroup("Economy measurements (18.10)")]
        public bool MeasureRegaleShelf { get; set; } = true;

        [SettingPropertyBool("Measure Caravan Trade", HintText = "log only: every 7 days the log gets the caravans' trading result - what they sold to and bought from towns, castles and villages, the wages they owe, the value of the goods in their packs, the notables' top-ups and the profit handed to their owners (off = no such line)", RequireRestart = false)]
        [SettingPropertyGroup("Economy measurements (18.10)")]
        public bool MeasureCaravanTrade { get; set; } = true;

        [SettingPropertyBool("Measure Iron Wood Flow", HintText = "log only: every 7 days the log gets where iron ore and hardwood went - stock by holder (town stalls, villages, village carts, merchant carts, caravans) and who used them up - and where the village carts carrying hardwood are heading, how long the wood has been on the road, and which towns have no firewood beyond their craftsmen's stock (off = no such lines)", RequireRestart = false)]
        [SettingPropertyGroup("Economy measurements (18.10)")]
        public bool MeasureIronWoodFlow { get; set; } = true;

        [SettingPropertyBool("Ks Switch Signal", HintText = "with Start Calibration applied: a village part judges its works by what they really fetch under the calibration - the calibration's own price of each good where the part sells it (the price of its land after carting), nudged by how short or plentiful that good is at its market town compared with the town's other goods, averaged over about a month, minus the work's own costs and the rent of its land - instead of by the raw game price index, which tops out at ten times the base price and made nine parts in ten want to change. Side villages outside the calibration use the same reckoning when Side Village Craft Ks Signal is on. Off = the raw game price index, as before", RequireRestart = false)]
        [SettingPropertyGroup("Village works follow prices (18.10)")]
        public bool KsSwitchSignal { get; set; } = true;

        [SettingPropertyBool("Ks Switch Signal Rule", HintText = "with Ks Switch Signal: village parts really change their work by that reckoning, with the same brake as Start Calibration Switch Rule - another work must pay at least 25% better for about 60 days, one part of a district at a time, within what its land allows, at most 5% of the region's hands a season; the village pays for timber, tools and stone really bought at its market town's stall and for the town craftsmen, and the hands move over 60 days (vineyards, groves, orchards and date palms a year). AI villages and the player's villages alike. Off = works stay as the calibration set them (only the pressure to change is written to the log), unless Start Calibration Switch Rule is on", RequireRestart = false)]
        [SettingPropertyGroup("Village works follow prices (18.10)")]
        public bool KsSwitchSignalRule { get; set; } = false;

        [SettingPropertyFloatingInteger("Ks Switch Market Band", 0.00f, 0.50f, "0.00", HintText = "with Ks Switch Signal: how far a good's shortage or glut at the market town may move its price in the reckoning, compared with the town's other goods (0.15 = at most 15% up or down; 0 = the calibration's own prices only)", RequireRestart = false)]
        [SettingPropertyGroup("Village works follow prices (18.10)")]
        public float KsSwitchMarketBand { get; set; } = 0.15f;

        [SettingPropertyBool("Side Village Craft Ks Signal", HintText = "with Side Village Crafts and Ks Switch Signal: a side village outside the calibration weighs its crafts by the same reckoning as the calibrated village parts (land suitability x output x the calibration's prices at its market town, minus costs and land rent) instead of land suitability x the square root of the game price index, while the calibration has a plan to price from - but only while the calibrated village parts really change their work by that reckoning (Ks Switch Signal Rule or Start Calibration Switch Rule on), so side villages never move by a reckoning the calibration itself only measures. Off = land suitability x price index, as before", RequireRestart = false)]
        [SettingPropertyGroup("Village works follow prices (18.10)")]
        public bool SideVillageCraftKsSignal { get; set; } = true;

        [SettingPropertyBool("Ks Iron Hands Follow Market", HintText = "under the start calibration: once a week the hands at iron mines follow the iron of the whole market (Westeros or Essos) instead of the price at the mine's own market town - while the towns of the market hold less iron than their smiths' stock, mines whose bloomeries had wood get 5% more hands; above twice that stock, or at a mine whose bloomery stood without wood half the week, 5% fewer (the hands go back to the fields; the mines of a part of the district never take more than half its hands - where they already do, the extra iron hands come from its other mines). Off = iron mines move with the price index every 28 days, as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron ore under the start calibration (night 18.10)")]
        public bool KsIronHandsFollowMarket { get; set; } = true;

        [SettingPropertyBool("Bloomery Wood Credit", HintText = "under the start calibration, with Bloomery At Mine: when a mining village has no gold for the wood of its bloomery, the merchants of its market town give the wood on credit - only while a bloom sells there for more than the wood it burns, up to 7 days of the bloomery's need, only if the town's treasury covers all the credit its merchants have given (wood and food) and the village's oldest bill is not overdue (the same days as the merchants' food credit); the village pays back the oldest bill first from what its carts bring home (and a quarter of its purse each day); if the town goes to war with the village the merchants lose the debt (no gold is made). Off = no new credit (debts already given are still paid back), as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron ore under the start calibration (night 18.10)")]
        public bool BloomeryWoodCredit { get; set; } = true;

        [SettingPropertyBool("Ks Ramp Mineral Times", HintText = "under the start calibration, during its ramp (the weeks when the old and the calibrated output are blended): the game's share of a mining village's ore, salt, clay and silver counts the mineral as many times as Banner Kings lists it, as outside the calibration - until now the calibration's list dropped the double entry first and the game half of the blend gave half the ore (about a thousand iron blooms lost once). Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Iron ore under the start calibration (night 18.10)")]
        public bool KsRampMineralTimes { get; set; } = true;

        [SettingPropertyBool("Ks Food Hands Follow Market", HintText = "under the start calibration, from 49 days after the end of its supply ramp: once a week the hands of a village part follow the food of the whole market (Westeros or Essos) - a work whose food the market's stalls lack today (below half of the stock they should hold, even counting food on the merchants' carts) takes up to 5% more hands, a work whose food lies on the stalls at more than twice that stock gives up to 5%, the other works of the same land give or take the difference; salt pits, sea salt and date groves get 5% more or fewer hands the same way. Hands move only between works the part's land allows, never more than 5% of a work's hands a week; no gold is paid or made. In winter the hands stay where they are (a winter shortage is the season, not the market). The 28-day price rule of salt and dates stops then (one rule). Only while the work-switch rule is off (Start Calibration Switch Rule, Ks Switch Signal Rule): with it on, that rule alone moves the works. Off = as before", RequireRestart = false)]
        [SettingPropertyGroup("Food follows the market under the start calibration (night 18.10)")]
        public bool KsFoodHandsFollowMarket { get; set; } = true;

        [SettingPropertyBool("Ks Food Hands Grow Groves", HintText = "with Ks Food Hands Follow Market: vineyards, olive groves, citrus orchards and date groves take more hands when the market lacks their fruit, like any other work - the new trees bear at once (the switch rule plants trees over 364 days and charges for it). Off = trees only give hands up under this rule, they never gain", RequireRestart = false)]
        [SettingPropertyGroup("Food follows the market under the start calibration (night 18.10)")]
        public bool KsFoodHandsGrowGroves { get; set; } = true;

        [SettingPropertyBool("Bloomery Colliers", HintText = "under the start calibration, with Bloomery At Mine: when a mine's bloomery has too little wood for the day's ore, the miners who would stand idle burn charcoal instead - they cut the district's own wood (the world's woodcutter output times how fit the mine's land is for timber: 0 in deserts and on the steppe) and char it for the bloomery. The mine smelts fewer blooms than with bought wood (part of its hands make charcoal), but no hands stand idle and no gold changes hands; bought, forest and credited wood still come first. Off = idle hands, as before", RequireRestart = false)]
        [SettingPropertyGroup("Charcoal for bloomeries under the start calibration (night 18.10)")]
        public bool BloomeryColliers { get; set; } = true;

        [SettingPropertyInteger("Bandit Limit Per Hideout", 12, 48, "0", HintText = "most bandit bands the game keeps for each hideout their clan holds - the bands roaming around it plus those inside; Realm of Thrones keeps 12 (6 around, 6 inside). The extra bands roam around the hideout (the hideout fight stays as it was) and are still born only from real outlaws - deserters, routed soldiers, the hungry and the burnt out - so where there are no such men no band forms. Works only with Outlaw Law Enabled; 12 = Realm of Thrones' own limit", RequireRestart = false)]
        [SettingPropertyGroup("Bandit numbers (night 18.10)")]
        public int BanditLimitPerHideout { get; set; } = 12;

        [SettingPropertyBool("Bandit Births Where People", HintText = "with Bandit Limit Per Hideout above Realm of Thrones' own: every band the game raises for a clan with hideouts is born at one of the clan's hideouts whose land has outlaws enough for a band (chosen the way the game chooses), never as an empty band that is removed at once; where none of the clan's hideouts has such men, no band is born. Off = the game picks the hideout as before, and births where no men are come out empty and are removed", RequireRestart = false)]
        [SettingPropertyGroup("Bandit numbers (night 18.10)")]
        public bool BanditBirthsWherePeople { get; set; } = true;

        [SettingPropertyBool("Bandit Cost Log", HintText = "writes one daily line with the bandit bands against their limit, the bands born that day, the time their AI and our work on them take each day, and the real seconds a game day took (diagnostics only; the timers are set when a campaign starts or loads)", RequireRestart = false)]
        [SettingPropertyGroup("Bandit numbers (night 18.10)")]
        public bool BanditCostLog { get; set; } = true;

        [SettingPropertyBool("Book Holdings Restore", HintText = "once per save, in the first hour the party is out on the map, set the realms back as the chronicles have them at this point of the war: King's Landing and the Red Keep return to King Joffrey, the five castles Renly took from Stannis (Sharp Point, Stonedance, Sweetport, Cape Wrath, Fellwood) return to Stannis's bannermen and Starfall to House Dayne; lords of the old side who sit there are sent to their own keeps, the old garrisons march to their own lords (no men are made or lost), the northern host near King's Landing falls back to its own fortress, and the North pays back the 1,125,434 denars it carried off from the royal treasury. Harrenhal stays with the Boltons and Essos is left as it is. Does nothing in a campaign started with this version; off = nothing changes", RequireRestart = false)]
        [SettingPropertyGroup("Book holdings (night 18.10)")]
        public bool BookHoldingsRestore { get; set; } = true;

        [SettingPropertyBool("Book Holdings Garrison", HintText = "with Book Holdings Restore: right after each returned keep changes hands, its new lord's realm marches men in to hold it - first from the parties of the new lord's own house, then from the nearest lords' parties of his realm - up to 400 men in a town and 200 in a castle, and never more than the game itself would keep there (its garrison limit, and the garrison the place can feed and the realm and the purses of its houses can bear - at least 125 in a town and 75 in a castle, as the game's own lords leave). No men are made: every soldier leaves a lord's party, and each lord keeps at least half of his men and never fewer than 20; the player's parties and parties in a battle, a siege, at sea or under contract as sellswords give none. If the realm has too few men to spare, the keep gets what there is. Only on the one-time restore - a save already restored is not touched; off = the returned keeps start with an empty garrison as before", RequireRestart = false)]
        [SettingPropertyGroup("Book holdings (night 18.10)")]
        public bool BookHoldingsGarrison { get; set; } = true;

        [SettingPropertyBool("Book Holdings Free Own Prisoners", HintText = "with Book Holdings Restore: right after each returned keep changes hands, the common prisoners in its dungeon who are soldiers of the new lord's realm (troops of the culture of the realm or of one of its houses, never bandits) are set free and join its garrison - the same men, none made or lost; every other prisoner stays in the dungeon (lords of the new lord's side are freed by the game itself). The freed men come without their arms, which their captors took; the garrison buys what is missing as for any new man. Only on the one-time restore - a save already restored is not touched; off = all common prisoners stay in the dungeon as before", RequireRestart = false)]
        [SettingPropertyGroup("Book holdings (night 18.10)")]
        public bool BookHoldingsFreeOwnPrisoners { get; set; } = true;

        public void ApplyTo(Settings s)
        {
            s.TidyBannerKingsArmourList = TidyBannerKingsArmourList;
            s.ForgeArmourEnabled = ForgeArmourEnabled;
