            s.ClassCostLeg = ClassCostLeg;
            s.ClassCostHead = ClassCostHead;
            s.ClassCostHand = ClassCostHand;
            s.ClassCostCape = ClassCostCape;
            s.ClassCostHorse = ClassCostHorse;
            s.ClassCostShield = ClassCostShield;
