            s.StaminaPerTier = StaminaPerTier;
            s.ForgeWorksWithoutYou = ForgeWorksWithoutYou;
            s.SmithWoodKg = SmithWoodKg;
            s.SmithWoodKgPerPiece = SmithWoodKgPerPiece;
