            s.SmeltArmourOnce = SmeltArmourOnce;
            s.SmeltKeepsScraps = SmeltKeepsScraps;
            s.SmithNoCrudeInput = SmithNoCrudeInput;
            s.ForgeOneClock = ForgeOneClock;
            s.ForgeOnlyWhileThere = ForgeOnlyWhileThere;
